INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('comet-ml/opik/local-dev', 'community', 'comet-ml', 'opik', 'comet-ml/opik', 'local-dev', 0, 0, 36, '2026-03-08T01:57:15.323Z', '2026-03-08T02:02:59.279Z', 'd7de43d37abb51e42ecf63878225daa144a55404e23fb854c5e8722b6f23826a', '{"id":"comet-ml/opik/local-dev","name":"local-dev","description":{"en":"The local-dev skill enables developers to debug, evaluate, and monitor LLM applications and RAG systems with comprehensive tracing and production-ready dashboards. It benefits developers working on AI agent workflows.","zh":"本地开发工具提供综合跟踪、自动评估和生产就绪仪表板，用于调试、评估和监控LLM应用程序、RAG系统和代理工作流","ja":"ローカル開発ツールは、LLMアプリケーション、RAGシステム、エージェントワークフローのデバッグ、評価、監視に使用できる包括的なトレーシング、自動評価、生产就绪ダッシュボードを提供する","ko":"로컬 개발 도구는 LLM 애플리케이션, RAG 시스템, 에이전트 워크플로우 디버깅, 평가, 모니터링을 위한综合 트레이싱, 자동 평가, 생산 준비 대시보드를 제공한다","es":"local-dev es una herramienta para depurar y evaluar aplicaciones de LLM con trazas completas y tableros de producción listos","fr":"local-dev est un outil pour déboguer et évaluer les applications LLM avec des traces complètes et des tableaux de bord de production prêts","de":"local-dev ist ein Tool zum Debuggen und Bewerten von LLM-Anwendungen mit umfassenden Spuren und produktionsbereiten Dashboards","pt":"O local-dev é uma ferramenta para desenvolvedores que desejam depurar, avaliar e monitorar aplicações LLM com facilidade. Com recursos como rastreamento abrangente e painéis de produção, os desenvolvedores podem trabalhar de forma eficiente.","ru":"Local-dev - это инструмент для разработчиков, которые хотят отладить, оценить и контролировать приложения ИИ Агентов легко. С функциями, такими как полное трассирование и панели производства, разработчики могут работать эффективно.","ar":"Local-Dev هو أداة لمطورين يرغبون في تصحيح أخطاء وتقييم ومراقبة تطبيقات وكلاء الذكاء الاصطناعي بسهولة. باستخدام ميزات مثل التتبع الشامل واللوحات الإنتاجية، يمكن للمطورين العمل بفعالية."},"seo":{"title":{"en":"local-dev: Comprehensive Debugging Setup Guide | AI Agent...","zh":"本地开发设置指南 - Local Dev","ja":"ローカル開発設定ガイド - Local Dev","ko":"로컬 개발 설정 가이드 - Local Dev","es":"Guía de Configuración de local-dev para Agentes de IA","fr":"Guide de Configuration de local-dev pour Outils d''IA","de":"Einrichtungsleitfaden für local-dev bei KI-Agenten","pt":"Guia de Configuração Local-Dev: Desenvolvimento de Aplica...","ru":"Настройка Local-Dev: Руководство по разработке приложений...","ar":"دليل إعداد Local-Dev: تطوير تطبيقات وكلاء الذكاء الاصطناعي"},"description":{"en":"Unlock efficient LLM application development with local-dev. Learn how to debug, evaluate, and monitor your workflows with our expert guide and start buildin...","zh":"使用本地开发工具调试、评估和监控LLM应用程序、RAG系统和代理工作流","ja":"ローカル開発ツールを使用してLLMアプリケーション、RAGシステム、エージェントワークフローをデバッグ、評価、監視する","ko":"로컬 개발 도구를 사용하여 LLM 애플리케이션, RAG 시스템, 에이전트 워크플ロー 디버깅, 평가, 모니터링","es":"Aprende a depurar y evaluar aplicaciones de LLM con local-dev. Obtén trazas completas y tableros de producción listos","fr":"Découvrez comment déboguer et évaluer les applications LLM avec local-dev. Obtenez des traces complètes et des tableaux de bord de production prêts","de":"Erfahren Sie, wie Sie LLM-Anwendungen mit local-dev debuggen und bewerten. Erhalten Sie umfassende Spuren und produktionsbereite Dashboards","pt":"Aprenda a configurar o local-dev para depurar, avaliar e monitorar aplicações LLM com rastreamento abrangente e painéis de produção","ru":"Узнайте, как настроить local-dev для отладки, оценки и мониторинга приложений ИИ Агентов с полным трассированием и панелями производства","ar":"تعلم كيفية تكوين Local-Dev لتصحيح أخطاء وتقييم ومراقبة تطبيقات وكلاء الذكاء الاصطناعي باستخدام تتبع شاملة ولوحات إنتاج"},"definition":{"en":"local-dev is a debugging and monitoring tool for LLM applications, RAG systems, and agentic workflows, providing features like automated evaluations and tracing.","zh":"本地开发是指使用综合工具调试、评估和监控AIエージェント应用程序的过程","ja":"ローカル開発とは、包括的なツールを使用してAIエージェントアプリケーションをデバッグ、評価、監視するプロセスである","ko":"로컬 개발은綜合ツール을 사용하여 AI 에이전트 애플리케이션을 디버깅, 평가, 모니터링하는 프로세스이다","es":"local-dev es una herramienta de desarrollo local para agentes de IA que permite la depuración y evaluación de aplicaciones de LLM","fr":"local-dev est un outil de développement local pour les outils d''IA qui permet le débogage et l''évaluation des applications LLM","de":"local-dev ist ein lokales Entwicklungstool für KI-Agenten, das die Fehlersuche und Bewertung von LLM-Anwendungen ermöglicht","pt":"O local-dev é uma ferramenta de desenvolvimento local para aplicações LLM que fornece recursos de depuração, avaliação e monitoramento","ru":"Local-dev - это инструмент локальной разработки для приложений ИИ Агентов, который предоставляет средства отладки, оценки и контроля","ar":"Local-Dev هو أداة تطوير محلية لتطبيقات وكلاء الذكاء الاصطناعي التي توفر ميزات تصحيح أخطاء وتقييم ومراقبة"},"features":{"en":["Comprehensive tracing for LLM applications and RAG systems","Automated evaluations for efficient workflow monitoring","Production-ready dashboards for real-time insights","Supports multiple modes, including Standard and BE-only","Utilizes scripts like dev-runner.sh for easy startup and shutdown","Enables verification of status with the --verify command"],"zh":["综合跟踪和自动评估","生产就绪仪表板","支持LLM应用程序、RAG系统和代理工作流","使用--restart、--start、--stop和--verify命令","支持标准和BE-only模式","使用localhost:5174和localhost:5173进行本地开发"],"ja":["包括的なトレーシングと自動評価","生产就绪ダッシュボード","LLMアプリケーション、RAGシステム、エージェントワークフローのサポート","--restart、--start、--stop、--verifyコマンドの使用","標準とBE-onlyモードのサポート","localhost:5174とlocalhost:5173を使用したローカル開発"],"ko":["綜合 트레이싱과 자동 평가","생산 준비 대시보드","LLM 애플리케이션, RAG 시스템, 에이전트 워크플로우 지원","--restart, --start, --stop, --verify 명령어 사용","표준과 BE-only 모드 지원","localhost:5174와 localhost:5173를 사용한 로컬 개발"],"es":["Depuración y evaluación de aplicaciones de LLM","Trazas completas para el análisis de errores","Tableros de producción listos para la monitorización","Modos de ejecución flexibles (Standard, BE-only)","Comandos CLI para una ejecución automática","Soporte para la verificación del estado del sistema"],"fr":["Débogage et évaluation des applications LLM","Traces complètes pour l''analyse des erreurs","Tableaux de bord de production prêts pour la surveillance","Modes d''exécution flexibles (Standard, BE-only)","Commandes CLI pour une exécution automatisée","Prise en charge de la vérification de l''état du système"],"de":["Fehlersuche und Bewertung von LLM-Anwendungen","Umfassende Spuren für die Fehleranalyse","Produktionsbereite Dashboards für die Überwachung","Flexible Ausführungsmodi (Standard, BE-only)","CLI-Befehle für eine automatisierte Ausführung","Unterstützung für die Überprüfung des Systemzustands"],"pt":["Rastreamento abrangente para aplicações LLM","Painéis de produção para monitoramento","Comandos CLI para controle de execução","Modos de execução flexíveis (Standard, BE-only)","Verificação de status com comando --verify"],"ru":["Полное трассирование для приложений ИИ Агентов","Панели производства для контроля","Команды CLI для управления выполнением","Гибкие режимы выполнения (Standard, BE-only)","Проверка статуса с помощью команды --verify"],"ar":["التتبع الشامل لتطبيقات وكلاء الذكاء الاصطناعي","اللوحات الإنتاجية لمراقبة","أوامر CLI للسيطرة على التنفيذ","أوضاع تنفيذ مرنة (Standard, BE-only)","التحقق من الحالة باستخدام الأمر --verify"]},"keywords":{"en":["how to use local-dev","local-dev setup guide","local-dev alternative","local-dev vs debugging tools","what is local-dev","local-dev install","debugging LLM applications","monitoring RAG systems","agentic workflow optimization"],"zh":["本地开发","LLM应用程序","RAG系统","代理工作流","综合跟踪","自动评估","生产就绪仪表板","AIエージェント","ローカル開発ツール"],"ja":["ローカル開発","LLMアプリケーション","RAGシステム","エージェントワークフロー","包括的なトレーシング","自動評価","生产就绪ダッシュボード","AIエージェント","ローカル開発ツール"],"ko":["로컬 개발","LLM 애플리케이션","RAG 시스템","에이전트 워크플ロー","綜合 트레이싱","자동 평가","생산 준비 대시보드","AI 에이전트","로컬 개발 도구"],"es":["local-dev","agentes de IA","desarrollo local","depuración de LLM","evaluación de aplicaciones","trazas de errores","tableros de producción","modos de ejecución","comandos CLI"],"fr":["local-dev","outils d''IA","développement local","débogage de LLM","évaluation des applications","traces d''erreurs","tableaux de bord de production","modes d''exécution","commandes CLI"],"de":["local-dev","KI-Agenten","lokales Entwicklung","Fehlersuche von LLM","Bewertung von Anwendungen","Fehler-Spuren","produktionsbereite Dashboards","Ausführungsmodi","CLI-Befehle"],"pt":["local-dev","desenvolvimento de aplicações LLM","rastreamento abrangente","painéis de produção","comandos CLI","modos de execução","verificação de status"],"ru":["local-dev","разработка приложений ИИ Агентов","полное трассирование","панели производства","команды CLI","режимы выполнения","проверка статуса"],"ar":["Local-Dev","تطوير تطبيقات وكلاء الذكاء الاصطناعي","التتبع الشامل","اللوحات الإنتاجية","أوامر CLI","أوضاع التنفيذ","التحقق من الحالة"]}},"owner":"comet-ml","repo":"opik","repoPath":"comet-ml/opik","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.323Z","topics":[],"category":"community","skillMd":{"name":"local-dev","description":"Local development environment setup and commands. Use when helping with dev server, Docker, or local testing.","bodyPreview":"# Local Development\n\n## Quick Start\n\n```bash\n./scripts/dev-runner.sh --restart   # First time / full rebuild\n./scripts/dev-runner.sh --start     # Daily start (no rebuild)\n./scripts/dev-runner.sh --stop      # Stop everything\n./scripts/dev-runner.sh --verify    # Check status\n```\n\n## Modes\n\n| Mode | Command | Frontend | Use When |\n|------|---------|----------|----------|\n| Standard | `--restart` | localhost:5174 | Frontend work, full-stack |\n| BE-only | `--be-only-restart` | localhost:5173 | Bac","body":"# Local Development\n\n## Quick Start\n\n```bash\n./scripts/dev-runner.sh --restart   # First time / full rebuild\n./scripts/dev-runner.sh --start     # Daily start (no rebuild)\n./scripts/dev-runner.sh --stop      # Stop everything\n./scripts/dev-runner.sh --verify    # Check status\n```\n\n## Modes\n\n| Mode | Command | Frontend | Use When |\n|------|---------|----------|----------|\n| Standard | `--restart` | localhost:5174 | Frontend work, full-stack |\n| BE-only | `--be-only-restart` | localhost:5173 | Backend-focused, faster rebuilds |\n\n## URLs\n\n- **Frontend**: localhost:5174 (standard) / localhost:5173 (BE-only)\n- **Backend API**: localhost:8080\n- **Health**: http://localhost:8080/health-check?name=all\n\n## Build Commands\n\n```bash\n./scripts/dev-runner.sh --build-be   # Backend only\n./scripts/dev-runner.sh --build-fe   # Frontend only\n./scripts/dev-runner.sh --lint-be    # Spotless\n./scripts/dev-runner.sh --lint-fe    # ESLint\n./scripts/dev-runner.sh --migrate    # DB migrations\n```\n\n## Logs\n\n```bash\ntail -f /tmp/opik-backend.log        # Backend\ntail -f /tmp/opik-frontend.log       # Frontend (standard)\ndocker logs -f opik-frontend-1       # Frontend (BE-only)\n```\n\n## SDK Config\n\n```bash\nexport OPIK_URL_OVERRIDE=''http://localhost:8080''\nexport OPIK_WORKSPACE=''default''\n```\n\n## Troubleshooting\n\n**Won''t start:**\n```bash\n./scripts/dev-runner.sh --verify\nlsof -i :8080                        # Port conflict?\n./scripts/dev-runner.sh --stop && ./scripts/dev-runner.sh --restart\n```\n\n**Build fails:**\n```bash\ncd apps/opik-backend && mvn clean install -DskipTests\ncd apps/opik-frontend && rm -rf node_modules && npm install\n```\n\n**Database issues:**\n```bash\n./scripts/dev-runner.sh --stop\n./opik.sh --clean                    # WARNING: deletes data\n./scripts/dev-runner.sh --restart\n```\n"},"lastSynced":"2026-03-08T02:02:59.279Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing comprehensive tracing and production-ready dashboards for LLM applications and RAG systems","zh":"适合需要对LLM应用和RAG系统进行全面跟踪和生产就绪仪表板的AI代理开发人员","ja":"LLMアプリケーションとRAGシステムの包括的なトレースとプロダクションレディーダッシュボードを必要とするAIエージェント開発者に最適","ko":"LLM 애플리케이션 및 RAG 시스템에 대한 포괄적인 추적 및 프로덕션 준비 대시보드를 필요로 하는 AI 에이전트 개발자에게 적합","es":"Perfecto para desarrolladores de Agentes de IA que necesitan un rastreo integral y paneles de producción listos para aplicaciones LLM y sistemas RAG","fr":"Parfait pour les développeurs d''Agents d''IA ayant besoin d''un traçage complet et de tableaux de bord prêts pour la production pour les applications LLM et les systèmes RAG","de":"Perfekt für AI-Agent-Entwickler, die umfassendes Tracing und produktionsbereite Dashboards für LLM-Anwendungen und RAG-Systeme benötigen","pt":"Perfeito para Desenvolvedores de Agentes de IA que precisam de rastreamento abrangente e painéis de produção prontos para aplicações LLM e sistemas RAG","ru":"Идеально подходит для разработчиков агентов ИИ, которым требуются всестороннее отслеживание и готовые к производству панели для приложений LLM и систем RAG","ar":"مثالي لمطوري وكيل الذكاء الاصطناعي الذين يحتاجون إلى تتبع شاملة ولوحات تحكم جاهزة للإنتاج لتطبيقات LLM وأنظمة RAG"},"recommendation":{"en":"Empowers agents to debug, evaluate, and monitor workflows with comprehensive tracing and production-ready dashboards using scripts like dev-runner.sh, enabling efficient daily starts and stops with commands like --start and --stop, and verifying status with --verify","zh":"赋予代理调试、评估和监视工作流的能力，使用dev-runner.sh等脚本实现全面跟踪和生产就绪仪表板，能够使用--start和--stop等命令高效地启动和停止，并使用--verify命令验证状态","ja":"エージェントにデバッグ、評価、ワークフローの監視を可能にすることで、dev-runner.shなどのスクリプトを使用して包括的なトレースとプロダクションレディーダッシュボードを実現します。また、--startおよび--stopなどのコマンドを使用して効率的にスタートとストップを行い、--verifyコマンドを使用してステータスを確認します","ko":"dev-runner.sh와 같은 스크립트를 사용하여 포괄적인 추적 및 프로덕션 준비 대시보드를 통해 에이전트가 디버깅, 평가 및 워크플로우 모니터링을 할 수 있도록 합니다. 또한 --start 및 --stop과 같은 명령어를 사용하여 효율적으로 시작 및 중지를 수행하고 --verify 명령어를 사용하여 상태를 확인합니다","es":"Habilita a los agentes a depurar, evaluar y monitorear flujos de trabajo con un rastreo integral y paneles de producción listos usando scripts como dev-runner.sh, lo que permite arranques y paradas diarios eficientes con comandos como --start y --stop, y verificando el estado con --verify","fr":"Permet aux agents de déboguer, d''évaluer et de surveiller les flux de travail avec un traçage complet et des tableaux de bord prêts pour la production en utilisant des scripts comme dev-runner.sh, ce qui permet des démarrages et arrêts quotidiens efficaces avec des commandes comme --start et --stop, et en vérifiant le statut avec --verify","de":"Ermächtigt Agenten, Workflows mit umfassendem Tracing und produktionsbereiten Dashboards zu debuggen, zu bewerten und zu überwachen, indem Skripte wie dev-runner.sh verwendet werden, wodurch effiziente tägliche Start- und Stoppvorgänge mit Befehlen wie --start und --stop ermöglicht werden und der Status mit --verify überprüft wird","pt":"Habilita os agentes a depurar, avaliar e monitorar fluxos de trabalho com rastreamento abrangente e painéis de produção prontos usando scripts como dev-runner.sh, permitindo inícios e paradas diários eficientes com comandos como --start e --stop, e verificando o status com --verify","ru":"Позволяет агентам отлаживать, оценивать и контролировать рабочие процессы с помощью всестороннего отслеживания и готовых к производству панелей, используя скрипты, такие как dev-runner.sh, что позволяет эффективно запускать и останавливать их ежедневно с помощью команд, таких как --start и --stop, и проверять статус с помощью --verify","ar":"تمكن الوكيل من تصحيح الأخطاء وتقييم ومراقبة سير العمل باستخدام تتبع شامل ولوحات تحكم جاهزة للإنتاج باستخدام سكريبتات مثل dev-runner.sh، مما يسمح بالstarts و stops اليومية بكفاءة باستخدام أوامر مثل --start و --stop، والتحقق من الحالة باستخدام --verify"},"useCases":{"en":["Debugging LLM applications with comprehensive tracing","Evaluating RAG systems with production-ready dashboards","Monitoring AI agent workflows with daily starts and stops"],"zh":["使用全面跟踪调试LLM应用","使用生产就绪仪表板评估RAG系统","使用每日启动和停止监视AI代理工作流"],"ja":["包括的なトレースを使用してLLMアプリケーションをデバッグする","プロダクションレディーダッシュボードを使用してRAGシステムを評価する","毎日のスタートとストップを使用してAIエージェントのワークフローを監視する"],"ko":["포괄적인 추적을 사용하여 LLM 애플리케이션 디버깅","프로덕션 준비 대시보드를 사용하여 RAG 시스템 평가","매일 시작 및 중지를 사용하여 AI 에이전트 워크플로우 모니터링"],"es":["Depuración de aplicaciones LLM con un rastreo integral","Evaluación de sistemas RAG con paneles de producción listos","Monitoreo de flujos de trabajo de agentes de IA con arranques y paradas diarios"],"fr":["Débogage des applications LLM avec un traçage complet","Évaluation des systèmes RAG avec des tableaux de bord prêts pour la production","Surveillance des flux de travail des agents d''IA avec des démarrages et arrêts quotidiens"],"de":["Fehlersuche in LLM-Anwendungen mit umfassendem Tracing","Bewertung von RAG-Systemen mit produktionsbereiten Dashboards","Überwachung von AI-Agent-Workflows mit täglichen Start- und Stoppvorgängen"],"pt":["Depuração de aplicações LLM com rastreamento abrangente","Avaliação de sistemas RAG com painéis de produção prontos","Monitoramento de fluxos de trabalho de agentes de IA com inícios e paradas diários"],"ru":["Отладка приложений LLM с помощью всестороннего отслеживания","Оценка систем RAG с готовыми к производству панелями","Контроль рабочих процессов агентов ИИ с ежедневными запусками и остановками"],"ar":["تصحيح أخطاء تطبيقات LLM مع تتبع شامل","تقييم أنظمة RAG مع لوحات تحكم جاهزة للإنتاج","مراقبة سير عمل وكلاء الذكاء الاصطناعي مع starts و stops اليومية"]},"limitations":{"en":["Requires execution of scripts like dev-runner.sh","Limited to local development environment","Dependent on specific command-line flags like --restart and --be-only-restart"],"zh":["需要执行dev-runner.sh等脚本","仅限本地开发环境","依赖特定命令行标志如--restart和--be-only-restart"],"ja":["dev-runner.shなどのスクリプトの実行が必要","ローカル開発環境のみ","--restartおよび--be-only-restartなどの特定のコマンドラインフラグに依存"],"ko":["dev-runner.sh와 같은 스크립트의 실행이 필요","로컬 개발 환경만","--restart 및 --be-only-restart와 같은 특정 명령줄 플래그에 의존"],"es":["Requiere la ejecución de scripts como dev-runner.sh","Limitado a un entorno de desarrollo local","Dependiente de flags de línea de comandos específicos como --restart y --be-only-restart"],"fr":["Nécessite l''exécution de scripts comme dev-runner.sh","Limité à un environnement de développement local","Dépendant de flags de ligne de commande spécifiques comme --restart et --be-only-restart"],"de":["Erfordert die Ausführung von Skripten wie dev-runner.sh","Begrenzt auf eine lokale Entwicklungsumgebung","Abhängig von spezifischen Befehlszeilenflags wie --restart und --be-only-restart"],"pt":["Requer a execução de scripts como dev-runner.sh","Limitado ao ambiente de desenvolvimento local","Dependente de flags de linha de comando específicas como --restart e --be-only-restart"],"ru":["Требует выполнения скриптов, таких как dev-runner.sh","Ограничен локальной средой разработки","Зависит от конкретных флагов командной строки, таких как --restart и --be-only-restart"],"ar":["يتطلب تنفيذ سكريبتات مثل dev-runner.sh","محدود بالبيئة المحلية للتطوير","يعتمد على علامات سطر الأوامر المحددة مثل --restart و --be-only-restart"]},"version":4},"contentHash":"d7de43d37abb51e42ecf63878225daa144a55404e23fb854c5e8722b6f23826a","qualityScore":36}');
