INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('comet-ml/opik/local-dev', 'local-dev', 'comet-ml', 'opik', 'community', 'local-dev comet-ml opik community The local-dev skill enables developers to debug, evaluate, and monitor LLM applications and RAG systems with comprehensive tracing and production-ready dashboards. It benefits developers working on AI agent workflows. 本地开发工具提供综合跟踪、自动评估和生产就绪仪表板，用于调试、评估和监控LLM应用程序、RAG系统和代理工作流 ローカル開発ツールは、LLMアプリケーション、RAGシステム、エージェントワークフローのデバッグ、評価、監視に使用できる包括的なトレーシング、自動評価、生产就绪ダッシュボードを提供する 로컬 개발 도구는 LLM 애플리케이션, RAG 시스템, 에이전트 워크플로우 디버깅, 평가, 모니터링을 위한综合 트레이싱, 자동 평가, 생산 준비 대시보드를 제공한다 local-dev es una herramienta para depurar y evaluar aplicaciones de LLM con trazas completas y tableros de producción listos local-dev est un outil pour déboguer et évaluer les applications LLM avec des traces complètes et des tableaux de bord de production prêts local-dev ist ein Tool zum Debuggen und Bewerten von LLM-Anwendungen mit umfassenden Spuren und produktionsbereiten Dashboards O local-dev é uma ferramenta para desenvolvedores que desejam depurar, avaliar e monitorar aplicações LLM com facilidade. Com recursos como rastreamento abrangente e painéis de produção, os desenvolvedores podem trabalhar de forma eficiente. Local-dev - это инструмент для разработчиков, которые хотят отладить, оценить и контролировать приложения ИИ Агентов легко. С функциями, такими как полное трассирование и панели производства, разработчики могут работать эффективно. Local-Dev هو أداة لمطورين يرغبون في تصحيح أخطاء وتقييم ومراقبة تطبيقات وكلاء الذكاء الاصطناعي بسهولة. باستخدام ميزات مثل التتبع الشامل واللوحات الإنتاجية، يمكن للمطورين العمل بفعالية. how to use local-dev local-dev setup guide local-dev alternative local-dev vs debugging tools what is local-dev local-dev install debugging LLM applications monitoring RAG systems agentic workflow optimization 本地开发 LLM应用程序 RAG系统 代理工作流 综合跟踪 自动评估 生产就绪仪表板 AIエージェント ローカル開発ツール Comprehensive tracing for LLM applications and RAG systems Automated evaluations for efficient workflow monitoring Production-ready dashboards for real-time insights Supports multiple modes, including Standard and BE-only Utilizes scripts like dev-runner.sh for easy startup and shutdown Enables verification of status with the --verify command local-dev is a debugging and monitoring tool for LLM applications, RAG systems, and agentic workflows, providing features like automated evaluations and tracing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MrZhang123/ai-workspace/json-canvas', 'community', 'MrZhang123', 'ai-workspace', 'MrZhang123/ai-workspace', 'json-canvas', 0, 0, 36, '2026-03-08T01:57:15.322Z', '2026-03-08T02:02:59.279Z', '174481b16ead9bfe7b417e59b14a952d72395fe04b31aa9e351d73d62f28fb90', '{"id":"MrZhang123/ai-workspace/json-canvas","name":"json-canvas","description":{"en":"The json-canvas skill enables AI agents to create and edit JSON Canvas files, used in Obsidian and other applications, following the JSON Canvas Spec 1.0. This skill benefits developers working with infinite canvas data.","zh":"JSON Canvas 技术允许开发者创建和编辑无限画布数据，用于 Obsidian 等应用","ja":"JSON Canvas は、AIエージェントとの連携により、無限キャンバスデータを作成・編集できる技術です","ko":"JSON Canvas는 Obsidian용 무한 캔버스 데이터 생성을 위한 기술로, AI 도구와의 상호작용을 지원합니다","es":"Json-canvas permite a los agentes compatibles crear y editar archivos de canvas JSON válidos para Obsidian y otras aplicaciones.","fr":"Json-canvas permet aux agents compatibles de créer et d''éditer des fichiers de canvas JSON valides pour Obsidian et d''autres applications.","de":"Json-canvas ermöglicht es kompatiblen Agents, gültige JSON-Canvas-Dateien für Obsidian und andere Anwendungen zu erstellen und zu bearbeiten.","pt":"O JSON Canvas é um formato de arquivo aberto para dados de canvas infinito, permitindo a criação e edição de arquivos .canvas com arrays de nodes e edges.","ru":"JSON Canvas — это открытый формат файла для данных бесконечного холста, позволяющий создавать и редактировать файлы .canvas с массивами узлов и ребер.","ar":"JSON Canvas هو تنسيق ملف مفتوح للبيانات الشبكية غير المحدودة، مما يسمح بإنشاء وتحرير ملفات .canvas مع مصفوفات العقد والاقترانات"},"seo":{"title":{"en":"json-canvas: JSON Canvas File Creation for AI Agents | AI...","zh":"JSON Canvas 技术指南：创建和编辑无限画布数据","ja":"JSON Canvas セットアップガイド：AIエージェントとの相互作用","ko":"JSON Canvas 개발자 가이드: Obsidian용 무한 캔버스 데이터 생성","es":"Guía de configuración de json-canvas para agentes de inte...","fr":"Guide de démarrage rapide pour json-canvas avec les outil...","de":"Einrichtungsleitfaden für json-canvas in KI-Agents","pt":"Guia de Configuração do JSON Canvas para Ferramentas de IA","ru":"Настройка JSON Canvas для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد JSON Canvas للأدوات الذكية"},"description":{"en":"Discover how to create and edit valid JSON Canvas files with the json-canvas skill, optimized for Obsidian and other applications. Learn more and get started...","zh":"了解 JSON Canvas 技术，使用 AI 工具创建和编辑无限画布数据，适用于 Obsidian 等应用","ja":"JSON Canvas を使用して AIエージェントと連携し、無限キャンバスデータを作成・編集する方法を学ぶ","ko":"Obsidian용 무한 캔버스 데이터 생성을 위한 JSON Canvas 기술紹介, AI 도구와의 상호작용","es":"Aprende a crear y editar archivos de canvas JSON válidos con json-canvas para agentes de inteligencia artificial","fr":"Découvrez comment créer et éditer des fichiers de canvas JSON valides avec json-canvas pour les outils d''IA","de":"Erfahren Sie, wie Sie gültige JSON-Canvas-Dateien mit json-canvas für KI-Agents erstellen und bearbeiten","pt":"Aprenda a criar e editar arquivos JSON Canvas válidos para aplicações como Obsidian com nossa guia de configuração","ru":"Узнайте, как создавать и редактировать допустимые файлы JSON Canvas для приложений, таких как Obsidian, с нашей помощью","ar":"تعلم كيفية إنشاء وتحرير ملفات JSON Canvas صالحة لبرامج مثل Obsidian باستخدام دليلنا"},"definition":{"en":"json-canvas is an AI agent skill that enables the creation and editing of valid JSON Canvas files, containing nodes and edges, used in applications like Obsidian.","zh":"JSON Canvas 是一种开放的文件格式，用于存储无限画布数据","ja":"JSON Canvas は、無限キャンバスデータを保存するためのオープンなファイル形式です","ko":"JSON Canvas는 무한 캔버스 데이터를 저장하기 위한 공개 파일 형식입니다","es":"Json-canvas es un formato de archivo abierto para datos de canvas infinito que contiene JSON válido según la especificación JSON Canvas 1.0","fr":"Json-canvas est un format de fichier ouvert pour les données de canvas infini qui contient du JSON valide selon la spécification JSON Canvas 1.0","de":"Json-canvas ist ein offenes Dateiformat für infinite Canvas-Daten, das gültiges JSON gemäß der JSON Canvas Spezifikation 1.0 enthält","pt":"JSON Canvas é um formato de arquivo que contém dados de canvas em formato JSON, com arrays de nodes e edges.","ru":"JSON Canvas — это формат файла, содержащий данные холста в формате JSON, с массивами узлов и ребер.","ar":"JSON Canvas هو تنسيق ملف يحتوي على بيانات الشبكة بالتنسيق JSON، مع مصفوفات العقد والاقترانات"},"features":{"en":["Creates and edits valid JSON Canvas files (.canvas) following the JSON Canvas Spec 1.0","Contains two top-level arrays: nodes and edges","Supports Obsidian and other applications using JSON Canvas files","Enables skills-compatible agents to work with infinite canvas data","Follows the JSON Canvas Spec 1.0 for file structure and content"],"zh":["支持创建和编辑无限画布数据","使用 JSON 格式存储数据","兼容 Obsidian 等应用","提供 nodes 和 edges 两个顶级数组","遵循 JSON Canvas Spec 1.0 标准"],"ja":["無限キャンバスデータの作成・編集をサポート","JSON形式でデータを保存","Obsidian などのアプリケーションと互換性がある","nodes と edges の 2 つのトップレベル配列を提供","JSON Canvas Spec 1.0 標準に準拠"],"ko":["무한 캔버스 데이터 생성 및 편집 지원","JSON 형식으로 데이터 저장","Obsidian 등의 애플리케이션과 호환","nodes와 edges의 2개의 최상위 배열 제공","JSON Canvas Spec 1.0 표준 준수"],"es":["Creación y edición de archivos de canvas JSON válidos","Compatibilidad con la especificación JSON Canvas 1.0","Estructura de archivo con dos matrices principales: nodos y bordes","Uso en aplicaciones como Obsidian","Soporte para datos de canvas infinito"],"fr":["Création et édition de fichiers de canvas JSON valides","Compatibilité avec la spécification JSON Canvas 1.0","Structure de fichier avec deux tableaux principaux : nœuds et bords","Utilisation dans des applications comme Obsidian","Prise en charge des données de canvas infini"],"de":["Erstellung und Bearbeitung gültiger JSON-Canvas-Dateien","Kompatibilität mit der JSON Canvas Spezifikation 1.0","Dateistruktur mit zwei Hauptarrays: Knoten und Kanten","Verwendung in Anwendungen wie Obsidian","Unterstützung für infinite Canvas-Daten"],"pt":["Criação e edição de arquivos .canvas válidos","Suporte a arrays de nodes e edges","Compatibilidade com aplicações como Obsidian","Seguimento do padrão JSON Canvas Spec 1.0","Estrutura de arquivo com nodes e edges"],"ru":["Создание и редактирование допустимых файлов .canvas","Поддержка массивов узлов и ребер","Совместимость с приложениями, такими как Obsidian","Соответствие спецификации JSON Canvas Spec 1.0","Структура файла с узлами и ребрами"],"ar":["إنشاء وتحرير ملفات .canvas صالحة","دعم مصفوفات العقد والاقترانات","التوافق مع البرامج مثل Obsidian","الامتثال لمواصفات JSON Canvas Spec 1.0","هيكل الملف مع العقد والاقترانات"]},"keywords":{"en":["what is json-canvas","how to use json-canvas","json-canvas setup guide","json-canvas alternative","json-canvas vs obsidian","json-canvas install","json-canvas file format","json-canvas spec 1.0","infinite canvas data","json canvas file creation"],"zh":["JSON Canvas","无限画布数据","Obsidian","AI工具","JSON 格式","nodes","edges","JSON Canvas Spec 1.0"],"ja":["JSON Canvas","無限キャンバスデータ","Obsidian","AIエージェント","JSON形式","nodes","edges","JSON Canvas Spec 1.0"],"ko":["JSON Canvas","무한 캔버스 데이터","Obsidian","AI 도구","JSON 형식","nodes","edges","JSON Canvas Spec 1.0"],"es":["json-canvas","agentes de inteligencia artificial","archivos de canvas JSON","especificación JSON Canvas 1.0","Obsidian","datos de canvas infinito","creación de archivos de canvas","edición de archivos de canvas"],"fr":["json-canvas","outils d''IA","fichiers de canvas JSON","spécification JSON Canvas 1.0","Obsidian","données de canvas infini","création de fichiers de canvas","édition de fichiers de canvas"],"de":["json-canvas","KI-Agents","JSON-Canvas-Dateien","JSON Canvas Spezifikation 1.0","Obsidian","infinite Canvas-Daten","Erstellung von Canvas-Dateien","Bearbeitung von Canvas-Dateien"],"pt":["json canvas","ferramentas de ia","configuração json canvas","arquivos .canvas","obsidian","json canvas spec 1.0","desenvolvimento de software","tecnologias de ia"],"ru":["json canvas","ии агенты","настройка json canvas","файлы .canvas","obsidian","json canvas spec 1.0","разработка программного обеспечения","технологии ии"],"ar":["json canvas","أدوات ذكية","إعداد json canvas","ملفات .canvas","obsidian","مواصفات json canvas 1.0","تطوير البرمجيات","تكنولوجيا الذكاء الاصطناعي"]}},"owner":"MrZhang123","repo":"ai-workspace","repoPath":"MrZhang123/ai-workspace","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.322Z","topics":[],"category":"community","skillMd":{"name":"json-canvas","description":"Create and edit JSON Canvas files (.canvas) with nodes, edges, groups, and connections. Use when working with .canvas files, creating visual canvases, mind maps, flowcharts, or when the user mentions Canvas files in Obsidian.","bodyPreview":"# JSON Canvas Skill\n\nThis skill enables skills-compatible agents to create and edit valid JSON Canvas files (`.canvas`) used in Obsidian and other applications.\n\n## Overview\n\nJSON Canvas is an open file format for infinite canvas data. Canvas files use the `.canvas` extension and contain valid JSON following the [JSON Canvas Spec 1.0](https://jsoncanvas.org/spec/1.0/).\n\n## File Structure\n\nA canvas file contains two top-level arrays:\n\n```json\n{\n  \"nodes\": [],\n  \"edges\": []\n}\n```\n\n- `nodes` (optio","body":"# JSON Canvas Skill\n\nThis skill enables skills-compatible agents to create and edit valid JSON Canvas files (`.canvas`) used in Obsidian and other applications.\n\n## Overview\n\nJSON Canvas is an open file format for infinite canvas data. Canvas files use the `.canvas` extension and contain valid JSON following the [JSON Canvas Spec 1.0](https://jsoncanvas.org/spec/1.0/).\n\n## File Structure\n\nA canvas file contains two top-level arrays:\n\n```json\n{\n  \"nodes\": [],\n  \"edges\": []\n}\n```\n\n- `nodes` (optional): Array of node objects\n- `edges` (optional): Array of edge objects connecting nodes\n\n## Nodes\n\nNodes are objects placed on the canvas. There are four node types:\n- `text` - Text content with Markdown\n- `file` - Reference to files/attachments\n- `link` - External URL\n- `group` - Visual container for other nodes\n\n### Z-Index Ordering\n\nNodes are ordered by z-index in the array:\n- First node = bottom layer (displayed below others)\n- Last node = top layer (displayed above others)\n\n### Generic Node Attributes\n\nAll nodes share these attributes:\n\n| Attribute | Required | Type | Description |\n|-----------|----------|------|-------------|\n| `id` | Yes | string | Unique identifier for the node |\n| `type` | Yes | string | Node type: `text`, `file`, `link`, or `group` |\n| `x` | Yes | integer | X position in pixels |\n| `y` | Yes | integer | Y position in pixels |\n| `width` | Yes | integer | Width in pixels |\n| `height` | Yes | integer | Height in pixels |\n| `color` | No | canvasColor | Node color (see Color section) |\n\n### Text Nodes\n\nText nodes contain Markdown content.\n\n```json\n{\n  \"id\": \"6f0ad84f44ce9c17\",\n  \"type\": \"text\",\n  \"x\": 0,\n  \"y\": 0,\n  \"width\": 400,\n  \"height\": 200,\n  \"text\": \"# Hello World\\n\\nThis is **Markdown** content.\"\n}\n```\n\n#### Newline Escaping (Common Pitfall)\n\nIn JSON, newline characters inside strings **must** be represented as `\\n`. Do **not** use the literal sequence `\\\\n` in a `.canvas` file—Obsidian will render it as the characters `\\` and `n` instead of a line break.\n\nExamples:\n\n```json\n{ \"type\": \"text\", \"text\": \"Line 1\\nLine 2\" }\n```\n\n```json\n{ \"type\": \"text\", \"text\": \"Line 1\\\\nLine 2\" }\n```\n\n| Attribute | Required | Type | Description |\n|-----------|----------|------|-------------|\n| `text` | Yes | string | Plain text with Markdown syntax |\n\n### File Nodes\n\nFile nodes reference files or attachments (images, videos, PDFs, notes, etc.).\n\n```json\n{\n  \"id\": \"a1b2c3d4e5f67890\",\n  \"type\": \"file\",\n  \"x\": 500,\n  \"y\": 0,\n  \"width\": 400,\n  \"height\": 300,\n  \"file\": \"Attachments/diagram.png\"\n}\n```\n\n```json\n{\n  \"id\": \"b2c3d4e5f6789012\",\n  \"type\": \"file\",\n  \"x\": 500,\n  \"y\": 400,\n  \"width\": 400,\n  \"height\": 300,\n  \"file\": \"Notes/Project Overview.md\",\n  \"subpath\": \"#Implementation\"\n}\n```\n\n| Attribute | Required | Type | Description |\n|-----------|----------|------|-------------|\n| `file` | Yes | string | Path to file within the system |\n| `subpath` | No | string | Link to heading or block (starts with `#`) |\n\n### Link Nodes\n\nLink nodes display external URLs.\n\n```json\n{\n  \"id\": \"c3d4e5f678901234\",\n  \"type\": \"link\",\n  \"x\": 1000,\n  \"y\": 0,\n  \"width\": 400,\n  \"height\": 200,\n  \"url\": \"https://obsidian.md\"\n}\n```\n\n| Attribute | Required | Type | Description |\n|-----------|----------|------|-------------|\n| `url` | Yes | string | External URL |\n\n### Group Nodes\n\nGroup nodes are visual containers for organizing other nodes.\n\n```json\n{\n  \"id\": \"d4e5f6789012345a\",\n  \"type\": \"group\",\n  \"x\": -50,\n  \"y\": -50,\n  \"width\": 1000,\n  \"height\": 600,\n  \"label\": \"Project Overview\",\n  \"color\": \"4\"\n}\n```\n\n```json\n{\n  \"id\": \"e5f67890123456ab\",\n  \"type\": \"group\",\n  \"x\": 0,\n  \"y\": 700,\n  \"width\": 800,\n  \"height\": 500,\n  \"label\": \"Resources\",\n  \"background\": \"Attachments/background.png\",\n  \"backgroundStyle\": \"cover\"\n}\n```\n\n| Attribute | Required | Type | Description |\n|-----------|----------|------|-------------|\n| `label` | No | string | Text label for the group |\n| `background` | No | string | Path to background image |\n| `backgroundStyle` | No | string | Background rendering style |\n\n#### Background Styles\n\n| Value | Description |\n|-------|-------------|\n| `cover` | Fills entire width and height of node |\n| `ratio` | Maintains aspect ratio of background image |\n| `repeat` | Repeats image as pattern in both directions |\n\n## Edges\n\nEdges are lines connecting nodes.\n\n```json\n{\n  \"id\": \"f67890123456789a\",\n  \"fromNode\": \"6f0ad84f44ce9c17\",\n  \"toNode\": \"a1b2c3d4e5f67890\"\n}\n```\n\n```json\n{\n  \"id\": \"0123456789abcdef\",\n  \"fromNode\": \"6f0ad84f44ce9c17\",\n  \"fromSide\": \"right\",\n  \"fromEnd\": \"none\",\n  \"toNode\": \"b2c3d4e5f6789012\",\n  \"toSide\": \"left\",\n  \"toEnd\": \"arrow\",\n  \"color\": \"1\",\n  \"label\": \"leads to\"\n}\n```\n\n| Attribute | Required | Type | Default | Description |\n|-----------|----------|------|---------|-------------|\n| `id` | Yes | string | - | Unique identifier for the edge |\n| `fromNode` | Yes | string | - | Node ID where connection starts |\n| `fromSide` | No | string | - | Side where edge starts |\n| `fromEnd` | No | string | `none` | Shape at edge start |\n| `toNode` | Yes | string | - | Node ID where connection ends |\n| `toSide` | No | string | - | Side where edge ends |\n| `toEnd` | No | string | `arrow` | Shape at edge end |\n| `color` | No | canvasColor | - | Line color |\n| `label` | No | string | - | Text label for the edge |\n\n### Side Values\n\n| Value | Description |\n|-------|-------------|\n| `top` | Top edge of node |\n| `right` | Right edge of node |\n| `bottom` | Bottom edge of node |\n| `left` | Left edge of node |\n\n### End Shapes\n\n| Value | Description |\n|-------|-------------|\n| `none` | No endpoint shape |\n| `arrow` | Arrow endpoint |\n\n## Colors\n\nThe `canvasColor` type can be specified in two ways:\n\n### Hex Colors\n\n```json\n{\n  \"color\": \"#FF0000\"\n}\n```\n\n### Preset Colors\n\n```json\n{\n  \"color\": \"1\"\n}\n```\n\n| Preset | Color |\n|--------|-------|\n| `\"1\"` | Red |\n| `\"2\"` | Orange |\n| `\"3\"` | Yellow |\n| `\"4\"` | Green |\n| `\"5\"` | Cyan |\n| `\"6\"` | Purple |\n\nNote: Specific color values for presets are intentionally undefined, allowing applications to use their own brand colors.\n\n## Complete Examples\n\n### Simple Canvas with Text and Connections\n\n```json\n{\n  \"nodes\": [\n    {\n      \"id\": \"8a9b0c1d2e3f4a5b\",\n      \"type\": \"text\",\n      \"x\": 0,\n      \"y\": 0,\n      \"width\": 300,\n      \"height\": 150,\n      \"text\": \"# Main Idea\\n\\nThis is the central concept.\"\n    },\n    {\n      \"id\": \"1a2b3c4d5e6f7a8b\",\n      \"type\": \"text\",\n      \"x\": 400,\n      \"y\": -100,\n      \"width\": 250,\n      \"height\": 100,\n      \"text\": \"## Supporting Point A\\n\\nDetails here.\"\n    },\n    {\n      \"id\": \"2b3c4d5e6f7a8b9c\",\n      \"type\": \"text\",\n      \"x\": 400,\n      \"y\": 100,\n      \"width\": 250,\n      \"height\": 100,\n      \"text\": \"## Supporting Point B\\n\\nMore details.\"\n    }\n  ],\n  \"edges\": [\n    {\n      \"id\": \"3c4d5e6f7a8b9c0d\",\n      \"fromNode\": \"8a9b0c1d2e3f4a5b\",\n      \"fromSide\": \"right\",\n      \"toNode\": \"1a2b3c4d5e6f7a8b\",\n      \"toSide\": \"left\"\n    },\n    {\n      \"id\": \"4d5e6f7a8b9c0d1e\",\n      \"fromNode\": \"8a9b0c1d2e3f4a5b\",\n      \"fromSide\": \"right\",\n      \"toNode\": \"2b3c4d5e6f7a8b9c\",\n      \"toSide\": \"left\"\n    }\n  ]\n}\n```\n\n### Project Board with Groups\n\n```json\n{\n  \"nodes\": [\n    {\n      \"id\": \"5e6f7a8b9c0d1e2f\",\n      \"type\": \"group\",\n      \"x\": 0,\n      \"y\": 0,\n      \"width\": 300,\n      \"height\": 500,\n      \"label\": \"To Do\",\n      \"color\": \"1\"\n    },\n    {\n      \"id\": \"6f7a8b9c0d1e2f3a\",\n      \"type\": \"group\",\n      \"x\": 350,\n      \"y\": 0,\n      \"width\": 300,\n      \"height\": 500,\n      \"label\": \"In Progress\",\n      \"color\": \"3\"\n    },\n    {\n      \"id\": \"7a8b9c0d1e2f3a4b\",\n      \"type\": \"group\",\n      \"x\": 700,\n      \"y\": 0,\n      \"width\": 300,\n      \"height\": 500,\n      \"label\": \"Done\",\n      \"color\": \"4\"\n    },\n    {\n      \"id\": \"8b9c0d1e2f3a4b5c\",\n      \"type\": \"text\",\n      \"x\": 20,\n      \"y\": 50,\n      \"width\": 260,\n      \"height\": 80,\n      \"text\": \"## Task 1\\n\\nImplement feature X\"\n    },\n    {\n      \"id\": \"9c0d1e2f3a4b5c6d\",\n      \"type\": \"text\",\n      \"x\": 370,\n      \"y\": 50,\n      \"width\": 260,\n      \"height\": 80,\n      \"text\": \"## Task 2\\n\\nReview PR #123\",\n      \"color\": \"2\"\n    },\n    {\n      \"id\": \"0d1e2f3a4b5c6d7e\",\n      \"type\": \"text\",\n      \"x\": 720,\n      \"y\": 50,\n      \"width\": 260,\n      \"height\": 80,\n      \"text\": \"## Task 3\\n\\n~~Setup CI/CD~~\"\n    }\n  ],\n  \"edges\": []\n}\n```\n\n### Research Canvas with Files and Links\n\n```json\n{\n  \"nodes\": [\n    {\n      \"id\": \"1e2f3a4b5c6d7e8f\",\n      \"type\": \"text\",\n      \"x\": 300,\n      \"y\": 200,\n      \"width\": 400,\n      \"height\": 200,\n      \"text\": \"# Research Topic\\n\\n## Key Questions\\n\\n- How does X affect Y?\\n- What are the implications?\",\n      \"color\": \"5\"\n    },\n    {\n      \"id\": \"2f3a4b5c6d7e8f9a\",\n      \"type\": \"file\",\n      \"x\": 0,\n      \"y\": 0,\n      \"width\": 250,\n      \"height\": 150,\n      \"file\": \"Literature/Paper A.pdf\"\n    },\n    {\n      \"id\": \"3a4b5c6d7e8f9a0b\",\n      \"type\": \"file\",\n      \"x\": 0,\n      \"y\": 200,\n      \"width\": 250,\n      \"height\": 150,\n      \"file\": \"Notes/Meeting Notes.md\",\n      \"subpath\": \"#Key Insights\"\n    },\n    {\n      \"id\": \"4b5c6d7e8f9a0b1c\",\n      \"type\": \"link\",\n      \"x\": 0,\n      \"y\": 400,\n      \"width\": 250,\n      \"height\": 100,\n      \"url\": \"https://example.com/research\"\n    },\n    {\n      \"id\": \"5c6d7e8f9a0b1c2d\",\n      \"type\": \"file\",\n      \"x\": 750,\n      \"y\": 150,\n      \"width\": 300,\n      \"height\": 250,\n      \"file\": \"Attachments/diagram.png\"\n    }\n  ],\n  \"edges\": [\n    {\n      \"id\": \"6d7e8f9a0b1c2d3e\",\n      \"fromNode\": \"2f3a4b5c6d7e8f9a\",\n      \"fromSide\": \"right\",\n      \"toNode\": \"1e2f3a4b5c6d7e8f\",\n      \"toSide\": \"left\",\n      \"label\": \"supports\"\n    },\n    {\n      \"id\": \"7e8f9a0b1c2d3e4f\",\n      \"fromNode\": \"3a4b5c6d7e8f9a0b\",\n      \"fromSide\": \"right\",\n      \"toNode\": \"1e2f3a4b5c6d7e8f\",\n      \"toSide\": \"left\",\n      \"label\": \"informs\"\n    },\n    {\n      \"id\": \"8f9a0b1c2d3e4f5a\",\n      \"fromNode\": \"4b5c6d7e8f9a0b1c\",\n      \"fromSide\": \"right\",\n      \"toNode\": \"1e2f3a4b5c6d7e8f\",\n      \"toSide\": \"left\",\n      \"toEnd\": \"arrow\",\n      \"color\": \"6\"\n    },\n    {\n      \"id\": \"9a0b1c2d3e4f5a6b\",\n      \"fromNode\": \"1e2f3a4b5c6d7e8f\",\n      \"fromSide\": \"right\",\n      \"toNode\": \"5c6d7e8f9a0b1c2d\",\n      \"toSide\": \"left\",\n      \"label\": \"visualized by\"\n    }\n  ]\n}\n```\n\n### Flowchart\n\n```json\n{\n  \"nodes\": [\n    {\n      \"id\": \"a0b1c2d3e4f5a6b7\",\n      \"type\": \"text\",\n      \"x\": 200,\n      \"y\": 0,\n      \"width\": 150,\n      \"height\": 60,\n      \"text\": \"**Start**\",\n      \"color\": \"4\"\n    },\n    {\n      \"id\": \"b1c2d3e4f5a6b7c8\",\n      \"type\": \"text\",\n      \"x\": 200,\n      \"y\": 100,\n      \"width\": 150,\n      \"height\": 60,\n      \"text\": \"Step 1:\\nGather data\"\n    },\n    {\n      \"id\": \"c2d3e4f5a6b7c8d9\",\n      \"type\": \"text\",\n      \"x\": 200,\n      \"y\": 200,\n      \"width\": 150,\n      \"height\": 80,\n      \"text\": \"**Decision**\\n\\nIs data valid?\",\n      \"color\": \"3\"\n    },\n    {\n      \"id\": \"d3e4f5a6b7c8d9e0\",\n      \"type\": \"text\",\n      \"x\": 400,\n      \"y\": 200,\n      \"width\": 150,\n      \"height\": 60,\n      \"text\": \"Process data\"\n    },\n    {\n      \"id\": \"e4f5a6b7c8d9e0f1\",\n      \"type\": \"text\",\n      \"x\": 0,\n      \"y\": 200,\n      \"width\": 150,\n      \"height\": 60,\n      \"text\": \"Request new data\",\n      \"color\": \"1\"\n    },\n    {\n      \"id\": \"f5a6b7c8d9e0f1a2\",\n      \"type\": \"text\",\n      \"x\": 400,\n      \"y\": 320,\n      \"width\": 150,\n      \"height\": 60,\n      \"text\": \"**End**\",\n      \"color\": \"4\"\n    }\n  ],\n  \"edges\": [\n    {\n      \"id\": \"a6b7c8d9e0f1a2b3\",\n      \"fromNode\": \"a0b1c2d3e4f5a6b7\",\n      \"fromSide\": \"bottom\",\n      \"toNode\": \"b1c2d3e4f5a6b7c8\",\n      \"toSide\": \"top\"\n    },\n    {\n      \"id\": \"b7c8d9e0f1a2b3c4\",\n      \"fromNode\": \"b1c2d3e4f5a6b7c8\",\n      \"fromSide\": \"bottom\",\n      \"toNode\": \"c2d3e4f5a6b7c8d9\",\n      \"toSide\": \"top\"\n    },\n    {\n      \"id\": \"c8d9e0f1a2b3c4d5\",\n      \"fromNode\": \"c2d3e4f5a6b7c8d9\",\n      \"fromSide\": \"right\",\n      \"toNode\": \"d3e4f5a6b7c8d9e0\",\n      \"toSide\": \"left\",\n      \"label\": \"Yes\",\n      \"color\": \"4\"\n    },\n    {\n      \"id\": \"d9e0f1a2b3c4d5e6\",\n      \"fromNode\": \"c2d3e4f5a6b7c8d9\",\n      \"fromSide\": \"left\",\n      \"toNode\": \"e4f5a6b7c8d9e0f1\",\n      \"toSide\": \"right\",\n      \"label\": \"No\",\n      \"color\": \"1\"\n    },\n    {\n      \"id\": \"e0f1a2b3c4d5e6f7\",\n      \"fromNode\": \"e4f5a6b7c8d9e0f1\",\n      \"fromSide\": \"top\",\n      \"fromEnd\": \"none\",\n      \"toNode\": \"b1c2d3e4f5a6b7c8\",\n      \"toSide\": \"left\",\n      \"toEnd\": \"arrow\"\n    },\n    {\n      \"id\": \"f1a2b3c4d5e6f7a8\",\n      \"fromNode\": \"d3e4f5a6b7c8d9e0\",\n      \"fromSide\": \"bottom\",\n      \"toNode\": \"f5a6b7c8d9e0f1a2\",\n      \"toSide\": \"top\"\n    }\n  ]\n}\n```\n\n## ID Generation\n\nNode and edge IDs must be unique strings. Obsidian generates 16-character hexadecimal IDs:\n\n```json\n\"id\": \"6f0ad84f44ce9c17\"\n\"id\": \"a3b2c1d0e9f8g7h6\"\n\"id\": \"1234567890abcdef\"\n```\n\nThis format is a 16-character lowercase hex string (64-bit random value).\n\n## Layout Guidelines\n\n### Positioning\n\n- Coordinates can be negative (canvas extends infinitely)\n- `x` increases to the right\n- `y` increases downward\n- Position refers to top-left corner of node\n\n### Recommended Sizes\n\n| Node Type | Suggested Width | Suggested Height |\n|-----------|-----------------|------------------|\n| Small text | 200-300 | 80-150 |\n| Medium text | 300-450 | 150-300 |\n| Large text | 400-600 | 300-500 |\n| File preview | 300-500 | 200-400 |\n| Link preview | 250-400 | 100-200 |\n| Group | Varies | Varies |\n\n### Spacing\n\n- Leave 20-50px padding inside groups\n- Space nodes 50-100px apart for readability\n- Align nodes to grid (multiples of 10 or 20) for cleaner layouts\n\n## Validation Rules\n\n1. All `id` values must be unique across nodes and edges\n2. `fromNode` and `toNode` must reference existing node IDs\n3. Required fields must be present for each node type\n4. `type` must be one of: `text`, `file`, `link`, `group`\n5. `backgroundStyle` must be one of: `cover`, `ratio`, `repeat`\n6. `fromSide`, `toSide` must be one of: `top`, `right`, `bottom`, `left`\n7. `fromEnd`, `toEnd` must be one of: `none`, `arrow`\n8. Color presets must be `\"1\"` through `\"6\"` or valid hex color\n\n## References\n\n- [JSON Canvas Spec 1.0](https://jsoncanvas.org/spec/1.0/)\n- [JSON Canvas GitHub](https://github.com/obsidianmd/jsoncanvas)\n"},"lastSynced":"2026-03-08T02:02:59.279Z","agentAnalysis":{"suitability":{"en":"Perfect for Knowledge Management Agents needing to create and edit infinite canvas data in JSON format.","zh":"非常适合需要创建和编辑无限画布数据的JSON格式的知识管理代理。","ja":"無限キャンバスデータをJSON形式で作成および編集する必要があるナレッジマネジメントエージェントに最適です。","ko":"无한 대시보드 데이터를 JSON 형식으로 생성 및 편집해야 하는 지식 관리 에이전트에 적합합니다.","es":"Perfecto para agentes de gestión de conocimientos que necesitan crear y editar datos de lienzo infinito en formato JSON.","fr":"Idéal pour les agents de gestion des connaissances nécessitant la création et l''édition de données de canevas infini au format JSON.","de":"Perfekt für Wissensmanagement-Agenten, die infinite Canvas-Daten im JSON-Format erstellen und bearbeiten müssen.","pt":"Perfeito para Agentes de Gerenciamento de Conhecimento que precisam criar e editar dados de canvas infinito no formato JSON.","ru":"Идеально подходит для агентов управления знаниями, которым необходимо создавать и редактировать данные бесконечного холста в формате JSON.","ar":"مثالي للوكلاء إدارة المعرفة الذين يحتاجون إلى إنشاء وتحرير بيانات Canvas اللانهاية بتنسيق JSON."},"recommendation":{"en":"Empowers agents to generate and manipulate valid JSON Canvas files, following the JSON Canvas Spec 1.0, enabling seamless integration with Obsidian and other compatible applications through the use of .canvas files and JSON data structures.","zh":"赋予代理生成和操纵有效的JSON画布文件的能力，遵循JSON画布规范1.0，实现与Obsidian和其他兼容应用程序的无缝集成，通过使用.canvas文件和JSON数据结构。","ja":"エージェントに、JSON Canvas Spec 1.0に従った有効なJSONキャンバスファイルを生成および操作する能力を付与し、.canvasファイルおよびJSONデータ構造を使用してObsidianおよびその他の互換性のあるアプリケーションとのシームレスな統合を実現します。","ko":"에이전트가 JSON Canvas Spec 1.0을 따르는有效한 JSON 캔버스 파일을 생성하고 조작할 수 있는 능력을 부여하여, .canvas 파일과 JSON 데이터 구조를 사용하여 Obsidian 및 다른 호환 가능한 응용 프로그램과 원활하게 통합할 수 있습니다.","es":"Habilita a los agentes a generar y manipular archivos de lienzo JSON válidos, siguiendo la especificación JSON Canvas 1.0, lo que permite una integración sin problemas con Obsidian y otras aplicaciones compatibles a través del uso de archivos .canvas y estructuras de datos JSON.","fr":"Permet aux agents de générer et de manipuler des fichiers de canevas JSON valides, en suivant la spécification JSON Canvas 1.0, ce qui permet une intégration transparente avec Obsidian et d''autres applications compatibles grâce à l''utilisation de fichiers .canvas et de structures de données JSON.","de":"Ermöglicht es Agenten, gültige JSON-Canvas-Dateien zu generieren und zu manipulieren, indem sie der JSON-Canvas-Spezifikation 1.0 folgen, was eine nahtlose Integration mit Obsidian und anderen kompatiblen Anwendungen durch die Verwendung von .canvas-Dateien und JSON-Datentruktuen ermöglicht.","pt":"Habilita os agentes a gerar e manipular arquivos de Canvas JSON válidos, seguindo a Especificação do Canvas JSON 1.0, permitindo uma integração perfeita com o Obsidian e outros aplicativos compatíveis por meio do uso de arquivos .canvas e estruturas de dados JSON.","ru":"Позволяет агентам создавать и манипулировать действительными файлами JSON Canvas, следуя Спецификации JSON Canvas 1.0, обеспечивая бесшовную интеграцию с Obsidian и другими совместимыми приложениями посредством использования файлов .canvas и структур данных JSON.","ar":"تمكّن الوكلاء من إنشاء وتحريك ملفات JSON Canvas الصالحة، اتباعًا لمواصفات JSON Canvas 1.0، مما يُمكن من التكامل السلس مع تطبيق Obsidian وتطبيقات أخرى متوافقة من خلال استخدام ملفات .canvas وهياكل البيانات JSON."},"useCases":{"en":["Creating custom knowledge graphs with nodes and edges","Editing existing JSON Canvas files for data visualization","Generating new canvas files for infinite canvas data storage"],"zh":["使用节点和边创建自定义知识图","编辑现有的JSON画布文件以进行数据可视化","生成新的画布文件以存储无限画布数据"],"ja":["ノードとエッジを使用してカスタムのナレッジグラフを作成する","既存のJSONキャンバスファイルを編集してデータの視覚化を行う","無限キャンバスデータの保存のために新しいキャンバスファイルを生成する"],"ko":["노드와 에지로 사용자 지정 지식 그래프를 생성하는 것","기존 JSON 캔버스 파일을 편집하여 데이터 시각화를 수행하는 것","무한 캔버스 데이터를 저장하기 위한 새로운 캔버스 파일을 생성하는 것"],"es":["Creación de gráficos de conocimiento personalizados con nodos y bordes","Edición de archivos JSON Canvas existentes para la visualización de datos","Generación de nuevos archivos de lienzo para el almacenamiento de datos de lienzo infinito"],"fr":["Création de graphiques de connaissances personnalisés avec des nœuds et des arêtes","Édition de fichiers JSON Canvas existants pour la visualisation de données","Génération de nouveaux fichiers de canevas pour le stockage de données de canevas infini"],"de":["Erstellung von benutzerdefinierten Wissensgraphen mit Knoten und Kanten","Bearbeitung von vorhandenen JSON-Canvas-Dateien für die Datenvisualisierung","Erzeugung neuer Canvas-Dateien für die Speicherung von infiniten Canvas-Daten"],"pt":["Criar gráficos de conhecimento personalizados com nodos e arestas","Editar arquivos JSON Canvas existentes para visualização de dados","Gerar novos arquivos de canvas para armazenamento de dados de canvas infinito"],"ru":["Создание пользовательских графов знаний с узлами и ребрами","Редактирование существующих файлов JSON Canvas для визуализации данных","Генерация новых файлов холста для хранения данных бесконечного холста"],"ar":["إنشاء رسوم معرفية مخصصة مع العقد والزوايا","تحرير ملفات JSON Canvas الحالية لتصور البيانات","إنشاء ملفات新的 من Canvas لتخزين بيانات Canvas اللانهاية"]},"limitations":{"en":["Requires compatibility with JSON Canvas Spec 1.0","Limited to applications supporting .canvas files"],"zh":["需要兼容JSON画布规范1.0","仅限于支持.canvas文件的应用程序"],"ja":["JSON Canvas Spec 1.0との互換性が必要",".canvasファイルをサポートするアプリケーションに限定される"],"ko":["JSON 캔버스 사양 1.0과 호환성이 필요함",".canvas 파일을 지원하는 응용 프로그램으로 제한됨"],"es":["Requiere compatibilidad con la especificación JSON Canvas 1.0","Limitado a aplicaciones que admiten archivos .canvas"],"fr":["Nécessite la compatibilité avec la spécification JSON Canvas 1.0","Limité aux applications prenant en charge les fichiers .canvas"],"de":["Erfordert Kompatibilität mit der JSON-Canvas-Spezifikation 1.0","Begrenzt auf Anwendungen, die .canvas-Dateien unterstützen"],"pt":["Exige compatibilidade com a Especificação do Canvas JSON 1.0","Limitado a aplicações que suportam arquivos .canvas"],"ru":["Требует совместимости со Спецификацией JSON Canvas 1.0","Ограничен приложениями, поддерживающими файлы .canvas"],"ar":["يتطلب التوافق مع مواصفات JSON Canvas 1.0","محدود للتطبيقات التي تدعم ملفات .canvas"]},"version":4},"contentHash":"174481b16ead9bfe7b417e59b14a952d72395fe04b31aa9e351d73d62f28fb90","qualityScore":36}');
