INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MrZhang123/ai-workspace/json-canvas', 'json-canvas', 'MrZhang123', 'ai-workspace', 'community', 'json-canvas MrZhang123 ai-workspace community The json-canvas skill enables AI agents to create and edit JSON Canvas files, used in Obsidian and other applications, following the JSON Canvas Spec 1.0. This skill benefits developers working with infinite canvas data. JSON Canvas 技术允许开发者创建和编辑无限画布数据，用于 Obsidian 等应用 JSON Canvas は、AIエージェントとの連携により、無限キャンバスデータを作成・編集できる技術です JSON Canvas는 Obsidian용 무한 캔버스 데이터 생성을 위한 기술로, AI 도구와의 상호작용을 지원합니다 Json-canvas permite a los agentes compatibles crear y editar archivos de canvas JSON válidos para Obsidian y otras aplicaciones. Json-canvas permet aux agents compatibles de créer et d''éditer des fichiers de canvas JSON valides pour Obsidian et d''autres applications. Json-canvas ermöglicht es kompatiblen Agents, gültige JSON-Canvas-Dateien für Obsidian und andere Anwendungen zu erstellen und zu bearbeiten. O JSON Canvas é um formato de arquivo aberto para dados de canvas infinito, permitindo a criação e edição de arquivos .canvas com arrays de nodes e edges. JSON Canvas — это открытый формат файла для данных бесконечного холста, позволяющий создавать и редактировать файлы .canvas с массивами узлов и ребер. JSON Canvas هو تنسيق ملف مفتوح للبيانات الشبكية غير المحدودة، مما يسمح بإنشاء وتحرير ملفات .canvas مع مصفوفات العقد والاقترانات what is json-canvas how to use json-canvas json-canvas setup guide json-canvas alternative json-canvas vs obsidian json-canvas install json-canvas file format json-canvas spec 1.0 infinite canvas data json canvas file creation JSON Canvas 无限画布数据 Obsidian AI工具 JSON 格式 nodes edges JSON Canvas Spec 1.0 Creates and edits valid JSON Canvas files (.canvas) following the JSON Canvas Spec 1.0 Contains two top-level arrays: nodes and edges Supports Obsidian and other applications using JSON Canvas files Enables skills-compatible agents to work with infinite canvas data Follows the JSON Canvas Spec 1.0 for file structure and content json-canvas is an AI agent skill that enables the creation and editing of valid JSON Canvas files, containing nodes and edges, used in applications like Obsidian.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('web-infra-dev/rspack/rspack-sftrace', 'community', 'web-infra-dev', 'rspack', 'web-infra-dev/rspack', 'rspack-sftrace', 0, 0, 36, '2026-03-08T01:57:15.323Z', '2026-03-08T02:02:59.280Z', '3d86205c8082a7879d0388747c81ff4faadfe365d96b14feaa03490809f508ca', '{"id":"web-infra-dev/rspack/rspack-sftrace","name":"rspack-sftrace","description":{"en":"rspack-sftrace is a technical skill that utilizes sftrace (LLVM XRay) to trace rspack''s Rust function calls for performance analysis and troubleshooting, benefiting developers working with the fast Rust-based JavaScript bundler.","zh":"rspack-sftrace 是一个用于性能分析和故障排除的工具，使用 LLVM XRay 进行 Rust 函数调用跟踪，并将其转换为 perfetto protobuf 格式","ja":"rspack-sftrace は、パフォーマンス分析とトラブルシューティングのために使用されるツールであり、LLVM XRay を使用して Rust 関数呼び出しをトレースし、perfetto protobuf 形式に変換します","ko":"rspack-sftrace는 성능 분석 및 문제 해결을 위해 사용되는 도구로 LLVM XRay를 사용하여 Rust 함수 호출을 추적하고 perfetto protobuf 형식으로 변환합니다","es":"Rspack-sftrace es una herramienta de rastreo de funciones de Rust que utiliza sftrace (LLVM XRay) para analizar el rendimiento de aplicaciones JavaScript","fr":"Rspack-sftrace est un outil de traçage de fonctions Rust qui utilise sftrace (LLVM XRay) pour analyser les performances des applications JavaScript","de":"Rspack-sftrace ist ein Rust-Funktionen-Verfolgungstool, das sftrace (LLVM XRay) verwendet, um die Leistung von JavaScript-Anwendungen zu analysieren","pt":"O Rspack-Sftrace é uma ferramenta de traçamento de desempenho para análise de chamadas de funções Rust no Rspack","ru":"Rspack-Sftrace - это инструмент для анализа производительности, предназначенный для отслеживания вызовов функций Rust в Rspack","ar":"Rspack-Sftrace هو أداة تحليل الأداء لتحليل مكالمات دالات Rust في Rspack"},"seo":{"title":{"en":"rspack-sftrace: Performance Analysis Setup Guide | AI Age...","zh":"rspack-sftrace 性能分析设置指南","ja":"rspack-sftrace パフォーマンス分析セットアップガイド","ko":"rspack-sftrace 성능 분석 설정 가이드","es":"Guía de configuración de rspack-sftrace para análisis de ...","fr":"Guide de configuration de rspack-sftrace pour l''analyse d...","de":"Einrichtungsleitfaden für rspack-sftrace zur Leistungsana...","pt":"Guia de Configuração do Rspack-Sftrace: Ferramenta de Tra...","ru":"Настройка Rspack-Sftrace: Инструмент для Анализа Производ...","ar":"دليل إعداد Rspack-Sftrace: أداة تحليل الأداء للوكلاء الذكيين"},"description":{"en":"Unlock the full potential of rspack with sftrace, a Rust-based tracing tool for performance analysis. Get started with our setup guide and optimize your Java...","zh":"了解如何使用 rspack-sftrace 进行性能分析和故障排除，包括构建 sftrace 工具和转换为 perfetto protobuf 格式","ja":"rspack-sftrace を使用したパフォーマンス分析とトラブルシューティングの方法を学びます。sftrace ツールのビルドと perfetto protobuf 形式への変換を含みます","ko":"rspack-sftrace를 사용하여 성능 분석 및 문제 해결을 수행하는 방법을 알아보세요. sftrace 도구 빌드 및 perfetto protobuf 형식으로의 변환 포함","es":"Aprende a utilizar rspack-sftrace para mejorar el rendimiento de tus aplicaciones JavaScript con esta herramienta de rastreo de funciones de Rust","fr":"Découvrez comment utiliser rspack-sftrace pour améliorer les performances de vos applications JavaScript avec cet outil de traçage de fonctions Rust","de":"Erfahren Sie, wie Sie rspack-sftrace verwenden, um die Leistung Ihrer JavaScript-Anwendungen mit diesem Rust-Funktionen-Verfolgungstool zu verbessern","pt":"Aprenda a configurar o Rspack-Sftrace para análise de desempenho e solução de problemas em aplicações JavaScript","ru":"Узнайте, как настроить Rspack-Sftrace для анализа производительности и устранения неполадок в приложениях JavaScript с помощью ИИ Агентов","ar":"تعلم كيفية إعداد Rspack-Sftrace لتحليل الأداء ومعالجة المشكلات في التطبيقات JavaScript باستخدام الوكلاء الذكيين"},"definition":{"en":"rspack-sftrace is a skill that leverages sftrace to convert Rust function calls to perfetto protobuf format for in-depth performance analysis and troubleshooting of the rspack JavaScript bundler.","zh":"rspack-sftrace 是一个 Rust-based 的 JavaScript 打包工具，使用 sftrace (LLVM XRay) 进行性能分析","ja":"rspack-sftrace は、sftrace (LLVM XRay) を使用してパフォーマンス分析を行う Rust ベースの JavaScript バンドラーです","ko":"rspack-sftrace는 sftrace(LLVM XRay)를 사용하여 성능 분석을 수행하는 Rust 기반의 JavaScript 번들러입니다","es":"Rspack-sftrace es una herramienta de análisis de rendimiento que utiliza sftrace para rastrear llamadas a funciones de Rust","fr":"Rspack-sftrace est un outil d''analyse de performance qui utilise sftrace pour traçer les appels de fonctions Rust","de":"Rspack-sftrace ist ein Leistungsanalyse-Tool, das sftrace verwendet, um Rust-Funktionenaufrufe zu verfolgen","pt":"O Rspack-Sftrace é uma ferramenta de traçamento de desempenho que utiliza o LLVM XRay para análise de chamadas de funções Rust","ru":"Rspack-Sftrace - это инструмент для анализа производительности, использующий LLVM XRay для отслеживания вызовов функций Rust","ar":"Rspack-Sftrace هو أداة تحليل الأداء التي تستخدم LLVM XRay لتحليل مكالمات دالات Rust"},"features":{"en":["Utilizes sftrace (LLVM XRay) for tracing Rust function calls","Converts trace data to perfetto protobuf format","Supports default workflow with example directory tracing","Stores trace artifacts in the target example directory","Built using Rust and compatible with webpack API"],"zh":["使用 LLVM XRay 进行 Rust 函数调用跟踪","转换为 perfetto protobuf 格式","支持构建 sftrace 工具","用于性能分析和故障排除","与 webpack 兼容的 API"],"ja":["LLVM XRay を使用して Rust 関数呼び出しをトレース","perfetto protobuf 形式に変換","sftrace ツールのビルドをサポート","パフォーマンス分析とトラブルシューティングに使用","webpack と互換性のある API"],"ko":["LLVM XRay를 사용하여 Rust 함수 호출을 추적","perfetto protobuf 형식으로 변환","sftrace 도구 빌드를 지원","성능 분석 및 문제 해결에 사용","webpack과 호환되는 API"],"es":["Rastreo de llamadas a funciones de Rust con sftrace (LLVM XRay)","Conversión de artefactos de rastreo a formato perfetto protobuf","Compatibilidad con la API de webpack","Análisis de rendimiento de aplicaciones JavaScript","Almacenamiento de artefactos de rastreo en el directorio de ejemplo objetivo"],"fr":["Traçage des appels de fonctions Rust avec sftrace (LLVM XRay)","Conversion des artefacts de traçage au format perfetto protobuf","Compatibilité avec l''API de webpack","Analyse des performances des applications JavaScript","Stockage des artefacts de traçage dans le répertoire d''exemple cible"],"de":["Verfolgung von Rust-Funktionenaufrufen mit sftrace (LLVM XRay)","Konvertierung von Verfolgungsartefakten in perfetto-Protobuf-Format","Kompatibilität mit der webpack-API","Leistungsanalyse von JavaScript-Anwendungen","Speicherung von Verfolgungsartefakten im Zielbeispieldirectory"],"pt":["Utiliza o LLVM XRay para traçamento de chamadas de funções Rust","Converte artefatos de traçamento para formato perfetto protobuf","Permite análise de desempenho e solução de problemas em aplicações JavaScript","Compatível com a API do Webpack","Suporta build de ferramentas sftrace com cargo"],"ru":["Использует LLVM XRay для отслеживания вызовов функций Rust","Преобразует артефакты трассировки в формат perfetto protobuf","Позволяет анализировать производительность и устранять неполадки в приложениях JavaScript","Совместим с API Webpack","Поддерживает сборку инструментов sftrace с cargo"],"ar":["يستخدم LLVM XRay لتحليل مكالمات دالات Rust","يحول الملفات المصدر لتحليل الأداء إلى تنسيق perfetto protobuf","يسمح بتحليل الأداء ومعالجة المشكلات في التطبيقات JavaScript","متوافق مع واجهة برمجة تطبيقات Webpack","يدعم بناء أدوات sftrace مع cargo"]},"keywords":{"en":["how to use rspack-sftrace","rspack-sftrace setup guide","rspack-sftrace vs webpack","what is rspack-sftrace","rspack-sftrace install","perfetto protobuf format","LLVM XRay tracing","Rust-based JavaScript bundler","rspack performance analysis"],"zh":["rspack-sftrace","性能分析","故障排除","Rust","JavaScript","LLVM XRay","perfetto","webpack","AIエージェント"],"ja":["rspack-sftrace","パフォーマンス分析","トラブルシューティング","Rust","JavaScript","LLVM XRay","perfetto","webpack","AIエージェント"],"ko":["rspack-sftrace","성능 분석","문제 해결","Rust","JavaScript","LLVM XRay","perfetto","webpack","AI 도구"],"es":["rspack-sftrace","análisis de rendimiento","rastreo de funciones de Rust","sftrace","LLVM XRay","perfetto protobuf","webpack","aplicaciones JavaScript","herramientas de desarrollo"],"fr":["rspack-sftrace","analyse de performance","traçage de fonctions Rust","sftrace","LLVM XRay","perfetto protobuf","webpack","applications JavaScript","outils de développement"],"de":["rspack-sftrace","Leistungsanalyse","Rust-Funktionen-Verfolgung","sftrace","LLVM XRay","perfetto Protobuf","webpack","JavaScript-Anwendungen","Entwicklungstools"],"pt":["Rspack-Sftrace","análise de desempenho","solução de problemas","JavaScript","Rust","LLVM XRay","perfetto protobuf","WEBPACK","cargo","ferramentas de desenvolvimento"],"ru":["Rspack-Sftrace","анализ производительности","устранение неполадок","JavaScript","Rust","LLVM XRay","perfetto protobuf","WEBPACK","cargo","инструменты разработки","ИИ Агенты"],"ar":["Rspack-Sftrace","تحليل الأداء","معالجة المشكلات","JavaScript","Rust","LLVM XRay","perfetto protobuf","WEBPACK","cargo","أدوات التطوير","الوكلاء الذكيين"]}},"owner":"web-infra-dev","repo":"rspack","repoPath":"web-infra-dev/rspack","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.323Z","topics":[],"category":"community","skillMd":{"name":"rspack-sftrace","description":"Use sftrace, which is based on LLVM Xray instrumentation, to trace all Rust function calls. This can be used for performance analysis and troubleshooting.","bodyPreview":"# Rspack Sftrace\n\n## Overview\n\nUse sftrace (LLVM XRay) to trace rspack''s Rust function calls and convert them to perfetto protobuf format for performance analysis and troubleshooting.\n\nDefault workflow: run inside the target example directory (for example `examples/react`) and store all trace artifacts in that directory (not `/tmp`).\n\n## Workflow\n\n### 1) Build sftrace tools\n\n```sh\ngit clone https://github.com/quininer/sftrace\ncd sftrace\ncargo build --release\nmkdir \"$(./target/release/sftrace rec","body":"# Rspack Sftrace\n\n## Overview\n\nUse sftrace (LLVM XRay) to trace rspack''s Rust function calls and convert them to perfetto protobuf format for performance analysis and troubleshooting.\n\nDefault workflow: run inside the target example directory (for example `examples/react`) and store all trace artifacts in that directory (not `/tmp`).\n\n## Workflow\n\n### 1) Build sftrace tools\n\n```sh\ngit clone https://github.com/quininer/sftrace\ncd sftrace\ncargo build --release\nmkdir \"$(./target/release/sftrace record --print-solib-install-dir)\"\ncp ./target/release/libsftrace.so \"$(./target/release/sftrace record --print-solib-install-dir)/\"\n```\n\n### 2) Build sftrace-enabled profiling binding (once per code change)\n\n```sh\nSFTRACE=1 pnpm build:binding:profiling\n```\n\n### 3) Optional: Generate a filter file from symbols\n\n`sftrace filter` works on function symbols from an object file (for rspack, the binding `.node` file).\n\n```sh\n# Enter the target example directory first\ncd examples/react\n\n# Prefer the locally built profiling binding from the monorepo\nBINDING_NODE=\"$(realpath ../../crates/node_binding/rspack.linux-x64-gnu.node)\"\n\n# Regex mode\nsftrace filter -p \"$BINDING_NODE\" -r ''finish_modules|FlagDependencyExportsPlugin'' -o sftrace.filter\n\n# List mode (one regex per line)\n# sftrace filter -p \"$BINDING_NODE\" --list symbols.list -o sftrace.filter\n```\n\nIf your binding file name differs by platform, replace the `.node` path accordingly.\n\n### 4) Record sftrace (example: build in `examples/react`)\n\nRun from the target example directory and keep outputs local to that example.\n\n```sh\ncd examples/react\n\nTRACE_DIR=\"sftrace-$(date +%Y%m%d-%H%M%S)\"\nmkdir -p \"$TRACE_DIR\"\n\n# Full trace\nsftrace record -o \"$TRACE_DIR/sf.log\" -- pnpm build\n\n# Filtered trace (requires sftrace.filter from step 3)\nsftrace record -f sftrace.filter -o \"$TRACE_DIR/sf.filtered.log\" -- pnpm build\n```\n\n### 5) Analyze sf.log\n\nConvert sftrace log to perfetto protobuf format.\n\n```sh\ncd examples/react\nTRACE_DIR=\"sftrace-YYYYMMDD-HHMMSS\" # replace with your run directory\nsftrace convert \"$TRACE_DIR/sf.filtered.log\" -o \"$TRACE_DIR/sf.filtered.pb.gz\"\n```\n\n### 6) Optional: Visualization using [viztracer](https://github.com/gaogaotiantian/viztracer)\n\n```sh\nvizviewer --use_external_processor \"$TRACE_DIR/sf.filtered.pb.gz\"\n```\n\nUse this only for visualization.\n\n## Filtering Notes\n\n- `sftrace filter` matches function symbols by regex/list. It is not a first-class crate-path/module-path filter.\n- Filtering does not automatically keep all descendants. If a child function symbol does not match your filter, it may disappear from the trace.\n- Cross-thread relationships (for example via rayon) are not reconstructed as a single uninterrupted call chain.\n- For complete call stacks, record without filter (or with a broad filter) and narrow down during analysis.\n"},"lastSynced":"2026-03-08T02:02:59.280Z","agentAnalysis":{"suitability":{"en":"Ideal for Performance Analysis Agents requiring advanced Rust function call tracing and perfetto protobuf format conversion.","zh":"适用于需要高级Rust函数调用跟踪和perfetto protobuf格式转换的性能分析代理。","ja":"パフォーマンス分析エージェントが高度なRust関数呼び出しトレースとperfetto protobuf形式の変換を必要とする場合に適しています。","ko":"고급 Rust 함수 호출 추적 및 perfetto protobuf 형식 변환이 필요한 성능 분석 에이전트에 적합합니다.","es":"Ideal para agentes de análisis de rendimiento que requieren un seguimiento avanzado de llamadas a funciones de Rust y conversión de formato perfetto protobuf.","fr":"Idéal pour les agents d''analyse de performances nécessitant un traçage avancé des appels de fonctions Rust et une conversion de format perfetto protobuf.","de":"Ideal für Leistungsanalyse-Agents, die ein erweitertes Rust-Funktionenaufruf-Verfolgen und eine perfetto-Protobuf-Formatkonvertierung erfordern.","pt":"Ideal para Agentes de Análise de Desempenho que exigem rastreamento de chamadas de função Rust avançado e conversão de formato perfetto protobuf.","ru":"Идеально для агентов анализа производительности, требующих продвинутого отслеживания вызовов функций Rust и преобразования формата perfetto protobuf.","ar":"مثالي لعميل تحليل الأداء الذي يتطلب تتبع متقدم لدعوات وظيفة Rust وتحويل تنسيق perfetto protobuf."},"recommendation":{"en":"Empowers agents to trace rspack''s Rust function calls using sftrace (LLVM XRay) and convert them to perfetto protobuf format for in-depth performance analysis and troubleshooting, leveraging LLVM XRay and cargo build tools.","zh":"赋予代理使用sftrace（LLVM XRay）跟踪rpack的Rust函数调用，并将其转换为perfetto protobuf格式，利用LLVM XRay和cargo构建工具进行深入的性能分析和故障排除。","ja":"エージェントにsftrace（LLVM XRay）を使用してrpackのRust関数呼び出しをトレースし、それをperfetto protobuf形式に変換して、LLVM XRayとcargoビルドツールを利用した詳細なパフォーマンス分析とトラブルシューティングを行う力を与えます。","ko":"에이전트에 sftrace（LLVM XRay）를 사용하여 rpack의 Rust 함수 호출을 추적하고 이를 perfetto protobuf 형식으로 변환하여 LLVM XRay와 cargo 빌드 도구를 활용한 자세한 성능 분석 및 문제 해결을 가능하게 합니다.","es":"Habilita a los agentes para realizar un seguimiento de las llamadas a funciones de Rust de rspack utilizando sftrace (LLVM XRay) y convertirlas al formato perfetto protobuf para un análisis y depuración de rendimiento en profundidad, aprovechando las herramientas LLVM XRay y cargo build.","fr":"Permet aux agents de traçer les appels de fonctions Rust de rspack en utilisant sftrace (LLVM XRay) et de les convertir au format perfetto protobuf pour une analyse et une dépannage de performances en profondeur, en exploitant les outils LLVM XRay et cargo build.","de":"Ermöglicht es Agents, rspacks Rust-Funktionenaufrufe mit sftrace (LLVM XRay) zu verfolgen und in das perfetto-Protobuf-Format zu konvertieren, um eine umfassende Leistungsanalyse und Fehlersuche durchzuführen, indem es die LLVM-XRay- und cargo-Build-Tools nutzt.","pt":"Habilita os agentes a rastrear chamadas de função Rust do rspack usando sftrace (LLVM XRay) e convertê-las para o formato perfetto protobuf para análise e solução de problemas de desempenho aprofundados, aproveitando as ferramentas LLVM XRay e cargo build.","ru":"Наделяет агентов возможностью отслеживать вызовы функций Rust в rspack с помощью sftrace (LLVM XRay) и преобразовывать их в формат perfetto protobuf для глубокого анализа производительности и устранения неполадок, используя инструменты LLVM XRay и cargo build.","ar":"يُمكِّن الوكيل من تتبع دعوات وظيفة Rust لrspack باستخدام sftrace (LLVM XRay) وتحويلها إلى تنسيق perfetto protobuf من أجل تحليل أداء متعمق وإصلاح الأعطال، مستفيداً من أدوات LLVM XRay وأدوات بناء cargo."},"useCases":{"en":["Tracing Rust function calls for performance bottlenecks","Converting trace artifacts to perfetto protobuf format for visualization","Debugging rspack issues with detailed function call analysis"],"zh":["用于性能瓶颈的Rust函数调用跟踪","将跟踪工件转换为perfetto protobuf格式以进行可视化","使用详细的函数调用分析调试rpack问题"],"ja":["パフォーマンスボトルネックのためのRust関数呼び出しトレース","トレースアーティファクトをperfetto protobuf形式に変換して可視化する","詳細な関数呼び出し分析を使用してrpackの問題をデバッグする"],"ko":["성능 병목 현상을 위한 Rust 함수 호출 추적","추적 아티팩트를 perfetto protobuf 형식으로 변환하여 시각화","詳細한 함수 호출 분석을 사용하여 rpack 문제를 디버깅"],"es":["Seguimiento de llamadas a funciones de Rust para identificar cuellos de botella de rendimiento","Conversión de artefactos de seguimiento al formato perfetto protobuf para visualización","Depuración de problemas de rspack con un análisis detallado de llamadas a funciones"],"fr":["Traçage des appels de fonctions Rust pour identifier les goulots d''étranglement de performances","Conversion d''artefacts de traçage au format perfetto protobuf pour visualisation","Dépannage des problèmes de rspack avec une analyse détaillée des appels de fonctions"],"de":["Verfolgung von Rust-Funktionenaufrufen zur Identifizierung von Leistungsengpässen","Konvertierung von Verfolgungsartefakten in das perfetto-Protobuf-Format für Visualisierung","Fehlersuche bei rspack-Problemen mit detaillierter Funktionsaufrufanalyse"],"pt":["Rastreamento de chamadas de função Rust para gargalos de desempenho","Conversão de artefatos de rastreamento para formato perfetto protobuf para visualização","Depuração de problemas do rspack com análise detalhada de chamadas de função"],"ru":["Отслеживание вызовов функций Rust для узких мест производительности","Преобразование артефактов отслеживания в формат perfetto protobuf для визуализации","Отладка проблем rspack с подробным анализом вызовов функций"],"ar":["تتبع دعوات وظيفة Rust من أجل عيوب الأداء","تحويل مخرجات التتبع إلى تنسيق perfetto protobuf للتصوير","تصحيح أعطال rspack مع تحليل مفصل لدعوات الوظيفة"]},"limitations":{"en":["Requires sftrace tools and cargo build environment","Limited to Rust-based JavaScript bundler rspack","Default workflow stores trace artifacts in target example directory"],"zh":["需要sftrace工具和cargo构建环境","仅限于基于Rust的JavaScript打包工具rpack","默认工作流将跟踪工件存储在目标示例目录中"],"ja":["sftraceツールとcargoビルド環境が必要","RustベースのJavaScriptバンドラrpackに限定される","デフォルトのワークフローではトレースアーティファクトをターゲット例ディレクトリに保存する"],"ko":["sftrace 도구 및 cargo 빌드 환경이 필요","Rust 기반의 JavaScript 번들러 rpack에만 제한","기본 작업 흐름은 추적 아티팩트를 대상 예제 디렉토리에 저장"],"es":["Requiere herramientas sftrace y entorno de construcción de cargo","Limitado a rspack, un empaquetador de JavaScript basado en Rust","El flujo de trabajo predeterminado almacena artefactos de seguimiento en el directorio de ejemplo de destino"],"fr":["Nécessite des outils sftrace et un environnement de construction cargo","Limité à rspack, un bundleur JavaScript basé sur Rust","Le flux de travail par défaut stocke les artefacts de traçage dans le répertoire d''exemple cible"],"de":["Erfordert sftrace-Tools und cargo-Build-Umgebung","Begrenzt auf rspack, einen auf Rust basierenden JavaScript-Bundler","Der Standard-Arbeitsablauf speichert Verfolgungsartefakte im Ziel-Beispiel-Verzeichnis"],"pt":["Exige ferramentas sftrace e ambiente de build cargo","Limitado a bundler JavaScript baseado em Rust rspack","Fluxo de trabalho padrão armazena artefatos de rastreamento no diretório de exemplo de destino"],"ru":["Требует инструментов sftrace и среды сборки cargo","Ограничен bundler JavaScript на основе Rust rspack","Стандартный рабочий процесс хранит артефакты отслеживания в целевом примере директории"],"ar":["يتطلب أدوات sftrace وبيئة بناء cargo","محدود بمجمّع JavaScript المبني على Rust rspack","الworkflow الافتراضي يخزن مخرجات التتبع في الدليل المستهدف للاستخدام"]},"version":4},"contentHash":"3d86205c8082a7879d0388747c81ff4faadfe365d96b14feaa03490809f508ca","qualityScore":36}');
