trace artifacts in the target example directory Built using Rust and compatible with webpack API rspack-sftrace is a skill that leverages sftrace to convert Rust function calls to perfetto protobuf format for in-depth performance analysis and troubleshooting of the rspack JavaScript bundler.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('usenotra/notra/autumn-add-payments', 'community', 'usenotra', 'notra', 'usenotra/notra', 'autumn-add-payments', 0, 0, 36, '2026-03-08T01:57:15.326Z', '2026-03-08T02:03:03.513Z', '343037643cb5ac60e074de749b64ea45dd3dd2edce8cfe4f8cf4ad772bb98bff', '{"id":"usenotra/notra/autumn-add-payments","name":"autumn-add-payments","description":{"en":"autumn-add-payments automates Stripe checkout, upgrades, downgrades, and cancellations for developers. It handles payment flows and provides a seamless experience.","zh":"Autumn Payments自动处理Stripe checkout、升级、降级和取消，提供简单的支付流程","ja":"Autumn PaymentsはStripeのチェックアウト、アップグレード、ダウングレード、キャンセルを自動化し、簡単な支払いプロセスを提供","ko":"Autumn Payments는 스트라이프 체크아웃, 업그레이드, 다운그레이드, 취소를 자동화하여 간단한 결제 프로세스를 제공","es":"Autumn-add-payments es una herramienta para automatizar pagos con Stripe, incluyendo checkout, actualizaciones y cancelaciones","fr":"Autumn-add-payments est un outil pour automatiser les paiements avec Stripe, y compris la vérification, les mises à jour et les annulations","de":"Autumn-add-payments ist ein Tool zur Automatisierung von Zahlungen mit Stripe, einschließlich Checkout, Upgrades und Stornierungen","pt":"O Autumn Add Payments é uma ferramenta que automatiza pagamentos com Stripe, incluindo checkout, upgrades e cancelamentos.","ru":"Autumn Add Payments - это инструмент, который автоматизирует оплаты с помощью Stripe, включая checkout, апгрейды и отмены.","ar":"秋يضاف المدفوعات هو أداة لتحقيق الدفع الآلي مع سترايب، بما في ذلك الدفع والترقية والإلغاء."},"seo":{"title":{"en":"autumn-add-payments: Automated Stripe Checkout Setup Guid...","zh":"Autumn Payments Setup Guide - AIエージェント支付解决方案","ja":"Autumn Payments Setup Guide - AIエージェントによるストライプ決済","ko":"Autumn Payments Setup Guide - AI 에이전트를 이용한 스트라이프 결제 자동화","es":"Guía de configuración de autumn-add-payments para pagos a...","fr":"Configurer autumn-add-payments pour des paiements automat...","de":"Einrichtungsanleitung für autumn-add-payments zur Automat...","pt":"Guia de Configuração do Autumn Add Payments","ru":"Настройка Autumn Add Payments: ИИ Агенты для Оплаты","ar":"دليل إعداد秋يضاف المدفوعات - أدوات الذكاء الاصطناعي"},"description":{"en":"Streamline your payment process with autumn-add-payments. Learn how to automate Stripe checkout, upgrades, and cancellations - get started now!","zh":"使用Autumn Payments实现Stripe checkout、升级、降级和取消的自动化，简化您的支付流程","ja":"Autumn PaymentsでStripeのチェックアウト、アップグレード、ダウングレード、キャンセルを自動化し、支払いプロセスを簡素化","ko":"Autumn Payments로 스트라이프 체크아웃, 업그레이드, 다운그레이드, 취소를 자동화하여 결제 프로세스를 간소화","es":"Aprende a integrar autumn-add-payments para gestionar pagos con Stripe y automatizar el flujo de pago","fr":"Découvrez comment intégrer autumn-add-payments pour gérer les paiements avec Stripe et automatiser le flux de paiement","de":"Erfahren Sie, wie Sie autumn-add-payments integrieren, um Zahlungen mit Stripe zu verwalten und den Zahlungsfluss zu automatisieren","pt":"Aprenda a configurar o Autumn Add Payments para automatizar pagamentos com Stripe e melhorar a experiência do usuário","ru":"Узнайте, как настроить Autumn Add Payments для автоматизации оплат с помощью Stripe и улучшения пользовательского опыта","ar":"تعلم كيفية إعداد秋يضاف المدفوعات لتحسين تجربة المستخدم وتحقيق الدفع الآلي مع سترايب"},"definition":{"en":"autumn-add-payments is a skill that automates Stripe payment processes, including checkout, upgrades, and cancellations, using APIs and Stripe URLs.","zh":"Autumn Payments是一种AIエージェント支付解决方案，自动处理Stripe支付流程","ja":"Autumn PaymentsはAIエージェントによるストライプ決済自動化ソリューション","ko":"Autumn Payments는 AI 에이전트를 이용한 스트라이프 결제 자동화 솔루션","es":"Autumn-add-payments es una herramienta de pago que automatiza el flujo de pago con Stripe","fr":"Autumn-add-payments est un outil de paiement qui automatise le flux de paiement avec Stripe","de":"Autumn-add-payments ist ein Zahlungstool, das den Zahlungsfluss mit Stripe auto