INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('usenotra/notra/autumn-add-payments', 'autumn-add-payments', 'usenotra', 'notra', 'community', 'autumn-add-payments usenotra notra community autumn-add-payments automates Stripe checkout, upgrades, downgrades, and cancellations for developers. It handles payment flows and provides a seamless experience. Autumn Payments自动处理Stripe checkout、升级、降级和取消，提供简单的支付流程 Autumn PaymentsはStripeのチェックアウト、アップグレード、ダウングレード、キャンセルを自動化し、簡単な支払いプロセスを提供 Autumn Payments는 스트라이프 체크아웃, 업그레이드, 다운그레이드, 취소를 자동화하여 간단한 결제 프로세스를 제공 Autumn-add-payments es una herramienta para automatizar pagos con Stripe, incluyendo checkout, actualizaciones y cancelaciones Autumn-add-payments est un outil pour automatiser les paiements avec Stripe, y compris la vérification, les mises à jour et les annulations Autumn-add-payments ist ein Tool zur Automatisierung von Zahlungen mit Stripe, einschließlich Checkout, Upgrades und Stornierungen O Autumn Add Payments é uma ferramenta que automatiza pagamentos com Stripe, incluindo checkout, upgrades e cancelamentos. Autumn Add Payments - это инструмент, который автоматизирует оплаты с помощью Stripe, включая checkout, апгрейды и отмены. 秋يضاف المدفوعات هو أداة لتحقيق الدفع الآلي مع سترايب، بما في ذلك الدفع والترقية والإلغاء. how to use autumn-add-payments autumn-add-payments setup guide autumn-add-payments alternative autumn-add-payments vs Stripe autumn-add-payments install what is autumn-add-payments autumn-add-payments API documentation autumn-add-payments Stripe integration Autumn Payments AIエージェント支付 Stripe checkout 支付流程自动化 升级、降级和取消 card already on file attach功能 Automates Stripe checkout and returns Stripe URL or preview data Confirms purchases with `attach` command when card is already on file Handles payment flow with `checkout` and `attach` commands Provides Stripe checkout URL or preview data for new and returning customers Supports upgrades, downgrades, and cancellations automatically autumn-add-payments is a skill that automates Stripe payment processes, including checkout, upgrades, and cancellations, using APIs and Stripe URLs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('first-fluke/fullstack-starter/paid-ads', 'community', 'first-fluke', 'fullstack-starter', 'first-fluke/fullstack-starter', 'paid-ads', 0, 0, 36, '2026-03-08T01:57:15.327Z', '2026-03-08T02:03:05.708Z', '29d1f50e17b59b04556191bf82a77e51f72ce34d3034525f017d4835109ed35a', '{"id":"first-fluke/fullstack-starter/paid-ads","name":"paid-ads","description":{"en":"Paid-ads is a production-ready fullstack monorepo template for creating and optimizing paid advertising campaigns. It benefits performance marketers and developers working with Next.js, FastAPI, Flutter, and Terraform.","zh":"paid-ads 是一个生产就绪的全栈模板，包含 Next.js、FastAPI、Flutter、Terraform 和 mise。帮助您创建、优化和扩展付费广告活动。","ja":"paid-ads は、Next.js、FastAPI、Flutter、Terraform、mise を含むプロダクションレディフルスタックテンプレートです。有料広告キャンペーンの作成、最適化、拡張を支援します。","ko":"paid-ads는 Next.js, FastAPI, Flutter, Terraform 및 mise를 포함하는 프로덕션 준비 풀스택 템플릿입니다. 유료 광고 캠페인의 생성, 최적화 및 확장을 지원합니다.","es":"Plantilla de monorepo fullstack lista para producción con Next.js, FastAPI, Flutter, Terraform y mise para anuncios pagados","fr":"Modèle de monorepo fullstack prêt pour la production avec Next.js, FastAPI, Flutter, Terraform et mise pour annonces payantes","de":"Produktionsbereite Fullstack-Monorepo-Vorlage mit Next.js, FastAPI, Flutter, Terraform und mise für bezahlte Anzeigen","pt":"O modelo de anúncios pagos é um expert em marketing de desempenho com acesso direto às contas de plataformas de anúncios.","ru":"Платная реклама - это эксперт по маркетингу производительности с прямым доступом к учетным записям рекламных платформ.","ar":"الإعلانات المدفوعة هي خبير تسويق الأداء مع وصول مباشر إلى حسابات منصات الإعلان."},"seo":{"title":{"en":"Paid-Ads: Fullstack Monorepo Template Setup Guide | AI Ag...","zh":"paid-ads Setup Guide: Next.js 和 FastAPI 的生产就绪全栈模板","ja":"paid-ads セットアップガイド: Next.js と FastAPI のプロダクションレディフルスタックテン.