INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('first-fluke/fullstack-starter/paid-ads', 'paid-ads', 'first-fluke', 'fullstack-starter', 'community', 'paid-ads first-fluke fullstack-starter community Paid-ads is a production-ready fullstack monorepo template for creating and optimizing paid advertising campaigns. It benefits performance marketers and developers working with Next.js, FastAPI, Flutter, and Terraform. paid-ads 是一个生产就绪的全栈模板，包含 Next.js、FastAPI、Flutter、Terraform 和 mise。帮助您创建、优化和扩展付费广告活动。 paid-ads は、Next.js、FastAPI、Flutter、Terraform、mise を含むプロダクションレディフルスタックテンプレートです。有料広告キャンペーンの作成、最適化、拡張を支援します。 paid-ads는 Next.js, FastAPI, Flutter, Terraform 및 mise를 포함하는 프로덕션 준비 풀스택 템플릿입니다. 유료 광고 캠페인의 생성, 최적화 및 확장을 지원합니다. Plantilla de monorepo fullstack lista para producción con Next.js, FastAPI, Flutter, Terraform y mise para anuncios pagados Modèle de monorepo fullstack prêt pour la production avec Next.js, FastAPI, Flutter, Terraform et mise pour annonces payantes Produktionsbereite Fullstack-Monorepo-Vorlage mit Next.js, FastAPI, Flutter, Terraform und mise für bezahlte Anzeigen O modelo de anúncios pagos é um expert em marketing de desempenho com acesso direto às contas de plataformas de anúncios. Платная реклама - это эксперт по маркетингу производительности с прямым доступом к учетным записям рекламных платформ. الإعلانات المدفوعة هي خبير تسويق الأداء مع وصول مباشر إلى حسابات منصات الإعلان. how to use paid-ads paid-ads vs competitors paid-ads install guide what is paid-ads paid-ads setup tutorial paid-ads alternative solutions paid-ads and Next.js paid-ads and FastAPI paid-ads for customer acquisition paid-ads Next.js FastAPI Flutter Terraform mise 付费广告 全栈模板 生产就绪 Includes Next.js for server-side rendering and static site generation Utilizes FastAPI for building high-performance APIs Supports Flutter for cross-platform mobile app development Integrates Terraform for infrastructure as code management References mise for additional development tools and services Paid-ads is a fullstack monorepo template with Next.js, FastAPI, Flutter, Terraform, and mise for efficient customer acquisition through paid advertising campaigns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('camronh/EZVals/ship', 'community', 'camronh', 'EZVals', 'camronh/EZVals', 'ship', 0, 0, 36, '2026-03-08T01:57:15.328Z', '2026-03-08T02:03:08.149Z', '11c68aa150254e53d13d2475e7f8848d9616762b6d352f2d19c821620a6834a7', '{"id":"camronh/EZVals/ship","name":"ship","description":{"en":"The ship skill provides a simple yet powerful code-first eval framework for developers, facilitating streamlined testing and version management. It benefits developers working on the dev branch.","zh":"Ship是一个简单却强大的代码评估框架，通过代码评估确保代码质量","ja":"Shipは、シンプルながら強力なコード評価フレームワークで、コードの品質を保証します","ko":"Ship은 간단하지만 강력한 코드 평가 프레임워크로 코드 품질을 보장합니다","es":"Ship es un marco de evaluación de código simple pero potente para desarrolladores, que permite la ejecución de pruebas en paralelo y la actualización de registros de cambios","fr":"Ship est un cadre d''évaluation de code simple mais puissant pour les développeurs, qui permet l''exécution de tests en parallèle et la mise à jour des journaux des modifications","de":"Ship ist ein einfaches aber leistungsfähiges Code-Evaluierungsframework für Entwickler, das die Ausführung von Tests in Parallelverarbeitung und die Aktualisierung von Änderungsprotokollen ermöglicht","pt":"O Ship é um framework de avaliação de código simples mas poderoso, que permite aos desenvolvedores executar testes e gerenciar versões de forma eficiente","ru":"Ship - это простой но мощный фреймворк для оценки кода, который позволяет разработчикам запускать тесты и управлять версиями эффективно","ar":"Ship هو إطار تقييم رمز بسيط لكن قوي، يسمح للمطورين بتشغيل الاختبارات وإدارة الإصدارات بفعالية"},"seo":{"title":{"en":"ship: Code-First Eval Framework Setup Guide | AI Agent Skill","zh":"Ship代码评估框架设置指南","ja":"Shipコード評価フレームワークのベストプラクティス","ko":"Ship 코드 평가 프레임워크 설정 가이드","es":"Guía de configuración de ship: Marco de evaluación de código","fr":"Guide de mise en place de ship: Cadre d''évaluation de code","de":"Einrichtungsanleitung für ship: Code-Evaluierungsframework","pt":"Guia de Configuração do Ship: Framework de Avaliação de C...","ru":"Настройка Ship: Простой но Мощный Фреймворк для Оценки Код","ar":"دليل إعداد Ship: إطار تقييم رمز بسيط لكن قوي"},"description":{"en":"Discover how to leverage ship''s eval framework to streamline development. Learn to run tests in parallel with -n auto and manage version bumps efficiently.","zh":"Ship代码评估框架提供简单却强大的代码评估功能，确保您的代码质量","ja":"Shipコード評価フレームワークは、シンプルながら強力なコード評価機能を提供し、コードの品質を保証します","ko":"Ship 코드 평가 프레임워크는 간단하지만 강력한 코드 평가 기능을 제공하여 코드 품질을 보장합니다","es":"Aprende a utilizar ship, un potente marco de evaluación de código para desarrolladores, y descubre sus características clave","fr":"Découvrez comment utiliser ship, un puissant cadre d''évaluation de code pour les développeurs, et explorez ses fonctionnalités","de":"Erfahren Sie, wie Sie ship, ein leistungsfähiges Code-Evaluierungsframework für Entwickler, verwenden können und entdecken Sie seine wichtigsten Funktionen","pt":"Aprenda a configurar o Ship, um framework de avaliação de código simples mas poderoso, com passos práticos para desenvolvedores","ru":"Узнайте, как настроить Ship, простой но мощный фреймворк для оценки кода, с практическими шагами для разработчиков","ar":"تعرف على كيفية إعداد Ship، إطار تقييم رمز بسيط لكن قوي، مع خطوات عملية للمطورين"},"definition":{"en":"ship is a code-first eval framework that enables efficient testing and versioning through a series of commands and file updates, including changelog management.","zh":"Ship是代码评估框架，用于评估代码质量","ja":"Shipはコード評価フレームワークの一種で、コードの品質を評価します","ko":"Ship은 코드 평가 프레임워크의 일종으로 코드 품질을 평가합니다","es":"Ship es un marco de evaluación de código que permite a los desarrolladores ejecutar pruebas y actualizar registros de cambios de manera eficiente","fr":"Ship est un cadre d''évaluation de code qui permet aux développeurs d''exécuter des tests et de mettre à jour des journaux des modifications de manière efficace","de":"Ship ist ein Code-Evaluierungsframework, das es Entwicklern ermöglicht, Tests auszuführen und Änderungsprotokolle effizient zu aktualisieren","pt":"O Ship é um framework de avaliação de código que permite executar testes e gerenciar versões de forma automática","ru":"Ship - это фреймворк для оценки кода, который позволяет запускать тесты и управлять версиями автоматически","ar":"Ship هو إطار تقييم رمز يسمح بتشغيل الاختبارات وإدارة الإصدارات آليًا"},"features":{"en":["Runs tests in parallel using -n auto for efficient evaluation","Manages version bumps based on existing versions in the changelog","Updates docs/changelog.mdx to reflect new version releases","Verifies the current branch to ensure development on the dev branch","Supports stopping and reporting test failures for quality assurance","Automates changelog updates with the current date and version"],"zh":["支持代码评估","支持并行测试","支持版本升级","支持Changelog管理","支持多分支管理"],"ja":["コード評価をサポート","並列テストをサポート","バージョンアップをサポート","Changelog管理をサポート","多分支管理をサポート"],"ko":["코드 평가를 지원","병렬 테스트를 지원","버전 업그레이드를 지원","Changelog 관리를 지원","다중 분기 관리를 지원"],"es":["Ejecución de pruebas en paralelo con la opción -n auto","Actualización de registros de cambios en formato mdx","Verificación de la rama de desarrollo antes de ejecutar pruebas","Detención de la ejecución si las pruebas fallan","Sugerencia de la siguiente versión basada en el historial de versiones","Actualización del archivo de registro de cambios con la nueva versión"],"fr":["Exécution de tests en parallèle avec l''option -n auto","Mise à jour des journaux des modifications au format mdx","Vérification de la branche de développement avant d''exécuter des tests","Arrêt de l''exécution si les tests échouent","Suggestion de la prochaine version basée sur l''historique des versions","Mise à jour du fichier de journal des modifications avec la nouvelle version"],"de":["Ausführung von Tests in Parallelverarbeitung mit der Option -n auto","Aktualisierung von Änderungsprotokollen im mdx-Format","Überprüfung der Entwicklungsbranch vor der Ausführung von Tests","Beendigung der Ausführung, wenn die Tests fehlschlagen","Vorschlag der nächsten Version basierend auf der Versionshistorie","Aktualisierung der Änderungsprotokoll-Datei mit der neuen Version"],"pt":["Execução de testes em paralelo com -n auto","Gerenciamento de versões com base no changelog","Atualização automática do changelog","Verificação da branch de desenvolvimento","Execução de testes e relatório de falhas"],"ru":["Параллельный запуск тестов с -n auto","Управление версиями на основе changelog","Автоматическое обновление changelog","Проверка ветки разработки","Запуск тестов и отчет о ошибках"],"ar":["تشغيل الاختبارات بالتوازي مع -n auto","إدارة الإصدارات بالاعتماد على سجل التغييرات","تحديث تلقائي لسجل التغييرات","التحقق من فرع التطوير","تشغيل الاختبارات وتقرير الأخطاء"]},"keywords":{"en":["how to use ship","ship setup guide","ship alternative","ship vs eval frameworks","ship install","what is ship","ship for developers","ship eval framework","ship version management"],"zh":["Ship代码评估","代码评估框架","AI工具","代码质量","并行测试","版本升级","Changelog管理"],"ja":["Shipコード評価","コード評価フレームワーク","AIエージェント","コード品質","並列テスト","バージョンアップ","Changelog管理"],"ko":["Ship 코드 평가","코드 평가 프레임워크","AI 에이전트","코드 품질","병렬 테스트","버전 업그레이드","Changelog 관리"],"es":["ship marco de evaluación de código","pruebas en paralelo","actualización de registros de cambios","rama de desarrollo","tests automatizados","versiones de software","desarrollo de software","herramientas de desarrollo","frameworks de código"],"fr":["ship cadre d''évaluation de code","tests en parallèle","mise à jour des journaux des modifications","branche de développement","tests automatisés","versions de logiciel","développement de logiciel","outils de développement","frameworks de code"],"de":["ship Code-Evaluierungsframework","Tests in Parallelverarbeitung","Aktualisierung von Änderungsprotokollen","Entwicklungsbranch","automatisierte Tests","Software-Versionen","Software-Entwicklung","Entwicklungstools","Code-Frameworks"],"pt":["ship framework","avaliação de código","testes em paralelo","gerenciamento de versões","changelog","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Ship фреймворк","оценка кода","параллельный запуск тестов","управление версиями","changelog","разработка программного обеспечения","инструменты разработки"],"ar":["إطار Ship","تقييم الرمز","تشغيل الاختبارات بالتوازي","إدارة الإصدارات","سجل التغييرات","تطوير البرمجيات","أدوات التطوير"]}},"owner":"camronh","repo":"EZVals","repoPath":"camronh/EZVals","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.328Z","topics":[],"category":"community","skillMd":{"name":"ship","description":"Ship dev to main. Creates a release with version bump, changelog, and tag.","bodyPreview":"Follow these steps in order:\n\n## 1. Confirm on Dev\n\n- Verify we''re on the `dev` branch\n- If not, stop and ask\n\n## 2. Run Tests\n\n- Run tests and ensure all tests pass. (Use `-n auto` to run tests in parallel)\n- If tests fail, STOP and report the failures\n\n## 3. Version Bump\n\n- Read `docs/changelog.mdx` to see what''s in the `## Unreleased` section\n- Suggest the next version (based on existing versions in the changelog)\n- Update `docs/changelog.mdx`: change `## Unreleased` to `## <version> - <today","body":"Follow these steps in order:\n\n## 1. Confirm on Dev\n\n- Verify we''re on the `dev` branch\n- If not, stop and ask\n\n## 2. Run Tests\n\n- Run tests and ensure all tests pass. (Use `-n auto` to run tests in parallel)\n- If tests fail, STOP and report the failures\n\n## 3. Version Bump\n\n- Read `docs/changelog.mdx` to see what''s in the `## Unreleased` section\n- Suggest the next version (based on existing versions in the changelog)\n- Update `docs/changelog.mdx`: change `## Unreleased` to `## <version> - <today''s date>`\n- Update `pyproject.toml` version to match\n- Run `uv lock` to sync the lock file with the new version\n- Summarize the changes for this version in a human friendly way. Focus on impactful changes and user facing changes.\n\n## 4. Update Skill Version\n\n- Update the version comment in `ezvals/skills/evals/SKILL.md` (the `<!-- Version: X.X.X -->` line) to match the release version\n- The skill version **MUST** match the release tag — the Sync Skill to Marketplace workflow will fail otherwise\n\n## 5. Commit & Push Dev\n\n```bash\ngit add -A\ngit commit -m \"release <version>\"\ngit push origin dev\n```\n\n## 6. Merge to Main\n\n```bash\ngit checkout main\ngit pull origin main\ngit merge dev\ngit push origin main\n```\n\n## 7. Tag & Push\n\n```bash\ngit tag v<version>\ngit push origin v<version>\n```\n\n## 8. Return to Dev\n\n```bash\ngit checkout dev\n```\n\n## PyPI Publishing (Automatic)\n\nPublishing to PyPI is handled automatically by GitHub Actions:\n\n- **Dev builds** (`.github/workflows/publish-dev.yml`): Every push to `main` publishes a dev version (`0.0.0.dev{timestamp}`) to PyPI\n- **Release builds** (`.github/workflows/publish.yml`): Pushing a tag like `v0.1.0` triggers a release publish to PyPI\n\nYou don''t need to manually run `uv publish` - just push the tag and the workflow handles it.\n\n## Error Handling\n\n- If tests fail → stop and report\n- If merge conflicts occur → stop and ask for help\n- If not on dev → stop and ask\n"},"lastSynced":"2026-03-08T02:03:08.149Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing streamlined testing and version management on the dev branch","zh":"非常适合需要在开发分支上简化测试和版本管理的DevOps代理","ja":"DevOpsエージェントが開発ブランチでテストとバージョン管理をストリームライン化する必要がある場合に最適","ko":"개발 분기에서 테스트 및 버전 관리를 간소화해야 하는 DevOps 에이전트에 적합","es":"Perfecto para agentes de DevOps que necesitan pruebas y gestión de versiones optimizadas en la rama dev","fr":"Parfait pour les agents DevOps ayant besoin de tests et de gestion de versions rationalisés sur la branche dev","de":"Perfekt für DevOps-Agents, die optimierte Tests und Versionsverwaltung auf dem dev-Zweig benötigen","pt":"Perfeito para Agentes DevOps que precisam de testes e gerenciamento de versão simplificados na branch de desenvolvimento","ru":"Идеально подходит для агентов DevOps, которым необходим упрощенный тестирование и управление версиями на ветке разработки","ar":"مثالي لعمليات وكيل DevOps التي تحتاج إلى اختبارات ومدير إصدارات مبسط على الفرع التطويري"},"recommendation":{"en":"Empowers agents to automate testing workflows using parallel execution with `-n auto`, manage version bumps based on changelog updates, and maintain accurate release notes in `docs/changelog.mdx`","zh":"赋予代理自动化测试工作流的能力，使用并行执行 `-n auto`，根据更新的更改日志管理版本升级，并在 `docs/changelog.mdx` 中保持准确的发布说明","ja":"エージェントにテストワークフローを自動化する機能を付与し、並列実行 `-n auto` を使用し、更新された変更ログに基づいてバージョンのバンプを管理し、`docs/changelog.mdx` に正確なリリースノートを保持する","ko":"에이전트에 테스트 워크플로를 자동화하는 기능을 부여하고, 병렬 실행 `-n auto`를 사용하여, 업데이트된 변경 로그를 기준으로 버전을 관리하며, `docs/changelog.mdx`에 정확한 릴리스 노트를 유지","es":"Habilita a los agentes a automatizar flujos de trabajo de prueba utilizando ejecución paralela con `-n auto`, gestionar aumentos de versión basados en actualizaciones del registro de cambios y mantener notas de lanzamiento precisas en `docs/changelog.mdx`","fr":"Permet aux agents d''automatiser les flux de travail de test en utilisant l''exécution parallèle avec `-n auto`, de gérer les incréments de version basés sur les mises à jour du journal des modifications et de maintenir des notes de publication précises dans `docs/changelog.mdx`","de":"Ermöglicht es den Agents, Test-Workflows mit paralleler Ausführung mit `-n auto` zu automatisieren, Versions-Inkrementierungen basierend auf Aktualisierungen des Änderungsprotokolls zu verwalten und genaue Release-Notizen in `docs/changelog.mdx` zu pflegen","pt":"Habilita os agentes a automatizar fluxos de trabalho de teste usando execução paralela com `-n auto`, gerenciar aumentos de versão com base em atualizações do changelog e manter notas de lançamento precisas em `docs/changelog.mdx`","ru":"Наделяет агентов возможностью автоматизировать рабочие процессы тестирования с помощью параллельного выполнения с `-n auto`, управлять обновлениями версий на основе обновлений changelog и поддерживать точные заметки о выпуске в `docs/changelog.mdx`","ar":"يمنح الوكيل القدرة على توفير سير عمل الاختبار تلقائيا باستخدام التنفيذ المتوازي مع `-n auto`، وإدارة تحديثات الإصدار على أساس تحديثات سجل التغييرات، والحفاظ على ملاحظات الإصدار الدقيقة في `docs/changelog.mdx`"},"useCases":{"en":["Automating test suites on the dev branch","Generating version bumps based on changelog updates","Updating release notes in `docs/changelog.mdx`"],"zh":["在开发分支上自动化测试套件","根据更新的更改日志生成版本升级","在 `docs/changelog.mdx` 中更新发布说明"],"ja":["開発ブランチでテストスイートを自動化する","更新された変更ログに基づいてバージョンのバンプを生成する","`docs/changelog.mdx` にリリースノートを更新する"],"ko":["개발 분기에서 테스트 세트를 자동화","업데이트된 변경 로그를 기준으로 버전을 업그레이드","`docs/changelog.mdx`에 릴리스 노트를 업데이트"],"es":["Automatización de suites de pruebas en la rama dev","Generación de aumentos de versión basados en actualizaciones del registro de cambios","Actualización de notas de lanzamiento en `docs/changelog.mdx`"],"fr":["Automatisation des suites de tests sur la branche dev","Génération d''incréments de version basés sur les mises à jour du journal des modifications","Mise à jour des notes de publication dans `docs/changelog.mdx`"],"de":["Automatisierung von Test-Suiten auf dem dev-Zweig","Generierung von Versions-Inkrementierungen basierend auf Aktualisierungen des Änderungsprotokolls","Aktualisierung von Release-Notizen in `docs/changelog.mdx`"],"pt":["Automatizar conjuntos de testes na branch de desenvolvimento","Gerar aumentos de versão com base em atualizações do changelog","Atualizar notas de lançamento em `docs/changelog.mdx`"],"ru":["Автоматизировать наборы тестов на ветке разработки","Генерировать обновления версий на основе обновлений changelog","Обновлять заметки о выпуске в `docs/changelog.mdx`"],"ar":["توفير مجموعات الاختبار تلقائيا على الفرع التطويري","توليد تحديثات الإصدار على أساس تحديثات سجل التغييرات","تحديث ملاحظات الإصدار في `docs/changelog.mdx`"]},"limitations":{"en":["Requires presence on the `dev` branch","Dependent on successful test execution"],"zh":["需要在 `dev` 分支上存在","需要成功的测试执行"],"ja":["`dev` ブランチ上に存在する必要がある","成功したテスト実行に依存する"],"ko":["`dev` 분기에 존재해야 함","성공적인 테스트 실행에 의존"],"es":["Requiere presencia en la rama `dev`","Dependiente de la ejecución exitosa de pruebas"],"fr":["Nécessite une présence sur la branche `dev`","Dépendante de l''exécution réussie des tests"],"de":["Erfordert Anwesenheit auf dem `dev`-Zweig","Abhängig von der erfolgreichen Test-Ausführung"],"pt":["Exige presença na branch `dev`","Dependente da execução bem-sucedida de testes"],"ru":["Требует присутствия на ветке `dev`","Зависит от успешного выполнения тестов"],"ar":["يتطلب الحضور على الفرع `dev`","يعتمد على تنفيذ الاختبارات بنجاح"]},"version":4},"contentHash":"11c68aa150254e53d13d2475e7f8848d9616762b6d352f2d19c821620a6834a7","qualityScore":36}');
