INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('camronh/EZVals/ship', 'ship', 'camronh', 'EZVals', 'community', 'ship camronh EZVals community The ship skill provides a simple yet powerful code-first eval framework for developers, facilitating streamlined testing and version management. It benefits developers working on the dev branch. Ship是一个简单却强大的代码评估框架，通过代码评估确保代码质量 Shipは、シンプルながら強力なコード評価フレームワークで、コードの品質を保証します Ship은 간단하지만 강력한 코드 평가 프레임워크로 코드 품질을 보장합니다 Ship es un marco de evaluación de código simple pero potente para desarrolladores, que permite la ejecución de pruebas en paralelo y la actualización de registros de cambios Ship est un cadre d''évaluation de code simple mais puissant pour les développeurs, qui permet l''exécution de tests en parallèle et la mise à jour des journaux des modifications Ship ist ein einfaches aber leistungsfähiges Code-Evaluierungsframework für Entwickler, das die Ausführung von Tests in Parallelverarbeitung und die Aktualisierung von Änderungsprotokollen ermöglicht O Ship é um framework de avaliação de código simples mas poderoso, que permite aos desenvolvedores executar testes e gerenciar versões de forma eficiente Ship - это простой но мощный фреймворк для оценки кода, который позволяет разработчикам запускать тесты и управлять версиями эффективно Ship هو إطار تقييم رمز بسيط لكن قوي، يسمح للمطورين بتشغيل الاختبارات وإدارة الإصدارات بفعالية how to use ship ship setup guide ship alternative ship vs eval frameworks ship install what is ship ship for developers ship eval framework ship version management Ship代码评估 代码评估框架 AI工具 代码质量 并行测试 版本升级 Changelog管理 Runs tests in parallel using -n auto for efficient evaluation Manages version bumps based on existing versions in the changelog Updates docs/changelog.mdx to reflect new version releases Verifies the current branch to ensure development on the dev branch Supports stopping and reporting test failures for quality assurance Automates changelog updates with the current date and version ship is a code-first eval framework that enables efficient testing and versioning through a series of commands and file updates, including changelog management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jeninh/ampskills-dotfile/invoking-subagents', 'community', 'jeninh', 'ampskills-dotfile', 'jeninh/ampskills-dotfile', 'invoking-subagents', 0, 0, 36, '2026-03-08T01:57:15.330Z', '2026-03-08T02:03:11.190Z', 'c7b1f4ba8fdb376e73c1f55572be9cf64a0d5993ecb4491ee6d2fdf9a4d579b1', '{"id":"jeninh/ampskills-dotfile/invoking-subagents","name":"invoking-subagents","description":{"en":"The invoking-subagents skill allows developers to invoke subagents with specific prompts and flags, enabling precise control over tool interactions and repository access.","zh":"调用子代理需要使用synu claude命令，并设置精确的提示和限制，确保安全高效的AI工具调用。","ja":"サブエージェントの呼び出しには、synu claudeコマンドを使用し、正確なプロンプトと制限を設定する必要があります。","ko":"서브 에이전트 호출에는 synu claude 명령을 사용하고 정확한 프롬프트와 제한을 설정하는 것이 필요합니다.","es":"La invocación de subagentes permite a los desarrolladores ejecutar tareas en segundo plano con herramientas específicas","fr":"L''invocation de sous-agents permet aux développeurs d''exécuter des tâches en arrière-plan avec des outils spécifiques","de":"Die Invocation von Subagenten ermöglicht es Entwicklern, Aufgaben im Hintergrund mit spezifischen Tools auszuführen","pt":"O skill de invocação de subagentes permite executar comandos em segundo plano com segurança. Use o comando synu claude com flags para restringir as ferramentas","ru":"Навык вызова подагентов позволяет выполнять команды в фоновом режиме с безопасностью. Используйте команду synu claude с флагами, чтобы ограничить инструменты ИИ Агентов","ar":"مهارة استدعاء الوكلاء الفرعيين تسمح بتنفيذ أوامر في الخلفية بأمان. استخدم الأمر synu claude مع أعلام لتقيد الأدوات"},"seo":{"title":{"en":"Invoking-Subagents: Setup Guide for AI Agents","zh":"AI工具子代理调用设置指南","ja":"AIエージェントサブエージェントの呼び出しガイド","ko":"AI 에이전트 서브 에이전트 호출 설정 가이드","es":"Guía de configuración de invocación de subagentes","fr":"Guide d''invocation de sous-agents pour les développeurs","de":"Einrichtungsleitfaden für die Invocation von Subagenten","pt":"Invocação de Subagentes: Guia de Configuração","ru":"Вызов подагентов: Руководство по настройке ИИ Агентов","ar":"دعوة وكلاء فرعيين: إرشادات الإعداد"},"description":{"en":"Discover how to invoke subagents with precision, learn best practices for scoped repositories and restricted tool interactions, and get started with synu cla...","zh":"了解如何调用子代理，使用synu claude命令，设置精确的提示和限制，实现安全高效的AI工具调用","ja":"サブエージェントの呼び出し方を学び、synu claudeコマンドを使用して正確なプロンプトと制限を設定し、安全で効率的なAIエージェントの呼び出しを実現します","ko":"서브 에이전트 호출 방법을 배우고 synu claude 명령을 사용하여 정확한 프롬프트와 제한을 설정하여 안전하고 효율적인 AI 에이전트 호출을 구현합니다","es":"Aprende a invocar subagentes con synu claude y a restringir sus herramientas para mejorar la seguridad y la eficiencia","fr":"Découvrez comment invoquer des sous-agents avec synu claude et restreindre leurs outils pour améliorer la sécurité et l''efficacité","de":"Erfahren Sie, wie Sie Subagenten mit synu claude aufrufen und ihre Tools einschränken, um die Sicherheit und Effizienz zu verbessern","pt":"Aprenda a invocar subagentes com o comando synu claude e descubra como restringir ferramentas para melhorar a segurança","ru":"Узнайте, как вызвать подагентов с помощью команды synu claude и узнайте, как ограничить инструменты для повышения безопасности ИИ Агентов","ar":"تعرف على كيفية استدعاء الوكلاء الفرعيين بأمر synu claude واكتشف كيفية تقييد الأدوات لتحسين الأمان"},"definition":{"en":"Invoking-subagents is a skill that enables the invocation of subagents with restricted tool interactions, scoped to their current working directory.","zh":"子代理调用是AI工具中的一种技术，允许开发者在特定范围内调用子代理，实现更细粒度的控制和安全性。","ja":"サブエージェントの呼び出しは、AIエージェントの中で特定の範囲内でサブエージェントを呼び出す技術であり、より細かい制御とセキュリティを実現します。","ko":"서브 에이전트 호출은 AI 에이전트에서 특정 범위 내에서 서브 에이전트를 호출하는 기술로서 더 세부적인 제어와 보안을 구현합니다.","es":"La invocación de subagentes es una técnica que permite a los desarrolladores ejecutar tareas en segundo plano con herramientas restringidas","fr":"L''invocation de sous-agents est une technique qui permet aux développeurs d''exécuter des tâches en arrière-plan avec des outils restreints","de":"Die Invocation von Subagenten ist eine Technik, die es Entwicklern ermöglicht, Aufgaben im Hintergrund mit eingeschränkten Tools auszuführen","pt":"Invocação de subagentes é uma técnica que permite executar comandos em segundo plano com segurança","ru":"Вызов подагентов - это техника, которая позволяет выполнять команды в фоновом режиме с безопасностью ИИ Агентов","ar":"دعوة الوكلاء الفرعيين هي تقنية تسمح بتنفيذ أوامر في الخلفية بأمان"},"features":{"en":["Invoke subagents using the synu claude command with flags","Scoped to the current working directory (cwd) for repository-specific interactions","Supports restricted tool interactions, such as Glob, Grep, and Read","Allows execution of subagents in the background","Requires precise and thorough prompts for effective invocation","Enables aggressive restriction of tool interactions for improved security"],"zh":["使用synu claude命令调用子代理","设置精确的提示和限制","实现安全高效的AI工具调用","支持Glob、Grep、Read等工具","支持Task和Notebook等功能"],"ja":["synu claudeコマンドを使用してサブエージェントを呼び出す","正確なプロンプトと制限を設定する","安全で効率的なAIエージェントの呼び出しを実現する","Glob、Grep、Readなどのツールをサポートする","TaskとNotebookなどの機能をサポートする"],"ko":["synu claude 명령을 사용하여 서브 에이전트를 호출한다","정확한 프롬프트와 제한을 설정한다","안전하고 효율적인 AI 에이전트 호출을 구현한다","Glob, Grep, Read 등의 도구를 지원한다","Task와 Notebook 등의 기능을 지원한다"],"es":["Ejecución de tareas en segundo plano con synu claude","Restricción de herramientas para mejorar la seguridad","Uso de herramientas específicas como Glob, Grep y Read","Compatibilidad con ejecución en diferentes directorios","Soporte para ejecución en background con la bandera -p","Integración con herramientas de desarrollo como Edit y Notebook"],"fr":["Exécution de tâches en arrière-plan avec synu claude","Restriction des outils pour améliorer la sécurité","Utilisation d''outils spécifiques tels que Glob, Grep et Read","Compatibilité avec l''exécution dans différents répertoires","Prise en charge de l''exécution en arrière-plan avec la option -p","Intégration avec des outils de développement tels que Edit et Notebook"],"de":["Ausführung von Aufgaben im Hintergrund mit synu claude","Einschränkung von Tools zur Verbesserung der Sicherheit","Verwendung von spezifischen Tools wie Glob, Grep und Read","Kompatibilität mit der Ausführung in verschiedenen Verzeichnissen","Unterstützung für die Ausführung im Hintergrund mit der Option -p","Integration mit Entwicklungstools wie Edit und Notebook"],"pt":["Execução de comandos em segundo plano","Restrição de ferramentas com flags","Segurança melhorada com cwd","Uso de comandos como Glob, Grep e Read","Compatibilidade com repositórios diferentes"],"ru":["Выполнение команд в фоновом режиме","Ограничение инструментов с помощью флагов","Повышенная безопасность с cwd","Использование команд như Glob, Grep и Read","Совместимость с разными репозиториями ИИ Агентов"],"ar":["تنفيذ أوامر في الخلفية","تقيد الأدوات مع أعلام","أمان محسّن مع cwd","استخدام أوامر مثل Glob, Grep و Read","التوافق مع مستودعات مختلفة"]},"keywords":{"en":["how to use invoking-subagents","invoking-subagents setup guide","invoking-subagents alternative","invoking-subagents vs synu","what is invoking-subagents","invoking-subagents install","synu claude command","scoped repository interactions","restricted tool interactions"],"zh":["AI工具子代理调用","synu claude命令","AI工具调用设置","子代理安全性","AI开发者工具","Glob工具","Grep工具","Read工具","Task功能","Notebook功能"],"ja":["AIエージェントサブエージェントの呼び出し","synu claudeコマンド","AIエージェントの呼び出し設定","サブエージェントのセキュリティ","AI開発者ツール","Globツール","Grepツール","Readツール","Task機能","Notebook機能"],"ko":["AI 에이전트 서브 에이전트 호출","synu claude 명령","AI 에이전트 호출 설정","서브 에이전트 보안","AI 개발자 도구","Glob 도구","Grep 도구","Read 도구","Task 기능","Notebook 기능"],"es":["invocación de subagentes","synu claude","desarrollo de software","seguridad en el desarrollo","herramientas de desarrollo","ejecución en segundo plano","resticcion de herramientas","Agentes de IA","Herramientas de IA para desarrolladores"],"fr":["invocation de sous-agents","synu claude","développement de logiciels","sécurité dans le développement","outils de développement","exécution en arrière-plan","restriction des outils","Agents d''IA","Outils d''IA pour les développeurs"],"de":["Invocation von Subagenten","synu claude","Software-Entwicklung","Sicherheit in der Entwicklung","Entwicklungstools","Ausführung im Hintergrund","Einschränkung von Tools","Künstliche Intelligenz Agenten","KI-Tools für Entwickler"],"pt":["invocação de subagentes","synu claude","segurança em segundo plano","restrição de ferramentas","cwd","Glob","Grep","Read","repositórios diferentes"],"ru":["вызов подагентов","synu claude","безопасность в фоновом режиме","ограничение инструментов","cwd","Glob","Grep","Read","разные репозитории ИИ Агентов"],"ar":["دعوة وكلاء فرعيين","synu claude","أمان الخلفية","تقيد الأدوات","cwd","Glob","Grep","Read","مستودعات مختلفة"]}},"owner":"jeninh","repo":"ampskills-dotfile","repoPath":"jeninh/ampskills-dotfile","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.330Z","topics":[],"category":"community","skillMd":{"name":"invoking-subagents","description":"Spawns subagents with configurable tool access that return just the answers without flooding your context. Use for summarizing extensive git history, comparing across multiple repositories in parallel, or processing large diffs/logs.","bodyPreview":"Invoke with `synu claude --flags -p ''prompt''`.\n\n**Important:** Subagents are scoped to their cwd, just like you. To work in another repository, `cd` there first.\n\nUse a precise and thorough prompt. Aggressively restrict which tools it can interact with; if it doesn''t need Edit, don''t give it Edit. If it needs to read files, Glob, Grep, and Read are probably sufficient. Task can be helpful. Notebook, Slash, Write, Web, Edit, etc. should almost never be necessary. Execute them in the background. Y","body":"Invoke with `synu claude --flags -p ''prompt''`.\n\n**Important:** Subagents are scoped to their cwd, just like you. To work in another repository, `cd` there first.\n\nUse a precise and thorough prompt. Aggressively restrict which tools it can interact with; if it doesn''t need Edit, don''t give it Edit. If it needs to read files, Glob, Grep, and Read are probably sufficient. Task can be helpful. Notebook, Slash, Write, Web, Edit, etc. should almost never be necessary. Execute them in the background. You may invoke multiple when appropriate and in parallel if helpful. Once they''re running, you may either stop and wait for me to tell you they''re finished or continue with other work.\n\nExample exploring git history in another repo:\n\n```bash\ncd /path/to/other/repo && fish -c \"synu claude --disallowed-tools ''Bash(*) Explore Edit Read WebFetch WebSearch Glob Grep NotebookEdit NotebookRead SlashCommand Write'' --allowed-tools ''Bash(git log:*) Bash(git show:*)'' -p ''Using only git log and git show, summarise the major user-facing changes in HASH..HASH. Do not provide code snippets or technical details. Consider user-facing changes, like being able to set a port-out PIN or adding a new button or changing font sizes.''\"\n```\n\nRefer to [installing-synu.md](references/installing-synu.md) if it''s unavailable.\n"},"lastSynced":"2026-03-08T02:03:11.190Z","agentAnalysis":{"suitability":{"en":"Perfect for Advanced AI Agents needing precise control over subagent interactions and repository access","zh":"适用于需要对子代理交互和仓库访问进行精确控制的高级 AI 代理","ja":"サブエージェントの相互作用とリポジトリへのアクセスを正確に制御する必要がある高度な AI エージェントに最適","ko":"하위 에이전트 상호 작용 및 리포지토리 액세스를 정밀하게 제어해야 하는 고급 AI 에이전트에 적합","es":"Perfecto para Agentes de IA Avanzados que necesitan un control preciso sobre las interacciones de subagentes y el acceso al repositorio","fr":"Parfait pour les Agents de IA Avancés nécessitant un contrôle précis sur les interactions des sous-agents et l''accès au référentiel","de":"Perfekt für erweiterte KI-Agents, die eine präzise Kontrolle über Subagenten-Interaktionen und Repository-Zugriff benötigen","pt":"Perfeito para Agentes de IA Avançados que necessitam de controle preciso sobre interações de subagentes e acesso ao repositório","ru":"Идеально подходит для продвинутых агентов ИИ, которым требуется точный контроль над взаимодействием субагентов и доступом к репозиторию","ar":"مثالي للوكلاء الذكاء الاصطناعي المتقدم الذين يحتاجون إلى تحكم دقيق في تفاعلات الوكيل الفرعي ووصول إلى المستودع"},"recommendation":{"en":"Empowers agents to invoke subagents with specific prompts and flags, utilizing tools like Glob, Grep, and Read, while restricting unnecessary interactions with tools like Edit, Notebook, and Web, all executed in the background with precise control over cwd and repository access","zh":"赋予代理以特定提示和标志调用子代理的能力，利用像 Glob、Grep 和 Read 这样的工具，同时限制与像 Edit、Notebook 和 Web 这样的工具的不必要交互，所有操作都在后台执行，精确控制 cwd 和仓库访问","ja":"特定なプロンプトとフラグを使用してサブエージェントを呼び出すエージェントの能力を与え、Glob、Grep、Read などのツールを使用し、Edit、Notebook、Web などのツールとの不必要な相互作用を制限し、すべての操作をバックグラウンドで実行し、cwd とリポジトリへのアクセスを正確に制御","ko":"특정 프롬프트와 플래그를 사용하여 하위 에이전트를 호출하는 에이전트의 기능을 부여하고 Glob, Grep, Read와 같은 도구를 사용하여 Edit, Notebook, Web와 같은 도구와의 불필요한 상호 작용을 제한하고 모든 작업을 백그라운드에서 실행하고 cwd 및 리포지토리 액세스를 정밀하게 제어","es":"Habilita a los agentes a invocar a subagentes con llamadas y marcas específicas, utilizando herramientas como Glob, Grep y Read, mientras restringe las interacciones innecesarias con herramientas como Edit, Notebook y Web, todo ejecutado en segundo plano con un control preciso sobre cwd y acceso al repositorio","fr":"Autorise les agents à invoquer des sous-agents avec des invites et des indicateurs spécifiques, en utilisant des outils comme Glob, Grep et Read, tout en restreignant les interactions inutiles avec des outils comme Edit, Notebook et Web, le tout exécuté en arrière-plan avec un contrôle précis sur cwd et l''accès au référentiel","de":"Ermöglicht es Agents, Subagenten mit spezifischen Prompts und Flags aufzurufen, indem es Tools wie Glob, Grep und Read nutzt, während es unnötige Interaktionen mit Tools wie Edit, Notebook und Web einschränkt, alles im Hintergrund mit präziser Kontrolle über cwd und Repository-Zugriff ausgeführt","pt":"Habilita agentes a invocar subagentes com prompts e flags específicos, utilizando ferramentas como Glob, Grep e Read, enquanto restringe interações desnecessárias com ferramentas como Edit, Notebook e Web, tudo executado em segundo plano com controle preciso sobre cwd e acesso ao repositório","ru":"Позволяет агентам вызывать субагентов с конкретными подсказками и флагами, используя инструменты seperti Glob, Grep и Read,，同时 ограничивая ненужные взаимодействия с инструментами seperti Edit, Notebook и Web, все выполняется в фоновом режиме с точным контролем над cwd и доступом к репозиторию","ar":"تمكّن الوكلاء من استدعاء وكلاء فرعيين مع إشارات ورموز محددة، باستخدام أدوات مثل Glob و Grep و Read، في حين تقييد التفاعلات غير الضرورية مع أدوات مثل Edit و Notebook و Web، كل ذلك يتم تنفيذه في الخلفية مع التحكم الدقيق في cwd ووصول إلى المستودع"},"useCases":{"en":["Invoking subagents for task automation","Restricting subagent interactions to specific tools and repositories","Executing background tasks with precise control over flags and prompts"],"zh":["调用子代理进行任务自动化","限制子代理与特定工具和仓库的交互","在后台以精确控制标志和提示执行任务"],"ja":["タスクの自動化のためにサブエージェントを呼び出す","特定のツールやリポジトリとのサブエージェントの相互作用を制限する","バックグラウンドでフラグやプロンプトを正確に制御してタスクを実行する"],"ko":["작업 자동화를 위해 하위 에이전트를 호출","특정 도구 및 리포지토리와의 하위 에이전트 상호 작용을 제한","백그라운드에서 플래그 및 프롬프트를 정밀하게 제어하여 작업을 실행"],"es":["Invocar subagentes para la automatización de tareas","Restringir las interacciones de subagentes a herramientas y repositorios específicos","Ejecutar tareas en segundo plano con un control preciso sobre flags y prompts"],"fr":["Invoquer des sous-agents pour l''automatisation des tâches","Restreindre les interactions des sous-agents à des outils et des référentiels spécifiques","Exécuter des tâches en arrière-plan avec un contrôle précis sur les indicateurs et les invites"],"de":["Subagenten für die Aufgabenautomatisierung aufrufen","Subagenten-Interaktionen auf bestimmte Tools und Repositorys beschränken","Hintergrundaufgaben mit präziser Kontrolle über Flags und Prompts ausführen"],"pt":["Invocar subagentes para automação de tarefas","Restringir interações de subagentes a ferramentas e repositórios específicos","Executar tarefas em segundo plano com controle preciso sobre flags e prompts"],"ru":["Вызов субагентов для автоматизации задач","Ограничение взаимодействия субагентов с конкретными инструментами и репозиториями","Выполнение задач в фоновом режиме с точным контролем над флагами и подсказками"],"ar":["استدعاء وكلاء فرعيين لتحسين المهام","تقييد تفاعلات الوكلاء الفرعيين مع أدوات ومستودعات محددة","تنفيذ المهام في الخلفية مع التحكم الدقيق في الرّموز والإشارات"]},"limitations":{"en":["Requires precise prompt specification","Subagents scoped to their current working directory (cwd)","Limited to specific tools and repositories"],"zh":["需要精确的提示规范","子代理仅限于其当前工作目录 (cwd)","仅限于特定工具和仓库"],"ja":["正確なプロンプトの指定が必要","サブエージェントは現在の作業ディレクトリ (cwd) に限定される","特定のツールやリポジトリに限定される"],"ko":["정확한 프롬프트 명세가 필요","하위 에이전트는 현재 작업 디렉토리 (cwd)로 제한","특정 도구 및 리포지토리만 사용"],"es":["Requiere una especificación precisa de las llamadas","Los subagentes están limitados a su directorio de trabajo actual (cwd)","Limitado a herramientas y repositorios específicos"],"fr":["Nécessite une spécification précise des invites","Les sous-agents sont limités à leur répertoire de travail actuel (cwd)","Limité à des outils et des référentiels spécifiques"],"de":["Benötigt eine präzise Spezifikation der Prompts","Subagenten sind auf ihr aktuelles Arbeitsverzeichnis (cwd) beschränkt","Begrenzt auf bestimmte Tools und Repositorys"],"pt":["Exige especificação precisa de prompts","Subagentes com escopo limitado ao seu diretório de trabalho atual (cwd)","Limitado a ferramentas e repositórios específicos"],"ru":["Требует точной спецификации подсказок","Субагенты ограничены своим текущим рабочим каталогом (cwd)","Ограничен конкретными инструментами и репозиториями"],"ar":["يتطلب تحديدًا دقيقًا للإشارات","وكلاء فرعيون محدودون إلى دليلهم الحالي (cwd)","محدود بأدوات ومستودعات محددة"]},"version":4},"contentHash":"c7b1f4ba8fdb376e73c1f55572be9cf64a0d5993ecb4491ee6d2fdf9a4d579b1","qualityScore":36}');
