INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jeninh/ampskills-dotfile/invoking-subagents', 'invoking-subagents', 'jeninh', 'ampskills-dotfile', 'community', 'invoking-subagents jeninh ampskills-dotfile community The invoking-subagents skill allows developers to invoke subagents with specific prompts and flags, enabling precise control over tool interactions and repository access. 调用子代理需要使用synu claude命令，并设置精确的提示和限制，确保安全高效的AI工具调用。 サブエージェントの呼び出しには、synu claudeコマンドを使用し、正確なプロンプトと制限を設定する必要があります。 서브 에이전트 호출에는 synu claude 명령을 사용하고 정확한 프롬프트와 제한을 설정하는 것이 필요합니다. La invocación de subagentes permite a los desarrolladores ejecutar tareas en segundo plano con herramientas específicas L''invocation de sous-agents permet aux développeurs d''exécuter des tâches en arrière-plan avec des outils spécifiques Die Invocation von Subagenten ermöglicht es Entwicklern, Aufgaben im Hintergrund mit spezifischen Tools auszuführen O skill de invocação de subagentes permite executar comandos em segundo plano com segurança. Use o comando synu claude com flags para restringir as ferramentas Навык вызова подагентов позволяет выполнять команды в фоновом режиме с безопасностью. Используйте команду synu claude с флагами, чтобы ограничить инструменты ИИ Агентов مهارة استدعاء الوكلاء الفرعيين تسمح بتنفيذ أوامر في الخلفية بأمان. استخدم الأمر synu claude مع أعلام لتقيد الأدوات how to use invoking-subagents invoking-subagents setup guide invoking-subagents alternative invoking-subagents vs synu what is invoking-subagents invoking-subagents install synu claude command scoped repository interactions restricted tool interactions AI工具子代理调用 synu claude命令 AI工具调用设置 子代理安全性 AI开发者工具 Glob工具 Grep工具 Read工具 Task功能 Notebook功能 Invoke subagents using the synu claude command with flags Scoped to the current working directory (cwd) for repository-specific interactions Supports restricted tool interactions, such as Glob, Grep, and Read Allows execution of subagents in the background Requires precise and thorough prompts for effective invocation Enables aggressive restriction of tool interactions for improved security Invoking-subagents is a skill that enables the invocation of subagents with restricted tool interactions, scoped to their current working directory.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('andrelandgraf/fullstackrecipes/config-schema-setup', 'community', 'andrelandgraf', 'fullstackrecipes', 'andrelandgraf/fullstackrecipes', 'config-schema-setup', 0, 0, 36, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:21.894Z', '3fc1b2a49d19746915a7b5e5a7b34ecd119db6184b82437f9ff80ee1e1fa16dd', '{"id":"andrelandgraf/fullstackrecipes/config-schema-setup","name":"config-schema-setup","description":{"en":"config-schema-setup provides a Shadcn registry and collection of production-ready patterns for full stack web AI apps, enabling developers to set up Type-Safe Environment Configuration.","zh":"Config Schema Setup 提供类型安全的环境配置，包括全栈 Web AI 应用的生产就绪模式和步骤指南","ja":"Config Schema Setup は、フルスタック Web AI アプリの生产就绪パターンとステップバイステップガイドを含む、型安全な環境構成を提供します","ko":"Config Schema Setup은 풀스택 웹 AI 애플리케이션의 프로덕션 레디 패턴 및 단계별 가이드를 포함한 유형 안전 환경 구성 제공","es":"El config-schema-setup es una colección de patrones y guías paso a paso para aplicaciones web de pila completa con configuración de entorno tipo seguro","fr":"Le config-schema-setup est une collection de modèles et de guides étape par étape pour les applications web full stack avec configuration d''environnement type sûr","de":"Das config-schema-setup ist eine Sammlung von Mustern und Schritt-für-Schritt-Anleitungen für Full-Stack-Webanwendungen mit Typsicherer Umgebungskonfiguration","pt":"O config-schema-setup é um recurso para configurar ambientes de forma segura e eficaz para aplicativos web de IA.","ru":"Config-schema-setup - это ресурс для настройки безопасных и эффективных окружений для веб-приложений ИИ.","ar":"مخطط التهيئة هو مورد لتهيئة البيئات بأمان وفعالية لتطبيقات الويب الإعلامية الاصطناعية."},"seo":{"title":{"en":"config-schema-setup: Type-Safe Environment Configuration ...","zh":"Config Schema Setup 指南：全栈 Web AI 应用配置","ja":"Config Schema Setup ガイド：フルスタック Web AI アプリの構成","ko":"Config Schema Setup 가이드: 풀스택 웹 AI 애플리케이션 구성","es":"Configuración de Esquema de Configuración: Guía de Config...","fr":"Configuration de Schéma de Configuration: Guide de Config...","de":"Konfigurationsschema-Setup: Anleitung zur Einrichtung","pt":"Configuração de Esquema de Configuração: Guia de Setup","ru":"Настройка конфигурации схемы: Руководство по установке дл...","ar":"إعداد مخطط التهيئة: دليل الإعداد لآلات الإعلام الاصطناعي"},"description":{"en":"Discover how to set up Type-Safe Environment Configuration with config-schema-setup. Get the recipe directly via curl or MCP server and start building full s...","zh":"使用 Config Schema Setup 实现类型安全的环境配置，获取全栈 Web AI 应用的生产就绪模式和步骤指南","ja":"Config Schema Setup を使用して型安全な環境構成を実現し、フルスタック Web AI アプリの生产就绪パターンとステップバイステップガイドを取得","ko":"Config Schema Setup을 사용하여 유형 안전 환경 구성하기 및 풀스택 웹 AI 애플리케이션의 프로덕션 레디 패턴 및 단계별 가이드 얻기","es":"Descubre cómo configurar un esquema de configuración tipo seguro para aplicaciones web de pila completa con nuestra guía paso a paso","fr":"Découvrez comment configurer un schéma de configuration type sûr pour les applications web full stack avec notre guide étape par étape","de":"Erfahren Sie, wie Sie ein Konfigurationsschema für Typsichere Umgebungen für Full-Stack-Webanwendungen mit unserer Schritt-für-Schritt-Anleitung einrichten","pt":"Aprenda a configurar esquemas de configuração para aplicativos web de IA com o recurso fullstackrecipes MCP server","ru":"Узнайте, как настроить схемы конфигурации для веб-приложений ИИ с помощью ресурса fullstackrecipes MCP server для ИИ Агентов","ar":"تعلم كيفية إعداد مخططات التهيئة لتطبيقات الويب الإعلامية الاصطناعية باستخدام مورد الخادم MCP من fullstackrecipes"},"definition":{"en":"config-schema-setup is a collection of production-ready patterns and step-by-step guides for setting up Type-Safe Environment Configuration in full stack web AI apps.","zh":"Config Schema Setup 是一种全栈 Web AI 应用的环境配置解决方案，提供类型安全和生产就绪模式","ja":"Config Schema Setup は、フルスタック Web AI アプリの環境構成ソリューションで、型安全と生产就绪パターンを提供します","ko":"Config Schema Setup은 풀스택 웹 AI 애플리케이션의 환경 구성 솔루션으로, 유형 안전 및 프로덕션 레디 패턴을 제공","es":"El config-schema-setup es un conjunto de patrones y guías para configurar entornos tipo seguros para aplicaciones web","fr":"Le config-schema-setup est un ensemble de modèles et de guides pour configurer des environnements type sûrs pour les applications web","de":"Das config-schema-setup ist ein Satz von Mustern und Anleitungen zur Konfiguration von Typsicheren Umgebungen für Webanwendungen","pt":"O que é config-schema-setup? É um recurso para configurar esquemas de configuração para aplicativos web de IA.","ru":"Что такое config-schema-setup? Это ресурс для настройки схем конфигурации для веб-приложений ИИ.","ar":"ما هو مخطط التهيئة؟ هو مورد لتهيئة مخططات التهيئة لتطبيقات الويب الإعلامية الاصطناعية."},"features":{"en":["Provides a Shadcn registry for full stack web AI apps","Offers production-ready patterns for Type-Safe Environment Configuration","Includes step-by-step guides (recipes) for setup and configuration","Supports fetching recipes directly via curl","Integrates with MCP server for resource management","Uses text/plain API for recipe retrieval"],"zh":["类型安全的环境配置","全栈 Web AI 应用的生产就绪模式","步骤指南和示例代码","支持 MCP 服务器和 CLI","提供 recipe://fullstackrecipes.com/config-schema-setup 资源 URI"],"ja":["型安全な環境構成","フルスタック Web AI アプリの生产就绪パターン","ステップバイステップガイドとサンプルコード","MCP サーバーと CLI のサポート","recipe://fullstackrecipes.com/config-schema-setup リソース URI の提供"],"ko":["유형 안전 환경 구성","풀스택 웹 AI 애플리케이션의 프로덕션 레디 패턴","단계별 가이드 및 샘플 코드","MCP 서버 및 CLI 지원","recipe://fullstackrecipes.com/config-schema-setup 리소스 URI 제공"],"es":["Configuración de entorno tipo seguro","Patrones y guías paso a paso para aplicaciones web de pila completa","Compatibilidad con el servidor MCP","Acceso a recursos de configuración mediante URI","Uso de curl para recuperar recetas de configuración"],"fr":["Configuration d''environnement type sûr","Modèles et guides étape par étape pour les applications web full s