INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('andrelandgraf/fullstackrecipes/config-schema-setup', 'config-schema-setup', 'andrelandgraf', 'fullstackrecipes', 'community', 'config-schema-setup andrelandgraf fullstackrecipes community config-schema-setup provides a Shadcn registry and collection of production-ready patterns for full stack web AI apps, enabling developers to set up Type-Safe Environment Configuration. Config Schema Setup 提供类型安全的环境配置，包括全栈 Web AI 应用的生产就绪模式和步骤指南 Config Schema Setup は、フルスタック Web AI アプリの生产就绪パターンとステップバイステップガイドを含む、型安全な環境構成を提供します Config Schema Setup은 풀스택 웹 AI 애플리케이션의 프로덕션 레디 패턴 및 단계별 가이드를 포함한 유형 안전 환경 구성 제공 El config-schema-setup es una colección de patrones y guías paso a paso para aplicaciones web de pila completa con configuración de entorno tipo seguro Le config-schema-setup est une collection de modèles et de guides étape par étape pour les applications web full stack avec configuration d''environnement type sûr Das config-schema-setup ist eine Sammlung von Mustern und Schritt-für-Schritt-Anleitungen für Full-Stack-Webanwendungen mit Typsicherer Umgebungskonfiguration O config-schema-setup é um recurso para configurar ambientes de forma segura e eficaz para aplicativos web de IA. Config-schema-setup - это ресурс для настройки безопасных и эффективных окружений для веб-приложений ИИ. مخطط التهيئة هو مورد لتهيئة البيئات بأمان وفعالية لتطبيقات الويب الإعلامية الاصطناعية. how to use config-schema-setup config-schema-setup setup guide Type-Safe Environment Configuration full stack web AI apps config-schema-setup alternative config-schema-setup vs Shadcn config-schema-setup install what is config-schema-setup config-schema-setup MCP server config-schema-setup recipe Config Schema Setup 全栈 Web AI 应用 类型安全环境配置 生产就绪模式 MCP 服务器 CLI AIエージェント 环境配置解决方案 Provides a Shadcn registry for full stack web AI apps Offers production-ready patterns for Type-Safe Environment Configuration Includes step-by-step guides (recipes) for setup and configuration Supports fetching recipes directly via curl Integrates with MCP server for resource management Uses text/plain API for recipe retrieval config-schema-setup is a collection of production-ready patterns and step-by-step guides for setting up Type-Safe Environment Configuration in full stack web AI apps.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Nivl/melvin.la/i18n-translation', 'community', 'Nivl', 'melvin.la', 'Nivl/melvin.la', 'i18n-translation', 0, 0, 36, '2026-03-08T01:57:15.340Z', '2026-03-08T02:03:27.731Z', '6ad321b822d3b409d22fc0743bc8aa107ddd5abd668834d7b8a249ac7b4122c6', '{"id":"Nivl/melvin.la/i18n-translation","name":"i18n-translation","description":{"en":"The i18n-translation skill enables developers to translate Next.js web applications to different languages using next-intl, supporting locale-based routes and font configurations.","zh":"使用 next-intl 实现 Next.js 应用的国际化翻译，支持多语言和路由配置","ja":"Next.js アプリケーションの国際化翻訳を next-intl で実現し、多言語とルーティング設定をサポートします","ko":"next-intl을 사용하여 Next.js 애플리케이션의 국제화 번역을 구현하여 다중 언어와 라우팅 설정을 지원합니다","es":"El skill i18n-translation permite traducir aplicaciones web de Next.js a diferentes idiomas utilizando next-intl.","fr":"Le skill i18n-translation permet de traduire des applications web Next.js en plusieurs langues en utilisant next-intl.","de":"Das i18n-Translation-Skill ermöglicht die Übersetzung von Next.js-Webanwendungen in verschiedene Sprachen mithilfe von next-intl.","pt":"O skill i18n-translation permite traduzir aplicativos Next.js para diferentes idiomas usando next-intl.","ru":"Навык i18n-translation позволяет переводить приложения Next.js на разные языки с помощью next-intl и ИИ Агентов.","ar":"يسمح.skill i18n-translation بترجمة تطبيقات Next.js إلى لغات مختلفة باستخدام next-intl وأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"i18n-translation: Next.js Localization Setup Guide | AI A...","zh":"i18n Translation Setup Guide for Next.js","ja":"Next.js の国際化翻訳ベストプラクティス - AIエージェント","ko":"Next.js 국제화 번역 가이드 - AI 에이전트","es":"Guía de configuración de i18n-translation para Next.js","fr":"Configurer l''i18n-translation pour les applications Next.js","de":"i18n-Translation-Setup für Next.js-Anwendungen","pt":"Guia de Configuração de Tradução i18n para Next.js","ru":"Настройка перевода i18n для Next.js с ИИ Агентами","ar":"دليل إعداد الترجمة i18n ل Next.js باستخدام أدوات الذكاء ا..."},"description":{"en":"Unlock global reach with i18n-translation. Learn how to translate Next.js apps using next-intl and discover the power of locale-based routing.","zh":"使用 next-intl 实现 Next.js 应用的国际化翻译，支持多语言","ja":"Next.js アプリケーションの国際化翻訳を next-intl で実現し、多言語をサポートします - AIエージェント","ko":"next-intl을 사용하여 Next.js 애플리케이션의 국제화 번역을 구현하여 다중 언어를 지원합니다 - AI 에이전트","es":"Aprende a traducir aplicaciones web de Next.js a diferentes idiomas con next-intl. Mejora la experiencia del usuario con i18n-translation.","fr":"Découvrez comment traduire des applications web Next.js en plusieurs langues avec next-intl. Améliorez l''expérience utilisateur avec l''i18n-translation.","de":"Erfahren Sie, wie Sie Next.js-Webanwendungen in verschiedene Sprachen mit next-intl übersetzen. Verbessern Sie die Benutzererfahrung mit i18n-Translation.","pt":"Aprenda a traduzir seu aplicativo Next.js para diferentes idiomas usando next-intl e melhore a experiência do usuário","ru":"Узнайте, как перевести свое приложение Next.js на разные языки с помощью next-intl и улучшите пользовательский опыт с ИИ Агентами","ar":"تعلم كيفية ترجمة تطبيق Next.js إلى لغات مختلفة باستخدام next-intl و تحسين تجربة المستخدم مع أدوات الذكاء الاصطناعي"},"definition":{"en":"i18n-translation is a skill that enables Next.js localization using next-intl, allowing for seamless translation and routing configuration.","zh":"i18n Translation 是一种使用 next-intl 实现 Next.js 应用的国际化翻译技术","ja":"i18n Translation は、Next.js アプリケーションの国際化翻訳を next-intl で実現する技術です","ko":"i18n Translation은 next-intl을 사용하여 Next.js 애플리케이션의 국제화 번역을 구현하는 기술입니다","es":"i18n-translation es una función que permite traducir aplicaciones web a diferentes idiomas.","fr":"L''i18n-translation est une fonctionnalité qui permet de traduire des applications web en plusieurs langues.","de":"i18n-Translation ist eine Funktion, die die Übersetzung von Webanwendungen in verschiedene Sprachen ermöglicht.","pt":"i18n-translation é uma técnica de tradução de aplicativos para diferentes idiomas","ru":"i18n-translation - это техника перевода приложений на разные языки с ИИ Агентами","ar":"i18n-translation هو تقنية ترجمة تطبيقات إلى لغات مختلفة باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Utilizes next-intl for translation management","Supports locale-based routing with customizable layouts","Includes locale definitions and types in locales.ts","Configures next-intl requests using request.ts","Enables routing configuration with routing.ts","Integrates with Next.js for seamless localization"],"zh":["使用 next-intl 实现国际化翻译","支持多语言和路由配置","可自定义 locale 定义和类型","支持请求配置和路由设置"],"ja":["next-intl を使用した国際化翻訳の実現","多言語とルーティング設定のサポート","ロケール定義とタイプのカスタマイズ","リクエスト設定とルーティング設定のサポート"],"ko":["next-intl을 사용하여 국제화 번역을 구현","다중 언어와 라우팅 설정을 지원","로케일 정의와 유형을 커스터마이징","요청 설정과 라우팅 설정을 지원"],"es":["Traducción de aplicaciones web de Next.js con next-intl","Soporte para rutas basadas en el idioma","Configuración de fuente y diseño para cada idioma","Definición de locales y tipos con locales.ts","Configuración de solicitudes con request.ts"],"fr":["Traduction d''applications web Next.js avec next-intl","Prise en charge des routes basées sur la langue","Configuration de la police et du design pour chaque langue","Définition des locales et des types avec locales.ts","Configuration des requêtes avec request.ts"],"de":["Übersetzung von Next.js-Webanwendungen mit next-intl","Unterstützung für sprachbasierte Routen","Konfiguration von Schrift und Design für jede Sprache","Definition von Locales und Typen mit locales.ts","Konfiguration von Anfragen mit request.ts"],"pt":["Suporte a múltiplos idiomas com next-intl","Configuração de rotas baseadas em idioma","Definição de locais e tipos com locales.ts","Configuração de solicitação com request.ts","Suporte a layout com fontes configuráveis"],"ru":["Поддержка нескольких языков с помощью next-intl и ИИ Агентов","Настройка маршрутов на основе языка","Определение мест и типов с помощью locales.ts","Настройка запроса с помощью request.ts","Поддержка макета с настраиваемыми шрифтами"],"ar":["دعم اللغات المتعددة مع next-intl وأدوات الذكاء الاصطناعي","تكوين المسارات حسب اللغة","تعريف المواقع و الأنواع مع ملف locales.ts","تكوين الطلب مع ملف request.ts","دعم التخطيط مع خطوط قابلة للتعديل"]},"keywords":{"en":["how to use i18n-translation","next-intl tutorial","i18n-translation setup guide","Next.js localization best practices","i18n-translation vs react-intl","install i18n-translation","i18n-translation documentation","locale-based routing examples","next-intl configuration"],"zh":["i18n Translation","Next.js 国际化","next-intl","多语言支持","路由配置","AIエージェント"],"ja":["i18n Translation","Next.js 国際化","next-intl","多言語サポート","ルーティング設定","AIエージェント"],"ko":["i18n Translation","Next.js 국제화","next-intl","다중 언어 지원","라우팅 설정","AI 에이전트"],"es":["i18n-translation","next-intl","traducción de aplicaciones web","rutas basadas en el idioma","configuración de fuente y diseño","locales.ts","request.ts","Herramientas de AI para desarrolladores","Agents de IA para traducción"],"fr":["i18n-translation","next-intl","traduction d''applications web","routes basées sur la langue","configuration de la police et du design","locales.ts","request.ts","Outils d''IA pour les développeurs","Agents d''IA pour la traduction"],"de":["i18n-Translation","next-intl","Übersetzung von Webanwendungen","sprachbasierte Routen","Konfiguration von Schrift und Design","locales.ts","request.ts","KI-Tools für Entwickler","KI-Agenten für Übersetzung"],"pt":["i18n translation","next-intl","tradução de aplicativos","configuração de idioma","roteamento baseado em idioma","desenvolvimento de aplicativos Next.js","intl para react"],"ru":["i18n перевод","next-intl","перевод приложений","настройка языка","маршрутизация на основе языка","разработка приложений Next.js","intl для react и ИИ Агентов"],"ar":["ترجمة i18n","next-intl","ترجمة تطبيقات","تكوين اللغة","توجيه حسب اللغة","تطوير تطبيقات Next.js","intl لري액ت وأدوات الذكاء الاصطناعي"]}},"owner":"Nivl","repo":"melvin.la","repoPath":"Nivl/melvin.la","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.340Z","topics":[],"category":"community","skillMd":{"name":"i18n-translation","description":"Translate the Next.js web application to different languages using next-intl. Use this skill when the user requests to add a new language, translate content to an existing locale, update translation strings, fix missing translations, or work with internationalization (i18n) features including locale configuration, message files, and blog content translation.","bodyPreview":"# i18n Translation Skill\n\nTranslate the Next.js web application to different languages using `next-intl`.\n\n## Project Structure\n\n```\nweb/\n├── src/\n│   ├── i18n/\n│   │   ├── locales.ts           # Locale definitions and types\n│   │   ├── request.ts           # next-intl request configuration\n│   │   └── routing.ts           # Routing configuration\n│   ├── app/\n│   │   └── [locale]/            # Locale-based routes\n│   │       └── layout.tsx       # Layout with font configuration\n│   └── bundled_s","body":"# i18n Translation Skill\n\nTranslate the Next.js web application to different languages using `next-intl`.\n\n## Project Structure\n\n```\nweb/\n├── src/\n│   ├── i18n/\n│   │   ├── locales.ts           # Locale definitions and types\n│   │   ├── request.ts           # next-intl request configuration\n│   │   └── routing.ts           # Routing configuration\n│   ├── app/\n│   │   └── [locale]/            # Locale-based routes\n│   │       └── layout.tsx       # Layout with font configuration\n│   └── bundled_static/\n│       └── content/blog/        # Blog content by article and locale\n│           └── [article]/\n│               ├── en.mdx\n│               ├── fr.mdx\n│               └── ...\n└── messages/\n    ├── en.json                  # English (source of truth)\n    ├── en.d.json.ts             # TypeScript definitions\n    ├── fr.json                  # French translations\n    ├── es.json                  # Spanish translations\n    ├── ja.json                  # Japanese translations\n    ├── ko.json                  # Korean translations\n    ├── zh.json                  # Chinese Simplified translations\n    └── zh-tw.json               # Chinese Traditional translations\n```\n\n## Supported Locales\n\nCurrent supported locales are defined in `src/i18n/locales.ts`:\n- `en` - English (source of truth)\n- `fr` - French\n- `es` - Spanish\n- `ja` - Japanese\n- `ko` - Korean\n- `zh` - Chinese Simplified\n- `zh-tw` - Chinese Traditional\n\n## Workflows\n\n### Adding a New Locale\n\nFollow these steps to add a new language to the application:\n\n1. **Update locale definitions** in `src/i18n/locales.ts`:\n   - Add the new locale code to the `locales` array\n   - Example: `export const locales = [''en'', ''fr'', ''es'', ''ko'', ''zh'', ''zh-tw'', ''ja''] as const;`\n\n2. **Add language to LanguageSwitcher** in `src/components/layout/NavBar/LanguageSwitcher.tsx`:\n   - Add a new entry to the `languages` array with the locale key, native language label, and `isAI` flag\n   - **CRITICAL**: Set `isAI: true` for all AI-generated translations (all new languages added via this skill)\n   - **CRITICAL**: The `languages` array MUST be ordered alphabetically by the `key` field (locale code)\n   - Example:\n     ```typescript\n     {\n       key: ''ja'',\n       label: ''日本語'',\n       isAI: true,\n     }\n     ```\n   - This adds an \"AI\" superscript indicator in the language dropdown to inform users the translation is AI-generated\n\n3. **Create message file** at `messages/[locale].json`:\n   - Copy the structure from `messages/en.json` (source of truth)\n   - Translate all strings to the target language\n   - Maintain the same JSON structure and key names\n\n4. **Translate blog content**:\n   - For each article in `src/bundled_static/content/blog/[article]/`\n   - Create a new `[locale].mdx` file (e.g., `ja.mdx`)\n   - Translate the MDX content including frontmatter and body\n   - Keep frontmatter structure consistent (title, slug, excerpt, etc.)\n\n5. **Configure fonts** (if needed):\n   - Check if the language requires a specific Noto font (e.g., `Noto Sans JP` for Japanese)\n   - If needed, import the font in `src/app/[locale]/layout.tsx`\n   - Add the font variable to `src/app/globals.css`\n   - Note: Latin-specific fonts (like Baikal) have dedicated variables (e.g., `--font-condensed-latin`) for design-specific usage\n\n6. **Update this skill documentation** (`.agents/skills/i18n-translation/SKILL.md`):\n   - Add the new locale to the \"Supported Locales\" section\n   - Maintain alphabetical order by locale code for consistency\n   - Example: `- ''ja'' - Japanese`\n\n7. **Restart development server** for changes to take effect\n\n### Translating Existing Strings\n\nTo translate strings that are already defined in English:\n\n1. **Locate the key** in `messages/en.json`\n2. **Find the same key** in the target locale file (e.g., `messages/fr.json`)\n3. **Translate the value** while preserving:\n   - JSON structure\n   - Key names\n   - Variable placeholders (e.g., `{count}`, `{name}`)\n   - HTML entities if present\n\n### Adding New Translation Strings\n\nWhen new UI text is added to the application:\n\n1. **Add to English source** (`messages/en.json`):\n   - Use nested keys for organization (e.g., `\"HomePage\": { \"title\": \"...\" }`)\n   - Choose clear, descriptive key names\n\n2. **Add to all other locale files**:\n   - Add the same key structure to every `messages/[locale].json`\n   - Translate the value appropriately for each language\n\n3. **Use in components**:\n   ```typescript\n   import { useTranslations } from ''next-intl'';\n   \n   export function MyComponent() {\n     const t = useTranslations(''HomePage'');\n     return <h1>{t(''title'')}</h1>;\n   }\n   ```\n\n4. **Verify consistency** using `pnpm i18n:check` command\n\n### Translating Blog Articles\n\nBlog articles are stored as MDX files organized by article and locale:\n\n1. **Navigate to** `src/bundled_static/content/blog/[article]/`\n2. **Create or edit** the locale-specific MDX file (e.g., `fr.mdx`)\n3. **Translate frontmatter**:\n   ```yaml\n   ---\n   title: \"Titre de l''article\"\n   slug: \"slug-url\"\n   excerpt: \"Courte description\"\n   image: \"cover.avif\"\n   ogImage: \"cover.jpg\"\n   createdAt: \"2025-07-03\"\n   updatedAt: \"2025-07-03\"\n   ---\n   ```\n\n4. **Translate body content**:\n   - Translate all markdown content\n   - Keep code blocks and syntax intact\n   - Maintain heading structure and links\n\n5. **Restart dev server** after making changes for them to take effect\n\n### Fixing Missing Translations\n\nTo identify and fix missing translations:\n\n1. **Run consistency check**: `pnpm i18n:check`\n2. **Review errors** showing missing keys or locale files\n3. **Add missing translations** to the appropriate locale files\n4. **Ensure structure matches** `messages/en.json`\n\n## Best Practices\n\n### Translation Quality\n\n- Maintain **natural phrasing** in the target language, not literal translations\n- Preserve **tone and voice** consistent with the brand\n- Keep **technical terms** consistent (e.g., \"API\", \"GitHub\")\n- Use **proper capitalization** and punctuation for the target language\n- Consider **cultural context** for idioms and expressions\n\n### JSON Structure\n\n- Always preserve the **nested key structure** from English\n- Use **double quotes** for JSON strings\n- Maintain **proper indentation** (2 spaces)\n- Keep keys in the **same order** as the English file for easier comparison\n- Do not include **comments** in JSON files\n\n### Font Configuration\n\n- Latin scripts (English, French, Spanish): Use default fonts\n- CJK languages (Chinese, Japanese, Korean): Configure Noto CJK fonts\n- Right-to-left languages (Arabic, Hebrew): Ensure RTL support is configured\n- Use `--font-condensed-latin` variable for design-specific Latin fonts regardless of locale\n\n### Blog Content\n\n- Translate **all frontmatter fields** except dates and image paths\n- Keep **slug values** in the target language for SEO\n- Maintain **markdown formatting** (headings, lists, links)\n- Preserve **code blocks** without translation\n- Keep **image paths** and **links** functional\n\n## Validation\n\nAfter making translation changes:\n\n1. Run linting: `pnpm run lint --fix`\n2. Check i18n consistency: `pnpm i18n:check`\n3. Run tests: `pnpm run test:unit`\n4. Restart dev server: `pnpm run dev`\n5. Verify changes in browser for each affected locale\n\n## Common Issues\n\n### Missing Translation Keys\n\n**Symptom**: Console warnings about missing translation keys  \n**Solution**: Add the missing key to all locale files with appropriate translations\n\n### Inconsistent JSON Structure\n\n**Symptom**: i18n:check fails with structure errors  \n**Solution**: Ensure all locale files have the same nested key structure as `en.json`\n\n### Blog Content Not Updating\n\n**Symptom**: Changes to MDX files not reflected in the app  \n**Solution**: Restart the development server (`pnpm run dev`)\n\n### Font Not Displaying Correctly\n\n**Symptom**: Characters appear with wrong font or as boxes  \n**Solution**: Verify the correct Noto font is imported and configured in `layout.tsx` and `globals.css`\n\n### Build Failures After Translation\n\n**Symptom**: Build fails with MDX processing errors  \n**Solution**: Check MDX frontmatter syntax and ensure all required fields are present\n\n## Quick Reference\n\n### Commands\n- `pnpm i18n:check` - Check translation consistency\n- `pnpm run dev` - Start dev server (restart after blog changes)\n- `pnpm run build` - Production build (validates all content)\n\n### File Locations\n- Locale definitions: `src/i18n/locales.ts`\n- Language switcher: `src/components/layout/NavBar/LanguageSwitcher.tsx`\n- Message files: `messages/[locale].json`\n- Blog content: `src/bundled_static/content/blog/[article]/[locale].mdx`\n- Font config: `src/app/[locale]/layout.tsx` and `src/app/globals.css`\n\n### Key Patterns\n```typescript\n// In components\nconst t = useTranslations(''SectionName'');\nconst text = t(''keyName'');\n\n// Message structure\n{\n  \"SectionName\": {\n    \"keyName\": \"Translated text\"\n  }\n}\n\n// LanguageSwitcher entry for new locale\n{\n  key: ''ja'',           // Locale code (array MUST be sorted alphabetically by this key)\n  label: ''日本語'',      // Native language name\n  isAI: true,          // Always true for AI-generated translations\n}\n```\n"},"lastSynced":"2026-03-08T02:03:27.731Z","agentAnalysis":{"suitability":{"en":"Perfect for Multilingual Agents needing seamless Next.js web application translation capabilities using next-intl.","zh":"适用于需要无缝Next.js网页应用程序翻译能力的多语言代理，使用next-intl。","ja":"next-intlを使用して無縫なNext.js Webアプリケーション翻訳機能を必要とするマルチリンガルエージェントに適しています。","ko":"next-intl을 사용하여 무결점의 Next.js 웹 애플리케이션 번역 기능이 필요한 다국어 에이전트에게 적합합니다.","es":"Perfecto para agentes multilingües que necesitan capacidades de traducción de aplicaciones web Next.js sin problemas utilizando next-intl.","fr":"Parfait pour les agents multilingues ayant besoin de capacités de traduction d''applications web Next.js sans interruption en utilisant next-intl.","de":"Perfekt für multilinguale Agenten, die eine nahtlose Next.js-Webanwendung-Übersetzungsfunktion mit next-intl benötigen.","pt":"Perfeito para Agentes Multilíngues que necessitam de capacidades de tradução de aplicativos web Next.js sem interrupções usando next-intl.","ru":"Идеально для многоязычных агентов, которым необходимы возможности бесшовного перевода веб-приложений Next.js с помощью next-intl.","ar":"مثالي للوكلاء المتعددون اللغات الذين يحتاجون إلى khảیات ترجمة تطبيقات الويب Next.js دون انقطاع باستخدام next-intl."},"recommendation":{"en":"Empowers agents to translate Next.js applications into multiple languages, supporting locale-based routes and font configurations via next-intl, enabling efficient internationalization and localization with locales.ts and routing.ts configurations.","zh":"赋予代理翻译Next.js应用程序为多种语言提供支持，支持基于区域设置的路由和字体配置通过next-intl，实现高效的国际化和本地化与locales.ts和routing.ts配置。","ja":"エージェントにNext.jsアプリケーションを複数の言語に翻訳する能力を与え、next-intlを介してロケールベースのルーティングとフォント構成をサポートすることで、効率的な国際化とローカライズを可能にします。locales.tsとrouting.tsの構成も可能です。","ko":"에이전트에 Next.js 애플리케이션을 여러 언어로 번역할 수 있는 능력을 부여하며, next-intl을 통해 로케일 기반의 라우팅과 폰트 구성에 대한 지원을 제공하여 효율적인 국제화와 지역화를 구현합니다. locales.ts 및 routing.ts 구성도 가능합니다.","es":"Habilita a los agentes a traducir aplicaciones Next.js a varios idiomas, con soporte de rutas y configuraciones de fuentes basadas en el idioma a través de next-intl, lo que permite una internacionalización y localización eficientes con configuraciones de locales.ts y routing.ts.","fr":"Permet aux agents de traduire des applications Next.js dans plusieurs langues, en prenant en charge les itinéraires et les configurations de polices basées sur les paramètres régionaux via next-intl, ce qui permet une internationalisation et une localisation efficaces avec des configurations de locales.ts et routing.ts.","de":"Ermächtigt Agenten, Next.js-Anwendungen in mehrere Sprachen zu übersetzen, mit Unterstützung für lokalisierungsbasierte Routen und Schriftkonfigurationen über next-intl, ermöglicht eine effiziente Internationalisierung und Lokalisierung mit Konfigurationen von locales.ts und routing.ts.","pt":"Habilita os agentes a traduzir aplicativos Next.js para vários idiomas, suportando rotas baseadas em localização e configurações de fonte via next-intl, permitindo a internacionalização e localização eficientes com configurações locales.ts e routing.ts.","ru":"Наделяет агентов возможностью переводить приложения Next.js на несколько языков, поддерживая маршрутизацию на основе местоположения и конфигурации шрифтов через next-intl, обеспечивая эффективную интернационализацию и локализацию с помощью конфигураций locales.ts и routing.ts.","ar":"يمنح الوكلاء القدرة على ترجمة تطبيقات Next.js إلى عدة لغات، مع دعم المسارات المستندة إلى الموقع والإعدادات الخاصة بالخطوط عبر next-intl، مما يتيح التنويع والتوحيد الفعالين مع إعدادات locales.ts و routing.ts."},"useCases":{"en":["Translating web applications into multiple languages","Configuring locale-based routes for Next.js apps","Implementing font configurations for internationalized layouts"],"zh":["将Web应用程序翻译成多种语言","为Next.js应用程序配置基于区域设置的路由","为国际化布局实现字体配置"],"ja":["Webアプリケーションを複数の言語に翻訳する","Next.jsアプリケーションにロケールベースのルーティングを設定する","国際化されたレイアウトのフォント構成を実装する"],"ko":["웹 애플리케이션을 여러 언어로 번역하는 것","Next.js 애플리케이션에 로케일 기반의 라우팅을 구성하는 것","국제화된 레이아웃의 폰트 구성實施"],"es":["Traducir aplicaciones web a varios idiomas","Configurar rutas basadas en el idioma para aplicaciones Next.js","Implementar configuraciones de fuentes para diseños internacionalizados"],"fr":["Traduire des applications web dans plusieurs langues","Configurer des itinéraires basés sur les paramètres régionaux pour les applications Next.js","Mettre en œuvre des configurations de polices pour des mises en page internationalisées"],"de":["Webanwendungen in mehrere Sprachen übersetzen","Lokalisierungsbasierte Routen für Next.js-Anwendungen konfigurieren","Schriftkonfigurationen für internationalisierte Layouts implementieren"],"pt":["Traduzir aplicativos web para vários idiomas","Configurar rotas baseadas em localização para aplicativos Next.js","Implementar configurações de fonte para layouts internacionalizados"],"ru":["Переводить веб-приложения на несколько языков","Настроить маршрутизацию на основе местоположения для приложений Next.js","Реализовать конфигурации шрифтов для интернационализированных макетов"],"ar":["ترجمة تطبيقات الويب إلى عدة لغات","تكوين مسارات تستند إلى الموقع لتطبيقات Next.js","تنفيذ إعدادات الخطوط لمخططات متعددة اللغات"]},"limitations":{"en":["Requires next-intl library integration","Next.js framework only","Manual configuration of locales.ts and routing.ts needed"],"zh":["需要集成next-intl库","仅支持Next.js框架","需要手动配置locales.ts和routing.ts"],"ja":["next-intlライブラリの統合が必要","Next.jsフレームワークのみをサポート","locales.tsとrouting.tsの手動構成が必要"],"ko":["next-intl 라이브러리 통합이 필요함","Next.js 프레임워크만 지원함","locales.ts 및 routing.ts의 수동 구성 필요"],"es":["Requiere la integración de la biblioteca next-intl","Solo compatible con el framework Next.js","Se requiere configuración manual de locales.ts y routing.ts"],"fr":["Nécessite l''intégration de la bibliothèque next-intl","N''est compatible qu''avec le framework Next.js","Une configuration manuelle de locales.ts et routing.ts est nécessaire"],"de":["Benötigt die Integration der next-intl-Bibliothek","Nur mit dem Next.js-Framework kompatibel","Manuelle Konfiguration von locales.ts und routing.ts erforderlich"],"pt":["Requer integração da biblioteca next-intl","Apenas framework Next.js","Necessário configurar manualmente locales.ts e routing.ts"],"ru":["Требуется интеграция библиотеки next-intl","Только фреймворк Next.js","Необходимо вручную настроить locales.ts и routing.ts"],"ar":["يتطلب تكامل مكتبة next-intl","إطار عمل Next.js فقط","يتطلب تهيئة يدوية لملفات locales.ts و routing.ts"]},"version":4},"contentHash":"6ad321b822d3b409d22fc0743bc8aa107ddd5abd668834d7b8a249ac7b4122c6","qualityScore":36}');
