INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nivl/melvin.la/i18n-translation', 'i18n-translation', 'Nivl', 'melvin.la', 'community', 'i18n-translation Nivl melvin.la community The i18n-translation skill enables developers to translate Next.js web applications to different languages using next-intl, supporting locale-based routes and font configurations. 使用 next-intl 实现 Next.js 应用的国际化翻译，支持多语言和路由配置 Next.js アプリケーションの国際化翻訳を next-intl で実現し、多言語とルーティング設定をサポートします next-intl을 사용하여 Next.js 애플리케이션의 국제화 번역을 구현하여 다중 언어와 라우팅 설정을 지원합니다 El skill i18n-translation permite traducir aplicaciones web de Next.js a diferentes idiomas utilizando next-intl. Le skill i18n-translation permet de traduire des applications web Next.js en plusieurs langues en utilisant next-intl. Das i18n-Translation-Skill ermöglicht die Übersetzung von Next.js-Webanwendungen in verschiedene Sprachen mithilfe von next-intl. O skill i18n-translation permite traduzir aplicativos Next.js para diferentes idiomas usando next-intl. Навык i18n-translation позволяет переводить приложения Next.js на разные языки с помощью next-intl и ИИ Агентов. يسمح.skill i18n-translation بترجمة تطبيقات Next.js إلى لغات مختلفة باستخدام next-intl وأدوات الذكاء الاصطناعي. how to use i18n-translation next-intl tutorial i18n-translation setup guide Next.js localization best practices i18n-translation vs react-intl install i18n-translation i18n-translation documentation locale-based routing examples next-intl configuration i18n Translation Next.js 国际化 next-intl 多语言支持 路由配置 AIエージェント Utilizes next-intl for translation management Supports locale-based routing with customizable layouts Includes locale definitions and types in locales.ts Configures next-intl requests using request.ts Enables routing configuration with routing.ts Integrates with Next.js for seamless localization i18n-translation is a skill that enables Next.js localization using next-intl, allowing for seamless translation and routing configuration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thefixer3x/onasis-gateway/compliance-manager', 'community', 'thefixer3x', 'onasis-gateway', 'thefixer3x/onasis-gateway', 'compliance-manager', 0, 0, 36, '2026-03-08T01:57:15.344Z', '2026-03-08T02:03:31.242Z', 'c9895cbf636899fc1a3cc513224b6fb85819cfbf2f41f121e91550b2530eee04', '{"id":"thefixer3x/onasis-gateway/compliance-manager","name":"compliance-manager","description":{"en":"The Compliance Manager provides comprehensive security features for API services, including PCI-DSS data protection and GDPR compliance. It benefits developers and organizations requiring robust security and regulatory adherence.","zh":"Compliance Manager提供PCI-DSS数据保护、GDPR合规、PSD2合规等功能，帮助开发者创建安全可靠的API服务","ja":"Compliance Managerは、PCI-DSSデータ保護、GDPR準拠、PSD2準拠などを提供するAIエージェントで、開発者が安全で信頼できるAPIサービスを作成するのに役立ちます","ko":"Compliance Manager는 PCI-DSS 데이터 보호, GDPR 규정 준수, PSD2 규정 준수 등을 제공하는 AI 에이전트로 개발자가 보안이 강화된 API 서비스를 만들 수 있도록 도와줍니다","es":"El Compliance Manager es un servicio de API que proporciona protección de datos y cumplimiento normativo para aplicaciones","fr":"Le Compliance Manager est un service d''API qui assure la protection des données et la conformité réglementaire pour les applications","de":"Der Compliance Manager ist ein API-Service, der Datensicherheit und regulatorische Konformität für Anwendungen bietet","pt":"O Compliance Manager é uma solução de gerenciamento de conformidade que fornece proteção de dados PCI-DSS, conformidade GDPR e HIPAA","ru":"Compliance Manager - это решение для управления соответствием требованиям, обеспечивающее защиту данных PCI-DSS, GDPR и HIPAA с помощью ИИ Агентов","ar":"مدير الامتثال هو حل لإدارة الامتثال يوفر حماية البيانات PCI-DSS و الامتثال للوائح GDPR و HIPAA"},"seo":{"title":{"en":"Compliance-Manager: Secure API Service Setup Guide | AI A...","zh":"Compliance Manager_SETUP GUIDE: PCI-DSS数据保护和GDPR合规","ja":"Compliance Manager ベストプラクティス: AIエージェントによるPCI-DSSデータ保護とGDPR準拠","ko":"Compliance Manager 설정 가이드: PCI-DSS 데이터 보호 및 GDPR 규정 준수","es":"Guía de configuración de Compliance Manager: Protección d...","fr":"Guide de mise en place de Compliance Manager : Protection...","de":"Einrichtungsleitfaden für Compliance Manager: Datensicher...","pt":"Guia de Configuração do Compliance Manager para Desenvolv...","ru":"Настройка Compliance Manager: ИИ Агенты для Безопасности ...","ar":"دليل تنفيذ مدير الامتثال للبرمجة"},"description":{"en":"Unlock robust compliance management with Onasis Gateway''s API service. Learn how to implement PCI-DSS, GDPR, and HIPAA standards with our expert guide.","zh":"了解Compliance Manager的功能和特点，包括PCI-DSS数据保护、GDPR合规、PSD2合规等，助您打造安全可靠的API服务","ja":"Compliance Managerは、PCI-DSSデータ保護、GDPR準拠、PSD2準拠などを提供するAIエージェントです。詳細を確認してください","ko":"Compliance Manager의 주요 기능과 특징을 확인하세요. PCI-DSS 데이터 보호, GDPR 규정 준수, PSD2 규정 준수 등에 대한 지원을 제공합니다","es":"Aprende a implementar el Compliance Manager para proteger datos sensibles y cumplir con regulaciones como PCI-DSS, GDPR y HIPAA","fr":"Découvrez comment mettre en place le Compliance Manager pour protéger les données sensibles et respecter les réglementations comme PCI-DSS, GDPR et HIPAA","de":"Erfahren Sie, wie Sie den Compliance Manager implementieren, um sensible Daten zu schützen und die Vorschriften von PCI-DSS, GDPR und HIPAA einzuhalten","pt":"Aprenda a configurar o Compliance Manager para proteger dados sensíveis e atender regulamentações como PCI-DSS, GDPR e HIPAA","ru":"Узнайте, как настроить Compliance Manager для защиты данных и соблюдения требований PCI-DSS, GDPR и HIPAA с помощью ИИ Агентов","ar":"تعرف على كيفية تنفيذ مدير الامتثال لحماية البيانات الحساسة والامتثال للوائح مثل PCI-DSS و GDPR و HIPAA"},"definition":{"en":"Compliance-manager is a comprehensive API service warehouse with MCP server interfaces and REST endpoints, ensuring secure data protection and regulatory compliance.","zh":"Compliance Manager是一种提供数据保护和合规功能的AI工具，包括PCI-DSS、GDPR、PSD2等","ja":"Compliance Managerは、データ保護と準拠機能を提供するAIエージェントで、PCI-DSS、GDPR、PSD2などをサポートします","ko":"Compliance Manager는 데이터 보호 및 규정 준수 기능을 제공하는 AI 에이전트로서 PCI-DSS, GDPR, PSD2 등을 지원합니다","es":"El Compliance Manager es un conjunto de herramientas para garantizar la protección de datos y el cumplimiento de regulaciones","fr":"Le Compliance Manager est un ensemble d''outils pour assurer la protection des données et la conformité réglementaire","de":"Der Compliance Manager ist eine Sammlung von Tools, um die Datensicherheit und die regulatorische Konformität zu gewährleisten","pt":"O que é um Compliance Manager? É uma solução de gerenciamento de conformidade que protege dados sensíveis","ru":"Что такое Compliance Manager? Это решение для управления соответствием требованиям, обеспечивающее защиту данных","ar":"ما هو مدير الامتثال? هو حل لإدارة الامتثال لحماية البيانات الحساسة"},"features":{"en":["PCI-DSS data protection with card data masking and encryption","GDPR compliance through pseudonymization, consent management, and data minimization","PSD2 compliance with Strong Customer Authentication","SOX audit trail requirements implementation","HIPAA health data protection and secure audit logging","Multi-regulation validation framework for streamlined compliance"],"zh":["PCI-DSS数据保护","GDPR合规","PSD2合规","SOX审计跟踪","HIPAA健康数据保护","多规则验证框架"],"ja":["PCI-DSSデータ保護","GDPR準拠","PSD2準拠","SOX監査トレイル","HIPAAヘルスデータ保護","マルチ規制バリデーションフレームワーク"],"ko":["PCI-DSS 데이터 보호","GDPR 규정 준수","PSD2 규정 준수","SOX 감사 추적","HIPAA 건강 데이터 보호","다중 규정 검증 프레임워크"],"es":["Protección de datos de pago con PCI-DSS","Cumplimiento de la GDPR con pseudonimización y gestión de consentimiento","Autenticación de cliente fuerte con PSD2","Registro de auditoría seguro para SOX","Protección de datos de salud con HIPAA","Marco de validación de regulaciones múltiples"],"fr":["Protection des données de paiement avec PCI-DSS","Conformité à la GDPR avec pseudonymisation et gestion des consentements","Authentification client forte avec PSD2","Journal d''audit sécurisé pour SOX","Protection des données de santé avec HIPAA","Cadre de validation de réglementations multiples"],"de":["Schutz von Zahlungsdaten mit PCI-DSS","Einhaltung der GDPR mit Pseudonymisierung und Zustimmungsverwaltung","Starkes Kunden-Authentifizierungsverfahren mit PSD2","Sichere Audit-Protokollierung für SOX","Schutz von Gesundheitsdaten mit HIPAA","Rahmenwerk für die Validierung mehrerer Vorschriften"],"pt":["Proteção de dados PCI-DSS com mascaramento e criptografia","Conformidade GDPR com pseudonimização e gestão de consentimento","Conformidade HIPAA para proteção de dados de saúde","Validação de regulamentações múltiplas","Registro de auditoria seguro"],"ru":["Защита данных PCI-DSS с маскированием и шифрованием","Соответствие требованиям GDPR с псевдонимизацией и управлением согласием","Соответствие требованиям HIPAA для защиты данных здравоохранения","Валидация нескольких регламентов","Безопасный журнал аудита"],"ar":["حماية البيانات PCI-DSS بتقنيات Масك و تشفير","الامتثال للوائح GDPR مع التسمية البديلة و إدارة الموافقة","الامتثال للوائح HIPAA لحماية بيانات الصحة","التحقق من لوائح متعددة","سجل تدقيق آمن"]},"keywords":{"en":["how to use compliance-manager","compliance-manager setup guide","compliance-manager vs Onasis Gateway","compliance-manager install","what is compliance-manager","compliance-manager alternative","compliance-manager API service","compliance-manager security features","compliance-manager regulatory compliance"],"zh":["Compliance Manager","PCI-DSS","GDPR","PSD2","SOX","HIPAA","数据保护","AI工具","API服务"],"ja":["Compliance Manager","PCI-DSS","GDPR","PSD2","SOX","HIPAA","データ保護","AIエージェント","APIサービス"],"ko":["Compliance Manager","PCI-DSS","GDPR","PSD2","SOX","HIPAA","데이터 보호","AI 에이전트","API 서비스"],"es":["Compliance Manager","protección de datos","cumplimiento normativo","PCI-DSS","GDPR","PSD2","SOX","HIPAA","seguridad de datos","regulaciones de datos"],"fr":["Compliance Manager","protection des données","conformité réglementaire","PCI-DSS","GDPR","PSD2","SOX","HIPAA","sécurité des données","réglementations de données"],"de":["Compliance Manager","Datensicherheit","regulatorische Konformität","PCI-DSS","GDPR","PSD2","SOX","HIPAA","Datenschutz","Datenschutzvorschriften"],"pt":["compliance manager","proteção de dados","PCI-DSS","GDPR","HIPAA","gerenciamento de conformidade","segurança de dados","desenvolvedores"],"ru":["Compliance Manager","защита данных","PCI-DSS","GDPR","HIPAA","управление соответствием","безопасность данных","ИИ Агенты","разработчики"],"ar":["مدير الامتثال","حماية البيانات","PCI-DSS","GDPR","HIPAA","إدارة الامتثال","أمن البيانات","أدوات الذكاء الاصطناعي","مطورون"]}},"owner":"thefixer3x","repo":"onasis-gateway","repoPath":"thefixer3x/onasis-gateway","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.344Z","topics":[],"category":"community","skillMd":{"name":"compliance-manager","description":"Guardrails for edits to core/security/compliance-manager.js that preserve PCI/GDPR/PSD2/SOX/HIPAA controls (masking, encryption, SCA, consent checks, and audit logging). Use when changing compliance validators, security handling, or audit flows.","bodyPreview":"# Compliance Manager Guardian\n\n## Purpose & Scope\n\nApply this skill when modifying `core/security/compliance-manager.js`.\n\nThe Compliance Manager provides:\n- PCI-DSS data protection (card data masking, encryption)\n- GDPR compliance (pseudonymization, consent management, data minimization)\n- PSD2 compliance (Strong Customer Authentication)\n- SOX audit trail requirements\n- HIPAA health data protection\n- Multi-regulation validation framework\n- Secure audit logging\n\n## Non-Negotiables (Never Do)\n\n##","body":"# Compliance Manager Guardian\n\n## Purpose & Scope\n\nApply this skill when modifying `core/security/compliance-manager.js`.\n\nThe Compliance Manager provides:\n- PCI-DSS data protection (card data masking, encryption)\n- GDPR compliance (pseudonymization, consent management, data minimization)\n- PSD2 compliance (Strong Customer Authentication)\n- SOX audit trail requirements\n- HIPAA health data protection\n- Multi-regulation validation framework\n- Secure audit logging\n\n## Non-Negotiables (Never Do)\n\n### Compliance Validators\n- Never disable or bypass compliance validators.\n- Never weaken validation rules (for example, making required checks optional).\n- Never skip validation for \"trusted\" sources.\n- Never add bypass flags or debug modes that skip compliance.\n\n### PCI-DSS Rules\n- Never log these PCI fields (even in debug mode):\n  - `cvv`, `cvv2`, `cvc`, `cvc2`, `cid`, `cav2`\n  - `pin`, `pinBlock`\n  - `track1`, `track2`, `magneticStripe`\n- Never weaken card masking:\n  - Must show only first 6 and last 4 digits.\n  - Middle digits must be masked with `*`.\n- Never reduce encryption below AES-256-GCM.\n- Never store CVV/PIN after authorization.\n\n### GDPR Rules\n- Never process personal data without consent check.\n- Never skip pseudonymization for personal identifiers.\n- Never retain personal data beyond retention period.\n- Never disable data minimization for analytics.\n\n### PSD2 Rules\n- Never reduce SCA requirements below 2 factors.\n- Never bypass SCA for amounts over threshold.\n- Never skip transaction monitoring for high-value transactions.\n- Never disable cumulative amount tracking.\n\n### Audit Logging\n- Never skip audit logging for sensitive operations.\n- Never delete or modify existing audit entries.\n- Never log sensitive data in audit trails (mask first).\n- Never disable audit persistence.\n\n### Security Rollback\n- Never rollback security fixes without security team approval.\n- Never lower security levels in production.\n\n## Required Patterns (Must Follow)\n\n### Card Number Masking\n```javascript\n// Must mask showing only first 6 and last 4\nmaskCardNumber(cardNumber) {\n    const cleaned = cardNumber.replace(/\\D/g, '''');\n    const first6 = cleaned.substring(0, 6);\n    const last4 = cleaned.substring(cleaned.length - 4);\n    const masked = ''*''.repeat(cleaned.length - 10);\n    return `${first6}${masked}${last4}`;\n}\n// Example: 4111111111111111 -> 411111******1111\n```\n\n### Data Encryption\n```javascript\n// Must use AES-256-GCM\nencryptSensitiveData(data) {\n    const algorithm = ''aes-256-gcm'';  // Do not change\n    const key = process.env.ENCRYPTION_KEY;\n    if (!key) throw new Error(''ENCRYPTION_KEY is required'');\n\n    // 12-byte IV is recommended for GCM\n    const iv = crypto.randomBytes(12);\n\n    // Prefer @onasis/security-sdk for key handling if available\n    // If ENCRYPTION_KEY is a passphrase, derive a 32-byte key via scrypt.\n    const keyBuf = (key.length === 64 && /^[0-9a-f]+$/i.test(key))\n        ? Buffer.from(key, ''hex'')\n        : crypto.scryptSync(key, ''onasis-gateway'', 32);\n\n    const cipher = crypto.createCipheriv(''aes-256-gcm'', keyBuf, iv);\n    cipher.setAAD(Buffer.from(''compliance-encryption''));\n\n    const plaintext = typeof data === ''string'' ? data : JSON.stringify(data);\n    const ciphertext = Buffer.concat([cipher.update(plaintext, ''utf8''), cipher.final()]);\n    const authTag = cipher.getAuthTag();\n\n    return {\n        encrypted: ciphertext.toString(''base64''),\n        iv: iv.toString(''hex''),\n        authTag: authTag.toString(''hex''),\n        algorithm\n    };\n}\n```\n\n### Strong Customer Authentication\n```javascript\n// Must require 2+ factors\nvalidateSCA(data) {\n    const factors = [];\n\n    if (data.password || data.pin) factors.push(''knowledge'');\n    if (data.deviceId || data.token) factors.push(''possession'');\n    if (data.biometric || data.fingerprint) factors.push(''inherence'');\n\n    return factors.length >= 2;  // PSD2 requirement\n}\n```\n\n### Defense in Depth\n```javascript\n// Must apply all applicable protections\nenforceDataHandling(serviceId, data, operation) {\n    let processedData = { ...data };\n\n    if (service?.compliance?.pci) {\n        processedData = this.applyPCIProtections(processedData, operation);\n    }\n    if (service?.compliance?.gdpr) {\n        processedData = this.applyGDPRProtections(processedData, operation);\n    }\n    if (service?.compliance?.psd2) {\n        processedData = this.applyPSD2Protections(processedData, operation);\n    }\n\n    return processedData;\n}\n```\n\n### Audit Entry Creation\n```javascript\n// Must create audit entry for all compliance events\nlogAuditEntry(action, details) {\n    const entry = {\n        timestamp: new Date(),\n        action,\n        details,\n        id: crypto.randomUUID()\n    };\n\n    this.auditLog.push(entry);\n    this.emit(''audit:logged'', entry);\n    this.persistAuditEntry(entry);  // Must persist\n}\n```\n\n## Prohibited Fields Registry\n\n| Field | Regulation | Storage | Logging | Transmission |\n|-------|------------|---------|---------|--------------|\n| cvv, cvv2, cvc, cvc2 | PCI-DSS 3.2 | Never | Never | HTTPS only |\n| pin, pinBlock | PCI-DSS 3.4 | Never | Never | Encrypted |\n| track1, track2 | PCI-DSS 3.2 | Never | Never | Never |\n| magneticStripe | PCI-DSS 3.2 | Never | Never | Never |\n| Full card number | PCI-DSS 3.4 | Encrypted | Masked | Encrypted |\n\n## Integration Points\n\n| Component | Integration Method |\n|-----------|-------------------|\n| Base Client | Data passed through `enforceDataHandling()` |\n| Metrics Collector | `compliance_violations_total` metric |\n| API Routes | Middleware for request validation |\n| Database | Audit entries persisted to `audit.compliance_log` |\n\n## Compliance Validation Checklist\n\nBefore deploying changes:\n- [ ] Card data properly masked (first 6, last 4 only).\n- [ ] CVV/PIN never logged or stored.\n- [ ] Encryption uses AES-256-GCM.\n- [ ] SCA requires 2+ factors.\n- [ ] Audit entries created for all operations.\n- [ ] GDPR consent check in place.\n- [ ] Data minimization applied for analytics.\n- [ ] No PII in metric labels.\n- [ ] Audit log persisted to secure storage.\n"},"lastSynced":"2026-03-08T02:03:31.242Z","agentAnalysis":{"suitability":{"en":"Ideal for Security Agents requiring robust compliance features, including PCI-DSS data protection and GDPR compliance.","zh":"适用于需要强大的合规功能的安全代理，包括PCI-DSS数据保护和GDPR合规。","ja":"PCI-DSSデータ保護およびGDPRコンプライアンスを含む堅牢なコンプライアンス機能を必要とするセキュリティエージェントに適しています。","ko":"PCI-DSS 데이터 보호 및 GDPR 규정 준수를 포함하여 강력한 규정 준수 기능이 필요한 보안 에이전트에 적합합니다.","es":"Ideal para Agentes de Seguridad que requieren características de cumplimiento robustas, incluyendo protección de datos PCI-DSS y cumplimiento de GDPR.","fr":"Idéal pour les agents de sécurité nécessitant des fonctionnalités de conformité robustes, notamment la protection des données PCI-DSS et la conformité à la GDPR.","de":"Ideal für Sicherheitsagenten, die robuste Compliance-Funktionen benötigen, einschließlich PCI-DSS-Datenschutz und GDPR-Konformität.","pt":"Ideal para Agentes de Segurança que exigem recursos de conformidade robustos, incluindo proteção de dados PCI-DSS e conformidade com o GDPR.","ru":"Идеально подходит для агентов безопасности, требующих надежных функций соответствия, включая защиту данных PCI-DSS и соблюдение GDPR.","ar":"مثالي للوكلاء الأمنيين الذين يتطلبون ميزات متوافقة قوية، بما في ذلك حماية بيانات PCI-DSS وامتثال GDPR."},"recommendation":{"en":"Empowers agents to enforce multi-regulation validation frameworks, leveraging secure audit logging, and PSD2 compliance with Strong Customer Authentication, while ensuring HIPAA health data protection and SOX audit trail requirements through pseudonymization and consent management.","zh":"赋予代理执行多规则验证框架的能力，利用安全审计日志记录、PSD2合规性以及强客户身份验证，同时通过匿名化和同意管理确保HIPAA健康数据保护和SOX审计跟踪要求。","ja":"マルチ規制バリデーションフレームワークの実施をエージェントに可能にし、セキュアな監査ログ記録、PSD2コンプライアンスおよび強力な顧客認証を活用し、匿名化および同意管理を介してHIPAAヘルスデータ保護およびSOX監査トレイル要件を確保します。","ko":"다중 규제 유효성 검사 프레임워크를 시행할 수 있는 에이전트를 강화하며, 보안 감사 로깅, PSD2 규정 준수 및 강력한 고객 인증을 활용하여, 匿名化 및 동의 관리를 통해 HIPAA 건강 데이터 보호 및 SOX 감사 추적 요구사항을 보장합니다.","es":"Habilita a los agentes a aplicar marcos de validación de multi-regulación, aprovechando la registración de auditorías seguras y el cumplimiento de PSD2 con Autenticación de Cliente Fuerte, al tiempo que garantiza la protección de datos de salud HIPAA y los requisitos de seguimiento de auditorías SOX a través de la pseudonimización y la gestión de consentimientos.","fr":"Permet aux agents d''appliquer des cadres de validation de multi-réglementation, en exploitant l''enregistrement d''audit sécurisé et la conformité à la PSD2 avec une Authentification de Client Forte, tout en assurant la protection des données de santé HIPAA et les exigences de traçabilité d''audit SOX via la pseudonymisation et la gestion des consentements.","de":"Ermächtigt Agenten, Multi-Regulierungs-Validierungsframeworks durchzusetzen, indem sie sich auf sichere Audit-Protokollierung und PSD2-Konformität mit starker Kundenauthentifizierung stützen und gleichzeitig den Schutz von Gesundheitsdaten nach HIPAA und die Anforderungen an Audit-Trails nach SOX durch Pseudonymisierung und Consent-Management sicherstellen.","pt":"Habilita os agentes a aplicar estruturas de validação de regulamentação múltipla, aproveitando o registro de auditoria seguro e o cumprimento da PSD2 com Autenticação de Cliente Forte, garantindo ao mesmo tempo a proteção de dados de saúde HIPAA e os requisitos de auditoria SOX por meio da pseudonimização e gerenciamento de consentimento.","ru":"Наделяет агентов возможностью обеспечивать многорегуляторную валидацию, используя безопасный журнал аудита и соблюдение требований PSD2 с сильной аутентификацией клиентов, гарантируя при этом защиту данных о здоровье в соответствии со стандартами HIPAA и требования аудита SOX посредством псевдонимизации и управления согласием.","ar":"تمكين الوكلاء من فرض إطارات التحقق من 法规 متعددة، واستخدام سجل تدقيق أمني وتوافق PSD2 مع مصادقة العملاء القوية، مع ضمان حماية بيانات الصحة HIPAA ومتطلبات مسار تدقيق SOX من خلال الإسماع والتدبير المصرح به."},"useCases":{"en":["Implementing PCI-DSS data protection with card data masking and encryption","Ensuring GDPR compliance through pseudonymization and consent management","Validating compliance with multiple regulations, including PSD2 and HIPAA"],"zh":["使用卡数据屏蔽和加密来实施PCI-DSS数据保护","通过匿名化和同意管理来确保GDPR合规性","验证多个规则的合规性，包括PSD2和HIPAA"],"ja":["カードデータマスキングおよび暗号化を使用してPCI-DSSデータ保護を実施する","匿名化および同意管理を通じてGDPRコンプライアンスを確保する","PSD2およびHIPAAを含む複数の規制へのコンプライアンスを検証する"],"ko":["카드 데이터 마스킹 및 암호화를 사용하여 PCI-DSS 데이터 보호를 구현하는 것","匿名化 및 동의 관리를 통해 GDPR 규정 준수를 보장하는 것","PSD2 및 HIPAA를 포함한 여러 규제의 규정 준수 여부를 검증하는 것"],"es":["Implementar la protección de datos PCI-DSS con enmascaramiento y cifrado de datos de tarjetas","Garantizar el cumplimiento de GDPR a través de la pseudonimización y la gestión de consentimientos","Validar el cumplimiento de múltiples regulaciones, incluyendo PSD2 y HIPAA"],"fr":["Mettre en œuvre la protection des données PCI-DSS avec le masquage et le chiffrement des données de cartes","Assurer la conformité à la GDPR via la pseudonymisation et la gestion des consentements","Valider la conformité à plusieurs réglementations, notamment PSD2 et HIPAA"],"de":["Implementierung des PCI-DSS-Datenschutzes mit Kartendaten-Maskierung und -Verschlüsselung","Sicherstellung der GDPR-Konformität durch Pseudonymisierung und Consent-Management","Validierung der Konformität mit mehreren Vorschriften, einschließlich PSD2 und HIPAA"],"pt":["Implementar proteção de dados PCI-DSS com mascaramento e criptografia de dados de cartão","Garantir conformidade com o GDPR por meio da pseudonimização e gerenciamento de consentimento","Validar conformidade com várias regulamentações, incluindo PSD2 e HIPAA"],"ru":["Реализовать защиту данных PCI-DSS с помощью маскирования и шифрования данных карт","Обеспечить соответствие GDPR посредством псевдонимизации и управления согласием","Проверить соответствие нескольким регулированиям, включая PSD2 и HIPAA"],"ar":["تنفيذ حماية بيانات PCI-DSS باستخدام التمثيل والمشفرة للبيانات البنكية","ضمان امتثال GDPR من خلال الإسماع والإدارة المصرح بها","التحقق من امتثال عدة لوائح، بما في ذلك PSD2 وHIPAA"]},"limitations":{"en":["Requires integration with core/security/compliance-manager.js","Limited to regulatory frameworks specified, including PCI-DSS, GDPR, PSD2, SOX, and HIPAA"],"zh":["需要与core/security/compliance-manager.js集成","仅限于指定的规则框架，包括PCI-DSS、GDPR、PSD2、SOX和HIPAA"],"ja":["core/security/compliance-manager.jsとの統合が必要","PCI-DSS、GDPR、PSD2、SOX、HIPAAを含む指定された規制フレームワークに限定"],"ko":["core/security/compliance-manager.js와의 통합이 필요","PCI-DSS, GDPR, PSD2, SOX 및 HIPAA를 포함한 지정된 규제 프레임워크로 제한"],"es":["Requiere integración con core/security/compliance-manager.js","Limitado a marcos regulatorios especificados, incluyendo PCI-DSS, GDPR, PSD2, SOX y HIPAA"],"fr":["Nécessite une intégration avec core/security/compliance-manager.js","Limité aux cadres réglementaires spécifiés, notamment PCI-DSS, GDPR, PSD2, SOX et HIPAA"],"de":["Erfordert Integration mit core/security/compliance-manager.js","Begrenzt auf spezifizierte regulatorische Rahmenbedingungen, einschließlich PCI-DSS, GDPR, PSD2, SOX und HIPAA"],"pt":["Exige integração com core/security/compliance-manager.js","Limitado a estruturas regulamentares especificadas, incluindo PCI-DSS, GDPR, PSD2, SOX e HIPAA"],"ru":["Требует интеграции с core/security/compliance-manager.js","Ограничен до указанных нормативных рамок, включая PCI-DSS, GDPR, PSD2, SOX и HIPAA"],"ar":["يتطلب التكامل مع core/security/compliance-manager.js","محدود بالإطارات التنظيمية المحددة، بما في ذلك PCI-DSS وGDPR وPSD2 وSOX وHIPAA"]},"version":4},"contentHash":"c9895cbf636899fc1a3cc513224b6fb85819cfbf2f41f121e91550b2530eee04","qualityScore":36}');
