INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thefixer3x/onasis-gateway/compliance-manager', 'compliance-manager', 'thefixer3x', 'onasis-gateway', 'community', 'compliance-manager thefixer3x onasis-gateway community The Compliance Manager provides comprehensive security features for API services, including PCI-DSS data protection and GDPR compliance. It benefits developers and organizations requiring robust security and regulatory adherence. Compliance Manager提供PCI-DSS数据保护、GDPR合规、PSD2合规等功能，帮助开发者创建安全可靠的API服务 Compliance Managerは、PCI-DSSデータ保護、GDPR準拠、PSD2準拠などを提供するAIエージェントで、開発者が安全で信頼できるAPIサービスを作成するのに役立ちます Compliance Manager는 PCI-DSS 데이터 보호, GDPR 규정 준수, PSD2 규정 준수 등을 제공하는 AI 에이전트로 개발자가 보안이 강화된 API 서비스를 만들 수 있도록 도와줍니다 El Compliance Manager es un servicio de API que proporciona protección de datos y cumplimiento normativo para aplicaciones Le Compliance Manager est un service d''API qui assure la protection des données et la conformité réglementaire pour les applications Der Compliance Manager ist ein API-Service, der Datensicherheit und regulatorische Konformität für Anwendungen bietet O Compliance Manager é uma solução de gerenciamento de conformidade que fornece proteção de dados PCI-DSS, conformidade GDPR e HIPAA Compliance Manager - это решение для управления соответствием требованиям, обеспечивающее защиту данных PCI-DSS, GDPR и HIPAA с помощью ИИ Агентов مدير الامتثال هو حل لإدارة الامتثال يوفر حماية البيانات PCI-DSS و الامتثال للوائح GDPR و HIPAA how to use compliance-manager compliance-manager setup guide compliance-manager vs Onasis Gateway compliance-manager install what is compliance-manager compliance-manager alternative compliance-manager API service compliance-manager security features compliance-manager regulatory compliance Compliance Manager PCI-DSS GDPR PSD2 SOX HIPAA 数据保护 AI工具 API服务 PCI-DSS data protection with card data masking and encryption GDPR compliance through pseudonymization, consent management, and data minimization PSD2 compliance with Strong Customer Authentication SOX audit trail requirements implementation HIPAA health data protection and secure audit logging Multi-regulation validation framework for streamlined compliance Compliance-manager is a comprehensive API service warehouse with MCP server interfaces and REST endpoints, ensuring secure data protection and regulatory compliance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('osoleve/the-fold/troubleshooting', 'community', 'osoleve', 'the-fold', 'osoleve/the-fold', 'troubleshooting', 0, 0, 36, '2026-03-08T01:57:15.345Z', '2026-03-08T02:03:33.470Z', 'b743e94132fef4ebe5ce8022ea5632afe6f29a016f4f6cf769c27343b4736709', '{"id":"osoleve/the-fold/troubleshooting","name":"troubleshooting","description":{"en":"The troubleshooting skill provides a content-addressed homoiconic skill tree for agentic AI, allowing developers to diagnose and fix issues with the Fold daemon and session state. It benefits AI agent developers.","zh":"AI工具故障排除是一种内容寻址的同像技能树，用于解决daemon状态、会话状态腐败和测试挂起的问题","ja":"AIエージェントのトラブルシューティングは、daemonの状態、セッション状態の破損、テストのハングなどの問題を解決するためのコンテンツアドレッシングの同像技能ツリーです","ko":"AI 에이전트 트러블슈팅은 데몬 상태, 세션 상태 손상, 테스트 중단 등의 문제를 해결하기 위한 콘텐츠 주소 지정의 동형 스킬 트리입니다","es":"Nuestra guía de solución de problemas de AI Agents proporciona soluciones técnicas para problemas comunes, como el estado de demonio y la corrupción de estado de sesión","fr":"Notre guide de dépannage d''AI Tools fournit des solutions techniques pour les problèmes courants, tels que l''état du démon et la corruption de l''état de session","de":"Unser Troubleshooting-Leitfaden für AI-Agenten bietet technische Lösungen für häufige Probleme, wie den Daemon-Status und die Sitzungsstatus-Korruption","pt":"O Agentic AI oferece uma árvore de habilidades homoicônica para solução de problemas","ru":"ИИ Агенты предоставляют контент-адресованную homoiconic дерево навыков для решения проблем","ar":"برامج الإيجاد الذكي تقدم شجرة مهارات هوموايكونيك لمساعدة حل المشكلات"},"seo":{"title":{"en":"Troubleshooting: Setup Guide for AI Agents","zh":"AI工具故障排除设置指南","ja":"AIエージェントのトラブルシューティングベストプラクティス","ko":"AI 에이전트 트러블슈팅 가이드","es":"Guía de solución de problemas de AI Agents para desarroll...","fr":"Dépannage d''AI Tools : Guide de configuration et de débogage","de":"Troubleshooting-Leitfaden für AI-Agenten-Entwickler","pt":"Guia de Solução de Problemas para Agentic AI","ru":"Руководство по устранению неполадок ИИ Агентов","ar":"دليل حل المشكلات لبرامج الإيجاد الذكي"},"description":{"en":"Resolve issues with the Fold daemon and session state corruption using these expert troubleshooting tips - learn how to clear stale state and kill orphan wor...","zh":"快速解决AI工具故障排除问题，了解daemon状态、会话状态腐败和测试挂起的解决方法","ja":"AIエージェントのトラブルシューティングに役立つテクニックを紹介。daemonの状態、セッション状態の破損、テストのハングの解決方法など","ko":"AI 에이전트 트러블슈팅을 위한 빠른 해결 방법을 알아보세요. 데몬 상태, 세션 상태 손상, 테스트 중단 등","es":"Soluciona problemas comunes de AI Agents con nuestra guía de solución de problemas y mejora la eficiencia de tus proyectos de desarrollo","fr":"Résolvez les problèmes courants d''AI Tools avec notre guide de dépannage et améliorez l''efficacité de vos projets de développement","de":"Beheben Sie häufige Probleme von AI-Agenten mit unserem Troubleshooting-Leitfaden und verbessern Sie die Effizienz Ihrer Entwicklungsprojekte","pt":"Aprenda a solucionar problemas comuns no Agentic AI com nossa guia de solução de problemas","ru":"Устраняйте неполадки в ИИ Агентах с помощью нашего руководства","ar":"تعلم كيف تحل المشكلات الشائعة في برامج الإيجاد الذكي مع دليلنا"},"definition":{"en":"Troubleshooting is a systematic approach to identifying and resolving issues with the Fold daemon, session state corruption, and other problems in agentic AI systems","zh":"AI工具故障排除是解决AI工具运行中出现的问题的过程","ja":"AIエージェントのトラブルシューティングは、AIエージェントの実行中に発生する問題を解決するためのプロセスです","ko":"AI 에이전트 트러블슈팅은 AI 에이전트 실행 중 발생하는 문제를 해결하는 과정입니다","es":"Solución de problemas de AI Agents es el proceso de identificar y solucionar problemas técnicos en proyectos de desarrollo de AI","fr":"Le dépannage d''AI Tools est le processus d''identification et de résolution des problèmes techniques dans les projets de développement d''AI","de":"Das Troubleshooting von AI-Agenten ist der Prozess der Identifizierung und Behebung technischer Probleme in AI-Entwicklungsprojekten","pt":"Solução de problemas é uma habilidade que ajuda a identificar e corrigir erros no Agentic AI","ru":"Устранение неполадок - это навык, который помогает выявить и исправить ошибки в ИИ Агентах","ar":"حل المشكلات هو مهارة تساعد في تحديد وتصحيح الأخطاء في برامج الإيجاد الذكي"},"features":{"en":["Checks daemon status using ./fold --status command","Clears stale state and kills orphan workers using ./daemon.sh cleanup and ./daemon.sh stop","Resolves session state corruption by removing .fold-repl/ directory","Auto-starts fresh daemon using ./fold \"(help)\"","Diagnoses tests hanging due to fuel consumption and infinite loops"],"zh":["检查daemon状态","解决会话状态腐败","修复测试挂起","使用CLI命令行工具","自动启动daemon"],"ja":["daemonの状態の確認","セッション状態の破損の解決","テストのハングの修復","CLIコマンドラインツールの使用","daemonの自動起動"],"ko":["데몬 상태 확인","세션 상태 손상 해결","테스트 중단 修复","CLI 명령줄 도구 사용","데몬 자동 시작"],"es":["Verificación del estado del demonio con `./fold --status`","Reinicio del demonio con `./daemon.sh stop` y `./daemon.sh start`","Limpieza del estado de sesión con `rm -rf .fold-repl/`","Ejecución de pruebas con fuel consumption","Solución de problemas de bucles infinitos con `./fold \"(help)\"`"],"fr":["Vérification de l''état du démon avec `./fold --status`","Redémarrage du démon avec `./daemon.sh stop` et `./daemon.sh start`","Nettoyage de l''état de session avec `rm -rf .fold-repl/`","Exécution de tests avec fuel consumption","Résolution des problèmes de boucles infinies avec `./fold \"(help)\"`"],"de":["Überprüfung des Daemon-Status mit `./fold --status`","Neustart des Daemons mit `./daemon.sh stop` und `./daemon.sh start`","Bereinigung des Sitzungsstatus mit `rm -rf .fold-repl/`","Ausführung von Tests mit Fuel-Consumption","Behebung von Problemen mit unendlichen Schleifen mit `./fold \"(help)\"`"],"pt":["Verificação do status do daemon","Reinicialização do daemon","Limpeza do estado da sessão","Verificação do consumo de combustível","Auto-inicialização do daemon"],"ru":["Проверка статуса демона","Перезапуск демона","Очистка состояния сессии","Проверка потребления топлива","Автозапуск демона"],"ar":["فحص حالة الدايمون","إعادة تشغيل الدايمون","تنظيف حالة الجلسة","فحص استهلاك الوقود","تشغيل الدايمون تلقائيًا"]},"keywords":{"en":["how to use troubleshooting for AI agents","troubleshooting setup guide","Fold daemon troubleshooting","session state corruption fix","troubleshooting vs debugging","install troubleshooting for AI","what is troubleshooting in agentic AI","troubleshooting alternative for AI developers","resolving tests hanging due to fuel consumption"],"zh":["AI工具故障排除","daemon状态","会话状态腐败","测试挂起","CLI命令行工具","AI工具设置","AI工具调试"],"ja":["AIエージェントのトラブルシューティング","daemonの状態","セッション状態の破損","テストのハング","CLIコマンドラインツール","AIエージェントの設定","AIエージェントのデバッグ"],"ko":["AI 에이전트 트러블슈팅","데몬 상태","세션 상태 손상","테스트 중단","CLI 명령줄 도구","AI 에이전트 설정","AI 에이전트 디버깅"],"es":["solución de problemas de AI Agents","desarrollo de AI","troubleshooting de AI","estado del demonio","corrupción de estado de sesión","pruebas de AI","fuel consumption"],"fr":["dépannage d''AI Tools","développement d''AI","troubleshooting d''AI","état du démon","corruption de l''état de session","tests d''AI","fuel consumption"],"de":["Troubleshooting von AI-Agenten","Entwicklung von AI","Fehlerbehebung von AI","Daemon-Status","Sitzungsstatus-Korruption","AI-Tests","Fuel-Consumption"],"pt":["solução de problemas Agentic AI","guia de solução de problemas","erros comuns Agentic AI","solução de problemas de daemon","limpeza de estado de sessão","consumo de combustível"],"ru":["устранение неполадок ИИ Агентов","руководство по устранению неполадок","обычные ошибки ИИ Агентов","устранение неполадок демона","очистка состояния сессии","потребление топлива"],"ar":["حل مشكلات برامج الإيجاد الذكي","دليل حل المشكلات","أخطاء شائعة في برامج الإيجاد الذكي","حل مشكلات الدايمون","تنظيف حالة الجلسة","استهلاك الوقود"]}},"owner":"osoleve","repo":"the-fold","repoPath":"osoleve/the-fold","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.345Z","topics":[],"category":"community","skillMd":{"name":"troubleshooting","description":"Troubleshooting guide for The Fold - daemon issues, session corruption, file locations, and common problems. Use when ./fold isnt working, the daemon wont start, or you need to find system files.","bodyPreview":"# Troubleshooting The Fold\n\n## Quick Fixes\n\n### Check daemon status\n```bash\n./fold --status\n```\n\n### Daemon won''t start\n```bash\n./daemon.sh stop     # Clear stale state\n./daemon.sh cleanup  # Kill orphan workers\n./daemon.sh start    # Or just run ./fold - it auto-starts\n```\n\n### Session state corruption\n```bash\nrm -rf .fold-repl/   # Nuclear option - clears all session state\n./fold \"(help)\"      # Auto-starts fresh daemon\n```\n\n### Tests hanging\nCheck fuel consumption. Infinite loops exhaust fuel","body":"# Troubleshooting The Fold\n\n## Quick Fixes\n\n### Check daemon status\n```bash\n./fold --status\n```\n\n### Daemon won''t start\n```bash\n./daemon.sh stop     # Clear stale state\n./daemon.sh cleanup  # Kill orphan workers\n./daemon.sh start    # Or just run ./fold - it auto-starts\n```\n\n### Session state corruption\n```bash\nrm -rf .fold-repl/   # Nuclear option - clears all session state\n./fold \"(help)\"      # Auto-starts fresh daemon\n```\n\n### Tests hanging\nCheck fuel consumption. Infinite loops exhaust fuel and return `out-of-fuel` error.\n\n```scheme\n;; In REPL, check fuel status\n(fuel)\n```\n\n## File Locations\n\n### REPL Infrastructure\n\n| Path | Purpose |\n|------|---------|\n| `.fold-repl/ready` | Daemon ready file (presence indicates daemon is running) |\n| `.fold-repl/requests/<session>.ss` | Session request queue |\n| `.fold-repl/responses/<session>.txt` | Session response output |\n| `.fold-repl/daemon.log` | Daemon log (check for errors) |\n\n### Persistent State\n\n| Path | Purpose |\n|------|---------|\n| `.fold-sessions/` | Persistent session state (survives daemon restart) |\n| `.fold-users/` | User profile data |\n\n### Content-Addressed Store\n\n| Path | Purpose |\n|------|---------|\n| `.store/` | Content-addressed store root |\n| `.store/objects/` | CAS objects (blocks) |\n| `.store/heads/bbs/fold-*.head` | BBS issue heads (current hash per issue) |\n| `.store/heads/bbs/post-*.head` | BBS post heads (current hash per post) |\n\n### BBS Runtime\n\n| Path | Purpose |\n|------|---------|\n| `.bbs/` | BBS runtime data |\n| `.bbs/counter` | Next issue ID |\n| `.bbs/deps/` | Dependency tracking |\n| `.bbs/index/` | Search index cache |\n\n### Project Files\n\n| Path | Purpose |\n|------|---------|\n| `TAXONOMY.sexp` | Machine-readable project taxonomy |\n| `CLAUDE.md` | Agent instructions (this file) |\n| `docs/agent-operating-manual.md` | Agent procedures |\n\n## Common Issues\n\n### \"Daemon not responding\"\n\n1. Check if daemon is running: `./fold --status`\n2. Check daemon log: `cat .fold-repl/daemon.log`\n3. Kill and restart: `./daemon.sh stop && ./fold --status`\n\n### \"Session not found\"\n\nSessions are ephemeral unless named with `-s`:\n```bash\n./fold -s mywork \"(define x 10)\"  # Creates named session\n./fold -s mywork \"x\"              # Uses same session\n```\n\n### \"Module not found\" during require\n\n1. Check you''re in project root (where `core/`, `lattice/`, `boundary/` live)\n2. Verify module exists: `ls lattice/<module>/`\n3. Check for typos in module name\n\n### \"Out of fuel\" error\n\nThe expression exceeded its fuel budget. Options:\n- Simplify the expression\n- Check for infinite recursion\n- Increase fuel budget (if safe)\n\n### \"Hash mismatch\" or CAS errors\n\nThe CAS store may be corrupted. Options:\n1. Check `.store/` permissions\n2. Run integrity check: `./fold \"(cas-verify)\"`\n3. Rebuild from git: `rm -rf .store && ./fold \"(cas-rebuild)\"`\n\n### BBS shows stale data\n\nAfter reloading modules, refresh BBS state:\n```scheme\n(bbs-init!)  ; Refresh from disk\n```\n"},"lastSynced":"2026-03-08T02:03:33.470Z","agentAnalysis":{"suitability":{"en":"Ideal for Agentic AI Developers needing advanced Fold daemon and session state debugging capabilities.","zh":"适合需要高级 Fold 守护进程和会话状态调试功能的 Agentic AI 开发人员。","ja":"Agentic AI 開発者が高度な Fold デーモンおよびセッション状態のデバッグ機能を必要とする場合に適しています。","ko":"고급 Fold 데몬 및 세션 상태 디버깅 기능이 필요한 Agentic AI 개발자에게 적합합니다.","es":"Ideal para desarrolladores de AI Agentic que necesitan capacidades avanzadas de depuración de daemon Fold y estado de sesión.","fr":"Idéal pour les développeurs d''AI Agentic ayant besoin de fonctionnalités avancées de débogage de daemon Fold et d''état de session.","de":"Ideal für Agentic-AI-Entwickler, die erweiterte Funktionen zur Fehlersuche für Fold-Daemon und Sitzungsstatus benötigen.","pt":"Ideal para desenvolvedores de AI Agentic que necessitam de capacidades avançadas de depuração de daemon Fold e estado de sessão.","ru":"Идеально для разработчиков Agentic AI, которым требуются расширенные возможности отладки демона Fold и состояния сессии.","ar":"مثالي لمطوري الذكاء الاصطناعي Agentic الذين يحتاجون إلى機能 متقدمة لتصحيح أخطاء daemon Fold و حالة الجلسة."},"recommendation":{"en":"Empowers agents to diagnose and fix issues with the Fold daemon and session state using content-addressed homoiconic skill trees, providing quick fixes for daemon status checks, session state corruption, and test hangs, leveraging bash scripts and daemon management.","zh":"赋予代理诊断和修复 Fold 守护进程和会话状态问题的能力，使用基于内容的同像技能树，提供守护进程状态检查、会话状态损坏和测试挂起的快速解决方案，利用 bash 脚本和守护进程管理。","ja":"エージェントに Fold デーモンおよびセッション状態の問題を診断して修正する能力を付与します。コンテンツアドレッシングのホモアイコニック スキルツリーを使用して、デーモンの状態チェック、セッション状態の破損、テストのハングなど、迅速な解決策を提供します。さらに、bash スクリプトとデーモンの管理を活用します。","ko":"에이전트가 Fold 데몬 및 세션 상태 문제를 진단하고 수정할 수 있는 기능을 제공하며, 콘텐츠 주소 지정 호모아이кон 스킬 트리를 사용하여 데몬 상태 검사, 세션 상태 손상 및 테스트 중단과 같은 빠른 해결책을 제공하며, bash 스크립트 및 데몬 관리를 활용합니다.","es":"Permite a los agentes diagnosticar y solucionar problemas con el daemon Fold y el estado de sesión utilizando árboles de habilidades homoicónicos direccionados por contenido, proporcionando soluciones rápidas para comprobaciones de estado de daemon, corrupción de estado de sesión y bloqueos de prueba, aprovechando scripts de bash y administración de daemon.","fr":"Permet aux agents de diagnostiquer et de résoudre les problèmes avec le daemon Fold et l''état de session en utilisant des arbres de compétences homoicóniques adressés par contenu, fournissant des solutions rapides pour les vérifications d''état de daemon, la corruption d''état de session et les blocages de test, en exploitant les scripts bash et la gestion de daemon.","de":"Ermöglich es den Agenten, Probleme mit dem Fold-Daemon und dem Sitzungsstatus zu diagnostizieren und zu beheben, indem sie inhaltsadressierte homoikonische Fähigkeitsbäume verwenden, wodurch schnelle Lösungen für Daemon-Statusprüfungen, Sitzungsstatuskorruption und Testblockaden bereitgestellt werden, indem bash-Skripte und Daemon-Verwaltung genutzt werden.","pt":"Habilita os agentes a diagnosticar e corrigir problemas com o daemon Fold e o estado de sessão usando árvores de habilidades homoicônicas com endereçamento de conteúdo, fornecendo soluções rápidas para verificações de status do daemon, corrupção de estado de sessão e travas de teste, aproveitando scripts bash e gerenciamento de daemon.","ru":"Наделяет агентов возможностью диагностировать и исправлять проблемы с демоном Fold и состоянием сессии, используя деревья навыков с содержательным адресованием, обеспечивающие быстрые исправления для проверок состояния демона, повреждения состояния сессии и зависаний тестов, используя скрипты bash и управление демоном.","ar":"تمكّن الوكيل من تشخيص ومعالجة المشاكل المتعلقة بdaemon Fold و حالة الجلسة باستخدام أشجار المهارات ذات العنونة المحتوى، وتوفير حلول سريعة لفحوصات حالة الدемон وفساد حالة الجلسة وتعليق الاختبارات، بالاستفادة من سكريبتات bash وإدارة الدемон."},"useCases":{"en":["Debugging daemon startup issues","Resolving session state corruption","Identifying and resolving test hangs due to fuel consumption","Performing nuclear resets of session state"],"zh":["调试守护进程启动问题","解决会话状态损坏问题","识别和解决由于燃料消耗导致的测试挂起问题","执行会话状态的核重置"],"ja":["デーモンの起動問題のデバッグ","セッション状態の破損の解決","燃料消費によるテストのハングの特定と解決","セッション状態の核リセットの実行"],"ko":["데몬 시작 문제 디버깅","세션 상태 손상 문제 해결","연료 소모로 인한 테스트 중단 문제 식별 및 해결","세션 상태의 핵 리셋 수행"],"es":["Depuración de problemas de inicio de daemon","Resolución de corrupción de estado de sesión","Identificación y resolución de bloqueos de prueba debido al consumo de combustible","Realización de restablecimientos nucleares del estado de sesión"],"fr":["Débogage des problèmes de démarrage de daemon","Résolution de la corruption d''état de session","Identification et résolution des blocages de test dus à la consommation de carburant","Réinitialisation nucléaire de l''état de session"],"de":["Fehlersuche bei Daemon-Startproblemen","Behebung von Sitzungsstatuskorruption","Identifizierung und Behebung von Testblockaden aufgrund von Treibstoffverbrauch","Durchführung von Kernrücksetzungen des Sitzungsstatus"],"pt":["Depuração de problemas de inicialização do daemon","Resolução de corrupção de estado de sessão","Identificação e resolução de travas de teste devido ao consumo de combustível","Realização de reinicializações nucleares do estado de sessão"],"ru":["Отладка проблем запуска демона","Решение проблемы повреждения состояния сессии","Определение и решение проблем зависаний тестов из-за потребления топлива","Выполнение ядерных перезагрузок состояния сессии"],"ar":["تصحيح أخطاء بدء تشغيل الدемон","حل مشكلة فساد حالة الجلسة","تحديد ومعالجة مشاكل تعليق الاختبارات بسبب استهلاك الوقود","إجراء إعادة تشغيل نووي لحالة الجلسة"]},"limitations":{"en":["Requires Fold daemon installation","Bash script execution required","Limited to Fold daemon and session state troubleshooting"],"zh":["需要 Fold 守护进程安装","需要 bash 脚本执行","仅限 Fold 守护进程和会话状态故障排除"],"ja":["Fold デーモンのインストールが必要","bash スクリプトの実行が必要","Fold デーモンおよびセッション状態のトラブルシューティングのみ"],"ko":["Fold 데몬 설치가 필요합니다","bash 스크립트 실행이 필요합니다","Fold 데몬 및 세션 상태 문제 해결만 가능"],"es":["Requiere instalación de daemon Fold","Se requiere ejecución de scripts de bash","Limitado a la solución de problemas de daemon Fold y estado de sesión"],"fr":["Nécessite l''installation de daemon Fold","Exécution de scripts bash requise","Limité au débogage de daemon Fold et d''état de session"],"de":["Erfordert Fold-Daemon-Installation","Bash-Skriptausführung erforderlich","Begrenzt auf Fehlersuche für Fold-Daemon und Sitzungsstatus"],"pt":["Requer instalação do daemon Fold","Execução de script bash necessária","Limitado à depuração do daemon Fold e do estado de sessão"],"ru":["Требуется установка демона Fold","Требуется выполнение скрипта bash","Ограничен отладкой демона Fold и состояния сессии"],"ar":["يتطلب تثبيت الدемон Fold","يتطلب تنفيذ سكريبت bash","محدود بتصحيح أخطاء الدемон Fold وحالة الجلسة"]},"version":4},"contentHash":"b743e94132fef4ebe5ce8022ea5632afe6f29a016f4f6cf769c27343b4736709","qualityScore":36}');
