INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('osoleve/the-fold/troubleshooting', 'troubleshooting', 'osoleve', 'the-fold', 'community', 'troubleshooting osoleve the-fold community The troubleshooting skill provides a content-addressed homoiconic skill tree for agentic AI, allowing developers to diagnose and fix issues with the Fold daemon and session state. It benefits AI agent developers. AI工具故障排除是一种内容寻址的同像技能树，用于解决daemon状态、会话状态腐败和测试挂起的问题 AIエージェントのトラブルシューティングは、daemonの状態、セッション状態の破損、テストのハングなどの問題を解決するためのコンテンツアドレッシングの同像技能ツリーです AI 에이전트 트러블슈팅은 데몬 상태, 세션 상태 손상, 테스트 중단 등의 문제를 해결하기 위한 콘텐츠 주소 지정의 동형 스킬 트리입니다 Nuestra guía de solución de problemas de AI Agents proporciona soluciones técnicas para problemas comunes, como el estado de demonio y la corrupción de estado de sesión Notre guide de dépannage d''AI Tools fournit des solutions techniques pour les problèmes courants, tels que l''état du démon et la corruption de l''état de session Unser Troubleshooting-Leitfaden für AI-Agenten bietet technische Lösungen für häufige Probleme, wie den Daemon-Status und die Sitzungsstatus-Korruption O Agentic AI oferece uma árvore de habilidades homoicônica para solução de problemas ИИ Агенты предоставляют контент-адресованную homoiconic дерево навыков для решения проблем برامج الإيجاد الذكي تقدم شجرة مهارات هوموايكونيك لمساعدة حل المشكلات how to use troubleshooting for AI agents troubleshooting setup guide Fold daemon troubleshooting session state corruption fix troubleshooting vs debugging install troubleshooting for AI what is troubleshooting in agentic AI troubleshooting alternative for AI developers resolving tests hanging due to fuel consumption AI工具故障排除 daemon状态 会话状态腐败 测试挂起 CLI命令行工具 AI工具设置 AI工具调试 Checks daemon status using ./fold --status command Clears stale state and kills orphan workers using ./daemon.sh cleanup and ./daemon.sh stop Resolves session state corruption by removing .fold-repl/ directory Auto-starts fresh daemon using ./fold "(help)" Diagnoses tests hanging due to fuel consumption and infinite loops Troubleshooting is a systematic approach to identifying and resolving issues with the Fold daemon, session state corruption, and other problems in agentic AI systems');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('heyuan110/heyuan110.github.io/blog-writer', 'community', 'heyuan110', 'heyuan110.github.io', 'heyuan110/heyuan110.github.io', 'blog-writer', 0, 0, 36, '2026-03-08T01:57:15.345Z', '2026-03-08T02:03:35.635Z', 'ecd16c447194b3e0451956a05ee84cb67872eea42d8a5ec1a1dc36bec5a816f0', '{"id":"heyuan110/heyuan110.github.io/blog-writer","name":"blog-writer","description":{"en":"The blog-writer skill generates technical blog posts using Hugo and hermit-V2 theme, benefiting developers and content creators. It streamlines the writing process with a structured approach.","zh":"博客写作专家技能使用 Hugo 和 AI 技术生成高质量的博客内容","ja":"AIエージェントのブログライター機能は、HugoとAI技術で高品質のブログコンテンツを生成する","ko":"블로그 작성 전문가 스킬은 Hugo와 AI 기술로 고품질 블로그 콘텐츠를 생성한다","es":"El agente de escritura de blogs AI utiliza Hugo y hermit-V2 para crear contenido técnico. Aprende a configurarlo y utilizarlo para tus necesidades de desarrollo.","fr":"L''agent d''écriture de blogs AI utilise Hugo et hermit-V2 pour créer du contenu technique. Découvrez comment le configurer et l''utiliser pour vos besoins de développement.","de":"Der Blog-Schreiber-AI-Agent verwendet Hugo und hermit-V2, um technische Inhalte zu erstellen. Erfahren Sie, wie Sie ihn einrichten und verwenden können, um Ihre Entwicklungsaufgaben zu erfüllen.","pt":"O blog-writer é uma ferramenta de criação de conteúdo que utiliza Hugo v0.153.2+ e tema hermit-V2 para produzir artigos de qualidade","ru":"ИИ Агент blog-writer является инструментом для создания контента, который использует Hugo v0.153.2+ и тему hermit-V2 для производства качественных статей","ar":"وكيل المدونة blog-writer هو أداة لإنشاء المحتوى التي تستخدم Hugo v0.153.2+ وسمة hermit-V2 لإنتاج مقالات عالية الجودة"},"seo":{"title":{"en":"blog-writer: Technical Blog Post Generation Setup Guide |...","zh":"博客写作专家：Hugo 博客搭建和 AI 内容生成","ja":"AIエージェントのためのブログライター：HugoとAIコンテンツの生成","ko":"블로그 작성 전문가: Hugo 블로그 설정 및 AI 콘텐츠 생성","es":"Guía de configuración de blog-writer para desarrolladores","fr":"Guide de mise en place de blog-writer pour les développeurs","de":"Einrichtungsleitfaden für blog-writer für Entwickler","pt":"Guia de Configuração do blog-writer para Desenvolvedores","ru":"Настройка ИИ Агента blog-writer: Руководство для Разработ...","ar":"دليل تنصيب وكيل المدونة blog-writer للأشخاص المطورين"},"description":{"en":"Unlock efficient blog writing with our AI agent skill, featuring Hugo v0.153.2+ and hermit-V2 theme. Get started now and streamline your content creation!","zh":"使用博客写作专家技能，通过 Hugo 和 AI 技术生成高质量的博客内容，提高搜索引擎排名","ja":"AIエージェントのブログライター機能を使用して、HugoとAI技術で高品質のブログコンテンツを生成し、検索エンジンランキングを向上させる","ko":"블로그 작성 전문가 스킬을 사용하여 Hugo와 AI 기술로 고품질 블로그 콘텐츠를 생성하고 검색 엔진 순위를 높여라","es":"Aprende a configurar y utilizar el agente de escritura de blogs AI para crear contenido técnico de alta calidad con Hugo y hermit-V2","fr":"Découvrez comment configurer et utiliser l''agent d''écriture de blogs AI pour créer du contenu technique de haute qualité avec Hugo et hermit-V2","de":"Erfahren Sie, wie Sie den Blog-Schreiber-AI-Agent einrichten und verwenden können, um technische Inhalte von hoher Qualität mit Hugo und hermit-V2 zu erstellen","pt":"Aprenda a configurar o blog-writer com Hugo v0.153.2+ e tema hermit-V2 para criar conteúdo de qualidade","ru":"Узнайте, как настроить ИИ Агента blog-writer с Hugo v0.153.2+ и темой hermit-V2 для создания качественного контента","ar":"تعلم كيفية تنصيب وكيل المدونة blog-writer باستخدام Hugo v0.153.2+ وسمة hermit-V2 لإنشاء محتوى عالي الجودة"},"definition":{"en":"blog-writer is a technical blog post generation skill utilizing Hugo and hermit-V2 theme to produce high-quality content","zh":"博客写作专家是一种使用 Hugo 和 AI 技术生成高质量博客内容的技能","ja":"ブログライターは、HugoとAI技術で高品質のブログコンテンツを生成するAIエージェントの機能","ko":"블로그 작성 전문가는 Hugo와 AI 기술로 고품질 블로그 콘텐츠를 생성하는 스킬","es":"Un agente de escritura de blogs AI es una herramienta que utiliza inteligencia artificial para crear contenido de blog de alta calidad","fr":"Un agent d''écriture de blogs AI est un outil qui utilise l''intelligence artificielle pour créer du contenu de blog de haute qualité","de":"Ein Blog-Schreiber-AI-Agent ist ein Tool, das künstliche Intelligenz verwendet, um hochwertige Blog-Inhalte zu erstellen","pt":"O blog-writer é uma ferramenta de criação de conteúdo automática","ru":"ИИ Агент blog-writer является автоматическим инструментом для создания контента","ar":"وكيل المدونة blog-writer هو أداة автоматية لإنشاء المحتوى"},"features":{"en":["Utilizes Hugo v0.153.2+ (Extended) for blog post generation","Supports hermit-V2 theme for customizable content presentation","Stores content in the `content/posts/` directory for easy management","Enforces a structured writing flow with mandatory steps for high-quality output","Allows for optional target keyword specification for SEO optimization","Integrates with external resources like URLs, documents, and GitHub repositories for reference"],"zh":["支持 Hugo v0.153.2+ (Extended) 版本","使用 hermit-V2 主题","内容目录存储在 `content/posts/` 中","强制执行流程，确保内容质量","支持目标关键词设置"],"ja":["Hugo v0.153.2+ (Extended) バージョンのサポート","hermit-V2 テーマの使用","コンテンツディレクトリは `content/posts/` に保存","強制実行プロセスにより、コンテンツ品質を確保","目標キーワードの設定をサポート"],"ko":["Hugo v0.153.2+ (Extended) 버전 지원","hermit-V2 테마 사용","콘텐츠 디렉토리는 `content/posts/`에 저장","강제 실행 프로세스로 콘텐츠 품질 보장","목표 키워드 설정 지원"],"es":["Utiliza Hugo v0.153.2+ (Extended) para la creación de contenido","Soporta el tema hermit-V2 para una mayor personalización","Permite la configuración de metadatos y palabras clave para SEO","Utiliza un directorio de contenido `content/posts/` para la organización de posts","Requiere la confirmación de los requisitos del usuario antes de comenzar a escribir","Soporta la creación de contenido técnico con enlaces de referencia y documentación"],"fr":["Utilise Hugo v0.153.2+ (Extended) pour la création de contenu","Prend en charge le thème hermit-V2 pour une personnalisation accrue","Permet la configuration des métadonnées et des mots-clés pour le SEO","Utilise un répertoire de contenu `content/posts/` pour l''organisation des billets","Exige la confirmation des exigences de l''utilisateur avant de commencer à écrire","Prend en charge la création de contenu technique avec des liens de référence et de documentation"],"de":["Verwendet Hugo v0.153.2+ (Extended) für die Erstellung von Inhalten","Unterstützt das hermit-V2-Theme für eine größere Anpassungsfähigkeit","Ermöglicht die Konfiguration von Metadaten und Schlüsselwörtern für SEO","Verwendet ein Inhaltsverzeichnis `content/posts/` für die Organisation von Beiträgen","Erfordert die Bestätigung der Benutzeranforderungen vor Beginn der Erstellung","Unterstützt die Erstellung von technischen Inhalten mit Referenzlinks und Dokumentation"],"pt":["Utiliza Hugo v0.153.2+ para gerar conteúdo","Tema hermit-V2 personalizável","Suporte a categorias pré-definidas","Otimização para palavras-chave","Integração com referências externas"],"ru":["Использует Hugo v0.153.2+ для генерации контента","Тема hermit-V2 с возможностью настройки","Поддержка предопределенных категорий","Оптимизация для ключевых слов","Интеграция с внешними ссылками"],"ar":["يستخدم Hugo v0.153.2+ لإنشاء المحتوى","سمة hermit-V2 قابلة للتخصيص","دعم الفئات المحددة مسبقًا","تحسين محركات البحث لالكلمات المفتاحية","التكامل مع المراجع الخارجية"]},"keywords":{"en":["how to use blog-writer","blog-writer alternative","blog-writer setup guide","what is blog-writer","blog-writer vs ghost","install blog-writer","hugo blog post generation","hermit-V2 theme tutorial","technical blog writing tips"],"zh":["博客写作专家","Hugo 博客","AI 内容生成","搜索引擎排名","高质量内容","hermit-V2 主题","目标关键词设置"],"ja":["AIエージェント","ブログライター","Hugo ブログ","AI コンテンツ生成","検索エンジンランキング","高品質コンテンツ","hermit-V2 テーマ","目標キーワード設定"],"ko":["블로그 작성 전문가","Hugo 블로그","AI 콘텐츠 생성","검색 엔진 순위","고품질 콘텐츠","hermit-V2 테마","목표 키워드 설정"],"es":["agente de escritura de blogs AI","herramientas de escritura de blogs","Hugo","hermit-V2","SEO para blogs","creación de contenido técnico","desarrollo web","herramientas de desarrollo"],"fr":["agent d''écriture de blogs AI","outils d''écriture de blogs","Hugo","hermit-V2","SEO pour les blogs","création de contenu technique","développement web","outils de développement"],"de":["Blog-Schreiber-AI-Agent","Blog-Schreiber-Tools","Hugo","hermit-V2","SEO für Blogs","Erstellung von technischen Inhalten","Webentwicklung","Entwicklungstools"],"pt":["blog-writer","Hugo","hermit-V2","criação de conteúdo","otimização de SEO","desenvolvimento web","ferramentas de desenvolvimento","automatização de conteúdo","geração de conteúdo"],"ru":["ИИ Агент blog-writer","Hugo","hermit-V2","создание контента","оптимизация SEO","веб-разработка","инструменты разработки","автоматизация контента","генерация контента"],"ar":["وكيل المدونة blog-writer","Hugo","hermit-V2","إنشاء المحتوى","تحسين محركات البحث","تطوير الويب","أدوات التطوير","أتمتة المحتوى","إنشاء المحتوى"]}},"owner":"heyuan110","repo":"heyuan110.github.io","repoPath":"heyuan110/heyuan110.github.io","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.345Z","topics":[],"category":"community","skillMd":{"name":"blog-writer","description":"技术博客写作专家，专注于 AI、编程、运维等技术领域的深度写作。自动抓取素材、生成配图、输出符合 Hugo 规范的博客文章。使用此 skill 当用户需要：(1) 撰写技术博客文章 (2) 整理技术资料成文章 (3) 介绍新工具/新技术","bodyPreview":"# 技术博客写作专家\n\n## 博客信息\n\n- **博客地址**: https://www.heyuan110.com/\n- **Hugo 版本**: v0.153.2+ (Extended)\n- **主题**: hermit-V2\n- **内容目录**: `content/posts/`\n\n---\n\n## 强制执行流程\n\n⚠️ **每一步必须完成后才能进入下一步，不可跳过。**\n\n---\n\n### Step 0: 确认需求\n\n在开始任何工作之前，**必须**向用户确认以下信息：\n\n1. **主题**：您想写什么内容？\n2. **素材**：有参考链接吗？（URL、文档、GitHub 仓库等）\n3. **目标关键词**：希望用户搜索什么词找到文章？（可选）\n\n如果用户已在指令中提供了这些信息，无需重复询问，直接进入 Step 1。\n\n---\n\n### Step 1: 确定分类和目录\n\n#### 分类规范\n\n根据文章内容选择分类，**只能使用以下预设值，禁止自创分类**：\n\n| 分类 | 适用内容 |\n|------|----------|\n| **AI Guides** | 教程、指南、安","body":"# 技术博客写作专家\n\n## 博客信息\n\n- **博客地址**: https://www.heyuan110.com/\n- **Hugo 版本**: v0.153.2+ (Extended)\n- **主题**: hermit-V2\n- **内容目录**: `content/posts/`\n\n---\n\n## 强制执行流程\n\n⚠️ **每一步必须完成后才能进入下一步，不可跳过。**\n\n---\n\n### Step 0: 确认需求\n\n在开始任何工作之前，**必须**向用户确认以下信息：\n\n1. **主题**：您想写什么内容？\n2. **素材**：有参考链接吗？（URL、文档、GitHub 仓库等）\n3. **目标关键词**：希望用户搜索什么词找到文章？（可选）\n\n如果用户已在指令中提供了这些信息，无需重复询问，直接进入 Step 1。\n\n---\n\n### Step 1: 确定分类和目录\n\n#### 分类规范\n\n根据文章内容选择分类，**只能使用以下预设值，禁止自创分类**：\n\n| 分类 | 适用内容 |\n|------|----------|\n| **AI Guides** | 教程、指南、安装配置、工具使用、最佳实践、产品评测、工作流 |\n| **Comparisons** | 工具对比、定价对比、基准测试 |\n\n> ⚠️ 以下为归档的旧中文分类，**仅用于已有旧文章**，新文章禁止使用：\n> AI原理、AI实战、Go、Java、Python、Docker、Linux、MySQL、macOS\n\n❌ 错误示例：`AI实战`、`Go实战`、`Docker教程`（这些都是无效分类）\n✅ 正确示例：写 AI 工具教程用 `categories = [''AI Guides'']`，写工具对比用 `categories = [''Comparisons'']`\n\n#### 目录命名\n\n使用 Page Bundle 结构，命名规范：`<日期>-<英文短标题>/`\n\n```\ncontent/posts/ai/2026-01-26-claude-code-guide/\n├── index.md      # 文章内容\n├── cover.webp    # 封面图（必须叫 cover.webp）\n└── other.webp    # 其他配图\n```\n\n⚠️ **必须**用 `date` 命令获取当前日期，URL 目录名只用英文。\n\n---\n\n### Step 2: 收集素材\n\n#### 2.1 读取用户提供的素材\n\n如果用户提供了参考链接，**必须认真阅读链接内容**，不可仅凭标题猜测：\n\n- **读取方式优先级**：\n  1. 首选 `WebFetch` 工具\n  2. 如遇反爬虫/403/访问限制，改用 Playwright MCP（`browser_navigate` + `browser_snapshot`）\n  3. 如果是 GitHub 链接，可用 `gh` 命令或访问 raw 内容\n- **特别关注**：核心观点、文章结构、配图含义、代码示例、技术细节\n\n#### 2.2 主动研究补充\n\n⚠️ **必须**执行以下主动研究，不能仅依赖用户提供的素材：\n\n- 使用 `WebSearch` 搜索该主题的**最新进展和权威资料**\n- 检查是否有该领域的**经典内容、官方文档、最佳实践**被遗漏\n- 搜索**对比观点或争议点**，确保文章视角全面\n- 如果涉及工具/框架，查找**官方文档和 GitHub 仓库**获取准确信息\n\n#### 2.3 获取已有文章列表（为内链做准备）\n\n⚠️ **必须**执行以下命令，获取博客已有文章目录：\n\n```bash\nls content/posts/ai/\n```\n\n记录已有文章列表，在 Step 4 撰写时用于添加内链。\n\n---\n\n### Step 3: 生成封面图\n\n⚠️ **必须**为每篇文章生成封面图。按以下优先级尝试：\n\n#### 方案 A（首选）：Rube MCP + Gemini AI 生图\n\n通过 Rube MCP 调用 `GEMINI_GENERATE_IMAGE` 生成封面图：\n\n**第一步：搜索工具并获取 session_id**\n\n调用 `RUBE_SEARCH_TOOLS` 搜索图像生成工具：\n```\nqueries: [{use_case: \"generate an AI image from a text prompt for a blog cover\"}]\nsession: {generate_id: true}\n```\n\n**第二步：生成图片**\n\n调用 `RUBE_MULTI_EXECUTE_TOOL` 执行生图：\n```\ntools: [{\n  tool_slug: \"GEMINI_GENERATE_IMAGE\",\n  arguments: {\n    prompt: \"基于文章主题的详细英文描述，描述画面内容、风格、色调\",\n    model: \"gemini-2.5-flash-image\",\n    aspect_ratio: \"16:9\"\n  }\n}]\nsession_id: \"上一步返回的 session_id\"\nsync_response_to_workbench: false\nmemory: {}\n```\n\n**提示词要求**：\n- 用**英文**撰写提示词（Gemini 对英文效果更好）\n- 描述具体的画面内容、风格、色调\n- 风格要求：科技感、简洁、专业，适合技术博客封面\n- 避免包含文字（AI 生成的文字通常不准确）\n\n**第三步：下载并转换**\n\n图片 URL 在返回结果的 `data.image.s3url` 中（URL 有时效，需尽快下载）：\n\n```bash\n# 下载 AI 生成的图片\ncurl -L -o cover_raw.png \"<s3url>\"\n\n# 转换为 webp 并调整尺寸\ncwebp -q 85 -resize 1200 630 cover_raw.png -o cover.webp\n\n# 清理临时文件\nrm cover_raw.png\n```\n\n如果 `cwebp` 不可用，使用 Python 转换：\n```python\npython3 -c \"\nfrom PIL import Image\nimg = Image.open(''cover_raw.png'').resize((1200, 630), Image.LANCZOS)\nimg.save(''cover.webp'', ''WEBP'', quality=85)\nimport os; os.remove(''cover_raw.png'')\n\"\n```\n\n如果 AI 生图失败（连接不可用、安全过滤拦截等），使用方案 B。\n\n#### 方案 B（兜底）：Python/Pillow 程序化生成\n\n当 AI 生图不可用时，执行以下 Python 脚本生成封面图（根据文章主题调整标题和关键词）：\n\n```python\npython3 -c \"\nfrom PIL import Image, ImageDraw, ImageFont\nimport subprocess\n\n# === Config: modify per article ===\nTITLE = ''Article Title Here''           # Cover title (English)\nSUBTITLE = ''Brief description''         # Subtitle (English)\nTAGS = [''Tag1'', ''Tag2'', ''Tag3'']        # Keyword tags (English)\nOUTPUT_DIR = ''content/posts/ai/directory-name''  # Article directory path\n# === End config ===\n\nWIDTH, HEIGHT = 1200, 630\nimg = Image.new(''RGB'', (WIDTH, HEIGHT))\ndraw = ImageDraw.Draw(img)\n\n# 深色渐变背景\nfor y in range(HEIGHT):\n    r = int(15 + (25 - 15) * y / HEIGHT)\n    g = int(23 + (35 - 23) * y / HEIGHT)\n    b = int(42 + (60 - 42) * y / HEIGHT)\n    draw.line([(0, y), (WIDTH, y)], fill=(r, g, b))\n\n# 装饰元素：顶部渐变线条\nfor x in range(WIDTH):\n    alpha = int(255 * (1 - abs(x - WIDTH/2) / (WIDTH/2)))\n    draw.line([(x, 0), (x, 3)], fill=(100, 149, 237, alpha))\n\n# 加载字体（macOS 系统字体，按优先级尝试多个）\n# 新文章为英文，以下字体均支持英文显示\nFONT_PATHS = [\n    ''/System/Library/Fonts/STHeiti Medium.ttc'',\n    ''/System/Library/Fonts/STHeiti Light.ttc'',\n    ''/Library/Fonts/Arial Unicode.ttf'',\n    ''/System/Library/Fonts/PingFang.ttc'',\n    ''/System/Library/Fonts/Hiragino Sans GB.ttc'',\n    ''/System/Library/Fonts/Supplemental/Songti.ttc'',\n]\n\ndef load_font(size):\n    for path in FONT_PATHS:\n        try:\n            return ImageFont.truetype(path, size)\n        except (IOError, OSError):\n            continue\n    raise RuntimeError(''No suitable font found. Please check font paths.'')\n\nfont_title = load_font(52)\nfont_subtitle = load_font(28)\nfont_tag = load_font(20)\n\n# 绘制标题（自动换行）\nmax_width = WIDTH - 120\nwords = TITLE\nlines = []\ncurrent_line = ''''\nfor char in words:\n    test_line = current_line + char\n    bbox = draw.textbbox((0, 0), test_line, font=font_title)\n    if bbox[2] - bbox[0] > max_width:\n        lines.append(current_line)\n        current_line = char\n    else:\n        current_line = test_line\nif current_line:\n    lines.append(current_line)\n\ny_offset = 180 if len(lines) <= 2 else 140\nfor line in lines:\n    bbox = draw.textbbox((0, 0), line, font=font_title)\n    x = (WIDTH - (bbox[2] - bbox[0])) // 2\n    draw.text((x, y_offset), line, fill=''white'', font=font_title)\n    y_offset += 70\n\n# 绘制副标题\nif SUBTITLE:\n    bbox = draw.textbbox((0, 0), SUBTITLE, font=font_subtitle)\n    x = (WIDTH - (bbox[2] - bbox[0])) // 2\n    draw.text((x, y_offset + 20), SUBTITLE, fill=(180, 180, 200), font=font_subtitle)\n\n# 绘制标签\ntag_y = HEIGHT - 80\ntotal_width = sum(draw.textbbox((0, 0), f'' {t} '', font=font_tag)[2] - draw.textbbox((0, 0), f'' {t} '', font=font_tag)[0] + 24 for t in TAGS) + 12 * (len(TAGS) - 1)\ntag_x = (WIDTH - total_width) // 2\nfor tag in TAGS:\n    text = f'' {tag} ''\n    bbox = draw.textbbox((0, 0), text, font=font_tag)\n    tw, th = bbox[2] - bbox[0], bbox[3] - bbox[1]\n    # 标签背景\n    draw.rounded_rectangle(\n        [(tag_x, tag_y), (tag_x + tw + 20, tag_y + th + 14)],\n        radius=6, fill=(40, 60, 100), outline=(80, 120, 180)\n    )\n    draw.text((tag_x + 10, tag_y + 7), text, fill=(160, 200, 255), font=font_tag)\n    tag_x += tw + 32\n\n# 保存为 webp\npng_path = f''{OUTPUT_DIR}/cover.png''\nwebp_path = f''{OUTPUT_DIR}/cover.webp''\nimg.save(png_path)\nsubprocess.run([''cwebp'', ''-q'', ''85'', png_path, ''-o'', webp_path], check=True)\nimport os\nos.remove(png_path)\n\n# 验证文件大小\nsize_kb = os.path.getsize(webp_path) / 1024\nprint(f''封面图已生成: {webp_path} ({size_kb:.1f} KB)'')\nif size_kb > 200:\n    print(''⚠️ 警告：文件超过 200KB，请降低质量参数重新生成'')\n\"\n```\n\n如果 `cwebp` 不可用，使用 Pillow 直接保存 webp：\n```python\nimg.save(f''{OUTPUT_DIR}/cover.webp'', ''WEBP'', quality=85)\n```\n\n⚠️ **方案 B 生成后必须验证**：用 Read 工具查看生成的封面图，确认英文标题、副标题、标签均正常显示，**不存在任何方框、问号、乱码字符**。如果出现异常，必须排查字体路径后重新生成。\n\n#### 封面图检查清单（无论哪种方案都必须满足）\n\n- [ ] 文件名为 `cover.webp`\n- [ ] 尺寸 1200×630px\n- [ ] 大小 < 200KB\n- [ ] 内容与文章主题相关\n- [ ] **无乱码**：必须用 Read 工具查看生成的封面图，确认图片中不存在任何乱码、乱字符或不可读文字。如有乱码必须重新生成\n\n---\n\n### Step 4: 撰写文章\n\n#### 4.1 Front Matter + 封面图引用（TOML 格式）\n\n```toml\n+++\ndate = ''2026-01-26T10:00:00+08:00''\ndraft = false\ntitle = ''Article Title (50-60 chars, primary keyword first)''\ndescription = ''SEO description for search results and social sharing (120-160 chars)''\ntoc = true\ntags = [''Claude Code'', ''AI Agent'', ''specific-tag'']\ncategories = [''AI Guides'']\nkeywords = [''search keyword 1'', ''search keyword 2'']\n+++\n\n![Descriptive ALT text with primary keyword](cover.webp)\n```\n\n⚠️ **封面图必须在正文中引用**：在 Front Matter（`+++`）结束后的**第一行**，必须用 `![ALT 文本](cover.webp)` 引用封面图。不引用则封面图不会显示在文章中。ALT 文本应包含核心关键词，描述图片内容。\n\n| 字段 | 必填 | 说明 |\n|------|------|------|\n| `date` | ✓ | ISO 8601 格式，含时区 `+08:00` |\n| `title` | ✓ | 50-60 字符，关键词前置 |\n| `description` | ✓ | 120-160 字符，包含核心关键词 |\n| `categories` | ✓ | 只能使用 Step 1 中的预设值 |\n| `tags` | ✓ | 3-5 个标签（英文） |\n| `toc` | 推荐 | 长文设为 `true` |\n| `keywords` | 推荐 | SEO 补充关键词（英文） |\n| `draft` | 可选 | 默认 `false` |\n\n#### 4.2 写作规范检查项\n\n撰写时必须逐项确保：\n\n**开头三要素**（首段 100 字内必须出现核心关键词）：\n- ✅ 为什么需要这个技术？（背景）\n- ✅ 这个技术是什么？（定义）\n- ✅ 读完能获得什么？（价值）\n\n**内容深度**：\n- ✅ 每个核心概念都配实际案例，让读者能举一反三\n- ✅ 复杂概念必须用类比或比喻解释（让小学生也能听懂）\n- ✅ 不浮于表面，深入讲解原理和细节\n- ✅ 代码示例完整可运行，有英文注释（新文章全英文，禁止混合中英）\n\n**推荐的内容结构**（所有新文章必须用英文撰写）：\n\n```markdown\n## Background / Why You Need This\n## Core Concepts\n## Getting Started / Basic Usage\n## Real-World Examples\n## Advanced Tips\n## FAQ / Common Issues\n## Related Reading\n```\n\n**通俗化表达示例**（所有新文章用英文撰写）：\n\n```markdown\n# ❌ Bad — too jargon-heavy\nDocker containers are a lightweight virtualization technology that uses namespaces and cgroups for resource isolation.\n\n# ✅ Good — use analogies\nThink of a Docker container as a \"packed lunchbox.\" You put your app and everything it needs inside the box —\nno matter which computer you open it on, the contents are exactly the same.\n```\n\n**SEO 要点**：\n- 标题、描述、首段包含核心关键词\n- 使用语义化标题层级（H2 > H3 > H4）\n- 图片使用描述性 ALT 文本，包含关键词\n\n**GEO（生成式引擎优化）要点**：\n- 内容结构清晰，便于 AI 理解和引用\n- 提供明确的定义和解释\n- 使用列表、表格等结构化格式\n- 给出具体数据和案例支撑观点\n\n#### 4.3 链接策略\n\n⚠️ **必须**基于 Step 2.3 获取的已有文章列表添加链接。\n\n**内链（3-8 个）**：\n- 在正文中自然引用已有相关文章\n- 添加内链前确认目标文章确实存在（基于 Step 2.3 的文章列表）\n- 文末添加「Related Reading」板块\n\n```markdown\n## Related Reading\n\n- [Article Title 1](/posts/ai/2026-xx-xx-article-name/) — Brief description\n- [Article Title 2](/posts/ai/2026-xx-xx-article-name/) — Brief description\n```\n\n**外链（3-5 个）**：\n- 优先链接权威来源：官方文档、GitHub 仓库、技术标准（RFC、W3C）\n- 在正文中自然引用，为读者提供延伸阅读\n\n#### 4.4 嵌套代码块处理\n\n当需要在代码块中展示包含代码块的内容时，**必须使用不同数量的反引号**：\n\n`````markdown\n````markdown\n```python\nprint(\"Hello World\")\n```\n````\n`````\n\n规则：外层反引号数量必须**大于**内层。如外层 4 个，内层 3 个。\n\n---\n\n### Step 5: 发布前检查\n\n⚠️ **以下所有检查项必须逐一确认**，任何不通过的项目必须修复后才能完成。\n\n#### 格式检查\n\n- [ ] 标题 ≤ 60 字符，关键词前置\n- [ ] Description 120-160 字符，包含核心关键词\n- [ ] Front Matter 使用 TOML 格式（`+++`）\n- [ ] `categories` 使用预设值，未自创分类\n- [ ] 目录名使用英文命名\n- [ ] 日期使用 `date` 命令获取的真实日期\n- [ ] 封面图为 `cover.webp`，尺寸 1200×630，大小 ≤ 200KB\n\n#### 内容质量检查\n\n- [ ] **封面图已在正文中引用**：Front Matter 后第一行为 `![ALT](cover.webp)`\n- [ ] 开头三要素齐全：背景、定义、价值\n- [ ] 每个核心概念都配了实际案例\n- [ ] 复杂概念有通俗类比\n- [ ] 代码示例完整可运行，有英文注释\n- [ ] 内链数量 ≥ 3，且目标文章确实存在\n- [ ] 外链数量 ≥ 3，指向权威来源\n- [ ] 文末有「Related Reading」板块\n\n#### Hugo 构建验证\n\n⚠️ **必须**执行构建验证：\n\n```bash\nhugo --minify\n```\n\n确认无报错后，文章才算完成。\n\n---\n\n## 内容策略（与 AGENTS.md 对齐）\n\n### 文章类型（按优先级）\n\n1. **Guide** — \"How to set up X\", \"Complete guide to Y\"\n2. **Setup** — Step-by-step installation and configuration\n3. **Comparison** — \"X vs Y: Which is better for Z?\"\n4. **Best Tools** — \"Top 10 tools for X in 2026\"\n5. **Workflow** — \"My AI development workflow\"\n6. **Review** — In-depth tool/framework evaluation\n\n### 禁止内容类型\n\n- 个人日记\n- 没有搜索意图的日志式帖子\n- 没有商业或信息价值的内容\n\n### 主题集群（每个需 10+ 篇文章）\n\n- Claude Code\n- AI Agent Frameworks\n- AI Coding Tools\n- AI Engineering Workflows\n- Tool Comparisons\n\n### 迁移规则\n\n- **禁止**批量翻译旧中文文章\n- **禁止**修改已有的中文文章\n- **禁止**更改已被索引的中文 URL\n- **禁止**在同一页面混合中英文\n- 旧中文内容作为归档遗留保留\n\n---\n\n## 注意事项\n\n1. **日期必须真实**：使用 `date` 命令获取当前日期\n2. **URL 必须英文**：目录名使用英文\n3. **Front Matter 用 TOML**：使用 `+++` 而非 `---`\n4. **图片必须 webp**：封面图命名为 `cover.webp`\n5. **素材必须实际阅读**：不可仅凭链接标题猜测内容\n6. **分类只能用预设值**：`AI Guides` 或 `Comparisons`，禁止使用旧中文分类\n7. **所有新文章必须英文**：正文、标题、描述、标签、ALT 文本、代码注释全部用英文（遵循 AGENTS.md 规范）\n8. **禁止混合中英文**：同一页面内不得混合中英文内容\n"},"lastSynced":"2026-03-08T02:03:35.635Z","agentAnalysis":{"suitability":{"en":"Ideal for Technical Content Agents specializing in developer documentation and Hugo-based publishing workflows.","zh":"适用于专攻开发者文档和Hugo-based发布工作流的技术内容代理。","ja":"開発者向けドキュメントやHugoベースのパブリッシングワークフローを専門とするテクニカルコンテンツエージェントに最適。","ko":"개발자 문서 및 Hugo 기반 발행 워크플로우를 전문으로 하는 기술 콘텐츠 에이전트에 적합합니다.","es":"Ideal para Agentes de Contenido Técnico especializados en documentación para desarrolladores y flujos de trabajo de publicación basados en Hugo.","fr":"Idéal pour les agents de contenu technique spécialisés dans la documentation des développeurs et les workflows de publication basés sur Hugo.","de":"Ideal für technische Inhaltsagenten, die sich auf Entwicklerdokumentation und Hugo-basierte Publikationsworkflows spezialisieren.","pt":"Ideal para Agentes de Conteúdo Técnico especializados em documentação para desenvolvedores e fluxos de trabalho de publicação baseados no Hugo.","ru":"Идеально подходит для технических контент-агентов, специализирующихся на документации для разработчиков и рабочих процессах публикации на основе Hugo.","ar":"مثالي للوكلاء المحتوى الفني المتخصصين في توثيق المطورين والتدفقات العمل بناء على Hugo."},"recommendation":{"en":"Enables automated generation of structured technical blog posts using Hugo v0.153.2+ with hermit-V2 theme. Streamlines content creation with enforced workflow validation and predefined category taxonomy (AI Guides, tutorials, documentation).","zh":"使用Hugo v0.153.2+和hermit-V2主题，实现结构化技术博客文章的自动化生成。通过强制工作流验证和预定义类别分类法（AI指南，教程，文档）简化内容创建。","ja":"Hugo v0.153.2+およびhermit-V2テーマを使用して、構造化されたテクニカルブログ記事の自動生成を可能にします。強制的なワークフロー検証および事前定義されたカテゴリ分類法（AIガイド、チュートリアル、ドキュメント）によりコンテンツ作成を簡素化します。","ko":"Hugo v0.153.2+ 및 hermit-V2 테마를 사용하여 구조화된 기술 블로그 게시물의 자동 생성을 가능하게 합니다. 강제 워크플로우 검증 및 사전 정의된 카테고리 분류법(AI 가이드, 자습서, 문서)을 통해 콘텐츠 생성을 간소화합니다.","es":"Permite la generación automática de publicaciones de blogs técnicos estructurados utilizando Hugo v0.153.2+ con tema hermit-V2. Simplifica la creación de contenido con validación de flujo de trabajo y taxonomía de categoría predefinida (Guías de IA, tutoriales, documentación).","fr":"Permet la génération automatisée de billets de blog techniques structurés en utilisant Hugo v0.153.2+ avec le thème hermit-V2. Simplifie la création de contenu avec une validation de workflow et une taxonomie de catégorie prédéfinie (Guides d''IA, tutoriels, documentation).","de":"Ermöglicht die automatisierte Generierung von strukturierten technischen Blog-Beiträgen unter Verwendung von Hugo v0.153.2+ mit hermit-V2-Thema. Vereinfacht die Inhaltserschaffung durch Workflow-Validierung und vordefinierte Kategorientaxonomie (AI-Anleitungen, Tutorials, Dokumentation).","pt":"Permite a geração automática de posts de blog técnicos estruturados usando o Hugo v0.153.2+ com o tema hermit-V2. Simplifica a criação de conteúdo com validação de fluxo de trabalho aplicada e taxonomia de categorias predefinida (Guia de IA, tutoriais, documentação).","ru":"Позволяет автоматически генерировать структурированные технические блог-посты, используя Hugo v0.153.2+ с темой hermit-V2. Упрощает создание контента с применением валидации рабочего процесса и предопределенной таксономии категорий (Руководства по ИИ, учебники, документация).","ar":"يمكنه توليد منشورات مدونة تقنية منظمه تلقائيا باستخدام Hugo v0.153.2+ مع موضوع hermit-V2. يبسط إنشاء المحتوى مع التحقق من سير العمل المعمول به وتaxonomy الفئات المحددة مسبقا (دليل الذكاء الاصطناعي، دروس، توثيق)."},"useCases":{"en":["Automating technical tutorial publication","Generating structured developer documentation","Maintaining Hugo-based blog consistency","Enforcing content categorization standards"],"zh":["自动化技术教程出版","生成结构化开发者文档","维护Hugo-based博客一致性","强制内容分类标准"],"ja":["テクニカルチュートリアルの自動化出版","構造化された開発者向けドキュメントの生成","Hugoベースのブログの一貫性の維持","コンテンツ分類基準の強制"],"ko":["기술 자습서의 자동화된 출판","구조화된 개발자 문서의 생성","Hugo 기반 블로그 일관성의 유지","콘텐츠 분류 기준의 강제"],"es":["Automatización de la publicación de tutoriales técnicos","Generación de documentación de desarrolladores estructurada","Mantenimiento de la coherencia del blog basado en Hugo","Aplicación de estándares de categorización de contenido"],"fr":["Automatisation de la publication de didacticiels techniques","Génération de documentation de développeurs structurée","Maintenance de la cohérence du blog basé sur Hugo","Application des normes de catégorisation de contenu"],"de":["Automatisierung der Veröffentlichung von technischen Tutorials","Generierung von strukturierter Entwicklerdokumentation","Beibehaltung der Konsistenz von Hugo-basierten Blogs","Durchsetzung von Inhaltscategorisierungsstandards"],"pt":["Publicação automática de tutoriais