INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('heyuan110/heyuan110.github.io/blog-writer', 'blog-writer', 'heyuan110', 'heyuan110.github.io', 'community', 'blog-writer heyuan110 heyuan110.github.io community The blog-writer skill generates technical blog posts using Hugo and hermit-V2 theme, benefiting developers and content creators. It streamlines the writing process with a structured approach. 博客写作专家技能使用 Hugo 和 AI 技术生成高质量的博客内容 AIエージェントのブログライター機能は、HugoとAI技術で高品質のブログコンテンツを生成する 블로그 작성 전문가 스킬은 Hugo와 AI 기술로 고품질 블로그 콘텐츠를 생성한다 El agente de escritura de blogs AI utiliza Hugo y hermit-V2 para crear contenido técnico. Aprende a configurarlo y utilizarlo para tus necesidades de desarrollo. L''agent d''écriture de blogs AI utilise Hugo et hermit-V2 pour créer du contenu technique. Découvrez comment le configurer et l''utiliser pour vos besoins de développement. Der Blog-Schreiber-AI-Agent verwendet Hugo und hermit-V2, um technische Inhalte zu erstellen. Erfahren Sie, wie Sie ihn einrichten und verwenden können, um Ihre Entwicklungsaufgaben zu erfüllen. O blog-writer é uma ferramenta de criação de conteúdo que utiliza Hugo v0.153.2+ e tema hermit-V2 para produzir artigos de qualidade ИИ Агент blog-writer является инструментом для создания контента, который использует Hugo v0.153.2+ и тему hermit-V2 для производства качественных статей وكيل المدونة blog-writer هو أداة لإنشاء المحتوى التي تستخدم Hugo v0.153.2+ وسمة hermit-V2 لإنتاج مقالات عالية الجودة how to use blog-writer blog-writer alternative blog-writer setup guide what is blog-writer blog-writer vs ghost install blog-writer hugo blog post generation hermit-V2 theme tutorial technical blog writing tips 博客写作专家 Hugo 博客 AI 内容生成 搜索引擎排名 高质量内容 hermit-V2 主题 目标关键词设置 Utilizes Hugo v0.153.2+ (Extended) for blog post generation Supports hermit-V2 theme for customizable content presentation Stores content in the `content/posts/` directory for easy management Enforces a structured writing flow with mandatory steps for high-quality output Allows for optional target keyword specification for SEO optimization Integrates with external resources like URLs, documents, and GitHub repositories for reference blog-writer is a technical blog post generation skill utilizing Hugo and hermit-V2 theme to produce high-quality content');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('u9401066/pubmed-search-mcp/tool-sync', 'community', 'u9401066', 'pubmed-search-mcp', 'u9401066/pubmed-search-mcp', 'tool-sync', 0, 0, 36, '2026-03-08T01:57:15.348Z', '2026-03-08T02:03:42.374Z', '59f9bea00aa1f12ec2b9eecd8cb84c37db5e8700f0995b72b256df92447273e4', '{"id":"u9401066/pubmed-search-mcp/tool-sync","name":"tool-sync","description":{"en":"The tool-sync skill automates MCP server setup for biomedical literature research, ensuring consistency across instructions, skills, and README files. It benefits developers and researchers by providing a professional MCP server with 40 tools and multi-source search capabilities.","zh":"tool-sync 是一个自动同步 MCP 工具文档的技能，确保代码一致性","ja":"tool-sync は、MCP ツールのドキュメントを自動同期してコードの一貫性を確保するスキルです","ko":"tool-sync는 MCP 도구 문서를 자동 동기화하여 코드 일관성을 보장하는 기술입니다","es":"tool-sync es una herramienta de sincronización para servidores MCP que mantiene actualizadas las herramientas y documentación. Automatiza la actualización de herramientas y documentación","fr":"tool-sync est un outil de synchronisation pour les serveurs MCP qui maintient les outils et la documentation à jour. Il automatise la mise à jour des outils et de la documentation","de":"tool-sync ist ein Synchronisierungstool für MCP-Server, das die Tools und Dokumentation auf dem neuesten Stand hält. Es automatisiert die Aktualisierung von Tools und Dokumentation","pt":"O tool-sync é uma ferramenta para sincronizar automaticamente as ferramentas no servidor MCP, garantindo a consistência das instruções e listas de ferramentas.","ru":"Tool-sync - это инструмент для автоматической синхронизации инструментов на сервере MCP, обеспечивающий согласованность инструкций и списков инструментов.","ar":"tool-sync هو أداة لتنسيق الأدوات تلقائيًا على مخدم MCP، مما يضمن توافق الإرشادات وقوائم الأدوات."},"seo":{"title":{"en":"tool-sync: Automated MCP Server Setup Guide | AI Agent Skill","zh":"tool-sync 设置指南：自动同步 MCP 工具文档","ja":"tool-sync セットアップガイド：MCP ツールの自動同期","ko":"tool-sync 설정 가이드: MCP 도구 문서 자동 동기화","es":"Guía de Configuración de tool-sync para Servidores MCP","fr":"Guide d''Installation de tool-sync pour les Serveurs MCP","de":"Einrichtungs-Anleitung für tool-sync auf MCP-Servern","pt":"Guia de Configuração do tool-sync para MCP Server","ru":"Настройка tool-sync для сервера MCP: ИИ Агенты","ar":"دليل إعداد tool-sync لمخدم MCP"},"description":{"en":"Discover how tool-sync streamlines biomedical literature research with multi-source search and citation networks. Learn how to automate your MCP server setup...","zh":"了解 tool-sync 技术，自动同步 MCP 工具文档，确保代码一致性","ja":"tool-sync テクノロジーについて学び、MCP ツールのドキュメントを自動同期してコードの一貫性を確保する","ko":"tool-sync 기술에 대해 알아보고 MCP 도구 문서를 자동 동기화하여 코드 일관성을 보장합니다","es":"Aprende a configurar tool-sync para mantener tus herramientas MCP actualizadas. Descubre cómo funciona esta herramienta de sincronización","fr":"Découvrez comment configurer tool-sync pour garder vos outils MCP à jour. Comprenez le fonctionnement de cet outil de synchronisation","de":"Erfahren Sie, wie Sie tool-sync konfigurieren, um Ihre MCP-Tools auf dem neuesten Stand zu halten. Erhalten Sie Einblicke in die Funktionsweise dieses Synchr...","pt":"Aprenda a configurar o tool-sync para sincronizar ferramentas no servidor MCP e otimizar a pesquisa biomédica","ru":"Откройте для себя возможности tool-sync для сервера MCP и оптимизируйте поиск биомедицинской литературы с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد tool-sync لتنسيق الأدوات على مخدم MCP وتحسين البحث البيولوجي"},"definition":{"en":"tool-sync is an AI agent skill that automates the synchronization of MCP tool documentation, ensuring consistency and accuracy across all related files and code.","zh":"tool-sync 是一种自动同步技术，用于保持 MCP 工具文档与代码的一致性","ja":"tool-sync は、MCP ツールのドキュメントとコードの一貫性を維持する自動同期テクノロジーです","ko":"tool-sync는 MCP 도구 문서와 코드의 일관성을 유지하기 위한 자동 동기화 기술입니다","es":"tool-sync es una herramienta de sincronización que mantiene las herramientas y documentación de un servidor MCP actualizadas","fr":"tool-sync est un outil de synchronisation qui maintient les outils et la documentation d''un serveur MCP à jour","de":"tool-sync ist ein Synchronisierungstool, das die Tools und Dokumentation eines MCP-Servers auf dem neuesten Stand hält","pt":"O tool-sync é uma ferramenta de sincronização automática para servidores MCP que garante a consistência das ferramentas e instruções.","ru":"Tool-sync - это инструмент автоматической синхронизации для серверов MCP, обеспечивающий согласованность инструментов и инструкций.","ar":"tool-sync هو أداة لتنسيق تلقائي للأدوات على مخدمات MCP التي تضمن توافق الأدوات والإرشادات."},"features":{"en":["Automatically synchronizes tool documentation when MCP tools are added, removed, or renamed","Supports multi-source search via PubMed, Europe PMC, CORE, and OpenAlex","Provides full-text access and citation networks for in-depth research","Performs PICO analysis for comprehensive literature reviews","Updates tool_registry.py and tools/__init__.py files to reflect changes in MCP tools"],"zh":["自动同步 MCP 工具文档","支持 register_*_tools() 函数和 @mcp.tool() 装饰器","更新 tool_registry.py 和 tools/__init__.py 文件","支持删除或重命名 MCP 工具","确保代码一致性"],"ja":["MCP ツールのドキュメントを自動同期","register_*_tools() 関数と @mcp.tool() デコレータをサポート","tool_registry.py と tools/__init__.py ファイルを更新","MCP ツールの削除または名前変更をサポート","コードの一貫性を確保"],"ko":["MCP 도구 문서를 자동 동기화","register_*_tools() 함수와 @mcp.tool() 데코레이터를 지원","tool_registry.py와 tools/__init__.py 파일을 업데이트","MCP 도구의 삭제 또는 이름 변경을 지원","코드 일관성을 보장"],"es":["Sincronización automática de herramientas y documentación","Actualización de la lista de herramientas en tool_registry.py","Compatibilidad con registro de herramientas mediante register_*_tools() y @mcp.tool()","Actualización de la documentación en presentation/mcp_server","Soporte para eliminación y renombramiento de herramientas","Sincronización de hasta 6 archivos de documentación"],"fr":["Synchronisation automatique des outils et de la documentation","Mise à jour de la liste des outils dans tool_registry.py","Compatibilité avec l''enregistrement d''outils via register_*_tools() et @mcp.tool()","Mise à jour de la documentation dans presentation/mcp_server","Prise en charge de la suppression et du renommage d''outils","Synchronisation de jusqu''à 6 fichiers de documentation"],"de":["Automatische Synchronisierung von Tools und Dokumentation","Aktualisierung der Tool-Liste in tool_registry.py","Kompatibilität mit der Registrierung von Tools über register_*_tools() und @mcp.tool()","Aktualisierung der Dokumentation in presentation/mcp_server","Unterstützung für das Löschen und Umbenennen von Tools","Synchronisierung von bis zu 6 Dokumentationsdateien"],"pt":["Sincronização automática de ferramentas","Suporte a multi-fonte de busca (PubMed, Europe PMC, CORE, OpenAlex)","Acesso a texto completo e redes de citação","Análise PICO e muito mais"],"ru":["Автоматическая синхронизация инструментов","Поддержка поиска из нескольких источников (PubMed, Europe PMC, CORE, OpenAlex)","Доступ к полному тексту и сетям цитирования","Анализ PICO и многое другое"],"ar":["تنسيق تلقائي للأدوات","دعم البحث من عدة مصادر (PubMed, Europe PMC, CORE, OpenAlex)","وصول إلى النص الكامل وشبكات الاقتباس","تحليل PICO وغيرها"]},"keywords":{"en":["how to use tool-sync","tool-sync setup guide","biomedical literature research tools","MCP server automation","multi-source search engines","tool-sync vs other research tools","automated citation networks","PICO analysis software","tool-sync install guide"],"zh":["tool-sync","MCP 工具","自动同步","代码一致性","AI エージェント","工具文档","技术文档","自动化"],"ja":["tool-sync","MCP ツール","自動同期","コードの一貫性","AIエージェント","ツールドキュメント","テクニカルドキュメント","自動化"],"ko":["tool-sync","MCP 도구","자동 동기화","코드 일관성","AI 에이전트","도구 문서","기술 문서","자동화"],"es":["tool-sync","servidores MCP","sincronización de herramientas","documentación automática","register_*_tools()","mcp.tool()","tool_registry.py","Agente de IA","Herramientas de desarrollo"],"fr":["tool-sync","serveurs MCP","synchronisation d''outils","documentation automatique","register_*_tools()","mcp.tool()","tool_registry.py","Agent IA","Outils de développement"],"de":["tool-sync","MCP-Server","Synchronisierung von Tools","automatische Dokumentation","register_*_tools()","mcp.tool()","tool_registry.py","KI-Agent","Entwicklungstools"],"pt":["tool-sync","MCP server","sincronização de ferramentas","pesquisa biomédica","PubMed","Europe PMC","CORE","OpenAlex"],"ru":["tool-sync","сервер MCP","синхронизация инструментов","биомедицинский поиск","PubMed","Europe PMC","CORE","OpenAlex","ИИ Агенты"],"ar":["tool-sync","مخدم MCP","تنسيق الأدوات","البحث البيولوجي","PubMed","Europe PMC","CORE","OpenAlex","وكلاء الذكاء الاصطناعي"]}},"owner":"u9401066","repo":"pubmed-search-mcp","repoPath":"u9401066/pubmed-search-mcp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.348Z","topics":[],"category":"community","skillMd":{"name":"tool-sync","description":"Auto-sync MCP tool documentation when tools are added, removed, or renamed. Triggers: TS, tool-sync, 工具同步, 同步工具, sync tools, new tool, 新增工具, 工具變更, update tools.","bodyPreview":"# MCP 工具文檔自動同步\n\n## 描述\n當 MCP 工具被新增、移除、重新命名時，自動同步所有相關文檔。\n確保 instructions、skills、README 中的工具數量和列表永遠與程式碼一致。\n\n## 觸發條件\n以下情境**必須**觸發此 Skill：\n1. 新增了 `register_*_tools()` 函數或 `@mcp.tool()` 裝飾器\n2. 修改了 `tool_registry.py` 的 `TOOL_CATEGORIES`\n3. 修改了 `tools/__init__.py` 的 `register_all_tools()`\n4. 刪除或重新命名任何 MCP 工具\n5. 用戶明確要求 \"同步工具\" / \"tool sync\"\n\n## 自動同步的文件（共 6 個）\n\n| # | 文件 | 更新內容 | 更新方式 |\n|---|------|----------|----------|\n| 1 | `presentation/mcp_server/tool_registry.py` | `TOOL_CATEGORIES` dict | 手動 — 新增/移除工","body":"# MCP 工具文檔自動同步\n\n## 描述\n當 MCP 工具被新增、移除、重新命名時，自動同步所有相關文檔。\n確保 instructions、skills、README 中的工具數量和列表永遠與程式碼一致。\n\n## 觸發條件\n以下情境**必須**觸發此 Skill：\n1. 新增了 `register_*_tools()` 函數或 `@mcp.tool()` 裝飾器\n2. 修改了 `tool_registry.py` 的 `TOOL_CATEGORIES`\n3. 修改了 `tools/__init__.py` 的 `register_all_tools()`\n4. 刪除或重新命名任何 MCP 工具\n5. 用戶明確要求 \"同步工具\" / \"tool sync\"\n\n## 自動同步的文件（共 6 個）\n\n| # | 文件 | 更新內容 | 更新方式 |\n|---|------|----------|----------|\n| 1 | `presentation/mcp_server/tool_registry.py` | `TOOL_CATEGORIES` dict | 手動 — 新增/移除工具分類 |\n| 2 | `presentation/mcp_server/tools/__init__.py` | `register_all_tools()` | 手動 — import + 呼叫 register 函數 |\n| 3 | `presentation/mcp_server/instructions.py` | SERVER_INSTRUCTIONS 工具列表 | 🤖 `--update-docs` 自動 |\n| 4 | `.github/copilot-instructions.md` | Tool Categories 表格 | 🤖 `--update-docs` 自動 |\n| 5 | `.claude/skills/pubmed-mcp-tools-reference/SKILL.md` | 完整工具參考 | 🤖 `--update-docs` 自動 |\n| 6 | `README.md` + `README.zh-TW.md` | 工具數量 badge | 🤖 `--update-docs` 自動 |\n\n## 執行流程\n\n### Step 1: 手動修改（AI Agent 負責）\n確保以下兩個「源頭」檔案正確：\n\n```python\n# 1. tool_registry.py — 新增分類\nTOOL_CATEGORIES = {\n    ...\n    \"new_category\": {\n        \"name\": \"新分類名稱\",\n        \"description\": \"分類描述\",\n        \"tools\": [\"tool_name_1\", \"tool_name_2\"],\n    },\n}\n\n# 2. tools/__init__.py — 註冊函數\nfrom .new_module import register_new_tools\n\ndef register_all_tools(mcp, searcher):\n    ...\n    register_new_tools(mcp)  # 新增呼叫\n```\n\n### Step 2: 執行自動同步腳本\n```bash\nuv run python scripts/count_mcp_tools.py --update-docs\n```\n\n### Step 3: 驗證\n```bash\n# 檢查工具數量是否正確\nuv run python scripts/count_mcp_tools.py\n\n# 檢查驗證是否通過（TOOL_CATEGORIES 與 FastMCP runtime 同步）\nuv run python scripts/count_mcp_tools.py --verbose\n```\n\n### Step 4: 回報結果\n```\n🔄 MCP 工具同步完成\n\n📊 統計：\n  - 工具總數: XX → YY (+N)\n  - 分類數: XX → YY (+N)\n  - 更新文件: N 個\n\n📝 已更新：\n  ✅ tool_registry.py - 新增 \"image_search\" 分類\n  ✅ tools/__init__.py - 新增 register_image_search_tools\n  ✅ instructions.py - 工具列表已同步\n  ✅ copilot-instructions.md - Tool Categories 已同步\n  ✅ SKILL.md (tools-reference) - 已重新生成\n  ✅ README.md - 工具數量已更新\n  ✅ README.zh-TW.md - 工具數量已更新\n\n⚠️ 驗證: PASSED ✅\n```\n\n## 重要規則\n\n### 🔴 必須遵守\n1. **任何工具變更後都要執行** `count_mcp_tools.py --update-docs`\n2. **先修改源頭**（tool_registry.py + tools/__init__.py），再執行腳本\n3. **驗證必須通過** — `TOOL_CATEGORIES` 與 FastMCP runtime 必須同步\n\n### ⚠️ 注意事項\n- `count_mcp_tools.py` 會自動偵測 `TOOL_CATEGORIES` 中所有類別（動態取得，不再硬編碼）\n- `instructions.py` 只更新工具列表區塊，搜尋策略等手寫內容不會被覆蓋\n- `pubmed-mcp-tools-reference` SKILL 會完全重新生成\n- CHANGELOG 更新由 `changelog-updater` skill 另行處理\n\n## 與其他 Skill 的關係\n- **git-precommit**: commit 前會呼叫本 Skill 的同步步驟\n- **git-doc-updater**: 文檔更新時也會觸發工具同步檢查\n- **ddd-architect**: 新增功能模組時會提醒執行工具同步\n"},"lastSynced":"2026-03-08T02:03:42.374Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated MCP server setup and synchronization for biomedical literature research.","zh":"适合需要自动化MCP服务器设置和同步的生物医学文献研究的开发代理","ja":"MCPサーバーの自動セットアップと同期が必要な開発エージェントに最適","ko":"MCP 서버 자동 설정 및 동기화가 필요한 생물의학 문헌 연구 개발 에이전트에 적합","es":"Perfecto para agentes de desarrollo que necesitan configuración y sincronización automática del servidor MCP para investigación de literatura biomédica.","fr":"Parfait pour les agents de développement ayant besoin d''une configuration et de synchronisation automatisées du serveur MCP pour la recherche de littérature biomédicale.","de":"Perfekt für Entwicklungssagenten, die eine automatisierte MCP-Server-Konfiguration und -Synchronisierung für die biomedizinische Literaturforschung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de configuração e sincronização automatizadas do servidor MCP para pesquisa de literatura biomédica.","ru":"Идеально для агентов разработки, требующих автоматизированной настройки и синхронизации сервера MCP для исследований биомедицинской литературы.","ar":"مثالي لعمليات التطوير التي تحتاج إلى إعداد وتزامن автомاتيكي للخادم MCP لأبحاث الأدب البيولوجي الطبي."},"recommendation":{"en":"Empowers agents to maintain consistency across instructions, skills, and README files by automatically synchronizing tool documentation, ensuring a professional MCP server with 40 tools and multi-source search capabilities using Python.","zh":"通过自动同步工具文档，确保指令、技能和README文件的一致性，从而使代理能够维护专业的MCP服务器，拥有40种工具和多源搜索功能，使用Python","ja":"Pythonを使用して、ツールのドキュメントを自動的に同期することで、指示、スキル、およびREADMEファイルの一貫性を確保し、40のツールとマルチソース検索機能を備えたプロフェッショナルなMCPサーバーをエージェントが維持できるようにする","ko":"Python을 사용하여 도구 문서를 자동으로 同기화함으로써 지침, 기술 및 README 파일의 일관성을 보장하여 에이전트가 전문적인 MCP 서버를 유지할 수 있도록 하며, 40가지 도구 및 멀티소스 검색 기능을 제공","es":"Permite a los agentes mantener la consistencia en las instrucciones, habilidades y archivos README al sincronizar automáticamente la documentación de herramientas, garantizando un servidor MCP profesional con 40 herramientas y capacidades de búsqueda multi-origen utilizando Python.","fr":"Permet aux agents de maintenir la cohérence dans les instructions, les compétences et les fichiers README en synchronisant automatiquement la documentation des outils, garantissant un serveur MCP professionnel avec 40 outils et des capacités de recherche multi-sources utilisant Python.","de":"Ermöglicht es den Agenten, Konsistenz über Anweisungen, Fähigkeiten und README-Dateien hinweg zu gewährleisten, indem es die Werkzeugdokumentation automatisch synchronisiert, was einen professionellen MCP-Server mit 40 Werkzeugen und Multi-Quellen-Suchfunktionen unter Verwendung von Python sicherstellt.","pt":"Habilita os agentes a manter a consistência em todo o conjunto de instruções, habilidades e arquivos README, sincronizando automaticamente a documentação das ferramentas, garantindo um servidor MCP profissional com 40 ferramentas e capacidades de pesquisa multi-fonte usando Python.","ru":"Наделяет агентов возможностью поддерживать последовательность во всей инструкции, навыках и файлах README, автоматически синхронизируя документацию инструментов, обеспечивая профессиональный сервер MCP с 40 инструментами и возможностями поиска из нескольких источников с помощью Python.","ar":"تمكن الوكلاء من الحفاظ على الاتساق عبر الإرشادات والمهارات وملفات README من خلال مزامنة توثيق الأدوات تلقائيًا، مما يضمن خادم MCP محترف مع 40 أداة وقدرات بحث متعددة المصادر باستخدام Python."},"useCases":{"en":["Automating MCP tool documentation updates","Synchronizing tool lists across instructions and README files","Ensuring consistency in MCP server setup"],"zh":["自动化MCP工具文档更新","同步指令和README文件中的工具列表","确保MCP服务器设置的一致性"],"ja":["MCPツールのドキュメント更新の自動化","指示とREADMEファイルのツールリストの同期","MCPサーバーの設定の一貫性の確保"],"ko":["MCP 도구 문서 업데이트의 자동화","지침 및 README 파일의 도구 목록 동기화","MCP 서버 설정의 일관성 보장"],"es":["Automatizar actualizaciones de documentación de herramientas MCP","Sincronizar listas de herramientas en instrucciones y archivos README","Garantizar la consistencia en la configuración del servidor MCP"],"fr":["Automatiser les mises à jour de la documentation des outils MCP","Synchroniser les listes d''outils dans les instructions et les fichiers README","Assurer la cohérence dans la configuration du serveur MCP"],"de":["Automatisierung von MCP-Werkzeugdokumentations-Updates","Synchronisierung von Werkzeuglisten in Anweisungen und README-Dateien","Gewährleistung der Konsistenz in der MCP-Server-Konfiguration"],"pt":["Automatizar atualizações da documentação da ferramenta MCP","Sincronizar listas de ferramentas em todo o conjunto de instruções e arquivos README","Garantir a consistência na configuração do servidor MCP"],"ru":["Автоматизировать обновления документации инструментов MCP","Синхронизировать списки инструментов во всей инструкции и файлах README","Обеспечить последовательность в настройке сервера MCP"],"ar":["تأتمتة تحديثات توثيق أدوات MCP","مزامنة قوائم الأدوات عبر الإرشادات وملفات README","ضمان الاتساق في إعداد الخادم MCP"]},"limitations":{"en":["Requires access to MCP server codebase","Python environment necessary","Limited to MCP tool documentation synchronization"],"zh":["需要访问MCP服务器代码库","需要Python环境","仅限MCP工具文档同步"],"ja":["MCPサーバーのコードベースへのアクセスが必要","Python環境が必要","MCPツールのドキュメントの同期のみ"],"ko":["MCP 서버 코드베이스에 접근해야 함","Python 환경이 필요","MCP 도구 문서 동기화만 가능"],"es":["Requiere acceso al código base del servidor MCP","Entorno de Python necesario","Limitado a la sincronización de la documentación de herramientas MCP"],"fr":["Nécessite un accès au code source du serveur MCP","Environnement Python nécessaire","Limité à la synchronisation de la documentation des outils MCP"],"de":["Benötigt Zugriff auf den MCP-Server-Codebase","Python-Umgebung erforderlich","Begrenzt auf die Synchronisierung der MCP-Werkzeugdokumentation"],"pt":["Requer acesso ao código-fonte do servidor MCP","Ambiente Python necessário","Limitado à sincronização da documentação da ferramenta MCP"],"ru":["Требует доступа к кодовой базе сервера MCP","Необходимо окружение Python","Ограничен синхронизацией документации инструментов MCP"],"ar":["يتطلب الوصول إلى قاعدة код الخادم MCP","بيئة Python ضرورية","محدود بمزامنة توثيق أدوات MCP"]},"version":4},"contentHash":"59f9bea00aa1f12ec2b9eecd8cb84c37db5e8700f0995b72b256df92447273e4","qualityScore":36}');
