INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('u9401066/pubmed-search-mcp/tool-sync', 'tool-sync', 'u9401066', 'pubmed-search-mcp', 'community', 'tool-sync u9401066 pubmed-search-mcp community The tool-sync skill automates MCP server setup for biomedical literature research, ensuring consistency across instructions, skills, and README files. It benefits developers and researchers by providing a professional MCP server with 40 tools and multi-source search capabilities. tool-sync 是一个自动同步 MCP 工具文档的技能，确保代码一致性 tool-sync は、MCP ツールのドキュメントを自動同期してコードの一貫性を確保するスキルです tool-sync는 MCP 도구 문서를 자동 동기화하여 코드 일관성을 보장하는 기술입니다 tool-sync es una herramienta de sincronización para servidores MCP que mantiene actualizadas las herramientas y documentación. Automatiza la actualización de herramientas y documentación tool-sync est un outil de synchronisation pour les serveurs MCP qui maintient les outils et la documentation à jour. Il automatise la mise à jour des outils et de la documentation tool-sync ist ein Synchronisierungstool für MCP-Server, das die Tools und Dokumentation auf dem neuesten Stand hält. Es automatisiert die Aktualisierung von Tools und Dokumentation O tool-sync é uma ferramenta para sincronizar automaticamente as ferramentas no servidor MCP, garantindo a consistência das instruções e listas de ferramentas. Tool-sync - это инструмент для автоматической синхронизации инструментов на сервере MCP, обеспечивающий согласованность инструкций и списков инструментов. tool-sync هو أداة لتنسيق الأدوات تلقائيًا على مخدم MCP، مما يضمن توافق الإرشادات وقوائم الأدوات. how to use tool-sync tool-sync setup guide biomedical literature research tools MCP server automation multi-source search engines tool-sync vs other research tools automated citation networks PICO analysis software tool-sync install guide tool-sync MCP 工具 自动同步 代码一致性 AI エージェント 工具文档 技术文档 自动化 Automatically synchronizes tool documentation when MCP tools are added, removed, or renamed Supports multi-source search via PubMed, Europe PMC, CORE, and OpenAlex Provides full-text access and citation networks for in-depth research Performs PICO analysis for comprehensive literature reviews Updates tool_registry.py and tools/__init__.py files to reflect changes in MCP tools tool-sync is an AI agent skill that automates the synchronization of MCP tool documentation, ensuring consistency and accuracy across all related files and code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('joshuacook/motoko/learn', 'community', 'joshuacook', 'motoko', 'joshuacook/motoko', 'learn', 0, 0, 36, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:44.343Z', 'e06e8d004a5ac2171962564a193cf269061812290337589debf241d06926dc06', '{"id":"joshuacook/motoko/learn","name":"learn","description":{"en":"The Learn skill enables intelligent updates of roles and documents based on session summaries, utilizing the Context Lake pattern with MCP integration for efficient knowledge management.","zh":"Learn是Claude Code的文件系统知识管理功能，能够智能地更新角色和文档","ja":"LearnはAIエージェントの役割更新機能で、MCP統合とContext Lakeパターンを使用","ko":"Learn은 Claude Code의 파일 시스템 지식 관리 기능으로 MCP 통합과 Context Lake 패턴을 사용","es":"El aprendizaje automático de Claude Code utiliza un enfoque de gestión de conocimientos basado en el sistema de archivos y el patrón de lago de contexto con integración de MCP","fr":"L''apprentissage automatique de Claude Code utilise une approche de gestion des connaissances basée sur le système de fichiers et le modèle de lac de contexte avec intégration de MCP","de":"Das maschinelle Lernen von Claude Code verwendet einen dateisystembasierten Ansatz für das Wissensmanagement und das Kontext-See-Muster mit MCP-Integration","pt":"O Learn é um agente de aprendizado de máquina que utiliza o padrão Context Lake com integração MCP para atualizar papéis e documentos com base em resumos de sessão","ru":"ИИ Агент Learn - это агент машинного обучения, который использует шаблон Context Lake с интеграцией MCP для обновления ролей и документов на основе сводок сессий","ar":"وكيل التعلم الاصطناعي Learn هو وكيل تعلم الاصطناعي يستخدم نمط Context Lake مع التكامل MCP لتحديث الأدوار والوثائق بناءً على ملخصات الجلسات"},"seo":{"title":{"en":"Learn: Intelligent Role Curation for AI Agents | AI Agent...","zh":"Learn 智能更新指南 - Claude Code 文件系统","ja":"Learn Setup Guide - AIエ