INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('joshuacook/motoko/learn', 'learn', 'joshuacook', 'motoko', 'community', 'learn joshuacook motoko community The Learn skill enables intelligent updates of roles and documents based on session summaries, utilizing the Context Lake pattern with MCP integration for efficient knowledge management. Learn是Claude Code的文件系统知识管理功能，能够智能地更新角色和文档 LearnはAIエージェントの役割更新機能で、MCP統合とContext Lakeパターンを使用 Learn은 Claude Code의 파일 시스템 지식 관리 기능으로 MCP 통합과 Context Lake 패턴을 사용 El aprendizaje automático de Claude Code utiliza un enfoque de gestión de conocimientos basado en el sistema de archivos y el patrón de lago de contexto con integración de MCP L''apprentissage automatique de Claude Code utilise une approche de gestion des connaissances basée sur le système de fichiers et le modèle de lac de contexte avec intégration de MCP Das maschinelle Lernen von Claude Code verwendet einen dateisystembasierten Ansatz für das Wissensmanagement und das Kontext-See-Muster mit MCP-Integration O Learn é um agente de aprendizado de máquina que utiliza o padrão Context Lake com integração MCP para atualizar papéis e documentos com base em resumos de sessão ИИ Агент Learn - это агент машинного обучения, который использует шаблон Context Lake с интеграцией MCP для обновления ролей и документов на основе сводок сессий وكيل التعلم الاصطناعي Learn هو وكيل تعلم الاصطناعي يستخدم نمط Context Lake مع التكامل MCP لتحديث الأدوار والوثائق بناءً على ملخصات الجلسات how to use learn what is learn learn alternative learn vs knowledge management systems learn install guide learn setup for AI agents intelligent role curation Context Lake pattern MCP integration Learn Claude Code 文件系统知识管理 AIエージェント MCP Context Lake 智能更新 角色更新 Intelligent curation of role structures Appends timestamped session summaries to Recent Context Curates currently relevant information in Right Now section Utilizes Context Lake pattern for efficient knowledge management Integrates with MCP for seamless updates Activates on user commands like ''learn'' and ''update roles'' Learn is a filesystem-first knowledge management system that intelligently updates roles and documents based on session summaries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('milosptr/pos-system/printing-guide', 'community', 'milosptr', 'pos-system', 'milosptr/pos-system', 'printing-guide', 0, 0, 36, '2026-03-08T01:57:15.350Z', '2026-03-08T02:03:46.486Z', '6e9e53bdbf505d20972b50d5013d12e05f281b7ebb0d5f3879cfcda53143b804', '{"id":"milosptr/pos-system/printing-guide","name":"printing-guide","description":{"en":"The printing-guide skill integrates Epson thermal receipt printers via the ePOS SDK, enabling seamless printing for POS systems. It benefits developers and businesses seeking reliable printing solutions.","zh":"本打印指南介绍 Epson 打印机集成的技术细节，包括 ePOS SDK 和 Vuex 模块","ja":"この印刷ガイドでは、Epson プリンター統合の技術的詳細を説明します。ePOS SDK と Vuex モジュールを含みます","ko":"이 인쇄 가이드는 Epson 프린터 통합의 기술적 세부 사항을 설명합니다. ePOS SDK 및 Vuex 모듈을 포함합니다","es":"La guía de impresión para desarrolladores explica cómo integrar impresoras térmicas de Epson en sistemas POS utilizando el SDK ePOS.","fr":"La guide d''impression pour les développeurs explique comment intégrer les imprimantes thermiques Epson aux systèmes POS en utilisant le SDK ePOS.","de":"Der Druckleitfaden für Entwickler erklärt, wie Epson-Thermaldrucker in POS-Systeme mithilfe des ePOS-SDK integriert werden können.","pt":"O guia de impressão Epson é uma integração com o sistema POS via SDK ePOS, permitindo a configuração de conexão e gerenciamento de impressões","ru":"Руководство по печати Epson является интеграцией с системой POS через SDK ePOS, позволяющей настраивать подключение и управлять печатью","ar":"دليل الطباعة Epson هو دمج مع نظام نقاط البيع عبر SDK ePOS، مما يسمح بإعداد الاتصال وإدارة الطباعة"},"seo":{"title":{"en":"printing-guide: Epson Printer Integration Setup Guide | A...","zh":"打印指南 Setup Guide - Epson 打印机集成","ja":"印刷ガイド Setup Guide - Epson プリンター統合","ko":"인쇄 가이드 Setup Guide - Epson 프린터 통합","es":"Guía de configuración de impresión con Epson","fr":"Guide d''intégration d''imprimante Epson pour les développeurs","de":"Epson-Drucker-Integration-Leitfaden für Entwickler","pt":"Guia de Configuração de Impressão com Epson","ru":"Руководство по настройке печати с помощью Epson ИИ Агенты","ar":"دليل إعداد الطابعة Epson مع أداة ذكاء اصطناعي"},"description":{"en":"Discover how to integrate Epson thermal receipt printers with the ePOS SDK. Learn setup and connection details to get started with printing-guide today!","zh":"了解 Epson 打印机集成的技术细节，包括 ePOS SDK 和 Vuex 模块","ja":"Epson プリンター統合の技術的詳細を学びます。ePOS SDK と Vuex モジュールを含みます","ko":"Epson 프린터 통합의 기술적 세부 사항을 알아보세요. ePOS SDK 및 Vuex 모듈을 포함합니다","es":"Aprende a integrar impresoras térmicas de Epson en tu sistema POS con nuestra guía de configuración paso a paso","fr":"Découvrez comment intégrer les imprimantes thermiques Epson à votre système POS avec notre guide d''intégration étape par étape","de":"Erfahren Sie, wie Sie Epson-Thermaldrucker in Ihr POS-System integrieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a integrar a impressora Epson com o sistema POS utilizando o SDK ePOS. Veja como configurar a conexão e gerenciar impressões","ru":"Узнайте, как интегрировать принтер Epson с системой POS с помощью SDK ePOS. Просмотрите настройку подключения и управления печатью с ИИ Агенты","ar":"تعلم كيفية دمج الطابعة Epson مع نظام نقاط البيع باستخدام SDK ePOS. راجع إعداد الاتصال وإدارة الطباعة مع أداة ذكاء اصطناعي"},"definition":{"en":"printing-guide is a technical integration skill for Epson thermal receipt printers using the ePOS SDK, facilitating device connection and print management.","zh":"打印指南是 Epson 打印机集成的技术文档","ja":"印刷ガイドは、Epson プリンター統合の技術文書です","ko":"인쇄 가이드는 Epson 프린터 통합의 기술 문서입니다","es":"El printing-guide es una guía para desarrolladores que explica cómo integrar impresoras térmicas de Epson en sistemas POS","fr":"Le printing-guide est un guide pour les développeurs qui explique comment intégrer les imprimantes thermiques Epson aux systèmes POS","de":"Der printing-guide ist ein Leitfaden für Entwickler, der erklärt, wie Epson-Thermaldrucker in POS-Systeme integriert werden können","pt":"O que é o guia de impressão Epson? É uma ferramenta de integração com o sistema POS para impressoras Epson","ru":"Что такое руководство по печати Epson? Это инструмент интеграции с системой POS для принтеров Epson ИИ Агенты","ar":"ما هو دليل الطباعة Epson؟ هو أداة دمج مع نظام نقاط البيع لطابعات Epson"},"features":{"en":["Utilizes the Epson ePOS SDK library (253KB) for printer integration","Manages print operations via the Vuex module for print management","Handles device connections through the `resources/js/store/modules/epos.js` module","Supports legacy printing utilities via `resources/js/printing.js`","Connects to printers using IP Address `192.168.200.80` and Port `8008`"],"zh":["Epson ePOS SDK 库集成","Vuex 模块用于打印管理","设备连接管理","打印 IP 地址：192.168.200.80","打印端口：8008","支持 Epson 热敏收据打印机"],"ja":["Epson ePOS SDK ライブラリ統合","Vuex モジュールによる印刷管理","デバイス接続管理","印刷 IP アドレス：192.168.200.80","印刷ポート：8008","Epson 熱感レシートプリンター対応"],"ko":["Epson ePOS SDK 라이브러리 통합","Vuex 모듈을 통한 인쇄 관리","디바이스 연결 관리","인쇄 IP 주소：192.168.200.80","인쇄 포트：8008","Epson 열감지 레시트 프린터 지원"],"es":["Integración con impresoras térmicas de Epson","Uso del SDK ePOS para la gestión de la impresión","Gestión de la conexión con el dispositivo de impresión","Utilización de la biblioteca epos-2.20.0.js","Compatibilidad con la dirección IP 192.168.200.80 y el puerto 8008"],"fr":["Intégration avec les imprimantes thermiques Epson","Utilisation du SDK ePOS pour la gestion de l''impression","Gestion de la connexion avec le périphérique d''impression","Utilisation de la bibliothèque epos-2.20.0.js","Compatibilité avec l''adresse IP 192.168.200.80 et le port 8008"],"de":["Integration mit Epson-Thermaldruckern","Verwendung des ePOS-SDK für die Druckverwaltung","Verwaltung der Verbindung mit dem Druckgerät","Verwendung der Bibliothek epos-2.20.0.js","Kompatibilität mit der IP-Adresse 192.168.200.80 und dem Port 8008"],"pt":["Integração com o sistema POS via SDK ePOS","Configuração de conexão com o endereço IP e porta","Gerenciamento de impressões com o módulo Vuex","Utilização da biblioteca Epson ePOS SDK","Compatibilidade com o arquivo de recursos JavaScript"],"ru":["Интеграция с системой POS через SDK ePOS","Настройка подключения с помощью IP-адреса и порта","Управление печатью с помощью модуля Vuex","Использование библиотеки Epson ePOS SDK","Совместимость с файлом ресурсов JavaScript"],"ar":["دمج مع نظام نقاط البيع عبر SDK ePOS","إعداد الاتصال باستخدام العنوان IP والمنفذ","إدارة الطباعة باستخدام وحدة Vuex","استخدام مكتبة Epson ePOS SDK","التوافق مع ملف الموارد JavaScript"]},"keywords":{"en":["how to use printing-guide","printing-guide setup guide","Epson printer integration","ePOS SDK tutorial","printing-guide alternative","printing-guide vs other printer integrations","printing-guide install","what is printing-guide","printing-guide documentation"],"zh":["Epson 打印机集成","ePOS SDK","Vuex 模块","打印管理","设备连接管理","AIエージェント","打印指南","Epson 热敏收据打印机"],"ja":["Epson プリンター統合","ePOS SDK","Vuex モジュール","印刷管理","デバイス接続管理","AIエージェント","印刷ガイド","Epson 熱感レシートプリンター"],"ko":["Epson 프린터 통합","ePOS SDK","Vuex 모듈","인쇄 관리","디바이스 연결 관리","AI 도구","인쇄 가이드","Epson 열감지 레시트 프린터"],"es":["impresión térmica","Epson","SDK ePOS","sistemas POS","desarrollo de software","integración de hardware","guía de configuración","imprimir con Epson","soluciones de impresión"],"fr":["impression thermique","Epson","SDK ePOS","systèmes POS","développement de logiciels","intégration de matériel","guide de configuration","imprimer avec Epson","solutions d''impression"],"de":["Thermaldruck","Epson","ePOS-SDK","POS-Systeme","Software-Entwicklung","Hardware-Integration","Konfigurationsleitfaden","Drucken mit Epson","Drucklösungen"],"pt":["impressora Epson","sistema POS","SDK ePOS","integração de impressão","configuração de conexão","gerenciamento de impressões","módulo Vuex","biblioteca Epson ePOS SDK"],"ru":["принтер Epson","система POS","SDK ePOS","интеграция печати","настройка подключения","управление печатью","модуль Vuex","библиотека Epson ePOS SDK","ИИ Агенты"],"ar":["طابعة Epson","نظام نقاط البيع","SDK ePOS","دمج الطباعة","إعداد الاتصال","إدارة الطباعة","وحدة Vuex","مكتبة Epson ePOS SDK","أداة ذكاء اصطناعي"]}},"owner":"milosptr","repo":"pos-system","repoPath":"milosptr/pos-system","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.350Z","topics":[],"category":"community","skillMd":{"name":"printing-guide","description":"Reference for Epson thermal printer integration. Use when working with receipt printing, printer connection, or the ePOS SDK.","bodyPreview":"# Epson Printer Integration Guide\n\nThis POS system integrates with Epson thermal receipt printers via the ePOS SDK.\n\n## Architecture\n\n### Files\n- `resources/js/epos-2.20.0.js` - Epson ePOS SDK library (253KB)\n- `resources/js/store/modules/printing.js` - Vuex module for print management\n- `resources/js/store/modules/epos.js` - Device connection management\n- `resources/js/printing.js` - Legacy printing utilities\n\n### Connection Details\n- **IP Address**: `192.168.200.80`\n- **Port**: `8008`\n- **Prot","body":"# Epson Printer Integration Guide\n\nThis POS system integrates with Epson thermal receipt printers via the ePOS SDK.\n\n## Architecture\n\n### Files\n- `resources/js/epos-2.20.0.js` - Epson ePOS SDK library (253KB)\n- `resources/js/store/modules/printing.js` - Vuex module for print management\n- `resources/js/store/modules/epos.js` - Device connection management\n- `resources/js/printing.js` - Legacy printing utilities\n\n### Connection Details\n- **IP Address**: `192.168.200.80`\n- **Port**: `8008`\n- **Protocol**: ePOS Device Service\n\n## Vuex Store Structure\n\n### State\n```javascript\nstate: {\n    ePosDev: null,           // ePOS device instance\n    printer: null,           // Printer object\n    printingNotification: false,\n    printingAttempts: 0,\n    printing: {\n        order: null,         // Current order being printed\n        invoice: null,       // Current invoice being printed\n    },\n    printingHistory: []\n}\n```\n\n### Key Actions\n\n```javascript\n// Connect to printer\nthis.$store.dispatch(''setEpsonDevice'')\n\n// Print an order (kitchen ticket)\nthis.$store.dispatch(''setPrintingOrder'', order)\n\n// Print an invoice (receipt)\nthis.$store.dispatch(''setPrintingInvoice'', invoice)\n```\n\n## Connection Flow\n\n```javascript\n// In printing.js store module\n\nsetEpsonDevice({ commit, state }) {\n    const ePosDev = new epson.ePOSDevice();\n\n    ePosDev.connect(''192.168.200.80'', 8008, (result) => {\n        if (result === ''OK'' || result === ''SSL_CONNECT_OK'') {\n            ePosDev.createDevice(''local_printer'',\n                ePosDev.DEVICE_TYPE_PRINTER,\n                { crypto: false, buffer: false },\n                (printer, code) => {\n                    if (code === ''OK'') {\n                        printer.timeout = 60000;\n                        commit(''setEpsonDevice'', { ePosDev, printer });\n                    }\n                }\n            );\n        }\n    });\n}\n```\n\n## Receipt Formatting\n\n### Order Ticket (Kitchen)\n```javascript\n// Header\nprinter.addTextAlign(printer.ALIGN_CENTER);\nprinter.addTextSize(1, 2);\nprinter.addTextStyle(false, false, true, printer.COLOR_1);\nprinter.addText(''TABLE NAME\\n\\n'');\n\n// Time\nprinter.addTextSize(1, 1);\nprinter.addText(` Vreme: ${time}\\n`);\n\n// Items\nprinter.addTextSize(1, 2);\nprinter.addText('' —————————————————\\n'');\nitems.forEach(item => {\n    printer.addText(` ${item.qty} x ${item.name}\\n`);\n});\n\n// Cut\nprinter.addFeedLine(1);\nprinter.addCut(printer.CUT_FEED);\n```\n\n### Invoice Receipt\n```javascript\n// Header\nprinter.addText(''PREDRAČUN\\n'');  // \"Bill\" in Serbian\n\n// Items with prices\nitems.forEach(item => {\n    printer.addText(formatLine(item.name, item.total));\n});\n\n// Totals\nprinter.addText(''—————————————————\\n'');\nprinter.addText(formatLine(''UKUPNO:'', total));\nprinter.addText(formatLine(''PDV (20%):'', tax));\n\n// Receipt number\nprinter.addText(`\\nBroj: ${receiptNumber}\\n`);\n\n// Cut\nprinter.addCut(printer.CUT_FEED);\n```\n\n## Helper Functions\n\n```javascript\n// Right-align text with spacing\nfunction printerTextBetween(left, right, width = 48) {\n    const spaces = width - left.length - right.length;\n    return left + '' ''.repeat(spaces) + right;\n}\n\n// Format price\nfunction formatPrice(price) {\n    return new Intl.NumberFormat(''de-DE'').format(price);\n}\n```\n\n## Error Handling\n\n```javascript\n// Sentry integration for error tracking\nimport * as Sentry from ''@sentry/vue'';\n\nprinter.onreceive = (response) => {\n    if (!response.success) {\n        Sentry.captureException(new Error(''Print failed''));\n        commit(''setPrintingNotification'', true);\n    }\n};\n\n// Retry logic\nif (state.printingAttempts < 3) {\n    commit(''incrementPrintingAttempts'');\n    dispatch(''setEpsonDevice'');\n}\n```\n\n## Printer Commands Reference\n\n```javascript\n// Text formatting\nprinter.addTextAlign(printer.ALIGN_LEFT | ALIGN_CENTER | ALIGN_RIGHT);\nprinter.addTextSize(width, height);  // 1-8 each\nprinter.addTextStyle(reverse, underline, bold, color);\n\n// Line spacing\nprinter.addTextLineSpace(pixels);  // Default ~30\nprinter.addFeedLine(lines);\n\n// Paper cutting\nprinter.addCut(printer.CUT_FEED);     // Feed then cut\nprinter.addCut(printer.CUT_NO_FEED);  // Cut without feed\n\n// Send to printer\nprinter.send();\n```\n\n## Troubleshooting\n\n1. **Printer not connecting**: Check IP/port, ensure printer is on network\n2. **Print jobs stuck**: Call `disconnect()` and reconnect\n3. **Garbled text**: Ensure UTF-8 encoding for Serbian characters\n4. **Slow printing**: Check `buffer: false` setting\n\n## Real-time Notifications\n\nThe printing module shows a notification when:\n- Print job is in progress\n- Print job fails (with retry option)\n- Timeout after 30 seconds\n"},"lastSynced":"2026-03-08T02:03:46.486Z","agentAnalysis":{"suitability":{"en":"Perfect for Point-of-Sale Agents needing seamless Epson thermal receipt printer integration via the ePOS SDK.","zh":"非常适合需要无缝集成Epson热敏收据打印机的销售点代理，通过ePOS SDK实现。","ja":"Epsonの熱感レシートプリンターをePOS SDK経由でシームレスに統合する必要があるPOSエージェントに最適です。","ko":"ePOS SDK를 통해 Epson 熱감지 영수증 프린터를 무缝으로 통합해야 하는 POS 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Punto de Venta que necesitan una integración sin problemas de la impresora de recibos térmicos Epson a través del SDK ePOS.","fr":"Parfait pour les agents de point de vente ayant besoin d''une intégration transparente de l''imprimante de reçus thermiques Epson via le SDK ePOS.","de":"Perfekt für Point-of-Sale-Agenten, die eine nahtlose Integration des Epson-Thermal-Receipt-Druckers über das ePOS SDK benötigen.","pt":"Perfeito para Agentes de Pontos de Venda que precisam de integração sem problemas de impressora térmica Epson via o SDK ePOS.","ru":"Идеально подходит для агентов точки продаж, которым необходима бесшовная интеграция термопринтера Epson через SDK ePOS.","ar":" مثالي للوكلاء نقطة البيع الذين يحتاجون إلى دمج مطبعة حرارية Epson بدون مشاكل عبر SDK ePOS."},"recommendation":{"en":"Empowers agents to manage print jobs and device connections using the Epson ePOS SDK library, facilitating reliable printing solutions for POS systems over IP addresses and specific ports like 8008.","zh":"赋予代理管理打印作业和设备连接的能力，使用Epson ePOS SDK库，通过IP地址和特定端口（如8008）实现可靠的打印解决方案，适用于POS系统。","ja":"Epson ePOS SDKライブラリを使用して、エージェントが印刷ジョブとデバイスの接続を管理できるようにし、IPアドレスと特定のポート（例：8008）を介して、POSシステム向けの信頼性の高い印刷ソリューションを提供します。","ko":"Epson ePOS SDK 라이브러리를 사용하여 에이전트가 인쇄 작업 및 장치 연결을 관리할 수 있도록 하여, IP 주소 및 특정 포트(예: 8008)를 통해 POS 시스템을 위한 안정적인 인쇄 솔루션을 제공합니다.","es":"Habilita a los agentes a gestionar trabajos de impresión y conexiones de dispositivos utilizando la biblioteca del SDK Epson ePOS, lo que facilita soluciones de impresión confiables para sistemas POS a través de direcciones IP y puertos específicos como el 8008.","fr":"Permet aux agents de gérer les travaux d''impression et les connexions d''appareils en utilisant la bibliothèque du SDK Epson ePOS, ce qui facilite des solutions d''impression fiables pour les systèmes POS sur des adresses IP et des ports spécifiques comme le 8008.","de":"Ermöglicht es Agenten, Druckjobs und Geräteverbindungen mithilfe der Epson-ePOS-SDK-Bibliothek zu verwalten, was zuverlässige Drucklösungen für POS-Systeme über IP-Adressen und bestimmte Ports wie 8008 ermöglicht.","pt":"Habilita os agentes a gerenciar trabalhos de impressão e conexões de dispositivos usando a biblioteca do SDK Epson ePOS, facilitando soluções de impressão confiáveis para sistemas de ponto de venda sobre endereços IP e portas específicas como 8008.","ru":"Наделяет агентов возможностью управлять заданиями печати и подключениями устройств с помощью библиотеки SDK Epson ePOS, обеспечивая надежные решения для печати в системах точек продаж по IP-адресам и определенным портам, таким как 8008.","ar":"تمكن الوكلاء من إدارة مهام الطباعة واتهاب الأجهزة باستخدام مكتبة SDK Epson ePOS ، و تسهل حلول طباعة موثوقة لأنظمة نقطة البيع عبر عناوين IP ومنافذ محددة مثل 8008."},"useCases":{"en":["Configuring Epson printer settings for POS systems","Managing print queues via the ePOS SDK","Integrating thermal receipt printing into existing POS architectures"],"zh":["为POS系统配置Epson打印机设置","通过ePOS SDK管理打印队列","将热敏收据打印集成到现有的POS架构中"],"ja":["POSシステム向けのEpsonプリンター設定の構成","ePOS SDKを使用した印刷キューの管理","既存のPOSアーキテクチャへの熱感レシート印刷の統合"],"ko":["POS 시스템을 위한 Epson 프린터 설정 구성","ePOS SDK를 사용한 인쇄 큐 관리","기존 POS 아키텍처에热감지 영수증 인쇄 통합"],"es":["Configuración de la configuración de la impresora Epson para sistemas POS","Administración de colas de impresión a través del SDK ePOS","Integración de la impresión de recibos térmicos en arquitecturas POS existentes"],"fr":["Configuration des paramètres d''imprimante Epson pour les systèmes POS","Gestion des files d''impression via le SDK ePOS","Intégration de l''impression de reçus thermiques dans les architectures POS existantes"],"de":["Konfiguration der Epson-Drucker-Einstellungen für POS-Systeme","Verwaltung von Druckwarteschlangen über das ePOS-SDK","Integration des thermischen Quittungsdrucks in bestehende POS-Architekturen"],"pt":["Configurando configurações da impressora Epson para sistemas de ponto de venda","Gerenciando filas de impressão via o SDK ePOS","Integrando impressão de recibos térmicos em arquiteturas de ponto de venda existentes"],"ru":["Настройка параметров принтера Epson для систем точки продаж","Управление очередями печати через SDK ePOS","Интеграция термопечати чеков в существующие архитектуры точек продаж"],"ar":["تكوين إعدادات مطبعة Epson لأنظمة نقطة البيع","إدارة طوابير الطباعة عبر SDK ePOS","دمج طباعة الإيصالات الحرارية في الهياكل المعمارية لنقطة البيع الحالية"]},"limitations":{"en":["Requires Epson ePOS SDK library","Epson thermal receipt printers only","Specific IP address and port configuration needed"],"zh":["需要Epson ePOS SDK库","仅支持Epson热敏收据打印机","需要特定IP地址和端口配置"],"ja":["Epson ePOS SDKライブラリが必要","Epson熱感レシートプリンターのみをサポート","特定のIPアドレスとポートの構成が必要"],"ko":["Epson ePOS SDK 라이브러리가 필요","Epson 熱감지 영수증 프린터만 지원","특정 IP 주소 및 포트 구성이 필요"],"es":["Requiere la biblioteca del SDK Epson ePOS","Solo impresoras de recibos térmicos Epson","Se requiere una configuración de dirección IP y puerto específica"],"fr":["Nécessite la bibliothèque du SDK Epson ePOS","Imprimantes de reçus thermiques Epson uniquement","Une configuration d''adresse IP et de port spécifique est nécessaire"],"de":["Benötigt die Epson-ePOS-SDK-Bibliothek","Nur Epson-Thermal-Receipt-Drucker","Eine bestimmte IP-Adresse- und Portkonfiguration ist erforderlich"],"pt":["Requer a biblioteca do SDK Epson ePOS","Apenas impressoras de recibo térmico Epson","Configuração de endereço IP e porta específica necessária"],"ru":["Требует библиотеки SDK Epson ePOS","Только термопринтеры чеков Epson","Необходима настройка определенного IP-адреса и порта"],"ar":["يتطلب مكتبة SDK Epson ePOS","مطبعات إيصالات حرارية Epson فقط","يتطلب تكوين عنوان IP ومنفذ محدد"]},"version":4},"contentHash":"6e9e53bdbf505d20972b50d5013d12e05f281b7ebb0d5f3879cfcda53143b804","qualityScore":36}');
