INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('milosptr/pos-system/printing-guide', 'printing-guide', 'milosptr', 'pos-system', 'community', 'printing-guide milosptr pos-system community The printing-guide skill integrates Epson thermal receipt printers via the ePOS SDK, enabling seamless printing for POS systems. It benefits developers and businesses seeking reliable printing solutions. 本打印指南介绍 Epson 打印机集成的技术细节，包括 ePOS SDK 和 Vuex 模块 この印刷ガイドでは、Epson プリンター統合の技術的詳細を説明します。ePOS SDK と Vuex モジュールを含みます 이 인쇄 가이드는 Epson 프린터 통합의 기술적 세부 사항을 설명합니다. ePOS SDK 및 Vuex 모듈을 포함합니다 La guía de impresión para desarrolladores explica cómo integrar impresoras térmicas de Epson en sistemas POS utilizando el SDK ePOS. La guide d''impression pour les développeurs explique comment intégrer les imprimantes thermiques Epson aux systèmes POS en utilisant le SDK ePOS. Der Druckleitfaden für Entwickler erklärt, wie Epson-Thermaldrucker in POS-Systeme mithilfe des ePOS-SDK integriert werden können. O guia de impressão Epson é uma integração com o sistema POS via SDK ePOS, permitindo a configuração de conexão e gerenciamento de impressões Руководство по печати Epson является интеграцией с системой POS через SDK ePOS, позволяющей настраивать подключение и управлять печатью دليل الطباعة Epson هو دمج مع نظام نقاط البيع عبر SDK ePOS، مما يسمح بإعداد الاتصال وإدارة الطباعة how to use printing-guide printing-guide setup guide Epson printer integration ePOS SDK tutorial printing-guide alternative printing-guide vs other printer integrations printing-guide install what is printing-guide printing-guide documentation Epson 打印机集成 ePOS SDK Vuex 模块 打印管理 设备连接管理 AIエージェント 打印指南 Epson 热敏收据打印机 Utilizes the Epson ePOS SDK library (253KB) for printer integration Manages print operations via the Vuex module for print management Handles device connections through the `resources/js/store/modules/epos.js` module Supports legacy printing utilities via `resources/js/printing.js` Connects to printers using IP Address `192.168.200.80` and Port `8008` printing-guide is a technical integration skill for Epson thermal receipt printers using the ePOS SDK, facilitating device connection and print management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Syedaashnaghazanfar/todo-app/notification-ui', 'community', 'Syedaashnaghazanfar', 'todo-app', 'Syedaashnaghazanfar/todo-app', 'notification-ui', 0, 0, 36, '2026-03-08T01:57:15.350Z', '2026-03-08T02:03:47.163Z', 'b1470954596364db57b123d0b13f4d053961314448b77eb12a1c68d7bf378715', '{"id":"Syedaashnaghazanfar/todo-app/notification-ui","name":"notification-ui","description":{"en":"The notification-ui skill provides a visual interface for displaying notifications, benefiting developers who need to render app headers, display unread notification counts, and animate new arrivals.","zh":"Notification UI Skill提供了显示通知的视觉界面，包括bell icon、badge、动画指示器和交互式通知面板","ja":"Notification UI Skillは、ベルアイコン、バッジ、動画インジケーター、インタラクティブな通知パネルを備えた通知の表示インターフェイスを提供","ko":"Notification UI Skill은 벨 아이콘, 배지, 애니메이션 인디케이터 및 상호 작용형 알림 패널을 포함한 알림 표시를 위한 시각적 인터페이스를 제공","es":"La notificación UI proporciona una interfaz visual para mostrar notificaciones, incluyendo un icono de campana con insignia y un panel de notificación interactivo","fr":"L''interface de notification UI fournit une interface visuelle pour afficher les notifications, y compris un icône de cloche avec badge et un panneau de notification interactif","de":"Die Benachrichtigungs-UI bietet eine visuelle Oberfläche zum Anzeigen von Benachrichtigungen, einschließlich eines Glockensymbols mit Abzeichen und einem interaktiven Benachrichtigungspanel","pt":"A notificação UI fornece uma interface visual para exibir notificações, incluindo um ícone de sino com badge e painel de notificações interativo.","ru":"Интерфейс уведомлений предоставляет визуальный интерфейс для отображения уведомлений, включая иконку колокольчика с бейджем и интерактивную панель уведомлений.","ar":"واجهة الإشعارات توفر واجهة بصرية لعرض الإشعارات، بما في ذلك رمز الجرس مع شارة ولوحة إشعارات تفاعلية."},"seo":{"title":{"en":"notification-ui: Interactive Notification Panel Setup Gui...","zh":"Notification UI Skill Setup Guide - AIエージェント开发指南","ja":"Notification UI Skill ベストプラクティス - AIエージェントの実装方法","ko":"Notification UI Skill 개발 가이드 - AI 도구를 사용한 알림 인터페이스 구축","es":"Guía de Configuración de Notificación UI para Desarrollad...","fr":"Guide de Mise en Place de l''Interface de Notification pou...","de":"Einrichtungsleitfaden für Benachrichtigungs-UI für Entwic...","pt":"Guia de Configuração de Notificação UI","ru":"ИИ Агенты: Настройка Интерфейса Уведомлений","ar":"دليل إعداد واجهة الإشعارات"},"description":{"en":"Discover how to implement a visually appealing notification UI with animated indicators and interactive panels - get started with our setup guide today!","zh":"了解Notification UI Skill的功能和应用场景，实现高效的AIエージェント开发","ja":"Notification UI Skillの特徴と使い方をマスターして、AIエージェントの開発を効率化","ko":"Notification UI Skill의 주요 기능과 사용 방법을 익히고 AI 도구를 사용한 알림 인터페이스를 구축","es":"Aprende a implementar la interfaz de notificación UI en tu aplicación con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment mettre en place l''interface de notification UI dans votre application avec notre guide étape par étape pour développeurs","de":"Erfahren Sie, wie Sie die Benachrichtigungs-UI in Ihrer Anwendung implementieren, mit unserer Schritt-für-Schritt-Anleitung für Entwickler","pt":"Aprenda a implementar a notificação UI em seu aplicativo com nosso guia de configuração","ru":"Узнайте, как настроить интерфейс уведомлений в вашем приложении с помощью ИИ Агентов","ar":"تعلم كيفية تطبيق واجهة الإشعارات في تطبيقك باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"notification-ui is a technical skill that provides a visual interface for displaying notifications, including bell icons, badges, and interactive panels.","zh":"Notification UI Skill是一种提供显示通知视觉界面的AIエージェント技能","ja":"Notification UI Skillは、通知の表示インターフェイスを提供するAIエージェントのスキル","ko":"Notification UI Skill은 알림 표시를 위한 시각적 인터페이스를 제공하는 AI 도구의 스킬","es":"La notificación UI es una habilidad que proporciona una interfaz visual para mostrar notificaciones en aplicaciones","fr":"L''interface de notification UI est une compétence qui fournit une interface visuelle pour afficher les notifications dans les applications","de":"Die Benachrichtigungs-UI ist eine Fähigkeit, die eine visuelle Oberfläche zum Anzeigen von Benachrichtigungen in Anwendungen bietet","pt":"Notificação UI é um recurso que fornece uma interface visual para exibir notificações","ru":"Интерфейс уведомлений - это функция, предоставляющая визуальный интерфейс для отображения уведомлений","ar":"واجهة الإشعارات هي ميزة توفر واجهة بصرية لعرض الإشعارات"},"features":{"en":["Renders a bell icon with badge for unread notification counts","Displays an interactive notification panel with animated indicators","Supports animation of new notification arrivals","Allows user interaction with notifications, such as clicking to mark as read","Integrates with app headers for seamless notification display"],"zh":["bell icon和badge显示","动画指示器","交互式通知面板","新通知到达时的动画效果","用户与通知交互时的点击效果"],"ja":["ベルアイコンとバッジの表示","動画インジケーター","インタラクティブな通知パネル","新しい通知の到着時にアニメーション効果","ユーザーが通知と交互作用するときのクリック効果"],"ko":["벨 아이콘과 배지 표시","애니메이션 인디케이터","상호 작용형 알림 패널","새로운 알림이 도착했을 때 애니메이션 효과","사용자가 알림과 상호 작용할 때 클릭 효과"],"es":["Icono de campana con insignia para notificaciones no leídas","Panel de notificación interactivo para mostrar notificaciones","Indicadores animados para nuevas notificaciones","Compatibilidad con la renderización de la cabecera de la aplicación","Funcionalidad de clic para marcar notificaciones como leídas"],"fr":["Icône de cloche avec badge pour les notifications non lues","Panneau de notification interactif pour afficher les notifications","Indicateurs animés pour les nouvelles notifications","Compatibilité avec la renderisation de l''en-tête de l''application","Fonctionnalité de clic pour marquer les notifications comme lues"],"de":["Glockensymbol mit Abzeichen für ungelesene Benachrichtigungen","Interaktives Benachrichtigungspanel zum Anzeigen von Benachrichtigungen","Animierte Indikatoren für neue Benachrichtigungen","Kompatibilität mit der Renderierung der Applikationsheader","Klickfunktion zum Markieren von Benachrichtigungen als gelesen"],"pt":["Ícone de sino com badge","Painel de notificações interativo","Indicadores animados para novas notificações","Interação com notificações (clique para marcar como lida)","Renderização da barra de aplicativos com ícone de sino"],"ru":["Иконка колокольчика с бейджем","Интерактивная панель уведомлений","Анимированные индикаторы для новых уведомлений","Взаимодействие с уведомлениями (клик для отметки как прочитанное)","Рендеринг панели приложения с иконкой колокольчика"],"ar":["رمز الجرس مع شارة","لوحة إشعارات تفاعلية","مؤشرات متحركة للرسائل الجديدة","التفاعل مع الرسائل (النقر للتعليم على أنها مقروءة)","تجسيد شريط التطبيق مع رمز الجرس"]},"keywords":{"en":["how to use notification-ui","what is notification-ui","notification-ui alternative","notification-ui vs competitors","notification-ui install","notification-ui setup guide","notification ui tutorial","notification ui best practices"],"zh":["Notification UI Skill","AIエージェント开发","通知显示","bell icon","badge","动画指示器","交互式通知面板"],"ja":["Notification UI Skill","AIエージェントの開発","通知の表示","ベルアイコン","バッジ","動画インジケーター","インタラクティブな通知パネル"],"ko":["Notification UI Skill","AI 도구 개발","알림 표시","벨 아이콘","배지","애니메이션 인디케이터","상호 작용형 알림 패널"],"es":["notificación UI","interfaz de notificación","desarrollo de aplicaciones","renderización de la cabecera","panel de notificación","indicadores animados","Herramientas de AI para desarrolladores","Agentes de IA para notificaciones"],"fr":["interface de notification UI","interface de notification","développement d''applications","renderisation de l''en-tête","panneau de notification","indicateurs animés","Outils d''IA pour développeurs","Agents d''IA pour les notifications"],"de":["Benachrichtigungs-UI","Benachrichtigungs-Oberfläche","Anwendungsentwicklung","Renderierung der Applikationsheader","Benachrichtigungspanel","animierte Indikatoren","AI-Tools für Entwickler","KI-Agents für Benachrichtigungen"],"pt":["notificação ui","interface de notificação","ícone de sino","painel de notificações","desenvolvimento de aplicativos","guias de configuração"],"ru":["интерфейс уведомлений","ИИ Агенты","уведомления","панель уведомлений","разработка приложений","настройка интерфейса"],"ar":["واجهة الإشعارات","أدوات الذكاء الاصطناعي","الإشعارات","لوحة الإشعارات","تطوير التطبيقات","دليل الإعداد"]}},"owner":"Syedaashnaghazanfar","repo":"todo-app","repoPath":"Syedaashnaghazanfar/todo-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.350Z","topics":[],"category":"community","skillMd":{"name":"notification-ui","description":"Renders notification bell icon with unread count badge, pulse animations for new notifications, and dropdown panel (320px × max 400px) displaying notification items with purple theme for VERY IMPORTANT tasks. Includes mark-as-read interaction and empty state handling.","bodyPreview":"# Notification UI Skill\n\n## Overview\n\nThe notification UI skill provides the visual interface for displaying notifications, including a bell icon with badge, animated indicators, and an interactive notification panel.\n\n## When to Apply\n\nApply this skill:\n- When rendering the app header (bell icon)\n- When displaying unread notification count\n- When showing notification panel/dropdown\n- When animating new notification arrivals\n- When user interacts with notifications (click to mark as read)\n- When","body":"# Notification UI Skill\n\n## Overview\n\nThe notification UI skill provides the visual interface for displaying notifications, including a bell icon with badge, animated indicators, and an interactive notification panel.\n\n## When to Apply\n\nApply this skill:\n- When rendering the app header (bell icon)\n- When displaying unread notification count\n- When showing notification panel/dropdown\n- When animating new notification arrivals\n- When user interacts with notifications (click to mark as read)\n- When displaying empty state (no notifications)\n\n## Bell Icon Specifications\n\n### Icon Size and Position\n\n- **Size**: 24px × 24px\n- **Position**: Top-right header\n- **Color**: Default #374151 (gray), hover #1F2937 (dark gray)\n\n```jsx\nfunction BellIcon({ unreadCount, onClick }) {\n  return (\n    <button\n      className=\"bell-icon-button\"\n      onClick={onClick}\n      aria-label={`Notifications (${unreadCount} unread)`}\n    >\n      <svg\n        width=\"24\"\n        height=\"24\"\n        viewBox=\"0 0 24 24\"\n        fill=\"none\"\n        xmlns=\"http://www.w3.org/2000/svg\"\n        className=\"bell-icon\"\n      >\n        <path\n          d=\"M15 17H20L18.5951 15.5951C18.2141 15.2141 18 14.6973 18 14.1585V11C18 8.38757 16.3304 6.16509 14 5.34142V5C14 3.89543 13.1046 3 12 3C10.8954 3 10 3.89543 10 5V5.34142C7.66962 6.16509 6 8.38757 6 11V14.1585C6 14.6973 5.78595 15.2141 5.40493 15.5951L4 17H9M15 17V18C15 19.6569 13.6569 21 12 21C10.3431 21 9 19.6569 9 18V17M15 17H9\"\n          stroke=\"currentColor\"\n          strokeWidth=\"2\"\n          strokeLinecap=\"round\"\n          strokeLinejoin=\"round\"\n        />\n      </svg>\n      {unreadCount > 0 && (\n        <span className=\"badge\">{unreadCount > 99 ? ''99+'' : unreadCount}</span>\n      )}\n    </button>\n  );\n}\n```\n\n### Bell Icon Styling\n\n```css\n.bell-icon-button {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 8px;\n  background: transparent;\n  border: none;\n  cursor: pointer;\n  border-radius: 6px;\n  transition: background-color 0.2s ease;\n}\n\n.bell-icon-button:hover {\n  background-color: #F3F4F6;\n}\n\n.bell-icon {\n  color: #374151;\n  transition: color 0.2s ease;\n}\n\n.bell-icon-button:hover .bell-icon {\n  color: #1F2937;\n}\n```\n\n## Unread Count Badge\n\n### Badge Specifications\n\n- **Shape**: Circular\n- **Background**: #DC2626 (red)\n- **Text**: White (#FFFFFF)\n- **Display**: Count up to 99, then \"99+\"\n- **Position**: Top-right corner of bell icon\n\n```css\n.badge {\n  position: absolute;\n  top: 4px;\n  right: 4px;\n  min-width: 18px;\n  height: 18px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: #DC2626; /* Red */\n  color: #FFFFFF; /* White */\n  font-size: 10px;\n  font-weight: 700;\n  border-radius: 50%;\n  padding: 0 4px;\n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);\n}\n```\n\n### Badge Display Logic\n\n```javascript\nfunction getBadgeText(count) {\n  if (count === 0) return null; // No badge\n  if (count > 99) return ''99+'';\n  return count.toString();\n}\n```\n\n## Pulse Animation\n\n### Animation Specifications\n\n- **Duration**: 2 seconds\n- **Effect**: Purple glow (#8B5CF6)\n- **Trigger**: On new notification arrival\n- **Iterations**: 3 times, then stop\n\n```css\n@keyframes pulse {\n  0%, 100% {\n    box-shadow: 0 0 0 0 rgba(139, 92, 246, 0.7);\n  }\n  50% {\n    box-shadow: 0 0 0 8px rgba(139, 92, 246, 0);\n  }\n}\n\n.bell-icon-button.pulsing {\n  animation: pulse 2s ease-in-out 3;\n}\n```\n\n### Animation Trigger\n\n```jsx\nfunction NotificationBell({ notifications }) {\n  const [isPulsing, setIsPulsing] = useState(false);\n  const prevCountRef = useRef(notifications.length);\n\n  useEffect(() => {\n    // Detect new notification\n    if (notifications.length > prevCountRef.current) {\n      setIsPulsing(true);\n\n      // Stop animation after 6 seconds (3 iterations × 2s)\n      setTimeout(() => setIsPulsing(false), 6000);\n    }\n\n    prevCountRef.current = notifications.length;\n  }, [notifications.length]);\n\n  return (\n    <BellIcon\n      className={isPulsing ? ''pulsing'' : ''''}\n      unreadCount={notifications.filter(n => !n.read).length}\n    />\n  );\n}\n```\n\n## Notification Dropdown Panel\n\n### Panel Specifications\n\n- **Width**: 320px\n- **Max Height**: 400px\n- **Scrollable**: Yes (overflow-y: auto)\n- **Position**: Dropdown below bell icon\n- **Elevation**: Shadow for depth\n\n```css\n.notification-dropdown {\n  position: absolute;\n  top: calc(100% + 8px);\n  right: 0;\n  width: 320px;\n  max-height: 400px;\n  overflow-y: auto;\n  background-color: #FFFFFF;\n  border: 1px solid #E5E7EB;\n  border-radius: 8px;\n  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1),\n              0 4px 6px -2px rgba(0, 0, 0, 0.05);\n  z-index: 1000;\n}\n\n.notification-dropdown-header {\n  padding: 16px;\n  border-bottom: 1px solid #E5E7EB;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.notification-dropdown-title {\n  font-size: 16px;\n  font-weight: 600;\n  color: #111827;\n}\n\n.mark-all-read {\n  font-size: 12px;\n  color: #8B5CF6;\n  background: none;\n  border: none;\n  cursor: pointer;\n  font-weight: 600;\n}\n\n.mark-all-read:hover {\n  color: #7C3AED;\n  text-decoration: underline;\n}\n```\n\n## Notification Item Styling\n\n### Item Specifications\n\n- **Padding**: 16px\n- **Border**: Bottom separator (1px solid #F3F4F6)\n- **Hover**: Background change to #F9FAFB\n- **Purple Theme**: VERY IMPORTANT notifications use #8B5CF6 accent\n\n```css\n.notification-item {\n  padding: 16px;\n  border-bottom: 1px solid #F3F4F6;\n  cursor: pointer;\n  transition: background-color 0.15s ease;\n}\n\n.notification-item:hover {\n  background-color: #F9FAFB;\n}\n\n.notification-item:last-child {\n  border-bottom: none;\n}\n\n.notification-item.unread {\n  background-color: #FAF5FF; /* Very light purple */\n}\n\n.notification-item.unread:hover {\n  background-color: #F3E8FF; /* Light purple */\n}\n\n.notification-content {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.notification-header {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n}\n\n.notification-priority-indicator {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background-color: #8B5CF6; /* Purple for VERY IMPORTANT */\n  margin-top: 6px;\n  flex-shrink: 0;\n}\n\n.notification-message {\n  font-size: 14px;\n  color: #374151;\n  line-height: 1.5;\n  flex: 1;\n}\n\n.notification-item.unread .notification-message {\n  font-weight: 600;\n  color: #111827;\n}\n\n.notification-time {\n  font-size: 12px;\n  color: #9CA3AF;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n}\n\n.unread-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background-color: #8B5CF6; /* Purple */\n}\n```\n\n## Complete Notification Item Component\n\n```jsx\nfunction NotificationItem({ notification, onMarkAsRead }) {\n  const handleClick = () => {\n    if (!notification.read) {\n      onMarkAsRead(notification.id);\n    }\n  };\n\n  const relativeTime = formatRelativeTime(notification.timestamp);\n\n  return (\n    <div\n      className={`notification-item ${notification.read ? '''' : ''unread''}`}\n      onClick={handleClick}\n    >\n      <div className=\"notification-content\">\n        <div className=\"notification-header\">\n          <div className=\"notification-priority-indicator\" />\n          <p className=\"notification-message\">{notification.message}</p>\n        </div>\n        <div className=\"notification-time\">\n          {!notification.read && <span className=\"unread-dot\" />}\n          <span>{relativeTime}</span>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction formatRelativeTime(timestamp) {\n  const now = Date.now();\n  const diff = now - timestamp;\n  const minutes = Math.floor(diff / (1000 * 60));\n  const hours = Math.floor(diff / (1000 * 60 * 60));\n  const days = Math.floor(diff / (1000 * 60 * 60 * 24));\n\n  if (minutes < 1) return ''Just now'';\n  if (minutes < 60) return `${minutes}m ago`;\n  if (hours < 24) return `${hours}h ago`;\n  return `${days}d ago`;\n}\n```\n\n## Mark-as-Read Interaction\n\n### Click to Mark Read\n\nClicking an unread notification marks it as read:\n\n```jsx\nfunction handleNotificationClick(notification) {\n  if (!notification.read) {\n    // Mark as read\n    notificationPersistence.markAsRead(notification.id);\n\n    // Update UI state\n    setNotifications(notificationPersistence.getAll());\n    setUnreadCount(notificationPersistence.getUnreadCount());\n\n    // Optional: Navigate to task\n    navigateToTask(notification.taskId);\n  }\n}\n```\n\n### Visual Feedback\n\n```jsx\nfunction NotificationItem({ notification, onMarkAsRead }) {\n  const [isMarking, setIsMarking] = useState(false);\n\n  const handleClick = async () => {\n    if (!notification.read && !isMarking) {\n      setIsMarking(true);\n      await onMarkAsRead(notification.id);\n      setIsMarking(false);\n    }\n  };\n\n  return (\n    <div\n      className={`notification-item ${notification.read ? '''' : ''unread''} ${isMarking ? ''marking'' : ''''}`}\n      onClick={handleClick}\n    >\n      {/* ... */}\n    </div>\n  );\n}\n```\n\n## Empty State\n\n### Empty State Component\n\n```jsx\nfunction EmptyState() {\n  return (\n    <div className=\"notification-empty-state\">\n      <div className=\"empty-icon\">🔔</div>\n      <p className=\"empty-title\">No notifications</p>\n      <p className=\"empty-description\">\n        You''re all caught up! Notifications for VERY IMPORTANT tasks will appear here.\n      </p>\n    </div>\n  );\n}\n```\n\n### Empty State Styling\n\n```css\n.notification-empty-state {\n  padding: 48px 24px;\n  text-align: center;\n  color: #6B7280;\n}\n\n.empty-icon {\n  font-size: 48px;\n  margin-bottom: 16px;\n  opacity: 0.4;\n}\n\n.empty-title {\n  font-size: 16px;\n  font-weight: 600;\n  color: #374151;\n  margin-bottom: 8px;\n}\n\n.empty-description {\n  font-size: 14px;\n  color: #9CA3AF;\n  line-height: 1.5;\n}\n```\n\n## Complete Notification System\n\n```jsx\nfunction NotificationSystem() {\n  const [isOpen, setIsOpen] = useState(false);\n  const [notifications, setNotifications] = useState([]);\n  const [unreadCount, setUnreadCount] = useState(0);\n  const dropdownRef = useRef(null);\n\n  // Load notifications\n  useEffect(() => {\n    const loaded = notificationPersistence.getAll();\n    setNotifications(loaded);\n    setUnreadCount(notificationPersistence.getUnreadCount());\n  }, []);\n\n  // Close dropdown when clicking outside\n  useEffect(() => {\n    function handleClickOutside(event) {\n      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {\n        setIsOpen(false);\n      }\n    }\n\n    document.addEventListener(''mousedown'', handleClickOutside);\n    return () => document.removeEventListener(''mousedown'', handleClickOutside);\n  }, []);\n\n  const handleMarkAsRead = (id) => {\n    notificationPersistence.markAsRead(id);\n    setNotifications(notificationPersistence.getAll());\n    setUnreadCount(notificationPersistence.getUnreadCount());\n  };\n\n  const handleMarkAllAsRead = () => {\n    notificationPersistence.markAllAsRead();\n    setNotifications(notificationPersistence.getAll());\n    setUnreadCount(0);\n  };\n\n  return (\n    <div className=\"notification-system\" ref={dropdownRef}>\n      <NotificationBell\n        unreadCount={unreadCount}\n        onClick={() => setIsOpen(!isOpen)}\n        notifications={notifications}\n      />\n\n      {isOpen && (\n        <div className=\"notification-dropdown\">\n          <div className=\"notification-dropdown-header\">\n            <h3 className=\"notification-dropdown-title\">Notifications</h3>\n            {unreadCount > 0 && (\n              <button className=\"mark-all-read\" onClick={handleMarkAllAsRead}>\n                Mark all as read\n              </button>\n            )}\n          </div>\n\n          {notifications.length === 0 ? (\n            <EmptyState />\n          ) : (\n            <div className=\"notification-list\">\n              {notifications.map(notification => (\n                <NotificationItem\n                  key={notification.id}\n                  notification={notification}\n                  onMarkAsRead={handleMarkAsRead}\n                />\n              ))}\n            </div>\n          )}\n        </div>\n      )}\n    </div>\n  );\n}\n```\n\n## Responsive Behavior\n\n### Mobile Adjustments\n\n```css\n@media (max-width: 640px) {\n  .notification-dropdown {\n    position: fixed;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    width: 100%;\n    max-height: 100%;\n    border-radius: 0;\n  }\n\n  .notification-dropdown-header {\n    position: sticky;\n    top: 0;\n    background-color: #FFFFFF;\n    z-index: 1;\n  }\n}\n```\n\n## Integration Points\n\nThis skill integrates with:\n- **Notification Persistence Skill**: Reads notification data\n- **Notification Trigger Skill**: Displays triggered notifications\n- **Priority Classification Skill**: Uses purple theme for VERY IMPORTANT\n- **Notification Experience Agent**: Coordinates UI interactions\n\n## Accessibility\n\n- Bell icon button has aria-label with unread count\n- Keyboard navigation supported (Enter/Space to open/close)\n- Focus management in dropdown\n- Screen reader announcements for new notifications\n- Sufficient color contrast ratios (WCAG AA)\n\n## Performance Considerations\n\n- Dropdown renders only when open (conditional rendering)\n- Virtual scrolling for large notification lists (>50)\n- Debounced mark-as-read operations\n- Memoized components to prevent unnecessary re-renders\n"},"lastSynced":"2026-03-08T02:03:47.163Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring interactive notification interfaces with animated indicators and customizable notification panels.","zh":"适用于需要交互式通知界面、带有动画指示器和可自定义通知面板的前端代理。","ja":"フロントエンドエージェントがインタラクティブな通知インターフェイスとアニメーションインジケーターおよびカスタマイズ可能な通知パネルを必要とする場合に最適です。","ko":"프론트엔드 에이전트가 상호 작용형 알림 인터페이스와 애니메이션 인디케이터 및 사용자 정의 가능한 알림 패널을 필요로 하는 경우에 적합합니다.","es":"Ideal para Agentes Frontend que requieren interfaces de notificación interactivas con indicadores animados y paneles de notificación personalizables.","fr":"Idéal pour les agents Frontend nécessitant des interfaces de notification interactives avec des indicateurs animés et des panneaux de notification personnalisables.","de":"Ideal für Frontend-Agents, die interaktive Benachrichtigungsinterfaces mit animierten Indikatoren und anpassbaren Benachrichtigungspaneelen erfordern.","pt":"Ideal para Agentes de Frontend que requerem interfaces de notificação interativas com indicadores animados e painéis de notificação personalizáveis.","ru":"Идеально для агентов Frontend, требующих интерактивных уведомлений с анимированными индикаторами и настраиваемыми панелями уведомлений.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يتطلب واجهات إعلام تفاعلية مع مؤشرات متحركة وألواح إعلام قابلة للتخصيص."},"recommendation":{"en":"Empowers agents to render app headers with bell icons and badges, display unread notification counts, and animate new arrivals using interactive notification panels and dropdowns, leveraging HTML, CSS, and JavaScript protocols.","zh":"赋予代理渲染带有铃铛图标和徽章的应用程序标题、显示未读通知计数，并使用交互式通知面板和下拉菜单来渲染新通知，利用 HTML、CSS 和 JavaScript 协议。","ja":"エージェントは、HTML、CSS、JavaScript プロトコルを利用して、アプリケーションヘッダーをベルアイコンとバッジでレンダリングし、未読の通知カウントを表示し、インタラクティブな通知パネルとドロップダウンを使用して新しい着信をアニメーション化することができます。","ko":"에이전트가 HTML, CSS, JavaScript 프로토콜을 활용하여 애플리케이션 제목을 벨 아이콘과 배지로 렌더링하고, 읽지 않은 알림 수를 표시하고, 상호 작용형 알림 패널과 드롭다운을 사용하여新的 알림을 애니메이션화 할 수 있습니다.","es":"Habilita a los agentes para renderizar encabezados de aplicaciones con iconos de campana y insignias, mostrar recuentos de notificaciones no leídas y animar nuevas llegadas utilizando paneles de notificación interactivos y menús desplegables, aprovechando los protocolos HTML, CSS y JavaScript.","fr":"Permet aux agents de rendre des en-têtes d''applications avec des icônes de cloche et des badges, d''afficher des comptes de notifications non lus et d''animer les nouvelles arrivées en utilisant des panneaux de notification interactifs et des menus déroulants, en exploitant les protocoles HTML, CSS et JavaScript.","de":"Ermöglicht es Agents, App-Headern mit Glocken-Symbolen und Abzeichen zu rendern, ungelesene Benachrichtigungsanzahlen anzuzeigen und neue Ankünfte mithilfe interaktiver Benachrichtigungspaneelen und Dropdowns zu animieren, wobei die HTML-, CSS- und JavaScript-Protokolle genutzt werden.","pt":"Habilita os agentes a renderizar cabeçalhos de aplicativos com ícones de sino e emblemas, exibir contagens de notificações não lidas e animar novas chegadas usando painéis de notificação interativos e menus suspensos, aproveitando os protocolos HTML, CSS e JavaScript.","ru":"Наделяет агентов возможностью отображать заголовки приложений с колокольчиками и значками, отображать количество непрочитанных уведомлений и анимировать новые прибытия с помощью интерактивных панелей уведомлений и выпадающих меню, используя протоколы HTML, CSS и JavaScript.","ar":"تمكّن العميل من عرض رأس تطبيقات مع أيقونات الجرس والشعارات، وعرض عدد الإشعارات غير المقروءة، وتحريك الوارد الجديد باستخدام ألواح الإعلام التفاعلية والقوائم المنسدلة، مستفيدا من بروتوكولات HTML و CSS وJavaScript."},"useCases":{"en":["Rendering app headers with dynamic notification badges","Animating new notification arrivals with interactive indicators","Displaying unread notification counts and updating in real-time","Generating interactive notification panels with customizable layouts"],"zh":["渲染带有动态通知徽章的应用程序标题","使用交互式指示器渲染新的通知到达","显示未读通知计数并实时更新","生成带有可自定义布局的交互式通知面板"],"ja":["動的通知バッジを使用したアプリケーションヘッダーのレンダリング","インタラクティブなインジケーターを使用した新着通知のアニメーション化","未読の通知カウントの表示とリアルタイム更新","カスタマイズ可能なレイアウトを使用したインタラクティブな通知パネルの生成"],"ko":["동적 알림 배지를 사용한 애플리케이션 제목 렌더링","상호 작용형 인디케이터를 사용한 새로운 알림 도착 애니메이션화","읽지 않은 알림 수 표시 및 실시간 업데이트","사용자 정의 가능한 레이아웃을 사용한 상호 작용형 알림 패널 생성"],"es":["Renderizar encabezados de aplicaciones con insignias de notificación dinámicas","Animar las llegadas de nuevas notificaciones con indicadores interactivos","Mostrar recuentos de notificaciones no leídas y actualizar en tiempo real","Generar paneles de notificación interactivos con diseños personalizables"],"fr":["Rendre des en-têtes d''applications avec des badges de notification dynamiques","Animer les arrivées de nouvelles notifications avec des indicateurs interactifs","Afficher des comptes de notifications non lus et mettre à jour en temps réel","Générer des panneaux de notification interactifs avec des mises en page personnalisables"],"de":["App-Headern mit dynamischen Benachrichtigungsabzeichen rendern","Ankunft neuer Benachrichtigungen mit interaktiven Indikatoren animieren","Ungelesene Benachrichtigungsanzahlen anzeigen und in Echtzeit aktualisieren","Interaktive Benachrichtigungspaneelen mit anpassbaren Layouts generieren"],"pt":["Renderizar cabeçalhos de aplicativos com emblemas de notificação dinâmicos","Animar as chegadas de novas notificações com indicadores interativos","Exibir contagens de notificações não lidas e atualizar em tempo real","Gerar painéis de notificação interativos com layouts personalizáveis"],"ru":["Отображать заголовки приложений с динамическими значками уведомлений","Анимировать прибытия новых уведомлений с помощью интерактивных индикаторов","Отображать количество непрочитанных уведомлений и обновлять в режиме реального времени","Генерировать интерактивные панели уведомлений с настраиваемыми макетами"],"ar":["عرض رأس التطبيقات مع شارات إعلام ديناميكية","تحريك وصول الإشعارات الجديدة مع المؤشرات التفاعلية","عرض عدد الإشعارات غير المقروءة وتحديثه في الوقت الفعلي","توليد ألواح إعلام تفاعلية مع تخطيطات قابلة للتخصيص"]},"limitations":{"en":["Requires client-side rendering capabilities","Limited to web-based applications with HTML, CSS, and JavaScript support"],"zh":["需要客户端渲染功能","仅限于支持 HTML, CSS 和 JavaScript 的 Web 应用程序"],"ja":["クライアント側のレンダリング機能が必要","HTML、CSS、JavaScript をサポートする Web アプリケーションに限定される"],"ko":["클라이언트측 렌더링 기능이 필요","HTML, CSS, JavaScript를 지원하는 웹 애플리케이션에만 제한됨"],"es":["Requiere capacidades de renderizado en el lado del cliente","Limitado a aplicaciones web con soporte para HTML, CSS y JavaScript"],"fr":["Nécessite des capacités de rendu sur le côté client","Limité aux applications web avec prise en charge de HTML, CSS et JavaScript"],"de":["Benötigt Client-Seitige Renderfunktionen","Begrenzt auf Webanwendungen mit HTML-, CSS- und JavaScript-Unterstützung"],"pt":["Requer capacidades de renderização do lado do cliente","Limitado a aplicações baseadas na web com suporte a HTML, CSS e JavaScript"],"ru":["Требует возможностей рендеринга на стороне клиента","Ограничен веб-приложениями с поддержкой HTML, CSS и JavaScript"],"ar":["يتطلب إمكانيات عرض جانب العميل","محدود بتطبيقات الويب التي تدعم HTML و CSS وJavaScript"]},"version":4},"contentHash":"b1470954596364db57b123d0b13f4d053961314448b77eb12a1c68d7bf378715","qualityScore":36}');
