INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Syedaashnaghazanfar/todo-app/notification-ui', 'notification-ui', 'Syedaashnaghazanfar', 'todo-app', 'community', 'notification-ui Syedaashnaghazanfar todo-app community The notification-ui skill provides a visual interface for displaying notifications, benefiting developers who need to render app headers, display unread notification counts, and animate new arrivals. Notification UI Skill提供了显示通知的视觉界面，包括bell icon、badge、动画指示器和交互式通知面板 Notification UI Skillは、ベルアイコン、バッジ、動画インジケーター、インタラクティブな通知パネルを備えた通知の表示インターフェイスを提供 Notification UI Skill은 벨 아이콘, 배지, 애니메이션 인디케이터 및 상호 작용형 알림 패널을 포함한 알림 표시를 위한 시각적 인터페이스를 제공 La notificación UI proporciona una interfaz visual para mostrar notificaciones, incluyendo un icono de campana con insignia y un panel de notificación interactivo L''interface de notification UI fournit une interface visuelle pour afficher les notifications, y compris un icône de cloche avec badge et un panneau de notification interactif Die Benachrichtigungs-UI bietet eine visuelle Oberfläche zum Anzeigen von Benachrichtigungen, einschließlich eines Glockensymbols mit Abzeichen und einem interaktiven Benachrichtigungspanel A notificação UI fornece uma interface visual para exibir notificações, incluindo um ícone de sino com badge e painel de notificações interativo. Интерфейс уведомлений предоставляет визуальный интерфейс для отображения уведомлений, включая иконку колокольчика с бейджем и интерактивную панель уведомлений. واجهة الإشعارات توفر واجهة بصرية لعرض الإشعارات، بما في ذلك رمز الجرس مع شارة ولوحة إشعارات تفاعلية. how to use notification-ui what is notification-ui notification-ui alternative notification-ui vs competitors notification-ui install notification-ui setup guide notification ui tutorial notification ui best practices Notification UI Skill AIエージェント开发 通知显示 bell icon badge 动画指示器 交互式通知面板 Renders a bell icon with badge for unread notification counts Displays an interactive notification panel with animated indicators Supports animation of new notification arrivals Allows user interaction with notifications, such as clicking to mark as read Integrates with app headers for seamless notification display notification-ui is a technical skill that provides a visual interface for displaying notifications, including bell icons, badges, and interactive panels.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tylerbutler/birch/debug-cross-platform', 'community', 'tylerbutler', 'birch', 'tylerbutler/birch', 'debug-cross-platform', 0, 0, 36, '2026-03-08T01:57:15.351Z', '2026-03-08T02:03:50.645Z', 'e26333c97f9cf6442dd50e77e968edcdacc53ad2c0e56f089589b2faba9c043a', '{"id":"tylerbutler/birch/debug-cross-platform","name":"debug-cross-platform","description":{"en":"Debug-cross-platform is a comprehensive logging library for systematic cross-platform debugging, targeting Erlang and JavaScript.","zh":"跨平台调试是一种系统化的调试方法，使用全面的日志记录库，支持Erlang和JavaScript。","ja":"クロスプラットフォームデバッグは、ErlangとJavaScriptを対象とした包括的なログ記録ライブラリを使用したシステム化されたデバッグアプローチです。","ko":"크로스 플랫폼 디버깅은 Erlang과 JavaScript를 대상으로 하는 포괄적인 로깅 라이브러리를 사용한 시스템화된 디버깅 접근 방식입니다.","es":"Gleam es una biblioteca de registro integral que se ejecuta en Erlang y JavaScript. Ofrece un enfoque sistemático para la depuración de problemas que solo ocurren en uno de los dos","fr":"Gleam est une bibliothèque de journalisation complète qui s''exécute sur Erlang et JavaScript. Elle offre une approche systématique pour le débogage des problèmes qui ne surviennent que sur l''un des deux","de":"Gleam ist eine umfassende Protokollbibliothek, die auf Erlang und JavaScript läuft. Sie bietet einen systematischen Ansatz für die Fehlersuche bei Problemen, die nur auf einem der beiden auftreten","pt":"O debug-cross-platform é uma biblioteca de registro abrangente para Erlang e JavaScript. Fornece uma abordagem sistemática para depurar problemas que ocorrem apenas em uma das plataformas.","ru":"Debug-cross-platform — это всесторонняя библиотека журналирования для Erlang и JavaScript. Она обеспечивает системный подход к отладке проблем, возникающих только на одной из платформ.","ar":"debug-cross-platform هو مكتبة سجل شاملة للغة إرلنغ وجافاسكريبت. يوفر نهجًا منهجيًا لتصحيح الأخطاء التي تحدث فقط على واحدة من المنصات."},"seo":{"title":{"en":"Cross-Platform Debugging Setup Guide","zh":"跨平台调试设置指南 - AI工具","ja":"クロスプラットフォームデバッグ設定ガイド - AIエージェント","ko":"크로스 플랫폼 디버깅 설정 가이드 - AI 에이전트","es":"Guía de Configuración de Depuración Cruzada con Gleam","fr":"Guide de Configuration de Débogage Multi-plateforme avec ...","de":"Einrichtungsleitfaden für Cross-Platform-Debugging mit Gleam","pt":"Guia de Configuração do Debug Cross-Platform para Erlang ...","ru":"Настройка отладки для кросс-платформенной разработки на E...","ar":"دليل إعداد Debug Cross-Platform لёрلنغ وجافاسكريبت مع أدو..."},"description":{"en":"Streamline debugging across Erlang and JavaScript with a systematic approach and comprehensive logging library","zh":"使用系统化方法和全面的日志记录库简化Erlang和JavaScript的调试过程 - AI工具","ja":"ErlangとJavaScriptのデバッグをシステム化アプローチと包括的なログ記録ライブラリで効率化する","ko":"시스템화된 접근 방식과 포괄적인 로깅 라이브러리를 사용하여 Erlang과 JavaScript의 디버깅을 간소화하십시오 - AI 에이전트","es":"Aprende a depurar aplicaciones en Erlang y JavaScript con Gleam. Descubre cómo identificar y solucionar problemas con nuestra guía de depuración cruzada","fr":"Apprenez à déboguer des applications Erlang et JavaScript avec Gleam. Découvrez comment identifier et résoudre les problèmes avec notre guide de débogage mul...","de":"Erfahren Sie, wie Sie Anwendungen in Erlang und JavaScript mit Gleam debuggen. Entdecken Sie, wie Sie Probleme mit unserem Leitfaden zur Cross-Platform-Debug...","pt":"Aprenda a depurar aplicações em Erlang e JavaScript com o debug-cross-platform. Veja como identificar e solucionar problemas de forma eficaz.","ru":"Отладка кросс-платформенных приложений на Erlang и JavaScript с debug-cross-platform. Узнайте, как выявлять и решать проблемы быстро.","ar":"تعلم كيفية تصحيح أخطاء التطبيقات المكتوبة بلغة إرلنغ وجافاسكريبت باستخدام debug-cross-platform. استكشف كيفية تحديد وحل المشكلات بفعالية."},"definition":{"en":"A cross-platform debugging system for identifying issues in Erlang and JavaScript using a logging library","zh":"一种使用日志记录库来识别Erlang和JavaScript问题的跨平台调试系统 - AI工具","ja":"ErlangとJavaScriptの問題をログ記録ライブラリを使用して識別するクロスプラットフォームデバッグシステム","ko":"로그 기록 라이브러리를 사용하여 Erlang과 JavaScript의 문제를 식별하는 크로스 플랫폼 디버깅 시스템 - AI 에이전트","es":"La depuración cruzada es un enfoque sistemático para identificar y solucionar problemas que ocurren en diferentes plataformas, como Erlang y JavaScript","fr":"Le débogage multi-plateforme est une approche systématique pour identifier et résoudre les problèmes qui surviennent sur différentes plates-formes, comme Erlang et JavaScript","de":"Die Cross-Platform-Debugging ist ein systematischer Ansatz, um Probleme zu identifizieren und zu beheben, die auf verschiedenen Plattformen wie Erlang und JavaScript auftreten","pt":"O que é debug-cross-platform? É uma biblioteca de registro que permite depurar aplicações em Erlang e JavaScript de forma eficaz.","ru":"Что такое debug-cross-platform? Это библиотека журналирования, позволяющая эффективно отлаживать приложения на Erlang и JavaScript.","ar":"ما هو debug-cross-platform؟ إنه مكتبة سجل يسمح بتصحيح أخطاء التطبيقات المكتوبة بلغة إرلنغ وجافاسكريبت بفعالية."},"features":{"en":["Systematic approach to debugging","Comprehensive logging library for Erlang and JavaScript","Quick diagnosis using test-erlang and test-js","Identification of FFI implementation mismatches","Comparison of FFI implementations using diff"],"zh":["系统化的调试方法","支持Erlang和JavaScript的全面的日志记录库","使用test-erlang和test-js进行快速诊断","识别FFI实现不匹配","使用diff比较FFI实现"],"ja":["システム化されたデバッグアプローチ","ErlangとJavaScriptを対象とした包括的なログ記録ライブラリ","test-erlangとtest-jsを使用した迅速な診断","FFI実装の不一致の識別","diffを使用したFFI実装の比較"],"ko":["시스템화된 디버깅 접근 방식","Erlang과 JavaScript를 대상으로 하는 포괄적인 로깅 라이브러리","test-erlang과 test-js를 사용한 빠른 진단","FFI 구현 불일치 식별","diff를 사용한 FFI 구현 비교"],"es":["Enfoque sistemático para la depuración de problemas en Erlang y JavaScript","Compatibilidad con FFI para implementaciones de funciones en diferentes lenguajes","Herramientas de diagnóstico rápido para identificar problemas en ambos targets","Comparación de implementaciones de FFI para identificar diferencias","Soporte para testing en Erlang y JavaScript"],"fr":["Approche systématique pour le débogage des problèmes en Erlang et JavaScript","Compatibilité avec FFI pour les implémentations de fonctions dans différents langages","Outils de diagnostic rapide pour identifier les problèmes sur les deux cibles","Comparaison des implémentations de FFI pour identifier les différences","Prise en charge du testing en Erlang et JavaScript"],"de":["Systematischer Ansatz für die Fehlersuche bei Problemen in Erlang und JavaScript","Unterstützung für FFI für Funktionsimplementierungen in verschiedenen Sprachen","Werkzeuge für schnelle Diagnose zur Identifizierung von Problemen in beiden Zielen","Vergleich von FFI-Implementierungen zur Identifizierung von Unterschieden","Unterstützung für Testing in Erlang und JavaScript"],"pt":["Abordagem sistemática para depurar problemas em Erlang e JavaScript","Identificação de problemas de implementação de FFI","Comparações de implementações de FFI para Erlang e JavaScript","Suporte a testes em ambas as plataformas","Registro abrangente para identificar problemas"],"ru":["Системный подход к отладке проблем на Erlang и JavaScript","Выявление проблем реализации FFI","Сравнение реализаций FFI для Erlang и JavaScript","Поддержка тестирования на обеих платформах","Всестороннее журналирование для выявления проблем"],"ar":["نهج منهجي لتصحيح أخطاء التطبيقات على إرلنغ وجافاسكريبت","تحديد مشاكل تنفيذ FFI","مقارنة تنفيذات FFI للغة إرلنغ وجافاسكريبت","دعم الاختبار على كلا المنصتين","سجل شامل لتحديد المشكلات"]},"keywords":{"en":["cross-platform debugging","Erlang debugging","JavaScript debugging","logging library","FFI implementation","systematic debugging","quick diagnosis","debugging tools"],"zh":["跨平台调试","Erlang调试","JavaScript调试","日志记录库","FFI实现","系统化调试","快速诊断","AI工具","调试工具"],"ja":["クロスプラットフォームデバッグ","Erlangデバッグ","JavaScriptデバッグ","ログ記録ライブラリ","FFI実装","システム化デバッグ","迅速な診断","AIエージェント","デバッグツール"],"ko":["크로스 플랫폼 디버깅","Erlang 디버깅","JavaScript 디버깅","로깅 라이브러리","FFI 구현","시스템화된 디버깅","빠른 진단","AI 에이전트","디버깅 도구"],"es":["depuración cruzada","Gleam","Erlang","JavaScript","FFI","testing","debugging","Herramientas de desarrollo","Desarrollo de software"],"fr":["débogage multi-plateforme","Gleam","Erlang","JavaScript","FFI","testing","débogage","Outils de développement","Développement de logiciels"],"de":["Cross-Platform-Debugging","Gleam","Erlang","JavaScript","FFI","Testing","Fehlersuche","Entwicklungstools","Softwareentwicklung"],"pt":["debug-cross-platform","depuração de aplicações","Erlang","JavaScript","FFI","testes de unidade","registro de aplicações","desenvolvimento de software","otimização de desempenho"],"ru":["debug-cross-platform","отладка приложений","Erlang","JavaScript","FFI","юнит-тесты","журналирование приложений","разработка программного обеспечения","оптимизация производительности","ИИ Агенты"],"ar":["debug-cross-platform","تصحيح أخطاء التطبيقات","إرلنغ","جافاسكريبت","FFI","اختبارات الوحدة","سجل التطبيقات","تطوير البرمجيات","تحسين الأداء","أدوات الذكاء الاصطناعي"]}},"owner":"tylerbutler","repo":"birch","repoPath":"tylerbutler/birch","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.351Z","topics":[],"category":"community","skillMd":{"name":"debug-cross-platform","description":"Debug issues that only occur on one target (Erlang or JavaScript). Use when tests pass on one target but fail on the other.","bodyPreview":"# Cross-Platform Debugging\n\nSystematic approach to debugging issues that only occur on Erlang OR JavaScript.\n\n## Quick Diagnosis\n\n```bash\n# Run on both targets to identify which fails\njust test-erlang\njust test-js\n```\n\n## Common Causes\n\n### 1. FFI Implementation Mismatch\n\n**Symptom**: Different behavior between targets for the same function.\n\n**Check**:\n```bash\n# Compare FFI implementations\ndiff <(grep -A 20 \"function_name\" src/birch_ffi.erl) \\\n     <(grep -A 20 \"function_name\" src/birch_ffi.mjs","body":"# Cross-Platform Debugging\n\nSystematic approach to debugging issues that only occur on Erlang OR JavaScript.\n\n## Quick Diagnosis\n\n```bash\n# Run on both targets to identify which fails\njust test-erlang\njust test-js\n```\n\n## Common Causes\n\n### 1. FFI Implementation Mismatch\n\n**Symptom**: Different behavior between targets for the same function.\n\n**Check**:\n```bash\n# Compare FFI implementations\ndiff <(grep -A 20 \"function_name\" src/birch_ffi.erl) \\\n     <(grep -A 20 \"function_name\" src/birch_ffi.mjs)\n```\n\n**Common issues**:\n- Return type mismatch (tuples vs arrays)\n- Error handling differences\n- String encoding (UTF-8 handling)\n\n### 2. Platform-Specific APIs\n\n**Symptom**: Function works on one platform, undefined/error on other.\n\n**JavaScript-only APIs**:\n- `process.stdout`, `process.stderr` (Node.js)\n- `Deno.isatty()` (Deno)\n- `console.log` behavior varies by runtime\n\n**Erlang-only APIs**:\n- Process dictionary (`erlang:put/get`)\n- OTP behaviors (`gen_server`, etc.)\n- `:logger` integration\n\n### 3. Async Behavior\n\n**Symptom**: Race conditions or timing issues on JavaScript.\n\n**Check**:\n- Erlang is synchronous by default\n- JavaScript may need `await` or callbacks\n- Look for Promise handling in FFI\n\n### 4. Type Coercion\n\n**Symptom**: Unexpected values or type errors.\n\n| Gleam Type | Erlang | JavaScript |\n|------------|--------|------------|\n| `Int` | Integer | Number |\n| `Float` | Float | Number |\n| `String` | Binary | String |\n| `List` | List | Array |\n| `Tuple` | Tuple | Array |\n| `Nil` | `nil` atom | `undefined` |\n\n### 5. TTY/Terminal Detection\n\n**Symptom**: Color output works on one platform.\n\n**Check**:\n```gleam\n// In platform.gleam\nis_stdout_tty()  // Different implementation per platform\n```\n\n## Debugging Steps\n\n### Step 1: Isolate the Failure\n\n```bash\n# Run specific test\ngleam test --target erlang -- --filter \"test_name\"\ngleam test --target javascript -- --filter \"test_name\"\n```\n\n### Step 2: Add Debug Output\n\n```gleam\n// Temporary debug logging\nimport gleam/io\nio.debug(value)  // Works on both targets\n```\n\n### Step 3: Check FFI\n\n1. Read `src/birch/internal/platform.gleam` for declarations\n2. Compare `src/birch_ffi.erl` and `src/birch_ffi.mjs`\n3. Look for behavioral differences\n\n### Step 4: Test JavaScript Runtimes\n\n```bash\n# Test on all JS runtimes\njust test-integration-node\njust test-integration-deno\njust test-integration-bun\n```\n\n### Step 5: Check Runtime Detection\n\nIn `birch_ffi.mjs`, verify runtime detection:\n```javascript\n// Node.js\ntypeof process !== ''undefined'' && process.versions?.node\n\n// Deno\ntypeof Deno !== ''undefined''\n\n// Bun\ntypeof Bun !== ''undefined''\n\n// Browser\ntypeof window !== ''undefined''\n```\n\n## FFI Debugging Checklist\n\n- [ ] Both implementations exist for the function\n- [ ] Return types match Gleam declaration\n- [ ] Error cases handled identically\n- [ ] Edge cases (empty string, null, special chars) tested\n- [ ] All JS runtimes have fallbacks (Node, Deno, Bun, browser)\n\n## Quick Fixes\n\n| Issue | Erlang Fix | JavaScript Fix |\n|-------|------------|----------------|\n| Undefined function | Check module exports | Check `export` statement |\n| Wrong return type | Match Gleam type exactly | Return correct JS type |\n| Encoding issues | Use `unicode:characters_to_binary` | Use `TextEncoder` |\n| TTY detection | Check `os:type()` | Check `process.stdout.isTTY` |\n"},"lastSynced":"2026-03-08T02:03:50.645Z","agentAnalysis":{"suitability":{"en":"Perfect for Multi-Language Agents needing systematic cross-platform debugging capabilities across Erlang and JavaScript","zh":"适用于需要跨平台系统化调试功能的多语言代理，支持Erlang和JavaScript","ja":"マルチ言語エージェントがErlangとJavaScriptを横断してシステム的なクロスプラットフォームのデバッグ機能を必要とする場合に最適","ko":"멀티 언어 에이전트가 시스템적인 크로스 플랫폼 디버깅 기능을 필요로 하는 경우에 적합하며, Erlang과 JavaScript를 지원함","es":"Perfecto para agentes de multi-idioma que necesitan capacidades de depuración sistemáticas y multiplataforma en Erlang y JavaScript","fr":"Parfait pour les agents multilingues ayant besoin de capacités de débogage systématiques et multiplateformes sur Erlang et JavaScript","de":"Perfekt für Multi-Language-Agents, die systematische Cross-Plattform-Debugging-Funktionen über Erlang und JavaScript benötigen","pt":"Perfeito para Agentes de Multi-Língua que necessitam de capacidades de depuração sistemática cross-plataforma em Erlang e JavaScript","ru":"Идеально подходит для многоязычных агентов, требующих системных возможностей отладки на разных платформах для Erlang и JavaScript","ar":"مثالي للوكلاء المتعددين اللغات الذين يحتاجون إلى قدرات تصحيح آلي متقاطعة عبر منصات متعددة عبر Erlang و JavaScript"},"recommendation":{"en":"Empowers agents to diagnose and resolve FFI implementation mismatches using comprehensive logging and comparison tools like diff, targeting Erlang and JavaScript environments with libraries such as birch_ffi.erl and birch_ffi.mjs","zh":"赋予代理诊断和解决FFI实现不匹配问题的能力，使用诸如diff的综合日志和比较工具，针对Erlang和JavaScript环境，使用诸如birch_ffi.erl和birch_ffi.mjs的库","ja":"エージェントにFFIの実装の不一致を診断および解決する機能を提供する。diffなどの包括的なログと比較ツールを使用して、ErlangとJavaScriptの環境を対象とし、birch_ffi.erlやbirch_ffi.mjsなどのライブラリを使用する","ko":"에이전트에게 FFI 구현의 불일치를 진단하고 해결하는 능력을 부여함. diff와 같은 포괄적인 로그와 비교 도구를 사용하여 Erlang 및 JavaScript 환경을 대상으로 하며, birch_ffi.erl 및 birch_ffi.mjs와 같은 라이브러리를 사용함","es":"Habilita a los agentes a diagnosticar y resolver desajustes en la implementación de FFI utilizando herramientas de registro y comparación completas como diff, que apuntan a entornos de Erlang y JavaScript con bibliotecas como birch_ffi.erl y birch_ffi.mjs","fr":"Permet aux agents de diagnostiquer et de résoudre les incohérences d''implémentation FFI en utilisant des outils de journalisation et de comparaison complets tels que diff, ciblant les environnements Erlang et JavaScript avec des bibliothèques telles que birch_ffi.erl et birch_ffi.mjs","de":"Ermächtigt die Agenten, FFI-Implementierungsunterschiede mithilfe umfassender Protokollierungs- und Vergleichstools wie diff zu diagnostizieren und zu lösen, die auf Erlang- und JavaScript-Umgebungen mit Bibliotheken wie birch_ffi.erl und birch_ffi.mjs abzielen","pt":"Habilita os agentes a diagnosticar e resolver discrepâncias de implementação de FFI usando ferramentas de registro e comparação abrangentes como diff, mirando ambientes Erlang e JavaScript com bibliotecas como birch_ffi.erl e birch_ffi.mjs","ru":"Предоставляет агентам возможность диагностировать и устранять несоответствия реализации FFI с помощью всесторонних инструментов журналирования и сравнения, таких как diff, ориентированных на среды Erlang и JavaScript с библиотеками, такими как birch_ffi.erl и birch_ffi.mjs","ar":"تمكّن الوكلاء من تشخيص وعلاج حالات عدم مطابقة تنفيذ FFI باستخدام أدوات تسجيل ومقارنة شاملة مثل diff، تستهدف بيئات Erlang و JavaScript مع مكتبات مثل birch_ffi.erl و birch_ffi.mjs"},"useCases":{"en":["Debugging cross-platform issues in Erlang and JavaScript applications","Identifying FFI implementation mismatches between targets","Comparing debugging logs across different platforms using tools like just test-erlang and just test-js"],"zh":["调试Erlang和JavaScript应用中的跨平台问题","识别目标之间的FFI实现不匹配","使用just test-erlang和just test-js等工具比较不同平台的调试日志"],"ja":["ErlangとJavaScriptアプリケーションにおけるクロスプラットフォームの問題をデバッグする","ターゲット間のFFI実装の不一致を特定する","just test-erlangやjust test-jsなどのツールを使用して、異なるプラットフォームのデバッグログを比較する"],"ko":["Erlang과 JavaScript 애플리케이션에서 크로스 플랫폼 문제를 디버깅함","대상 간의 FFI 구현 불일치를 식별함","just test-erlang 및 just test-js와 같은 도구를 사용하여 다른 플랫폼의 디버깅 로그를 비교함"],"es":["Depuración de problemas multiplataforma en aplicaciones de Erlang y JavaScript","Identificación de desajustes en la implementación de FFI entre objetivos","Comparación de registros de depuración en diferentes plataformas utilizando herramientas como just test-erlang y just test-js"],"fr":["Débogage des problèmes multiplateformes dans les applications Erlang et JavaScript","Identification des incohérences d''implémentation FFI entre cibles","Comparaison des journaux de débogage sur différentes plateformes à l''aide d''outils tels que just test-erlang et just test-js"],"de":["Fehlerbehebung bei Cross-Plattform-Problemen in Erlang- und JavaScript-Anwendungen","Identifizierung von FFI-Implementierungsunterschieden zwischen Zielen","Vergleich von Debug-Protokollen auf verschiedenen Plattformen mit Tools wie just test-erlang und just test-js"],"pt":["Depuração de problemas de plataforma cruzada em aplicações Erlang e JavaScript","Identificação de discrepâncias de implementação de FFI entre alvos","Comparação de registros de depuração em diferentes plataformas usando ferramentas como just test-erlang e just test-js"],"ru":["Отладка межплатформенных проблем в приложениях Erlang и JavaScript","Определение несоответствий реализации FFI между целями","Сравнение журналов отладки на разных платформах с помощью инструментов, таких как just test-erlang и just test-js"],"ar":["تصحيح أخطاء منصة متقاطعة في تطبيقات Erlang و JavaScript","تحديد حالات عدم مطابقة تنفيذ FFI بين الأهداف","مقارنة سجلات التصحيح على منصات مختلفة باستخدام أدوات مثل just test-erlang و just test-js"]},"limitations":{"en":["Requires Erlang and JavaScript environments","Limited to debugging Erlang and JavaScript applications","Needs access to source code files like src/birch_ffi.erl and src/birch_ffi.mjs for comparison"],"zh":["需要Erlang和JavaScript环境","仅限于调试Erlang和JavaScript应用","需要访问源代码文件，如src/birch_ffi.erl和src/birch_ffi.mjs，进行比较"],"ja":["ErlangとJavaScriptの環境が必要","ErlangとJavaScriptアプリケーションのデバッグのみに限定される","比較のために、src/birch_ffi.erlやsrc/birch_ffi.mjsなどのソースコードファイルへのアクセスが必要"],"ko":["Erlang과 JavaScript 환경이 필요함","Erlang과 JavaScript 애플리케이션의 디버깅에만 제한됨","비교를 위해 src/birch_ffi.erl 및 src/birch_ffi.mjs와 같은 소스 코드 파일에 대한 액세스가 필요함"],"es":["Requiere entornos de Erlang y JavaScript","Limitado a la depuración de aplicaciones de Erlang y JavaScript","Necesita acceso a archivos de código fuente como src/birch_ffi.erl y src/birch_ffi.mjs para la comparación"],"fr":["Nécessite des environnements Erlang et JavaScript","Limité au débogage des applications Erlang et JavaScript","Nécessite un accès aux fichiers de code source tels que src/birch_ffi.erl et src/birch_ffi.mjs pour la comparaison"],"de":["Erlang- und JavaScript-Umgebungen sind erforderlich","Begrenzt auf die Fehlersuche in Erlang- und JavaScript-Anwendungen","Benötigt Zugriff auf Quellcode-Dateien wie src/birch_ffi.erl und src/birch_ffi.mjs für den Vergleich"],"pt":["Requer ambientes Erlang e JavaScript","Limitado à depuração de aplicações Erlang e JavaScript","Necessita acesso a arquivos de código fonte como src/birch_ffi.erl e src/birch_ffi.mjs para comparação"],"ru":["Требует сред Erlang и JavaScript","Ограничен отладкой приложений Erlang и JavaScript","Требует доступа к файлам исходного кода, таким как src/birch_ffi.erl и src/birch_ffi.mjs, для сравнения"],"ar":["يتطلب بيئات Erlang و JavaScript","محدود بتصحيح تطبيقات Erlang و JavaScript","يحتاج إلى الوصول إلى ملفات التعليمات البرمجية المصدر مثل src/birch_ffi.erl و src/birch_ffi.mjs للمقارنة"]},"version":4},"contentHash":"e26333c97f9cf6442dd50e77e968edcdacc53ad2c0e56f089589b2faba9c043a","qualityScore":36}');
