INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tylerbutler/birch/debug-cross-platform', 'debug-cross-platform', 'tylerbutler', 'birch', 'community', 'debug-cross-platform tylerbutler birch community Debug-cross-platform is a comprehensive logging library for systematic cross-platform debugging, targeting Erlang and JavaScript. 跨平台调试是一种系统化的调试方法，使用全面的日志记录库，支持Erlang和JavaScript。 クロスプラットフォームデバッグは、ErlangとJavaScriptを対象とした包括的なログ記録ライブラリを使用したシステム化されたデバッグアプローチです。 크로스 플랫폼 디버깅은 Erlang과 JavaScript를 대상으로 하는 포괄적인 로깅 라이브러리를 사용한 시스템화된 디버깅 접근 방식입니다. Gleam es una biblioteca de registro integral que se ejecuta en Erlang y JavaScript. Ofrece un enfoque sistemático para la depuración de problemas que solo ocurren en uno de los dos Gleam est une bibliothèque de journalisation complète qui s''exécute sur Erlang et JavaScript. Elle offre une approche systématique pour le débogage des problèmes qui ne surviennent que sur l''un des deux Gleam ist eine umfassende Protokollbibliothek, die auf Erlang und JavaScript läuft. Sie bietet einen systematischen Ansatz für die Fehlersuche bei Problemen, die nur auf einem der beiden auftreten O debug-cross-platform é uma biblioteca de registro abrangente para Erlang e JavaScript. Fornece uma abordagem sistemática para depurar problemas que ocorrem apenas em uma das plataformas. Debug-cross-platform — это всесторонняя библиотека журналирования для Erlang и JavaScript. Она обеспечивает системный подход к отладке проблем, возникающих только на одной из платформ. debug-cross-platform هو مكتبة سجل شاملة للغة إرلنغ وجافاسكريبت. يوفر نهجًا منهجيًا لتصحيح الأخطاء التي تحدث فقط على واحدة من المنصات. cross-platform debugging Erlang debugging JavaScript debugging logging library FFI implementation systematic debugging quick diagnosis debugging tools 跨平台调试 Erlang调试 JavaScript调试 日志记录库 FFI实现 系统化调试 快速诊断 AI工具 调试工具 Systematic approach to debugging Comprehensive logging library for Erlang and JavaScript Quick diagnosis using test-erlang and test-js Identification of FFI implementation mismatches Comparison of FFI implementations using diff A cross-platform debugging system for identifying issues in Erlang and JavaScript using a logging library');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sunbreak-pro/original-card-battle/design-research', 'community', 'sunbreak-pro', 'original-card-battle', 'sunbreak-pro/original-card-battle', 'design-research', 0, 0, 36, '2026-03-08T01:57:15.352Z', '2026-03-08T02:03:54.878Z', '70cad4220d0ec751bc2bfa3b0f2b1d4b0f26dfad60d574974f242e2163b638cb', '{"id":"sunbreak-pro/original-card-battle/design-research","name":"design-research","description":{"en":"The design-research Skill is a targeted retrieval system for developers building turn-based card battle roguelikes. It provides the shortest path to specific design documentation, loading only the necessary files like `battle_logic.md` instead of entire directories.","zh":"设计研究技能提供游戏开发的最短路径，优化游戏设计文档，提高开发效率","ja":"デザインリサーチスキルは、ゲーム開発の最短パスを提供し、ゲーム設計書のロードを最適化します","ko":"디자인 리서치 스킬은 게임 개발의 최단 경로를 제공하며 게임 디자인 문서를 최적화하여 개발 효율성을 향상시킵니다","es":"Design-research es una habilidad que proporciona el camino más corto a los documentos de diseño, cargando solo lo necesario. Ideal para desarrolladores de juegos","fr":"Design-research est une compétence qui fournit le chemin le plus court vers les documents de conception, en chargeant uniquement ce qui est nécessaire. Idéal pour les développeurs de jeux","de":"Design-research ist eine Fähigkeit, die den kürzesten Weg zu den Design-Dokumenten bietet, indem nur das Notwendige geladen wird. Ideal für Spieleentwickler","pt":"A pesquisa de design é uma habilidade que fornece o caminho mais curto para os documentos de design, carregando apenas o necessário","ru":"Исследование дизайна - это навык, который предоставляет самый короткий путь к документам по дизайну, загружая только необходимое","ar":"بحث التصميم هو مهارة توفر أقصر طريق إلى وثائق التصميم، وتحميل ما هو ضروري فقط"},"seo":{"title":{"en":"design-research: Rapid Game Design Doc Retrieval | AI Age...","zh":"设计研究技能：游戏开发最佳实践指南","ja":"デザインリサーチスキル：ゲーム開発のための最短パス","ko":"디자인 리서치 스킬: 게임 개발을 위한 최적화 가이드","es":"Guía de configuración de design-research para agentes de IA","fr":"Guide de mise en place de design-research pour les outils...","de":"Einrichtungsleitfaden für design-research in AI-Tools","pt":"Guia de Configuração de Pesquisa de Design para Ferrament...","ru":"Настройка ИИ Агентов: Руководство по Исследованию Дизайна","ar":"دليل إعداد وكيل إيه آي لبحث التصميم"},"description":{"en":"Accelerate your roguelike card game development. This AI Agent Skill provides targeted access to design docs like battle_logic.md and buff_debuff_system.md u...","zh":"了解设计研究技能，为游戏开发提供最短路径，优化游戏设计文档，提高开发效率","ja":"デザインリサーチスキルを使用して、ゲーム開発の最短パスを実現し、ゲーム設計書のロードを最適化する","ko":"디자인 리서치 스킬을 사용하여 게임 개발의 최단 경로를 제공하고 게임 디자인 문서를 최적화하여 개발 효율성을 향상시키세요","es":"Aprende a configurar design-research para agentes de IA y mejora tus habilidades de diseño de juegos con nuestra guía paso a paso","fr":"Découvrez comment configurer design-research pour les outils d''IA et améliorez vos compétences en conception de jeux avec notre guide étape par étape","de":"Erfahren Sie, wie Sie design-research für AI-Tools konfigurieren und verbessern Sie Ihre Fähigkeiten im Spiel-Design mit unserem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar a pesquisa de design para ferramentas de IA e otimize seu fluxo de trabalho de desenvolvimento com nossa guia passo a passo","ru":"Узнайте, как настроить исследование дизайна для ИИ Агентов и оптимизировать свой процесс разработки с нашей пошаговой инструкцией","ar":"تعلم كيفية إعداد بحث التصميم لوكيل إيه آي وامنح عملك التطوير بأفضل السبل مع دليلنا خطوة بخطوة"},"definition":{"en":"design-research is an AI Agent Skill that provides efficient, targeted access to game design documentation for roguelike turn-based card battle projects. It uses grep patterns and a quick index to deliver precise file content like `buff_debuff_system.md` without loading entire document sets.","zh":"设计研究技能是一种游戏开发技术，提供最短路径来访问设计文档","ja":"デザインリサーチスキルは、ゲーム開発のための技術であり、設計書への最短パスを提供する","ko":"디자인 리서치 스킬은 게임 개발을 위한 기술로 디자인 문서에 대한 최단 경로를 제공합니다","es":"Design-research es una habilidad de agente de IA que proporciona acceso rápido a documentos de diseño de juegos","fr":"Design-research est une compétence d''outil d''IA qui fournit un accès rapide aux documents de conception de jeux","de":"Design-research ist eine Fähigkeit von AI-Tools, die einen schnellen Zugriff auf Spiel-Design-Dokumente bietet","pt":"O que é pesquisa de design? É uma habilidade que ajuda a encontrar documentos de design de forma eficiente","ru":"Что такое исследование дизайна? Это навык, который помогает найти документы по дизайну наиболее эффективным образом","ar":"ما هو بحث التصميم؟ إنه مهارة تساعد على العثور على وثائق التصميم بفعالية"},"features":{"en":["Provides shortest-path retrieval for design documents, loading only what''s needed","Indexes core systems with specific file paths like `Overall_document/game_design_master.md`","Uses grep pattern matching (e.g., `lives\\|残機\\|探索回数`) for precise content targeting","Organizes documentation by topics including Battle Flow and Buff/Debuff systems","References specific markdown files such as `battle_document/battle_logic.md`"],"zh":["提供游戏设计文档的最短路径","优化游戏设计文档的加载","支持多种游戏开发技术，如React和Python","提供游戏开发的最佳实践指南","支持游戏设计文档的快速索引"],"ja":["ゲーム設計書への最短パスを提供","ゲーム設計書のロードを最適化","ReactやPythonなどのゲーム開発技術をサポート","ゲーム開発のベストプラクティスガイドを提供","ゲーム設計書のクイックインデックスをサポート"],"ko":["게임 디자인 문서에 대한 최단 경로 제공","게임 디자인 문서 로딩 최적화","React 및 Pythonなどの 게임 개발 기술 지원","게임 개발 최고의 실제 가이드 제공","게임 디자인 문서 빠른 색인을 지원"],"es":["Acceso rápido a documentos de diseño de juegos","Carga solo lo necesario, no todo","Soporte para sistemas de juego como vidas y buff/debuff","Integración con documentos de diseño de batalla","Búsqueda por patrones de greps como ''lives'' o ''phase''"],"fr":["Accès rapide aux documents de conception de jeux","Chargement uniquement de ce qui est nécessaire, pas tout","Prise en charge des systèmes de jeu tels que les vies et les buff/debuff","Intégration avec les documents de conception de bataille","Recherche par motifs de greps tels que ''lives'' ou ''phase''"],"de":["Schneller Zugriff auf Spiel-Design-Dokumente","Laden Sie nur das Notwendige, nicht alles","Unterstützung für Spiel-Systeme wie Leben und Buff/Debuff","Integration mit Kampf-Design-Dokumenten","Suche nach Grep-Mustern wie ''lives'' oder ''phase''"],"pt":["Caminho mais curto para documentos de design","Carregamento seletivo de documentos","Suporte a grep pattern para busca avançada","Integração com sistemas de design de jogo","Otimização do fluxo de trabalho de desenvolvimento"],"ru":["Самый короткий путь к документам по дизайну","Выборочная загрузка документов","Поддержка grep pattern для расширенного поиска","Интеграция с системами дизайна игр","Оптимизация процесса разработки"],"ar":["أقصر طريق إلى وثائق التصميم","تحميل انتقائي للوثائق","دعم grep pattern للبحث المتقدم","دمج مع أنظمة تصميم الألعاب","تحسين سير عمل التطوير"]},"keywords":{"en":["design-research AI agent skill","how to use design-research for game docs","design-research grep pattern search","roguelike card battle design documents","design-research vs manual doc search","install design-research AI skill","battle_logic.md access","buff_debuff_system.md retrieval"],"zh":["游戏开发","设计研究技能","游戏设计文档","最短路径","React","Python","游戏开发技术","最佳实践指南"],"ja":["ゲーム開発","デザインリサーチスキル","ゲーム設計書","最短パス","React","Python","ゲーム開発技術","ベストプラクティスガイド"],"ko":["게임 개발","디자인 리서치 스킬","게임 디자인 문서","최단 경로","React","Python","게임 개발 기술","최고의 실제 가이드"],"es":["design-research","agentes de IA","diseño de juegos","documentos de diseño","sistemas de juego","buff debuff","batalla","greps","desarrollo de juegos","herramientas de IA"],"fr":["design-research","outils d''IA","conception de jeux","documents de conception","systèmes de jeu","buff debuff","bataille","greps","développement de jeux","outils d''IA pour les jeux"],"de":["design-research","AI-Tools","Spiel-Design","Design-Dokumente","Spiel-Systeme","Buff Debuff","Kampf","Grep-Muster","Spiele-Entwicklung","AI-Tools für Spiele"],"pt":["ferramentas de ia","pesquisa de design","desenvolvimento de jogos","otimização de fluxo de trabalho","grep pattern","sistemas de design de jogo","documentos de design","guias de configuração"],"ru":["ИИ агенты","исследование дизайна","разработка игр","оптимизация процесса разработки","grep pattern","системы дизайна игр","документы по дизайну","руководства по настройке"],"ar":["وكيل إيه آي","بحث التصميم","تطوير الألعاب","تحسين سير عمل التطوير","grep pattern","أنظمة تصميم الألعاب","وثائق التصميم","دليل إعداد"]}},"owner":"sunbreak-pro","repo":"original-card-battle","repoPath":"sunbreak-pro/original-card-battle","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.352Z","topics":[],"category":"community","skillMd":{"name":"design-research","description":"Quickly search and reference game design documents. Use when checking specifications before implementation or researching design details. Triggers on check X specs, search design docs, how is X designed? requests. 使用時: 「design-researchを使用します」","bodyPreview":"# Design Research Skill\n\nProvides shortest path to design docs. Load only what''s needed, not everything.\n\n## Quick Index\n\n### Core Systems\n| Topic | File | Grep Pattern |\n|-------|------|--------------|\n| Overall game design | `Overall_document/game_design_master.md` | - |\n| Lives system | `Overall_document/DESIGN_CHANGE_PLAN_lives_system.md` | `lives\\|残機\\|探索回数` |\n| Battle flow | `battle_document/battle_logic.md` | `phase\\|フェーズ\\|ターン` |\n| Buff/Debuff | `battle_document/buff_debuff_system.md` | `b","body":"# Design Research Skill\n\nProvides shortest path to design docs. Load only what''s needed, not everything.\n\n## Quick Index\n\n### Core Systems\n| Topic | File | Grep Pattern |\n|-------|------|--------------|\n| Overall game design | `Overall_document/game_design_master.md` | - |\n| Lives system | `Overall_document/DESIGN_CHANGE_PLAN_lives_system.md` | `lives\\|残機\\|探索回数` |\n| Battle flow | `battle_document/battle_logic.md` | `phase\\|フェーズ\\|ターン` |\n| Buff/Debuff | `battle_document/buff_debuff_system.md` | `buff\\|debuff\\|duration` |\n\n### Character Classes\n| Topic | File | Grep Pattern |\n|-------|------|--------------|\n| Swordsman cards | `card_document/SWORDSMAN_CARDS_40.md` | `剣気\\|sword_` |\n| Mage cards | `card_document/MAGE_CARDS_40.md` | `共鳴\\|element\\|火\\|水\\|雷` |\n| Summoner cards | `card_document/SUMMONER_CARDS_40.md` | `召喚\\|summon` |\n| Common cards | `card_document/COMMON_CARDS_20.md` | `common_` |\n| Build system | `card_document/NEW_CHARACTER_SYSTEM_DESIGN.md` | `ビルド\\|build` |\n\n### Enemies by Depth\n| Depth | File | Grep Pattern |\n|-------|------|--------------|\n| Depth 1 | `enemy_document/depth1_enemy_database.md` | enemy name |\n| Depth 2 | `enemy_document/depth2_enemy_database.md` | enemy name |\n| Depth 3 | `enemy_document/depth3_enemy_database.md` | enemy name |\n| Depth 4 | `enemy_document/depth4_enemy_database.md` | enemy name |\n| Depth 5 (Boss) | `enemy_document/depth5_boss_database.md` | boss name |\n| Boss system | `enemy_document/boss_system_redesign.md` | `ボス\\|boss` |\n\n### Camp Facilities\n| Facility | Design | Implementation |\n|----------|--------|----------------|\n| Shop | `shop_design.md` | `shop_implementation_guide.md` |\n| Blacksmith | `blacksmith_design.md` | `blacksmith_implementation_guide.md` |\n| Guild | `guild_design.md` | `guild_implementation_guide.md` |\n| Library | `library_design.md` | - |\n| Sanctuary | `sanctuary_design.md` | - |\n| Storage | `storage_design.md` | - |\n| Overview | `camp_facilities_design.md` | - |\n\n### Other Systems\n| Topic | File | Grep Pattern |\n|-------|------|--------------|\n| Equipment/Items | `item_document/EQUIPMENT_AND_ITEMS_DESIGN.md` | `装備\\|equipment\\|item` |\n| Dungeon UI | `danjeon_document/dungeon_exploration_ui_design_v3.0.md` | `node\\|ノード\\|map` |\n| Return system | `danjeon_document/return_system_design.md` | `帰還\\|return\\|teleport` |\n| Inventory | `util_doument/inventory_design.md` | `inventory\\|所持品` |\n\n## Search Commands\n\n```bash\n# Search specific topic\ngrep -r \"keyword\" .claude/docs/ --include=\"*.md\"\n\n# Search within specific file\ngrep -n \"keyword\" .claude/docs/battle_document/battle_logic.md\n\n# List files\nls -la .claude/docs/*/\n```\n\n## Research Workflow\n\n1. **Quick Lookup**: Find relevant file from index above\n2. **Targeted Read**: Read only the specific section needed\n3. **Deep Dive**: Load additional files only if necessary\n\n## File Size Reference\n\n| Category | Total Size | Files |\n|----------|------------|-------|\n| battle_document | ~48K | 2 |\n| card_document | ~77K | 5 |\n| camp_document | ~286K | 10 |\n| enemy_document | ~111K | 6 |\n| item_document | ~42K | 1 |\n| danjeon_document | ~49K | 2 |\n| Overall_document | ~36K | 2 |\n\n**Tip**: camp_document is large due to implementation guides. For overview only, read `*_design.md` files.\n\n## Common Queries\n\n| Question | Reference |\n|----------|-----------|\n| Damage formula? | `battle_logic.md` → \"ダメージ計算\" |\n| Card cost balance? | Each card file → \"コスト\" |\n| Enemy stat guidelines? | `depth*_enemy_database.md` |\n| When do lives decrease? | `DESIGN_CHANGE_PLAN_lives_system.md` |\n| How many equipment slots? | `EQUIPMENT_AND_ITEMS_DESIGN.md` → \"スロット\" |\n| Soul acquisition conditions? | `sanctuary_design.md` or `return_system_design.md` |\n\n## Base Path\n\n```\n.claude/docs/\n├── Overall_document/\n├── battle_document/\n├── card_document/\n├── camp_document/\n├── enemy_document/\n├── item_document/\n├── danjeon_document/\n└── util_doument/\n```\n"},"lastSynced":"2026-03-08T02:03:54.878Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor and AutoGPT requiring rapid access to specific design documentation for turn-based card battle roguelikes","zh":"适合像Cursor和AutoGPT的AI代理，需要快速访问特定的设计文档，例如回合制卡牌战斗roguelikes","ja":"CursorやAutoGPTのようなAIエージェントに適しています。ターン制カードバトルroguelikesの特定のデザインドキュメントに迅速にアクセスする必要があります","ko":"Cursor와 AutoGPT와 같은 AI 에이전트에게 적합합니다. 턴제 카드 배틀 roguelikes를 위한 특정 디자인 문서에 빠르게 액세스해야 합니다","es":"Ideal para agentes de IA como Cursor y AutoGPT que requieren acceso rápido a documentación de diseño específica para roguelikes de batalla de cartas por turnos","fr":"Idéal pour les agents IA comme Cursor et AutoGPT nécessitant un accès rapide à une documentation de conception spécifique pour les roguelikes de combat de cartes au tour par tour","de":"Ideal für KI-Agents wie Cursor und AutoGPT, die einen schnellen Zugriff auf spezifische Design-Dokumentationen für roguelike-Kartenspiel-Schlachten benötigen","pt":"Ideal para Agentes de IA como Cursor e AutoGPT que requerem acesso rápido a documentação de design específica para roguelikes de batalha de cartas baseada em turnos","ru":"Идеально подходит для агентов ИИ, таких как Cursor и AutoGPT, требующих быстрого доступа к конкретной документации по дизайну для пошаговых карточных битв roguelikes","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و AutoGPT الذين يحتاجون إلى الوصول السريع إلى توثيق التصميم المحدد لروجاليكس المبنية على لعب البطاقات بالدورة"},"recommendation":{"en":"Empowers agents to efficiently retrieve targeted design documentation using grep patterns, loading only necessary files like `battle_logic.md` instead of entire directories, and leveraging markdown files for quick indexing of core systems such as battle flow and buff/debuff systems","zh":"赋予代理高效地检索目标设计文档的能力，使用grep模式，只加载必要的文件，如`battle_logic.md`，而不是整个目录，并利用markdown文件快速索引核心系统，如战斗流程和buff/debuff系统","ja":"エージェントがターゲットのデザインドキュメントを効率的に取得できるようにします。grepパターンを使用して、必要なファイルのみ（例：`battle_logic.md`）をロードし、ディレクトリ全体をロードせずに、マークダウンファイルを使用してコアシステム（バトルフロー、バフ/デバフシステムなど）のクイックインデックスを実現します","ko":"에이전트가 대상 디자인 문서를 효율적으로 검색할 수 있도록 합니다. grep 패턴을 사용하여 필요한 파일만 로드하고(예: `battle_logic.md`), 디렉토리 전체를 로드하지 않고, 마크다운 파일을 사용하여 핵심 시스템(전투 흐름, 버프/디버프 시스템 등)의 빠른 색인을 thực現합니다","es":"Habilita a los agentes a recuperar de manera eficiente la documentación de diseño objetivo utilizando patrones grep, cargando solo archivos necesarios como `battle_logic.md` en lugar de directorios completos, y aprovechando archivos markdown para un índice rápido de sistemas básicos como flujo de batalla y sistemas de buff/debuff","fr":"Permet aux agents de récupérer de manière efficace la documentation de conception ciblée en utilisant des modèles grep, en chargeant uniquement les fichiers nécessaires comme `battle_logic.md` au lieu de répertoires entiers, et en exploitant les fichiers markdown pour un indexage rapide des systèmes de base tels que le flux de bataille et les systèmes de buff/debuff","de":"Ermächtigt die Agents, die gezielte Design-Dokumentation effizient abzurufen, indem sie Muster von grep verwenden, nur notwendige Dateien wie `battle_logic.md` anstelle von gesamten Verzeichnissen laden und markdown-Dateien für ein schnelles Verzeichnis von Kernsystemen wie Kampffluss und Buff/Debuff-Systemen nutzen","pt":"Habilita os agentes a recuperar de forma eficiente a documentação de design direcionada usando padrões grep, carregando apenas arquivos necessários como `battle_logic.md` em vez de diretórios inteiros, e aproveitando arquivos markdown para indexação rápida de sistemas centrais, como fluxo de batalha e sistemas de buff/debuff","ru":"Наделяет агентов возможностью эффективно извлекать целевую документацию по дизайну, используя шаблоны grep, загружая только необходимые файлы, такие как `battle_logic.md`, вместо整个 директории, и используя файлы markdown для быстрой индексации основных систем, таких как поток битвы и системы бафф/дебафф","ar":"تمكين الوكيل من استرجاع توثيق التصميم المستهدف بفعالية باستخدام أنماط grep وتحميل الملفات الضرورية فقط مثل `battle_logic.md` بدلاً من المجلدات الكاملة، وتكييف الملفات markdown لفهارس السريعة لأنظمة核心 مثل تدفق المعركة ونظم تعزيز/الغاء التعزيز"},"useCases":{"en":["Retrieving specific battle logic documentation","Loading necessary files for lives system design","Indexing core game design systems like buff/debuff and battle flow"],"zh":["检索特定的战斗逻辑文档","加载生存系统设计所需的文件","索引核心游戏设计系统，如buff/debuff和战斗流程"],"ja":["特定のバトルロジックドキュメントを取得する","ライブスシステムデザインに必要なファイルをロードする","バフ/デバフやバトルフローなどのコアゲームデザインシステムをインデックスする"],"ko":["특정 전투 로직 문서 검색","생존 시스템 디자인을 위한 필요한 파일 로드","버프/디버프 및 전투 흐름 등의 핵심 게임 디자인 시스템 색인"],"es":["Recuperar documentación de lógica de batalla específica","Cargar archivos necesarios para el diseño del sistema de vidas","Indexar sistemas de diseño de juego básicos como buff/debuff y flujo de batalla"],"fr":["Récupérer la documentation de logique de combat spécifique","Charger les fichiers nécessaires pour la conception du système de vies","Indexer les systèmes de conception de jeu de base tels que buff/debuff et flux de combat"],"de":["Abrufen von spezifischer Kampflogik-Dokumentation","Laden von notwendigen Dateien für das Design des Lebenssystem","Indexieren von Kernsystemen des Spieledesigns wie Buff/Debuff und Kampffluss"],"pt":["Recuperar documentação de lógica de batalha específica","Carregar arquivos necessários para design do sistema de vidas","Indexar sistemas de design de jogo centrais, como sistemas de buff/debuff e fluxo de batalha"],"ru":["Извлечение конкретной документации по логике битвы","Загрузка необходимых файлов для проектирования системы жизней","Индексация основных систем дизайна игры, таких как системы бафф/дебафф и поток битвы"],"ar":["استرجاع توثيق 논리 المعركة المحدد","تحميل الملفات الضرورية لتصميم نظام الأرواح","فهارس لأنظمة تصميم اللعبة الأساسية، مثل أنظمة تعزيز/الغاء التعزيز وتدفق المعركة"]},"limitations":{"en":["Requires access to design documentation files","Limited to markdown file format","Dependent on accurate grep patterns for effective file retrieval"],"zh":["需要访问设计文档文件","仅限markdown文件格式","依赖于准确的grep模式以实现有效的文件检索"],"ja":["デザインドキュメントファイルへのアクセスが必要","マークダウンファイル形式のみ","有効なファイル取得のために正確なgrepパターンに依存する"],"ko":["디자인 문서 파일에 대한 액세스가 필요함","마크다운 파일 형식만 해당","유효한 파일 검색을 위해 정확한 grep 패턴에 의존"],"es":["Requiere acceso a archivos de documentación de diseño","Limitado al formato de archivo markdown","Dependiente de patrones grep precisos para una recuperación de archivos eficaz"],"fr":["Nécessite un accès aux fichiers de documentation de conception","Limité au format de fichier markdown","Dépendant de modèles grep précis pour une récupération de fichiers efficace"],"de":["Benötigt Zugriff auf Design-Dokumentationsdateien","Begrenzt auf markdown-Dateiformat","Abhängig von genauen grep-Mustern für eine effektive Dateiabfrage"],"pt":["Requer acesso a arquivos de documentação de design","Limitado ao formato de arquivo markdown","Dependente de padrões grep precisos para recuperação eficaz de arquivos"],"ru":["Требует доступа к файлам документации по дизайну","Ограничен форматом файла markdown","Зависит от точных шаблонов grep для эффективного извлечения файлов"],"ar":["يتطلب الوصول إلى ملفات توثيق التصميم","محدود بتنسيق ملف markdown","يعتمد على أنماط grep دقيقة لاسترجاع الملفات الفعالة"]},"version":4},"contentHash":"70cad4220d0ec751bc2bfa3b0f2b1d4b0f26dfad60d574974f242e2163b638cb","qualityScore":36}');
