INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vallafederico/solid-ai-rules/solid-core-rendering', 'solid-core-rendering', 'vallafederico', 'solid-ai-rules', 'community', 'solid-core-rendering vallafederico solid-ai-rules community solid-core-rendering is a utility for rendering SolidJS applications, enabling client-side rendering, server-side rendering, hydration, and streaming. It benefits developers building Single-Page Applications. Solid-Core-Rendering 是 SolidJS 应用的渲染工具，支持客户端渲染和服务器端渲染。 Solid-Core-Rendering は SolidJS アプリのレンダリングツールで、クライアントサイドレンダリングとサーバーサイドレンダリングをサポートしています。 Solid-Core-Rendering은 SolidJS 애플리케이션의 렌더링 도구로, 클라이언트 사이드 렌더링과 서버 사이드 렌더링을 지원합니다. El renderizado de SolidJS es una utilidad para montar aplicaciones en el DOM. Aprende a utilizar la función render para crear aplicaciones de una sola página. Le rendu SolidJS est une utilité pour monter des applications dans le DOM. Apprenez à utiliser la fonction render pour créer des applications à page unique. Das SolidJS-Rendering ist eine Utility zum Mounten von Anwendungen im DOM. Erfahren Sie, wie Sie die Render-Funktion verwenden, um Single-Page-Anwendungen zu erstellen. O Solid-Core-Rendering é uma biblioteca para renderização de aplicações SolidJS, permitindo renderização no lado do cliente e servidor Solid-Core-Rendering - это библиотека для рендеринга приложений SolidJS, позволяющая выполнять клиентскую и серверную отрисовку Solid-Core-Rendering هي مكتبة لتقديم تطبيقات SolidJS، مما يسمح بالتقديم على جانب العميل والخادم how to use solid-core-rendering solid-core-rendering setup guide solid-core-rendering vs react solid-core-rendering install what is solid-core-rendering solid-core-rendering alternative solid-core-rendering client-side rendering solid-core-rendering server-side rendering solid-core-rendering streaming Solid-Core-Rendering SolidJS 客户端渲染 服务器端渲染 hydration streaming AIエージェント 前端开发 Mounts SolidJS apps to the DOM using the render function from solid-js/web Supports client-side rendering for Single-Page Applications Enables server-side rendering (SSR) for improved SEO and performance Hydrates server-rendered markup for seamless client-side takeover Streams rendering for efficient and dynamic content updates solid-core-rendering is a set of utilities for rendering SolidJS applications, providing client-side rendering, server-side rendering, hydration, and streaming capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pollinations/pollinations/issue-maker', 'community', 'pollinations', 'pollinations', 'pollinations/pollinations', 'issue-maker', 0, 0, 36, '2026-03-08T01:57:15.356Z', '2026-03-08T02:04:01.700Z', '4a55aac1c8b2e2c8e61c2dc43e7cc2c5bf0e73059e7c7038cd671a6321317c94', '{"id":"pollinations/pollinations/issue-maker","name":"issue-maker","description":{"en":"issue-maker is a friendly open-source Gen-AI platform that automates GitHub issue creation following team conventions. It benefits development teams by assigning issues to the right team members based on domain expertise.","zh":"Issue-Maker 是一个开源的 Gen-AI 平台，能够自动将用户请求转换为 GitHub 问题，遵循团队约定。它支持 GitHub API 和 CLI 操作","ja":"Issue-Maker は、ユーザーのリクエストを GitHub の問題に自動変換するオープンソースの Gen-AI プラットフォームです。GitHub API と CLI 操作をサポートしています","ko":"Issue-Maker는 사용자의 요청을 깃허브 이슈로 자동 변환하는 오픈소스 Gen-AI 플랫폼입니다. 깃허브 API와 CLI 操作을 지원합니다","es":"Issue-Maker es una plataforma de código abierto que convierte solicitudes de usuario en incidencias de GitHub siguiendo las convenciones del equipo","fr":"Issue-Maker est une plateforme open-source qui transforme les demandes des utilisateurs en incidents GitHub suivant les conventions d''équipe","de":"Issue-Maker ist eine Open-Source-Plattform, die Benutzeranfragen in GitHub-Issues umwandelt, die den Teamkonventionen folgen","pt":"O Issue-Maker é uma plataforma de IA de código aberto que converte solicitações de usuário em problemas do GitHub, seguindo as convenções da equipe","ru":"Issue-Maker - это открытая платформа ИИ, которая преобразует запросы пользователей в проблемы GitHub, следуя соглашениям команды","ar":"Issue-Maker هو منصة ذكاء اصطناعي مفتوحة المصدر تحول طلبات المستخدم إلى قضايا على جيت هاب، متبعة اتفاقيات الفريق"},"seo":{"title":{"en":"issue-maker: GitHub Issue Automation Setup Guide | AI Age...","zh":"Issue-Maker 设置指南：自动创建 GitHub 问题","ja":"Issue-Maker のベストプラクティス：GitHub 問題自動生成","ko":"Issue-Maker 설정 가이드: 깃허브 이슈 자동 생성","es":"Guía de configuración de Issue-Maker: Creación de inciden...","fr":"Guide d''installation d''Issue-Maker: Outil de création d''i...","de":"Issue-Maker Einrichtungsleitfaden: GitHub-Issues erstellen","pt":"Issue-Maker: Guia de Configuração de Ferramentas de IA pa...","ru":"Issue-Maker: Настройка ИИ Агентов для GitHub","ar":"Issue-Maker: دليل إعداد أدوات الذكاء الاصطناعي لجيت هاب"},"description":{"en":"Streamline your GitHub workflow with issue-maker, a Gen-AI platform that turns user requests into issues. Learn how to set it up and automate your workflow t...","zh":"了解 Issue-Maker，这是一种开源的 Gen-AI 平台，能够自动将用户请求转换为 GitHub 问题，遵循团队约定","ja":"Issue-Maker は、ユーザーのリクエストを GitHub の問題に自動変換するオープンソースの Gen-AI プラットフォームです","ko":"Issue-Maker는 사용자의 요청을 깃허브 이슈로 자동 변환하는 오픈소스 Gen-AI 플랫폼입니다","es":"Aprende a configurar Issue-Maker, una plataforma de código abierto para crear incidencias de GitHub según las convenciones del equipo","fr":"Découvrez comment installer Issue-Maker, une plateforme open-source pour créer des incidents GitHub suivant les conventions d''équipe","de":"Erfahren Sie, wie Sie Issue-Maker einrichten, eine Open-Source-Plattform zum Erstellen von GitHub-Issues nach Teamkonventionen","pt":"Aprenda a configurar o Issue-Maker, uma plataforma de IA de código aberto, para criar problemas no GitHub de forma eficiente","ru":"Узнайте, как настроить Issue-Maker, открытую платформу ИИ, для создания проблем в GitHub","ar":"تعلم كيفية إعداد Issue-Maker، منصة الذكاء الاصطناعي مفتوحة المصدر، لإنشاء قضايا على جيت هاب بفعالية"},"definition":{"en":"issue-maker is an open-source Gen-AI platform that automates the creation of GitHub issues based on user requests, following predefined team conventions and rules.","zh":"Issue-Maker 是一种开源的 Gen-AI 平台，用于自动创建 GitHub 问题","ja":"Issue-Maker は、GitHub の問題を自動生成するオープンソースの Gen-AI プラットフォームです","ko":"Issue-Maker는 깃허브 이슈를 자동 생성하는 오픈소스 Gen-AI 플랫폼입니다","es":"Issue-Maker es una herramienta de código abierto que crea incidencias de GitHub según las convenciones del equipo","fr":"Issue-Maker est un outil open-source qui crée des incidents GitHub suivant les conventions d''équipe","de":"Issue-Maker ist ein Open-Source-Tool, das GitHub-Issues nach Teamkonventionen erstellt","pt":"O Issue-Maker é uma ferramenta de IA que automatiza a criação de problemas no GitHub","ru":"Issue-Maker - это инструмент ИИ, который автоматизирует создание проблем в GitHub","ar":"Issue-Maker هو أداة ذكاء اصطناعي تلقائية لإنشاء قضايا على جيت هاب"},"features":{"en":["Creates GitHub issues following team conventions and rules","Assigns issues to team members based on domain expertise","Utilizes the GitHub API for issue creation and management","Supports research-based issue creation using `gh search prs` command","Enforces no local side-effects, ensuring a clean and safe workflow"],"zh":["自动创建 GitHub 问题","支持 GitHub API 和 CLI 操作","遵循团队约定","支持多种编程语言","集成 GitHub 仓库"],"ja":["GitHub の問題を自動生成","GitHub API と CLI 操作をサポート","チームの約束に従う","複数のプログラミング言語をサポート","GitHub リポジトリを統合"],"ko":["깃허브 이슈 자동 생성","깃허브 API와 CLI 操作을 지원","팀 규칙을 준수","다양한 프로그래밍 언어를 지원","깃허브 저장소를 통합"],"es":["Creación de incidencias de GitHub según convenciones del equipo","Asignación de responsables según la experiencia en dominios","Uso de GitHub CLI para buscar solicitudes de extracción","Compatibilidad con formatos de estilo conciso y de puntos","Integración con flujos de trabajo de investigación","Seguimiento de las convenciones del equipo para crear incidencias"],"fr":["Création d''incidents GitHub suivant les conventions d''équipe","Assignation de responsables en fonction de l''expertise dans les domaines","Utilisation de GitHub CLI pour rechercher des demandes de pull","Compatibilité avec des formats de style concis et de points","Intégration avec des flux de travail de recherche","Suivi des conventions d''équipe pour créer des incidents"],"de":["Erstellung von GitHub-Issues nach Teamkonventionen","Zuweisung von Verantwortlichen nach Domänenexpertise","Verwendung von GitHub CLI zum Suchen von Pull-Requests","Unterstützung von kompakten Stil- und Punkteformaten","Integration mit Forschungs-Workflows","Einhaltung von Teamkonventionen für die Erstellung von Issues"],"pt":["Criação de problemas no GitHub com base em solicitações de usuário","Atribuição automática de problemas a membros da equipe com base em especialização","Pesquisa de inspiração de estilo em PRs do GitHub","Integração com a CLI do GitHub"],"ru":["Создание проблем в GitHub на основе запросов пользователей","Автоматическое назначение проблем членам команды на основе специализации","Поиск вдохновения стиля в PR GitHub","Интеграция с CLI GitHub"],"ar":["إنشاء قضايا على جيت هاب بناءً على طلبات المستخدم","تعيين تلقائي للقضايا إلى أعضاء الفريق بناءً على التخصص","بحث إلهام أسلوب في طلبات السحب على جيت هاب","التكامل مع واجهة سطر الأوامر لجيت هاب"]},"keywords":{"en":["how to use issue-maker","issue-maker setup guide","GitHub issue automation","issue-maker alternative","issue-maker vs GitHub automation tools","issue-maker install","what is issue-maker","issue-maker documentation","Gen-AI platform for GitHub"],"zh":["Issue-Maker","Gen-AI","GitHub","AIエージェント","自动创建问题","GitHub API","CLI 操作"],"ja":["Issue-Maker","Gen-AI","GitHub","AIエージェント","問題自動生成","GitHub API","CLI 操作"],"ko":["Issue-Maker","Gen-AI","깃허브","AI 에이전트","이슈 자동 생성","깃허브 API","CLI 操作"],"es":["Issue-Maker","herramientas de código abierto","incidencias de GitHub","convenciones del equipo","GitHub CLI","flujos de trabajo de investigación","creación de incidencias","asignación de responsables","estilo conciso","Herramientas de AI para desarrolladores","Agentes de IA para GitHub"],"fr":["Issue-Maker","outils open-source","incidents GitHub","conventions d''équipe","GitHub CLI","flux de travail de recherche","création d''incidents","assignation de responsables","style concis","Outils d''IA pour les développeurs","Agents d''IA pour GitHub"],"de":["Issue-Maker","Open-Source-Tools","GitHub-Issues","Teamkonventionen","GitHub CLI","Forschungs-Workflows","Erstellung von Issues","Zuweisung von Verantwortlichen","kompakter Stil","AI-Tools für Entwickler","KI-Agents für GitHub"],"pt":["Issue-Maker","Ferramentas de IA para GitHub","Criação de problemas automática","Atribuição de problemas","Integração com CLI do GitHub","Desenvolvimento de software","Ferramentas de desenvolvimento"],"ru":["Issue-Maker","ИИ Агенты для GitHub","Автоматическое создание проблем","Назначение проблем","Интеграция с CLI GitHub","Разработка программного обеспечения","Инструменты разработки"],"ar":["Issue-Maker","أدوات الذكاء الاصطناعي لجيت هاب","إنشاء قضايا تلقائي","تعيين القضايا","التكامل مع واجهة سطر الأوامر لجيت هاب","تطوير البرمجيات","أدوات التطوير"]}},"owner":"pollinations","repo":"pollinations","repoPath":"pollinations/pollinations","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.356Z","topics":[],"category":"community","skillMd":{"name":"issue-maker","description":"Create GitHub issues following Pollinations team conventions. Use when asked to create issues, track work, or plan features.","bodyPreview":"# Issue-Maker\n\nTurn any user request into GitHub issues following team conventions.\n\n---\n\n## Hard Rules\n\n1. **Repo:** `pollinations/pollinations`\n2. **Assignee:** Assign to appropriate team member based on domain expertise\n3. **No local side-effects** (no file creation/modification)\n\n---\n\n## Workflow\n\n### 1. Research First\n\nBefore creating any issues:\n\n```bash\n# Check @eulervoid''s PRs for style inspiration (concise, bullet-point format)\ngh search prs --repo pollinations/pollinations --author eul","body":"# Issue-Maker\n\nTurn any user request into GitHub issues following team conventions.\n\n---\n\n## Hard Rules\n\n1. **Repo:** `pollinations/pollinations`\n2. **Assignee:** Assign to appropriate team member based on domain expertise\n3. **No local side-effects** (no file creation/modification)\n\n---\n\n## Workflow\n\n### 1. Research First\n\nBefore creating any issues:\n\n```bash\n# Check @eulervoid''s PRs for style inspiration (concise, bullet-point format)\ngh search prs --repo pollinations/pollinations --author eulervoid --limit 5\n\n# Search existing issues for patterns\ngh search issues --repo pollinations/pollinations \"KEYWORD\" --limit 5\n```\n\n### 2. Plan\n\nList all planned issues:\n\n-   One sentence description per issue\n-   Identify assignee and labels\n-   Note related PRs or issues\n\n### 3. Create\n\n```bash\ngh issue create --repo pollinations/pollinations \\\n  --title \"EMOJI Short clear title\" \\\n  --body \"- Bullet point 1\n- Bullet point 2\n- Bullet point 3\" \\\n  --assignee HANDLE \\\n  --label \"LABEL\"\n```\n\n### 4. Output\n\nProvide Discord-compatible summary:\n\n-   Bold titles with issue numbers\n-   Plain URLs on separate lines (Discord auto-embeds)\n-   Group by category\n\n---\n\n## Team Handles\n\n| Name   | GitHub          | Domain                    |\n| ------ | --------------- | ------------------------- |\n| Thomas | **@voodoohop**  | General, Models, Infra    |\n| Joshua | **@eulervoid**  | Pollen, Backend, Auth     |\n| Elliot | **@elliotetag** | Community, Newsletter, UI |\n\n---\n\n## Common Labels\n\n| Label             | Use Case                                           |\n| ----------------- | -------------------------------------------------- |\n| `TRACKING`        | Meta/planning issues that track multiple sub-tasks |\n| `NEWS`            | Community announcements and updates                |\n| `ext-issue`       | External user requests (tier upgrades, etc.)       |\n| `app:review`      | New project submission (under review)              |\n| `app:info-needed` | Submission awaiting user response                  |\n| `app:approved`    | Project approved and merged                        |\n| `app:denied`      | Submission rejected                                |\n\n---\n\n## Issue Templates\n\n### Standard Issue (max 3 bullets)\n\n```markdown\n-   Adds X to Y\n-   Fix Z by doing W\n-   Related: #1234\n```\n\n### Tracking Issue (more detailed)\n\n```markdown\n## Overview\n\nBrief description\n\n## Tasks\n\n-   [ ] Task 1\n-   [ ] Task 2\n-   [ ] Task 3\n\n## Related\n\n-   #issue1\n-   #issue2\n```\n\n### Tier Upgrade Request\n\n```markdown\n-   Upgrade @USERNAME to TIER tier\n-   Qualification: [reason]\n-   Related: #original_request_issue\n```\n\n---\n\n## Style Guide\n\n-   **Short, sharp, no fluff**\n-   Smart emojis (not overdone)\n-   Bullet points over paragraphs\n-   Reference @eulervoid''s style: `repo:pollinations/pollinations author:eulervoid`\n\n---\n\n## Example Commands\n\n**Create simple issue:**\n\n```bash\ngh issue create --repo pollinations/pollinations \\\n  --title \"🔧 Fix caching header for image service\" \\\n  --body \"- Update cache-control header\n- Add proper ETag support\n- Related: #4100\" \\\n  --assignee voodoohop\n```\n\n**Create tracking issue:**\n\n```bash\ngh issue create --repo pollinations/pollinations \\\n  --title \"📋 TRACKING: Q4 Model Updates\" \\\n  --body \"## Overview\nTrack all model-related updates for Q4\n\n## Tasks\n- [ ] Add Claude Sonnet 4.5\n- [ ] Update pricing tiers\n- [ ] Deprecate old models\" \\\n  --label \"TRACKING\" \\\n  --assignee voodoohop\n```\n\n**Comment on issue:**\n\n```bash\ngh issue comment 1234 --repo pollinations/pollinations \\\n  --body \"✅ Done! Merged in #5678\"\n```\n"},"lastSynced":"2026-03-08T02:04:01.700Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated GitHub issue creation and assignment based on team conventions and domain expertise.","zh":"非常适合需要自动创建和分配GitHub问题的开发代理，基于团队惯例和领域专长。","ja":"開発エージェントが自動的にGitHubの問題を作成・割り当てる必要がある場合に最適です。チームの規範やドメインの専門知識に基づいて問題を作成・割り当てます。","ko":"개발 에이전트가 자동으로 GitHub 이슈를 생성하고 할당하는 데 적합하며 팀 규범과 도메인 전문知识에 따라 이슈를 생성하고 할당합니다.","es":"Perfecto para agentes de desarrollo que necesitan la creación y asignación automatizada de problemas de GitHub basada en convenciones de equipo y experiencia en el dominio.","fr":"Parfait pour les agents de développement nécessitant une création et une attribution automatiques des problèmes GitHub basées sur les conventions d''équipe et l''expertise domaine.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Erstellung und Zuweisung von GitHub-Problemen basierend auf Teamkonventionen und Domänenexpertise benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de criação e atribuição automatizada de problemas do GitHub com base em convenções da equipe e expertise em domínio.","ru":"Идеально для разработчиков, которым нужна автоматизация создания и назначения проблем GitHub на основе командных соглашений и опыта в области.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى إنشاء وتنسيق مشاكل GitHub آلي وفقًا لاتفاقيات الفريق والخبرة في المجال."},"recommendation":{"en":"Empowers agents to automate GitHub issue creation following team conventions, assigning issues to the right team members based on domain expertise, and utilizing GitHub search functionality for research inspiration from authors like @eulervoid, all while adhering to a concise, bullet-point format and avoiding local side-effects.","zh":"赋予代理人自动创建GitHub问题的能力，遵循团队惯例，根据领域专长将问题分配给合适的团队成员，并利用GitHub搜索功能从作者（如@eulervoid）那里获取研究灵感，同时保持简洁、项目符号格式并避免本地副作用。","ja":"エージェントがGitHubの問題を作成する自動化を可能にし、チームの規範に従って適切なチームメンバーに問題を割り当て、GitHubの検索機能を使用して@eulervoidのような著者から研究のインスピレーションを得ることができます。同時に、簡潔な箇条書き形式を保ち、ローカルの副作用を回避します。","ko":"에이전트가 GitHub 이슈를 자동으로 생성할 수 있는 기능을 제공하여 팀 규범을 따르며 도메인 전문知识에 따라 적절한 팀 구성원에게 이슈를 할당하고 GitHub 검색 기능을 사용하여 @eulervoid와 같은 저자로부터 연구灵感을 얻으며 간결하고 점 표기 형식을 유지하고 로컬副作用를 피합니다.","es":"Habilita a los agentes a automatizar la creación de problemas de GitHub siguiendo las convenciones del equipo, asignando problemas a los miembros del equipo adecuados basados en la experiencia en el dominio, y utilizando la funcionalidad de búsqueda de GitHub para la inspiración de la investigación de autores como @eulervoid, todo mientras se adhiere a un formato conciso y de puntos y evitando efectos secundarios locales.","fr":"Habilite les agents à automatiser la création de problèmes GitHub en suivant les conventions d''équipe, en attribuant les problèmes aux membres d''équipe appropriés en fonction de l''expertise domaine, et en utilisant la fonctionnalité de recherche GitHub pour l''inspiration de la recherche d''auteurs comme @eulervoid, tout en respectant un format concis et de points et en évitant les effets secondaires locaux.","de":"Ermächtigt Mittel, die Erstellung von GitHub-Problemen zu automatisieren, indem sie den Teamkonventionen folgen, Probleme den richtigen Teammitgliedern basierend auf Domänenexpertise zuweisen und die GitHub-Suchfunktion für Forschungsinspiration von Autoren wie @eulervoid nutzen, während sie sich an ein prägnantes, punktuelles Format halten und lokale Nebeneffekte vermeiden.","pt":"Habilita os agentes a automatizar a criação de problemas do GitHub seguindo as convenções da equipe, atribuindo problemas aos membros certos da equipe com base na expertise em domínio, e utilizando a funcionalidade de pesquisa do GitHub para inspiração em pesquisas de autores como @eulervoid, tudo isso enquanto adere a um formato conciso e em pontos e evita efeitos colaterais locais.","ru":"Наделяет агентов возможностью автоматизировать создание проблем GitHub в соответствии с командными соглашениями, назначать проблемы правильным членам команды на основе опыта в области, и использовать функциональность поиска GitHub для вдохновения от авторов, таких как @eulervoid, все это при соблюдении краткого, пунктирного формата и избегании локальных побочных эффектов.","ar":"تمكين الوكلاء من التutomatization إنشاء مشاكل GitHub اتباعًا لاتفاقيات الفريق، وتنسيق المشاكل لأعضاء الفريق المناسبين استنادًا إلى الخبرة في المجال، وتستخدم وظيفة البحث في GitHub للاستلهام من كتاب مثل @eulervoid، مع الالتزام بتنسيق متوافق وموجز وتجنب الآثار الجانبية المحلية."},"useCases":{"en":["Automating GitHub issue creation for user requests","Assigning issues to team members based on domain expertise","Researching PR styles from specific authors for inspiration"],"zh":["自动创建GitHub问题以响应用户请求","根据领域专长将问题分配给团队成员","研究来自特定作者（如@eulervoid）的PR样式以获取灵感"],"ja":["ユーザーからのリクエストに応じてGitHubの問題を作成する自動化","ドメインの専門知識に基づいて問題をチームメンバーに割り当てる","特定の著者（例：@eulervoid）からのPRスタイルを研究してインスピレーションを得る"],"ko":["사용자 요청에 대한 GitHub 이슈 자동 생성","도메인 전문知识에 따라 이슈를 팀 구성원에게 할당","특정 저자(@eulervoid와 같은)로부터의 PR 스타일 연구를 통한 영감 얻기"],"es":["Automatización de la creación de problemas de GitHub para solicitudes de usuario","Asignación de problemas a miembros del equipo basada en la experiencia en el dominio","Investigación de estilos de PR de autores específicos para la inspiración"],"fr":["Automation de la création de problèmes GitHub pour les demandes des utilisateurs","Attribution de problèmes aux membres d''équipe en fonction de l''expertise domaine","Recherche de styles de PR d''auteurs spécifiques pour l''inspiration"],"de":["Automatisierung der Erstellung von GitHub-Problemen für Benutzeranfragen","Zuweisung von Problemen zu Teammitgliedern basierend auf Domänenexpertise","Recherche von PR-Stilen von bestimmten Autoren für die Inspiration"],"pt":["Automatizar a criação de problemas do GitHub para solicitações de usuário","Atribuir problemas aos membros da equipe com base na expertise em domínio","Pesquisar estilos de PR de autores específicos para inspiração"],"ru":["Автоматизация создания проблем GitHub для запросов пользователей","Назначение проблем членам команды на основе опыта в области","Изучение стилей PR определенных авторов для вдохновения"],"ar":["التutomatization إنشاء مشاكل GitHub لطلبات المستخدم","تنسيق المشاكل لأعضاء الفريق استنادًا إلى الخبرة في المجال","البحث عن أساليب PR من مؤلفين معينين للإلهام"]},"limitations":{"en":["Requires access to GitHub repository pollinations/pollinations","No local file creation or modification allowed"],"zh":["需要访问GitHub仓库pollinations/pollinations","不允许创建或修改本地文件"],"ja":["GitHubリポジトリpollinations/pollinationsへのアクセスが必要","ローカルファイルの作成または変更は許可されません"],"ko":["GitHub 저장소 pollinations/pollinations에 접근할 수 있어야 함","로컬 파일의 생성 또는 수정을 허용하지 않음"],"es":["Requiere acceso al repositorio GitHub pollinations/pollinations","No se permite la creación o modificación de archivos locales"],"fr":["Nécessite l''accès au référentiel GitHub pollinations/pollinations","Aucune création ou modification de fichiers locaux autorisée"],"de":["Erfordert Zugriff auf das GitHub-Repository pollinations/pollinations","Keine lokale Dateierstellung oder -modifikation erlaubt"],"pt":["Requer acesso ao repositório GitHub pollinations/pollinations","Não é permitida a criação ou modificação de arquivos locais"],"ru":["Требуется доступ к репозиторию GitHub pollinations/pollinations","Не допускается создание или изменение локальных файлов"],"ar":["يتطلب الوصول إلى مستودع GitHub pollinations/pollinations","لا يسمح بإنشاء أو تعديل الملفات المحلية"]},"version":4},"contentHash":"4a55aac1c8b2e2c8e61c2dc43e7cc2c5bf0e73059e7c7038cd671a6321317c94","qualityScore":36}');
