INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pollinations/pollinations/issue-maker', 'issue-maker', 'pollinations', 'pollinations', 'community', 'issue-maker pollinations pollinations community issue-maker is a friendly open-source Gen-AI platform that automates GitHub issue creation following team conventions. It benefits development teams by assigning issues to the right team members based on domain expertise. Issue-Maker 是一个开源的 Gen-AI 平台，能够自动将用户请求转换为 GitHub 问题，遵循团队约定。它支持 GitHub API 和 CLI 操作 Issue-Maker は、ユーザーのリクエストを GitHub の問題に自動変換するオープンソースの Gen-AI プラットフォームです。GitHub API と CLI 操作をサポートしています Issue-Maker는 사용자의 요청을 깃허브 이슈로 자동 변환하는 오픈소스 Gen-AI 플랫폼입니다. 깃허브 API와 CLI 操作을 지원합니다 Issue-Maker es una plataforma de código abierto que convierte solicitudes de usuario en incidencias de GitHub siguiendo las convenciones del equipo Issue-Maker est une plateforme open-source qui transforme les demandes des utilisateurs en incidents GitHub suivant les conventions d''équipe Issue-Maker ist eine Open-Source-Plattform, die Benutzeranfragen in GitHub-Issues umwandelt, die den Teamkonventionen folgen O Issue-Maker é uma plataforma de IA de código aberto que converte solicitações de usuário em problemas do GitHub, seguindo as convenções da equipe Issue-Maker - это открытая платформа ИИ, которая преобразует запросы пользователей в проблемы GitHub, следуя соглашениям команды Issue-Maker هو منصة ذكاء اصطناعي مفتوحة المصدر تحول طلبات المستخدم إلى قضايا على جيت هاب، متبعة اتفاقيات الفريق how to use issue-maker issue-maker setup guide GitHub issue automation issue-maker alternative issue-maker vs GitHub automation tools issue-maker install what is issue-maker issue-maker documentation Gen-AI platform for GitHub Issue-Maker Gen-AI GitHub AIエージェント 自动创建问题 GitHub API CLI 操作 Creates GitHub issues following team conventions and rules Assigns issues to team members based on domain expertise Utilizes the GitHub API for issue creation and management Supports research-based issue creation using `gh search prs` command Enforces no local side-effects, ensuring a clean and safe workflow issue-maker is an open-source Gen-AI platform that automates the creation of GitHub issues based on user requests, following predefined team conventions and rules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('crowi/crowi/crowi-migration', 'community', 'crowi', 'crowi', 'crowi/crowi', 'crowi-migration', 0, 0, 36, '2026-03-08T01:57:15.356Z', '2026-03-08T02:04:02.305Z', '69c38ffd4e3c7af95ae36d938be53794fba33390d1ff2d2da2b8b5d3924a9ea6', '{"id":"crowi/crowi/crowi-migration","name":"crowi-migration","description":{"en":"The crowi-migration skill empowers development teams to share knowledge by migrating Crowi to version 2.0, utilizing Fastify and ts-rest for improved performance. It benefits developers working with Markdown Wiki.","zh":"Crowi 迁移工具是一种利用 Fastify、ts-rest 和 Next.js 进行团队知识共享的解决方案","ja":"Crowi 移行スキルは、Fastify、ts-rest、Next.js を使用したチームの知識共有ソリューションです","ko":"Crowi 마이그레이션 스킬은 Fastify, ts-rest, Next.js를 사용한 팀 지식 공유 솔루션입니다","es":"La migración a Crowi 2.0 implica actualizar a Fastify y ts-rest para mejorar el rendimiento. Nuestra guía te ayudará a hacerlo de manera efectiva.","fr":"La migration vers Crowi 2.0 implique une mise à jour vers Fastify et ts-rest pour améliorer les performances. Notre guide vous aidera à le faire de manière efficace.","de":"Die Migration zu Crowi 2.0 beinhaltet die Aktualisierung auf Fastify und ts-rest, um die Leistung zu verbessern. Unser Leitfaden hilft Ihnen dabei.","pt":"O Crowi 2.0 é uma plataforma de wiki baseada em Markdown que permite compartilhar conhecimento em equipe. A migração para essa versão pode ser complexa, mas com as dicas certas, é possível fazer a transição de forma eficaz.","ru":"Crowi 2.0 - это платформа wiki на основе Markdown, которая позволяет делиться знаниями в команде. Миграция на эту версию может быть сложной, но с правильными советами можно сделать переход эффективно для ИИ Агентов","ar":"كروي 2.0 هو منصة ويكي تعتمد على Markdown تتيح مشاركة المعرفة بين الفريق. يمكن أن تكون عملية الهجرة إلى هذه الإصدار معقدة، ولكن مع الإرشادات الصحيحة، يمكن إجراء التحول بفعالية للأدوات الذكية"},"seo":{"title":{"en":"crowi-migration: Fastify & ts-rest Migration Setup Guide ...","zh":"Crowi 迁移工具 Setup Guide - AIエージェント集成","ja":"Crowi 移行スキル Setup Guide - AIエージェントを活用","ko":"Crowi 마이그레이션 스킬 Setup Guide - AI 에이전트 통합","es":"Guía de migración Crowi - Mejora de rendimiento con Fasti...","fr":"Guide de migration Crowi - Amélioration des performances ...","de":"Crowi-Migrationsleitfaden - Leistungsverbesserung mit Fas...","pt":"Guia de Migração do Crowi - Melhores Práticas para Desenv...","ru":"Crowi Миграция: Руководство по Настройке для ИИ Агентов","ar":"دليل هجرة كروي - إرشادات قطع غيار لمنسقي الوكالات الذكية"},"description":{"en":"Migrate to Crowi 2.0 with ease! Learn how to transition from Express to Fastify + ts-rest and optimize your Markdown Wiki experience. Get started now!","zh":"Crowi 迁移工具帮助您将团队知识迁移到新平台，使用 Fastify、ts-rest 和 Next.js","ja":"Crowi 移行スキルは、Fastify、ts-rest、Next.js を使用してチームの知識を新しいプラットフォームに移行するのに役立ちます","ko":"Crowi 마이그레이션 스킬은 Fastify, ts-rest, Next.js를 사용하여 팀 지식을 새로운 플랫폼으로 마이그레이션하는 데 도움을 줍니다","es":"Aprende a migrar a Crowi 2.0 con nuestra guía paso a paso y mejora el rendimiento de tu wiki con Fastify y ts-rest","fr":"Découvrez comment migrer vers Crowi 2.0 avec notre guide étape par étape et améliorez les performances de votre wiki avec Fastify et ts-rest","de":"Erfahren Sie, wie Sie mit unserer Schritt-für-Schritt-Anleitung zu Crowi 2.0 migrieren und die Leistung Ihres Wikis mit Fastify und ts-rest verbessern","pt":"Aprenda a migrar para o Crowi 2.0 com nossa guia passo a passo, incluindo dicas para Express Route e Fastify + ts-rest","ru":"Узнайте, как перенести данные в Crowi 2.0 с помощью нашего пошагового руководства, включая советы по Express Route и Fastify + ts-rest для ИИ Агентов","ar":"تعلم كيفية تنفيذ هجرة إلى كروي 2.0 باستخدام دليلنا خطوة بخطوة، بما في ذلك نصائح حول Express Route و Fastify + ts-rest للأدوات الذكية"},"definition":{"en":"crowi-migration is a skill that enables the migration of Crowi to version 2.0, leveraging Fastify, ts-rest, and Next.js for enhanced functionality.","zh":"Crowi 迁移工具是一种 AI エージェント，帮助团队将知识迁移到新平台","ja":"Crowi 移行スキルは、チームの知識を新しいプラットフォームに移行する AI エージェントの一種です","ko":"Crowi 마이그레이션 스킬은 팀의 지식을 새로운 플랫폼으로 마이그레이션하는 AI 에이전트의 일종입니다","es":"Crowi-migración es el proceso de actualización a la versión 2.0 de Crowi, que implica cambiar a Fastify y ts-rest","fr":"La migration Crowi est le processus de mise à jour vers la version 2.0 de Crowi, qui implique le passage à Fastify et ts-rest","de":"Crowi-Migration ist der Prozess der Aktualisierung auf die Version 2.0 von Crowi, der die Umstellung auf Fastify und ts-rest beinhaltet","pt":"Crowi-migration é o processo de transição para o Crowi 2.0, incluindo a atualização de Express Route para Fastify + ts-rest","ru":"Crowi-миграция - это процесс перехода на Crowi 2.0, включая обновление Express Route до Fastify + ts-rest для ИИ Агентов","ar":"هجرة كروي هي عملية الانتقال إلى كروي 2.0، بما في ذلك تحديث Express Route إلى Fastify + ts-rest للأدوات الذكية"},"features":{"en":["Migrates Express routes to Fastify + ts-rest for improved performance","Utilizes Next.js 16 for enhanced web functionality","Supports API contract definition via ts-rest","Provides shared functionality through packages","Includes legacy implementation references for migration guidance","Employs Mongoose models for data management"],"zh":["使用 Fastify 和 ts-rest 进行 API 开发","利用 Next.js 进行 Web 开发","支持 Express Route 到 Fastify 和 ts-rest 的迁移","提供共享型和旧实现的参考"],"ja":["Fastify と ts-rest を使用した API 開発","Next.js を使用した Web 開発","Express Route から Fastify と ts-rest への移行をサポート","共有型と旧実装の参照を提供"],"ko":["Fastify와 ts-rest를 사용한 API 개발","Next.js를 사용한 웹 개발","Express Route에서 Fastify와 ts-rest로의 마이그레이션 지원","공유형과 旧実装의 참조 제공"],"es":["Actualización a Fastify para mejorar el rendimiento","Implementación de ts-rest para una API más robusta","Migración de rutas Express a Fastify","Uso de Next.js 16 para una mejor experiencia del usuario","Mejora de la seguridad con la actualización a Crowi 2.0"],"fr":["Mise à jour vers Fastify pour améliorer les performances","Implémentation de ts-rest pour une API plus robuste","Migration des routes Express vers Fastify","Utilisation de Next.js 16 pour une meilleure expérience utilisateur","Amélioration de la sécurité avec la mise à jour vers Crowi 2.0"],"de":["Aktualisierung auf Fastify für eine bessere Leistung","Implementierung von ts-rest für eine robustere API","Migration von Express-Routen zu Fastify","Verwendung von Next.js 16 für eine bessere Benutzererfahrung","Verbesserung der Sicherheit durch die Aktualisierung auf Crowi 2.0"],"pt":["Suporte a Express Route e Fastify + ts-rest","Integração com Next.js 16 e ts-rest","Compatibilidade com Mongoose e Swig","Arquitetura escalável com Crowi API e Crowi Web","Suporte a Markdown para compartilhamento de conhecimento"],"ru":["Поддержка Express Route и Fastify + ts-rest для ИИ Агентов","Интеграция с Next.js 16 и ts-rest","Совместимость с Mongoose и Swig","Масштабируемая архитектура с Crowi API и Crowi Web","Поддержка Markdown для обмена знаниями"],"ar":["دعم Express Route و Fastify + ts-rest للأدوات الذكية","التكامل مع Next.js 16 و ts-rest","التوافق مع Mongoose و Swig","هيكل معماري قابل للتوسيع مع Crowi API و Crowi Web","دعم Markdown لمشاركة المعرفة"]},"keywords":{"en":["how to use crowi-migration","crowi-migration setup guide","crowi-migration vs Express","Fastify + ts-rest migration","Crowi 2.0 migration tutorial","Markdown Wiki optimization"],"zh":["Crowi 迁移工具","AI エージェント","Fastify","ts-rest","Next.js","Express Route","团队知识共享","API 开发","Web 开发"],"ja":["Crowi 移行スキル","AI エージェント","Fastify","ts-rest","Next.js","Express Route","チームの知識共有","API 開発","Web 開発"],"ko":["Crowi 마이그레이션 스킬","AI 에이전트","Fastify","ts-rest","Next.js","Express Route","팀 지식 공유","API 개발","웹 개발"],"es":["migración Crowi","Fastify","ts-rest","Next.js 16","mejora de rendimiento","seguridad en Crowi","Actualización a Crowi 2.0","Guía de migración Crowi","Herramientas de migración"],"fr":["migration Crowi","Fastify","ts-rest","Next.js 16","amélioration des performances","sécurité dans Crowi","Mise à jour vers Crowi 2.0","Guide de migration Crowi","Outils de migration"],"de":["Crowi-Migration","Fastify","ts-rest","Next.js 16","Leistungsverbesserung","Sicherheit in Crowi","Aktualisierung auf Crowi 2.0","Crowi-Migrationsleitfaden","Migrationswerkzeuge"],"pt":["crowi migration","express route","fastify ts-rest","next.js 16","mongoose","swig","markdown wiki","desenvolvimento de software","migração de plataforma"],"ru":["crowi миграция","express route","fastify ts-rest","next.js 16","mongoose","swig","markdown wiki","разработка программного обеспечения","перенос платформы для ИИ Агентов"],"ar":["هجرة كروي","express route","fastify ts-rest","next.js 16","mongoose","swig","markdown wiki","تطوير البرمجيات","نقل منصة للأدوات الذكية"]}},"owner":"crowi","repo":"crowi","repoPath":"crowi/crowi","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.356Z","topics":[],"category":"community","skillMd":{"name":"crowi-migration","description":"|","bodyPreview":"# Crowi 2.0 Migration Skill\n\n## アーキテクチャ\n\n```\ncrowi/\n├── apps/\n│   ├── crowi-api/          # Fastify + ts-rest (port 3300)\n│   └── crowi-web/          # Next.js 16 (port 3301)\n├── packages/\n│   ├── api-contract/       # ts-rest 契約定義\n│   └── shared/             # 共有型\n└── lib/                    # 旧実装（参照元）\n    ├── routes/             # Express ルート\n    ├── views/              # Swig テンプレート\n    └── models/             # Mongoose モデル\n```\n\n## 移行パターン\n\n### Express Route → Fastify + ts-rest\n\n```typescript","body":"# Crowi 2.0 Migration Skill\n\n## アーキテクチャ\n\n```\ncrowi/\n├── apps/\n│   ├── crowi-api/          # Fastify + ts-rest (port 3300)\n│   └── crowi-web/          # Next.js 16 (port 3301)\n├── packages/\n│   ├── api-contract/       # ts-rest 契約定義\n│   └── shared/             # 共有型\n└── lib/                    # 旧実装（参照元）\n    ├── routes/             # Express ルート\n    ├── views/              # Swig テンプレート\n    └── models/             # Mongoose モデル\n```\n\n## 移行パターン\n\n### Express Route → Fastify + ts-rest\n\n```typescript\n// Before: lib/routes/page.js\nrouter.get(''/pages'', async (req, res) => {\n  const pages = await Page.find();\n  res.render(''page/list'', { pages });\n});\n\n// After: packages/api-contract/src/page.ts\nexport const pageContract = c.router({\n  listPages: {\n    method: ''GET'',\n    path: ''/pages'',\n    responses: { 200: z.object({ pages: z.array(PageSchema) }) },\n  },\n});\n\n// After: apps/crowi-api/src/routes/page.ts\nlistPages: async () => {\n  const pages = await Page.find();\n  return { status: 200, body: { pages } };\n},\n```\n\n### Swig Template → Next.js Page\n\n```typescript\n// Before: lib/views/page/list.html\n{% for page in pages %}\n  <div>{{ page.path }}</div>\n{% endfor %}\n\n// After: apps/crowi-web/app/(main)/pages/page.tsx\n''use client'';\nexport default function PagesPage() {\n  const { data } = useQuery([''pages''], () => client.page.listPages());\n  return data?.body.pages.map(page => <div key={page._id}>{page.path}</div>);\n}\n```\n\n## サブエージェント\n\n| Agent | 役割 | ツール |\n|-------|------|--------|\n| migration-planner | 計画立案 | Read, Grep, Glob |\n| migration-implementer | 実装 | Read, Write, Edit, Bash |\n| migration-reviewer | レビュー | Read, Grep, Bash |\n| migration-committer | コミット・PR | Read, Bash |\n\n## ワークフロー\n\n```\n/migrate {task-name}\n\nplanner → implementer → reviewer ─┬→ committer\n                          ↑       │\n                          └───────┘ (NEEDS_WORK)\n```\n\n## タスク管理\n\n- キュー: `.migration-state/queue.json`\n- タスク: `.migration-state/tasks/{task-id}.json`\n- ステータス: `PLANNED` → `REVIEW` → `APPROVED` → `COMMITTED`\n\n## 技術スタック\n\n- **API**: Fastify v5, ts-rest, MongoDB/Mongoose, JWT\n- **Web**: Next.js 16, React 19, Tailwind v4, shadcn/ui\n- **共通**: TypeScript 5.x strict, pnpm, Turborepo\n\n## Crowi テーマ\n\n```css\n--crowi-primary: #43676b;\n--crowi-header: #263a3c;\n--crowi-sidebar: #f8f9fa;\n```\n"},"lastSynced":"2026-03-08T02:04:02.305Z","agentAnalysis":{"suitability":{"en":"Perfect for Markdown Wiki Agents needing seamless migration to Crowi 2.0 with improved performance using Fastify and ts-rest.","zh":"非常适合需要使用Fastify和ts-rest实现无缝迁移至Crowi 2.0并提高性能的Markdown Wiki Agents","ja":"Fastifyとts-restを使用してCrowi 2.0への無縫な移行とパフォーマンスの向上を必要とするMarkdown Wikiエージェントに最適","ko":"Fastify와 ts-rest를 사용하여 Crowi 2.0으로의 무중단 마이그레이션과 성능 향상을 필요로 하는 Markdown Wiki 에이전트에 적합","es":"Perfecto para agentes de Wiki de Markdown que necesitan una migración sin problemas a Crowi 2.0 con un rendimiento mejorado utilizando Fastify y ts-rest.","fr":"Parfait pour les agents Wiki Markdown nécessitant une migration transparente à Crowi 2.0 avec des performances améliorées en utilisant Fastify et ts-rest.","de":"Perfekt für Markdown-Wiki-Agents, die eine nahtlose Migration zu Crowi 2.0 mit verbesserter Leistung unter Verwendung von Fastify und ts-rest benötigen.","pt":"Perfeito para agentes Wiki Markdown que necessitam de migração sem problemas para o Crowi 2.0 com desempenho melhorado usando Fastify e ts-rest.","ru":"Идеально подходит для агентов Wiki Markdown, которым необходима бесшовная миграция на Crowi 2.0 с улучшенной производительностью с помощью Fastify и ts-rest.","ar":"مثالي لعميل ويكي ماركداون الذي يحتاج إلى هجرة بدون مشاكل إلى Crowi 2.0 مع أداء محسن باستخدام Fastify و ts-rest."},"recommendation":{"en":"Empowers agents to migrate Crowi to version 2.0, leveraging Fastify and ts-rest for enhanced performance, and benefiting developers working with Markdown Wiki by utilizing Next.js 16 and ts-rest contract definitions.","zh":"赋予代理迁移Crowi至2.0版本的能力，利用Fastify和ts-rest实现增强的性能，并利用Next.js 16和ts-rest契约定义来造福与Markdown Wiki合作的开发人员","ja":"エージェントがCrowiをバージョン2.0に移行することを可能にし、Fastifyとts-restを使用してパフォーマンスを強化し、Next.js 16とts-rest契約定義を使用してMarkdown Wikiと共同作業する開発者に利益をもたらす","ko":"에이전트가 Crowi를 2.0 버전으로 마이그레이션할 수 있도록 해주고, Fastify와 ts-rest를 사용하여 성능을 강화하며, Next.js 16과 ts-rest 계약 정의를 사용하여 Markdown Wiki와 협력하는 개발자에게 이점을 제공","es":"Habilita a los agentes a migrar Crowi a la versión 2.0, aprovechando Fastify y ts-rest para un rendimiento mejorado, y beneficiando a los desarrolladores que trabajan con Markdown Wiki mediante la utilización de definiciones de contrato Next.js 16 y ts-rest.","fr":"Permet aux agents de migrer Crowi vers la version 2.0, en exploitant Fastify et ts-rest pour des performances améliorées, et en bénéficiant aux développeurs travaillant avec Markdown Wiki en utilisant les définitions de contrat Next.js 16 et ts-rest.","de":"Ermöglicht es Agenten, Crowi auf Version 2.0 zu migrieren, indem Fastify und ts-rest für eine verbesserte Leistung genutzt werden, und entwickelt Vorteile für Entwickler, die mit Markdown Wiki arbeiten, indem Next.js 16 und ts-rest-Vertragsdefinitionen verwendet werden.","pt":"Habilita os agentes a migrar o Crowi para a versão 2.0, aproveitando Fastify e ts-rest para um desempenho melhorado, e beneficiando os desenvolvedores que trabalham com Wiki Markdown ao utilizar definições de contrato Next.js 16 e ts-rest.","ru":"Наделяет агентов возможностью мигрировать Crowi на версию 2.0, используя Fastify и ts-rest для улучшения производительности, и принося пользу разработчикам, работающим с Wiki Markdown, используя определения контракта Next.js 16 и ts-rest.","ar":"يمنح العميل القدرة على نقل Crowi إلى الإصدار 2.0، واستخدام Fastify و ts-rest لتحسين الأداء، ويفيد المطورين الذين يعملون مع ويكي ماركداون باستخدام تعريفات عقد Next.js 16 و ts-rest."},"useCases":{"en":["Migrating Express routes to Fastify for better performance","Upgrading Crowi APIs with ts-rest for improved contract definitions","Integrating Next.js 16 for enhanced web applications"],"zh":["将Express路由迁移到Fastify以实现更好的性能","使用ts-rest升级Crowi API以改进契约定义","集成Next.js 16以增强Web应用程序"],"ja":["ExpressルーティングをFastifyに移行してパフォーマンスを向上させる","ts-restを使用してCrowi APIをアップグレードして契約定義を改善する","Next.js 16を統合してWebアプリケーションを強化する"],"ko":["Express 라우팅을 Fastify로 마이그레이션하여 성능을 개선","ts-rest를 사용하여 Crowi API를 업그레이드하여 계약 정의를 개선","Next.js 16을 통합하여 웹 애플리케이션을 강화"],"es":["Migrar rutas de Express a Fastify para un mejor rendimiento","Actualizar Crowi APIs con ts-rest para definiciones de contrato mejoradas","Integrar Next.js 16 para aplicaciones web mejoradas"],"fr":["Migrer des routes Express vers Fastify pour de meilleures performances","Mettre à jour les API Crowi avec ts-rest pour des définitions de contrat améliorées","Intégrer Next.js 16 pour des applications Web améliorées"],"de":["Express-Routen zu Fastify migrieren, um die Leistung zu verbessern","Crowi-APIs mit ts-rest aktualisieren, um verbesserte Vertragsdefinitionen zu erhalten","Next.js 16 integrieren, um verbesserte Webanwendungen zu erhalten"],"pt":["Migrar rotas Express para Fastify para melhor desempenho","Atualizar APIs Crowi com ts-rest para definições de contrato melhoradas","Integrar Next.js 16 para aplicações web melhoradas"],"ru":["Мигрировать маршруты Express в Fastify для лучшей производительности","Обновить API Crowi с ts-rest для улучшенных определений контракта","Интегрировать Next.js 16 для улучшенных веб-приложений"],"ar":["نقل مسارات Express إلى Fastify من أجل أداء أفضل","تحديث Crowi API مع ts-rest من أجل تعريفات عقد محسنة","دمج Next.js 16 من أجل تطبيقات ويب محسنة"]},"limitations":{"en":["Requires Crowi version 2.0 compatibility","Limited to Markdown Wiki development teams","Dependent on Fastify and ts-rest for improved performance"],"zh":["需要Crowi 2.0版本的兼容性","仅限于Markdown Wiki开发团队","依赖于Fastify和ts-rest来实现更好的性能"],"ja":["Crowiバージョン2.0の互換性が必要","Markdown Wiki開発チームのみに限定","パフォーマンスの向上のためにFastifyとts-restに依存"],"ko":["Crowi 2.0 버전의 호환성을 필요로 함","Markdown Wiki 개발 팀에만 제한","성능 개선을 위해 Fastify와 ts-rest에 의존"],"es":["Requiere compatibilidad con la versión 2.0 de Crowi","Limitado a equipos de desarrollo de Markdown Wiki","Dependiente de Fastify y ts-rest para un rendimiento mejorado"],"fr":["Nécessite une compatibilité avec la version 2.0 de Crowi","Limité aux équipes de développement de Wiki Markdown","Dépendant de Fastify et ts-rest pour des performances améliorées"],"de":["Benötigt Kompatibilität mit Crowi-Version 2.0","Begrenzt auf Markdown-Wiki-Entwicklungsteams","Abhängig von Fastify und ts-rest für eine verbesserte Leistung"],"pt":["Exige compatibilidade com a versão 2.0 do Crowi","Limitado a equipes de desenvolvimento de Wiki Markdown","Dependente de Fastify e ts-rest para desempenho melhorado"],"ru":["Требует совместимости с версией 2.0 Crowi","Ограничен командами разработки Wiki Markdown","Зависит от Fastify и ts-rest для улучшенной производительности"],"ar":["يتطلب توافقًا مع الإصدار 2.0 من Crowi","محدود لفريق التطوير ويكي ماركداون","يعتمد على Fastify و ts-rest لتحسين الأداء"]},"version":4},"contentHash":"69c38ffd4e3c7af95ae36d938be53794fba33390d1ff2d2da2b8b5d3924a9ea6","qualityScore":36}');
