INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('crowi/crowi/crowi-migration', 'crowi-migration', 'crowi', 'crowi', 'community', 'crowi-migration crowi crowi community The crowi-migration skill empowers development teams to share knowledge by migrating Crowi to version 2.0, utilizing Fastify and ts-rest for improved performance. It benefits developers working with Markdown Wiki. Crowi 迁移工具是一种利用 Fastify、ts-rest 和 Next.js 进行团队知识共享的解决方案 Crowi 移行スキルは、Fastify、ts-rest、Next.js を使用したチームの知識共有ソリューションです Crowi 마이그레이션 스킬은 Fastify, ts-rest, Next.js를 사용한 팀 지식 공유 솔루션입니다 La migración a Crowi 2.0 implica actualizar a Fastify y ts-rest para mejorar el rendimiento. Nuestra guía te ayudará a hacerlo de manera efectiva. La migration vers Crowi 2.0 implique une mise à jour vers Fastify et ts-rest pour améliorer les performances. Notre guide vous aidera à le faire de manière efficace. Die Migration zu Crowi 2.0 beinhaltet die Aktualisierung auf Fastify und ts-rest, um die Leistung zu verbessern. Unser Leitfaden hilft Ihnen dabei. O Crowi 2.0 é uma plataforma de wiki baseada em Markdown que permite compartilhar conhecimento em equipe. A migração para essa versão pode ser complexa, mas com as dicas certas, é possível fazer a transição de forma eficaz. Crowi 2.0 - это платформа wiki на основе Markdown, которая позволяет делиться знаниями в команде. Миграция на эту версию может быть сложной, но с правильными советами можно сделать переход эффективно для ИИ Агентов كروي 2.0 هو منصة ويكي تعتمد على Markdown تتيح مشاركة المعرفة بين الفريق. يمكن أن تكون عملية الهجرة إلى هذه الإصدار معقدة، ولكن مع الإرشادات الصحيحة، يمكن إجراء التحول بفعالية للأدوات الذكية how to use crowi-migration crowi-migration setup guide crowi-migration vs Express Fastify + ts-rest migration Crowi 2.0 migration tutorial Markdown Wiki optimization Crowi 迁移工具 AI エージェント Fastify ts-rest Next.js Express Route 团队知识共享 API 开发 Web 开发 Migrates Express routes to Fastify + ts-rest for improved performance Utilizes Next.js 16 for enhanced web functionality Supports API contract definition via ts-rest Provides shared functionality through packages Includes legacy implementation references for migration guidance Employs Mongoose models for data management crowi-migration is a skill that enables the migration of Crowi to version 2.0, leveraging Fastify, ts-rest, and Next.js for enhanced functionality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('derekcrosslu/CLAUDE_CODE_EXPLORE/Project Timeline', 'community', 'derekcrosslu', 'CLAUDE_CODE_EXPLORE', 'derekcrosslu/CLAUDE_CODE_EXPLORE', 'Project Timeline', 0, 0, 36, '2026-03-08T01:57:15.356Z', '2026-03-08T02:04:02.496Z', '5f471d133a878d83406f680ff63ce1b277e1a6bfc420c92078314796a2290a0d', '{"id":"derekcrosslu/CLAUDE_CODE_EXPLORE/Project Timeline","name":"Project Timeline","description":{"en":"The Project Timeline skill helps developers manage project timelines using the CLI. It provides features like getting the next task and marking checklist items as complete.","zh":"Project Timeline 是一个使用 CLI 管理项目时间表的工具，帮助开发者提高效率。使用 `venv/bin/python SCRIPTS/timeline_cli.py` 命令管理项目进度","ja":"Project Timeline は、CLI を使用してプロジェクト時間表を管理するツールです。開発者は `venv/bin/python SCRIPTS/timeline_cli.py` コマンドを使用してプロジェクトの進度を管理できます","ko":"Project Timeline은 CLI를 사용하여 프로젝트 타임라인을 관리하는 도구입니다. 개발자는 `venv/bin/python SCRIPTS/timeline_cli.py` 명령을 사용하여 프로젝트 진행 상황을 관리할 수 있습니다","es":"La línea de tiempo de proyecto es una herramienta de CLI que gestiona el progreso del proyecto. Utilice `venv/bin/python SCRIPTS/timeline_cli.py` para administrar su proyecto","fr":"La chronologie de projet est un outil de CLI qui gère l''avancement du projet. Utilisez `venv/bin/python SCRIPTS/timeline_cli.py` pour gérer votre projet","de":"Die Projekt-Zeitplan ist ein CLI-Tool, das den Projektfortschritt verwaltet. Verwenden Sie `venv/bin/python SCRIPTS/timeline_cli.py`, um Ihr Projekt zu verwalten","pt":"O Project Timeline CLI é uma ferramenta de linha de comando que ajuda a gerenciar o cronograma de projetos","ru":"Project Timeline - это инструмент командной строки для управления проектами","ar":"Project Timeline AI Tool هو أداة سطر أوامر تساعد في إدارة مشاريعك"},"seo":{"title":{"en":"Project Timeline: CLI Setup Guide | AI Agent Skill","zh":"Project Timeline 设置指南 - 使用