INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('derekcrosslu/CLAUDE_CODE_EXPLORE/Project Timeline', 'Project Timeline', 'derekcrosslu', 'CLAUDE_CODE_EXPLORE', 'community', 'Project Timeline derekcrosslu CLAUDE_CODE_EXPLORE community The Project Timeline skill helps developers manage project timelines using the CLI. It provides features like getting the next task and marking checklist items as complete. Project Timeline 是一个使用 CLI 管理项目时间表的工具，帮助开发者提高效率。使用 `venv/bin/python SCRIPTS/timeline_cli.py` 命令管理项目进度 Project Timeline は、CLI を使用してプロジェクト時間表を管理するツールです。開発者は `venv/bin/python SCRIPTS/timeline_cli.py` コマンドを使用してプロジェクトの進度を管理できます Project Timeline은 CLI를 사용하여 프로젝트 타임라인을 관리하는 도구입니다. 개발자는 `venv/bin/python SCRIPTS/timeline_cli.py` 명령을 사용하여 프로젝트 진행 상황을 관리할 수 있습니다 La línea de tiempo de proyecto es una herramienta de CLI que gestiona el progreso del proyecto. Utilice `venv/bin/python SCRIPTS/timeline_cli.py` para administrar su proyecto La chronologie de projet est un outil de CLI qui gère l''avancement du projet. Utilisez `venv/bin/python SCRIPTS/timeline_cli.py` pour gérer votre projet Die Projekt-Zeitplan ist ein CLI-Tool, das den Projektfortschritt verwaltet. Verwenden Sie `venv/bin/python SCRIPTS/timeline_cli.py`, um Ihr Projekt zu verwalten O Project Timeline CLI é uma ferramenta de linha de comando que ajuda a gerenciar o cronograma de projetos Project Timeline - это инструмент командной строки для управления проектами Project Timeline AI Tool هو أداة سطر أوامر تساعد في إدارة مشاريعك how to use Project Timeline Project Timeline CLI setup Project Timeline vs Trello Project Timeline install guide what is Project Timeline Project Timeline alternative tools Project Timeline setup tutorial Project Timeline workflow management Project Timeline Python integration Project Timeline CLI 项目时间表管理 开发效率 AI工具 项目管理 Manages project timelines using the CLI command `venv/bin/python SCRIPTS/timeline_cli.py` Provides the `next` command to retrieve the next task Supports filtering tasks by week using the `--week` flag Allows marking checklist items as complete Enables checking progress using the CLI Integrates with Python scripts for customized workflow management Project Timeline is a CLI-based tool for managing project timelines, allowing developers to track progress and stay organized.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HemSoft/hs-conductor/version', 'community', 'HemSoft', 'hs-conductor', 'HemSoft/hs-conductor', 'version', 0, 0, 36, '2026-03-08T01:57:15.360Z', '2026-03-08T02:04:12.868Z', '30f1ba0616ffed941c685e8c6e2a41245483b89286baab96a4af91136d15c779', '{"id":"HemSoft/hs-conductor/version","name":"version","description":{"en":"The version skill helps developers manage releases using Semantic Versioning. It benefits developers by providing a checklist for updating changelogs and package files.","zh":"版本管理是软件开发中的关键步骤，本文介绍了Semantic Versioning的应用和版本发布检查清单","ja":"バージョン管理はソフトウェア開発の重要なステップです。この記事では、Semantic Versioningの適用とバージョンリリースチェックリストについて説明します","ko":"버전 관리는 소프트웨어 개발의 중요한 단계입니다. 본 문서에서는 Semantic Versioning의 적용과 버전 릴리즈 체크리스트에 대해 설명합니다","es":"El agente de versión utiliza Semantic Versioning para gestionar versiones de hs-cli-conductor. Sigue el checklist de versión para actualizar CHANGELOG.md y package.json.","fr":"L''agent de version utilise Semantic Versioning pour gérer les versions de hs-cli-conductor. Suivez la checklist de version pour mettre à jour CHANGELOG.md et package.json.","de":"Der Version-Agent verwendet Semantic Versioning, um Versionen von hs-cli-conductor zu verwalten. Befolgen Sie die Versions-Checkliste, um CHANGELOG.md und package.json zu aktualisieren.","pt":"O gerenciamento de versões é crucial para o desenvolvimento de software. Aprenda a usar o Semantic Versioning com o hs-cli-conductor.","ru":"Управление версиями имеет решающее значение для разработки программного обеспечения. Узнайте, как использовать Semantic Versioning с hs-cli-conductor.","ar":"إدارة الإصدارات أمر بالغ الأهمية لتطوير البرمجيات. تعلم كيفية استخدام Semantic Versioning مع hs-cli-conductor."},"seo":{"title":{"en":"Version: Semantic Versioning Setup Guide | AI Agent Skill","zh":"版本管理Setup Guide - Semantic Versioning最佳实践","ja":"バージョン管理Setup Guide - Semantic Versioningのベストプラクティス","ko":"버전 관리 Setup Guide - Semantic Versioning 적용 가이드","es":"Guía de Configuración de Versiones con Semantic Versioning","fr":"Guide de Mise en Place de Versions avec Semantic Versioning","de":"Versions-Setup-Leitfaden mit Semantic Versioning","pt":"Guia de Configuração de Versão com Semantic Versioning","ru":"ИИ Агенты: Руководство по настройке версий с помощью Sema...","ar":"دليل إعداد الإصدار باستخدام Semantic Versioning للآلات ال..."},"description":{"en":"Learn how to manage versions with Semantic Versioning. Get the best practices for updating CHANGELOG.md and package.json files. Start now!","zh":"学习版本管理的最佳实践，包括Semantic Versioning和版本发布检查清单，提高您的开发效率","ja":"バージョン管理のベストプラクティスを学び、Semantic Versioningとバージョンリリースチェックリストを使用して開発効率を向上させましょう","ko":"버전 관리의 베스트 프랙티스를 학습하고, Semantic Versioning 및 버전 릴리즈 체크리스트를 사용하여 개발 효율성을 향상시키세요","es":"Aprende a gestionar versiones con el agente de AI Herramientas utilizando Semantic Versioning y checklist de versión","fr":"Découvrez comment gérer les versions avec l''agent d''outils d''IA en utilisant Semantic Versioning et une checklist de version","de":"Erfahren Sie, wie Sie Versionen mit dem AI-Tool-Agenten unter Verwendung von Semantic Versioning und einer Versions-Checkliste verwalten","pt":"Aprenda a gerenciar versões com o hs-cli-conductor usando Semantic Versioning. Atualize o CHANGELOG.md e package.json corretamente.","ru":"Научитесь управлять версиями с помощью hs-cli-conductor и Semantic Versioning. Обновите CHANGELOG.md и package.json правильно.","ar":"تعلم إدارة الإصدارات باستخدام hs-cli-conductor و Semantic Versioning. قم بتحديث CHANGELOG.md و package.json بشكل صحيح."},"definition":{"en":"Version is a management system using Semantic Versioning to track changes in software releases, following a major.minor.patch format.","zh":"版本管理是指使用Semantic Versioning规范管理软件版本的过程","ja":"バージョン管理は、Semantic Versioning規格を使用してソフトウェアバージョンを管理するプロセスです","ko":"버전 관리는 Semantic Versioning 규격을 사용하여 소프트웨어 버전을 관리하는 프로세스입니다","es":"El agente de versión es una herramienta de AI que gestiona versiones de software utilizando Semantic Versioning","fr":"L''agent de version est un outil d''IA qui gère les versions de logiciels en utilisant Semantic Versioning","de":"Der Version-Agent ist ein AI-Tool, das Softwareversionen unter Verwendung von Semantic Versioning verwaltet","pt":"O que é gerenciamento de versões? É o processo de controle de alterações em software usando Semantic Versioning.","ru":"Что такое управление версиями? Это процесс контроля изменений в программном обеспечении с помощью Semantic Versioning.","ar":"ما هي إدارة الإصدارات؟ هي عملية التحكم في التغييرات في البرمجيات باستخدام Semantic Versioning."},"features":{"en":["Updates CHANGELOG.md file according to Keep a Changelog standard","Modifies package.json file to reflect new version numbers","Follows Semantic Versioning (major.minor.patch) for release management","Includes Added, Changed, Fixed, Removed sections in changelog entries","Supports release version checklist for hs-cli-conductor"],"zh":["使用Semantic Versioning规范管理版本","更新CHANGELOG.md文件","修改package.json文件","遵循Keep a Changelog标准","包括Added、Changed、Fixed、Removedsections"],"ja":["Semantic Versioning規格を使用してバージョンを管理","CHANGELOG.mdファイルを更新","package.jsonファイルを変更","Keep a Changelog標準に従う","Added、Changed、Fixed、Removedセクションを含む"],"ko":["Semantic Versioning 규격을 사용하여 버전 관리","CHANGELOG.md 파일 업데이트","package.json 파일 수정","Keep a Changelog 표준 준수","Added, Changed, Fixed, Removed 섹션 포함"],"es":["Utiliza Semantic Versioning para gestionar versiones","Actualiza CHANGELOG.md y package.json según sea necesario","Sigue la norma Keep a Changelog","Incluye secciones Added, Changed, Fixed, Removed en el registro de cambios","Compatibilidad con hs-cli-conductor"],"fr":["Utilise Semantic Versioning pour gérer les versions","Mette à jour CHANGELOG.md et package.json selon les besoins","Suive la norme Keep a Changelog","Inclut des sections Added, Changed, Fixed, Removed dans le journal des modifications","Compatibilité avec hs-cli-conductor"],"de":["Verwaltet Versionen unter Verwendung von Semantic Versioning","Aktualisiert CHANGELOG.md und package.json nach Bedarf","Befolgt die Keep a Changelog-Norm","Enthält Abschnitte Added, Changed, Fixed, Removed im Änderungsprotokoll","Kompatibilität mit hs-cli-conductor"],"pt":["Uso de Semantic Versioning para gerenciar versões","Atualização do CHANGELOG.md","Atualização do package.json","Suporte ao formato Keep a Changelog","Inclusão de seções Added, Changed, Fixed, Removed","Compatibilidade com hs-cli-conductor"],"ru":["Использование Semantic Versioning для управления версиями","Обновление CHANGELOG.md","Обновление package.json","Поддержка формата Keep a Changelog","Включение разделов Added, Changed, Fixed, Removed","Совместимость с hs-cli-conductor"],"ar":["استخدام Semantic Versioning لإدارة الإصدارات","تحديث CHANGELOG.md","تحديث package.json","دعم تنسيق Keep a Changelog","إدراج أقسام Added, Changed, Fixed, Removed","التوافق مع hs-cli-conductor"]},"keywords":{"en":["how to use semantic versioning","version management best practices","semantic versioning vs calendar versioning","version setup guide","what is semantic versioning","version install for hs-cli-conductor","version alternative to calendar versioning","version management for AI agents"],"zh":["版本管理","Semantic Versioning","版本发布检查清单","软件开发","Keep a Changelog","package.json","CHANGELOG.md","AIエージェント","AI开发工具"],"ja":["バージョン管理","Semantic Versioning","バージョンリリースチェックリスト","ソフトウェア開発","Keep a Changelog","package.json","CHANGELOG.md","AIエージェント","AI開発ツール"],"ko":["버전 관리","Semantic Versioning","버전 릴리즈 체크리스트","소프트웨어 개발","Keep a Changelog","package.json","CHANGELOG.md","AI 에이전트","AI 개발 도구"],"es":["gestión de versiones","Semantic Versioning","hs-cli-conductor","CHANGELOG.md","package.json","agente de AI","Herramientas de AI","versiones de software"],"fr":["gestion de versions","Semantic Versioning","hs-cli-conductor","CHANGELOG.md","package.json","agent d''IA","outils d''IA","versions de logiciels"],"de":["Versionsverwaltung","Semantic Versioning","hs-cli-conductor","CHANGELOG.md","package.json","AI-Tool-Agent","AI-Tools","Softwareversionen"],"pt":["gerenciamento de versões","Semantic Versioning","hs-cli-conductor","CHANGELOG.md","package.json","Keep a Changelog","desenvolvimento de software","controle de versões","versionamento de software"],"ru":["управление версиями","Semantic Versioning","hs-cli-conductor","CHANGELOG.md","package.json","Keep a Changelog","разработка программного обеспечения","контроль версий","управление версиями программного обеспечения"],"ar":["إدارة الإصدارات","Semantic Versioning","hs-cli-conductor","CHANGELOG.md","package.json","Keep a Changelog","تطوير البرمجيات","مراقبة الإصدارات","إدارة إصدارات البرمجيات"]}},"owner":"HemSoft","repo":"hs-conductor","repoPath":"HemSoft/hs-conductor","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.360Z","topics":[],"category":"community","skillMd":{"name":"version","description":"V1.0 - Release version management checklist for hs-cli-conductor. Use when bumping versions or preparing releases.","bodyPreview":"# Version Management\n\nRelease version checklist for hs-cli-conductor using **Semantic Versioning** (major.minor.patch).\n\n## Version Bump Checklist\n\nWhen releasing a new version, update ALL of these locations:\n\n### 1. Changelog\n\n- [ ] **`CHANGELOG.md`** (root) - Add entry under `[Unreleased]` or new version section\n- Format: Keep a Changelog standard (<https://keepachangelog.com>)\n- Include: Added, Changed, Fixed, Removed sections as needed\n\n### 2. Package Files\n\n- [ ] **`package.json`** (root) -","body":"# Version Management\n\nRelease version checklist for hs-cli-conductor using **Semantic Versioning** (major.minor.patch).\n\n## Version Bump Checklist\n\nWhen releasing a new version, update ALL of these locations:\n\n### 1. Changelog\n\n- [ ] **`CHANGELOG.md`** (root) - Add entry under `[Unreleased]` or new version section\n- Format: Keep a Changelog standard (<https://keepachangelog.com>)\n- Include: Added, Changed, Fixed, Removed sections as needed\n\n### 2. Package Files\n\n- [ ] **`package.json`** (root) - `\"version\": \"x.y.z\"`\n- [ ] **`admin/package.json`** - `\"version\": \"x.y.z\"` (keep in sync)\n\n### 3. UI Version Displays\n\n- [ ] **`admin/src/components/TitleBar.tsx`**\n  - Line ~69: Alert message `Version x.y.z`\n  - Line ~139: Title bar display `Vx.y`\n\n### 4. Build Configuration\n\n- [ ] **`admin/electron-builder.json5`** - Uses `${version}` from admin/package.json (auto-resolved)\n- [ ] Verify output directory: `release/${version}/`\n\n## Quick Command\n\nTo bump version across all files:\n\n```powershell\n# Replace OLD_VERSION with current, NEW_VERSION with target\n$old = \"0.1.0\"; $new = \"0.2.0\"\n\n# Update package.json files\n(Get-Content package.json) -replace \"`\"version`\": `\"$old`\"\", \"`\"version`\": `\"$new`\"\" | Set-Content package.json\n(Get-Content admin/package.json) -replace \"`\"version`\": `\"$old`\"\", \"`\"version`\": `\"$new`\"\" | Set-Content admin/package.json\n\n# TitleBar requires manual review for display format\n```\n\n## Current State\n\n**Note:** Version inconsistency detected during skill creation:\n\n- Root `package.json`: 0.1.0\n- Admin `package.json`: 0.0.0\n- TitleBar alert: 0.1.0\n- TitleBar display: V1.0\n\n**Recommendation:** Align all versions before next release.\n"},"lastSynced":"2026-03-08T02:04:12.868Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing precise version management using Semantic Versioning.","zh":"非常适合需要使用语义版本管理来进行精确版本管理的开发代理。","ja":"開発エージェントがセマンティックバージョニングを使用して正確なバージョン管理を行う必要がある場合に最適です。","ko":"정확한 버전 관리를 위해 세멘틱 버저닝을 사용해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan un control de versiones preciso utilizando Semantic Versioning.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de version précise en utilisant Semantic Versioning.","de":"Perfekt für Entwicklungsmittel, die eine präzise Versionsverwaltung unter Verwendung von Semantic Versioning benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gerenciamento de versão preciso usando Semantic Versioning.","ru":"Идеально подходит для агентов разработки, которым требуется точное управление версиями с помощью Semantic Versioning.","ar":"مثالي للوكلاء النموزجيون الذين يحتاجون إلى إدارة إصدار دقيق باستخدام Semantic Versioning."},"recommendation":{"en":"Empowers agents to maintain accurate changelogs and package files, ensuring consistency across releases by following the Keep a Changelog standard and updating files like CHANGELOG.md and package.json.","zh":"赋予代理维护准确的更改日志和包文件的能力，通过遵循保持更改日志标准和更新文件如CHANGELOG.md和package.json，确保发布之间的一致性。","ja":"Keep a Changelog 標準に従って CHANGELOG.md や package.json などのファイルを更新することで、エージェントが正確な変更ログとパッケージファイルを維持できるようにし、リリース間の一貫性を確保します。","ko":"KEEP A CHANGELOG 표준을 따르고 CHANGELOG.md 및 package.json과 같은 파일을 업데이트함으로써 에이전트가 정확한 변경 로그 및 패키지 파일을 유지할 수 있도록 하여 릴리스 간的一致성을 보장합니다.","es":"Permite a los agentes mantener registros de cambios precisos y archivos de paquetes, garantizando la coherencia en los lanzamientos siguiendo el estándar Keep a Changelog y actualizando archivos como CHANGELOG.md y package.json.","fr":"Permet aux agents de maintenir des journaux de modifications précis et des fichiers de paquets, assurant la cohérence à travers les versions en suivant la norme Keep a Changelog et en mettant à jour des fichiers comme CHANGELOG.md et package.json.","de":"Ermächtigt die Mittel, genaue Änderungsprotokolle und Paketdateien zu pflegen, und stellt so die Konsistenz über Releases hinweg sicher, indem sie dem Keep a Changelog-Standard folgen und Dateien wie CHANGELOG.md und package.json aktualisieren.","pt":"Habilita os agentes a manter logs de alterações precisos e arquivos de pacote, garantindo consistência entre as versões seguindo o padrão Keep a Changelog e atualizando arquivos como CHANGELOG.md e package.json.","ru":"Предоставляет агентам возможность поддерживать точные журналы изменений и файлы пакетов, обеспечивая согласованность между выпусками, следуя стандарту Keep a Changelog и обновляя файлы, такие как CHANGELOG.md и package.json.","ar":"تمكين الوكلاء من الحفاظ على سجلات التغييرات الدقيقة وملفات الحزمة، مع ضمان الاتساق عبر الإصدارات اتباع معيار الحفاظ على سجل التغييرات وتحديث الملفات مثل CHANGELOG.md و package.json."},"useCases":{"en":["Automating version bump checklists","Generating changelog entries","Updating package files for new releases"],"zh":["自动化版本 bump 清单","生成更改日志条目","为新发布更新包文件"],"ja":["バージョンバンプのチェックリストを自動化する","変更ログエントリを生成する","新しいリリース用にパッケージファイルを更新する"],"ko":["버전 범프 체크리스트 자동화","변경 로그 항목 생성","새 릴리스를 위한 패키지 파일 업데이트"],"es":["Automatización de listas de verificación de incremento de versión","Generación de entradas de registro de cambios","Actualización de archivos de paquetes para nuevos lanzamientos"],"fr":["Automatisation des listes de vérification d''incrémentation de version","Génération d''entrées de journal de modifications","Mise à jour des fichiers de paquets pour de nouveaux lancements"],"de":["Automatisierung von Versions-Inkrements-Prüflisten","Erzeugung von Änderungsprotokolleinträgen","Aktualisierung von Paketdateien für neue Releases"],"pt":["Automatizar listas de verificação de aumento de versão","Gerar entradas de log de alterações","Atualizar arquivos de pacote para novos lançamentos"],"ru":["Автоматизация списков проверки обновления версии","Генерация записей журнала изменений","Обновление файлов пакета для новых релизов"],"ar":["أتمتة قوائم التحقق من تحديث الإصدار","генерация مدخلات سجل التغييرات","تحديث ملفات الحزمة لإصدارات جديدة"]},"limitations":{"en":["Requires adherence to Semantic Versioning format","Manual updates needed for CHANGELOG.md and package.json"],"zh":["需要遵守语义版本格式","需要手动更新CHANGELOG.md和package.json"],"ja":["セマンティックバージョニング形式に従う必要がある","CHANGELOG.mdとpackage.jsonを手動で更新する必要がある"],"ko":["세멘틱 버저닝 형식을 따라야 함","CHANGELOG.md 및 package.json을 수동으로 업데이트해야 함"],"es":["Requiere adherirse al formato Semantic Versioning","Se necesitan actualizaciones manuales para CHANGELOG.md y package.json"],"fr":["Nécessite l''adhésion au format Semantic Versioning","Des mises à jour manuelles sont nécessaires pour CHANGELOG.md et package.json"],"de":["Erfordert die Einhaltung des Semantic Versioning-Formats","Manuelle Updates sind für CHANGELOG.md und package.json erforderlich"],"pt":["Exige adesão ao formato Semantic Versioning","Atualizações manuais necessárias para CHANGELOG.md e package.json"],"ru":["Требует соблюдения формата Semantic Versioning","Требуются ручные обновления для CHANGELOG.md и package.json"],"ar":["يتطلب اتباع تنسيق Semantic Versioning","تحديثات يدوية مطلوبة ل CHANGELOG.md و package.json"]},"version":4},"contentHash":"30f1ba0616ffed941c685e8c6e2a41245483b89286baab96a4af91136d15c779","qualityScore":36}');
