INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HemSoft/hs-conductor/version', 'version', 'HemSoft', 'hs-conductor', 'community', 'version HemSoft hs-conductor community The version skill helps developers manage releases using Semantic Versioning. It benefits developers by providing a checklist for updating changelogs and package files. 版本管理是软件开发中的关键步骤，本文介绍了Semantic Versioning的应用和版本发布检查清单 バージョン管理はソフトウェア開発の重要なステップです。この記事では、Semantic Versioningの適用とバージョンリリースチェックリストについて説明します 버전 관리는 소프트웨어 개발의 중요한 단계입니다. 본 문서에서는 Semantic Versioning의 적용과 버전 릴리즈 체크리스트에 대해 설명합니다 El agente de versión utiliza Semantic Versioning para gestionar versiones de hs-cli-conductor. Sigue el checklist de versión para actualizar CHANGELOG.md y package.json. L''agent de version utilise Semantic Versioning pour gérer les versions de hs-cli-conductor. Suivez la checklist de version pour mettre à jour CHANGELOG.md et package.json. Der Version-Agent verwendet Semantic Versioning, um Versionen von hs-cli-conductor zu verwalten. Befolgen Sie die Versions-Checkliste, um CHANGELOG.md und package.json zu aktualisieren. O gerenciamento de versões é crucial para o desenvolvimento de software. Aprenda a usar o Semantic Versioning com o hs-cli-conductor. Управление версиями имеет решающее значение для разработки программного обеспечения. Узнайте, как использовать Semantic Versioning с hs-cli-conductor. إدارة الإصدارات أمر بالغ الأهمية لتطوير البرمجيات. تعلم كيفية استخدام Semantic Versioning مع hs-cli-conductor. how to use semantic versioning version management best practices semantic versioning vs calendar versioning version setup guide what is semantic versioning version install for hs-cli-conductor version alternative to calendar versioning version management for AI agents 版本管理 Semantic Versioning 版本发布检查清单 软件开发 Keep a Changelog package.json CHANGELOG.md AIエージェント AI开发工具 Updates CHANGELOG.md file according to Keep a Changelog standard Modifies package.json file to reflect new version numbers Follows Semantic Versioning (major.minor.patch) for release management Includes Added, Changed, Fixed, Removed sections in changelog entries Supports release version checklist for hs-cli-conductor Version is a management system using Semantic Versioning to track changes in software releases, following a major.minor.patch format.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ryu-qqq/conventionHub/legacy-controller', 'community', 'ryu-qqq', 'conventionHub', 'ryu-qqq/conventionHub', 'legacy-controller', 0, 0, 36, '2026-03-08T01:57:15.363Z', '2026-03-08T02:04:18.162Z', 'd1f4d9f11435eef1a5739707b4502e0b8e97b52b28085c96684870808765e912', '{"id":"ryu-qqq/conventionHub/legacy-controller","name":"legacy-controller","description":{"en":"The legacy-controller skill generates Controller and ApiMapper for the last stage of the migration cycle, benefiting developers with streamlined API integration.","zh":"Legacy Controller 是一种 AI 工具，用于创建 Controller 和 ApiMapper，完成马伊格雷이션周期的最后一步","ja":"Legacy Controller は、API マッパーを作成し、マイグレーションサイクルを完了する AI エージェントです","ko":"Legacy Controller는 마이그레이션 사이클의 마지막 단계에서 Controller와 ApiMapper를 생성하는 AI 에이전트입니다","es":"Legacy-controller es una herramienta para crear controladores y mapeadores de API para aplicaciones legacy. Permite la integración con Request/Response DTO y capas de persistencia.","fr":"Legacy-controller est un outil pour créer des contrôleurs et des mapeurs d''API pour les applications legacy. Il permet l''intégration avec Request/Response DTO et les couches de persistance.","de":"Legacy-controller ist ein Tool zum Erstellen von Controllern und API-Mappern für Legacy-Anwendungen. Es ermöglicht die Integration mit Request/Response-DTO und Persistenzschichten.","pt":"O Legacy Controller é a última etapa do ciclo de migração, responsável por criar Controller e ApiMapper para a API","ru":"Legacy Controller - последний этап цикла миграции, отвечающий за создание Controller и ApiMapper для API с использованием ИИ Агентов","ar":"Legacy Controller هو المرحلة الأخيرة من دورة الهجرة، مسؤول عن إنشاء Controller و ApiMapper ل واجهة برمجة التطبيقات"},"seo":{"title":{"en":"legacy-controller: Setup Guide for AI Agents | AI Agent S...","zh":"Legacy Controller Setup Guide: 使用 AI 工具实现 API Mapper 创建","ja":"Legacy Controller を使用した API マッパーの作成方法","ko":"Legacy Controller 설정 가이드: 마이그레이션 사이클의 마지막 단계","es":"Guía de configuración de legacy-controller para API de ad...","fr":"Guide de mise en place de legacy-controller pour les API ...","de":"Einrichtungsleitfaden für legacy-controller für Admin-APIs","pt":"Guia de Configuração do Legacy Controller: Migração de API","ru":"Настройка Legacy Controller: ИИ Агенты для Миграции API","ar":"دليل إعداد Legacy Controller: هجرة واجهة برمجة التطبيقات"},"description":{"en":"Discover how to leverage legacy-controller for seamless API integration. Learn how to use the /legacy-controller command for Admin API and web API setup.","zh":"了解如何使用 Legacy Controller 创建 Controller 和 ApiMapper，完成马伊格雷이션周期的最后一步","ja":"Legacy Controller を使用して API マッパーを作成し、アプリケーションのマイグレーションサイクルを完了する","ko":"Legacy Controller를 사용하여 Controller와 ApiMapper를 생성하고 마이그레이션 사이클의 마지막 단계를 완료하는 방법","es":"Aprende a configurar legacy-controller para crear controladores y mapeadores de API para tu aplicación. Descubre cómo funciona con Request/Response DTO y cap...","fr":"Découvrez comment configurer legacy-controller pour créer des contrôleurs et des mapeurs d''API pour votre application. Comprenez comment cela fonctionne avec...","de":"Erfahren Sie, wie Sie legacy-controller konfigurieren, um Controller und API-Mapper für Ihre Anwendung zu erstellen. Erfahren Sie, wie es mit Request/Respons...","pt":"Aprenda a configurar o Legacy Controller para migração de API, incluindo a criação de Controller e ApiMapper","ru":"Узнайте, как настроить Legacy Controller для миграции API, включая создание Controller и ApiMapper с помощью ИИ Агентов","ar":"تعلم كيفية إعداد Legacy Controller لهجرة واجهة برمجة التطبيقات، بما في ذلك إنشاء Controller و ApiMapper"},"definition":{"en":"legacy-controller is a skill that creates Controller and ApiMapper for the final stage of the migration cycle, utilizing commands like /legacy-controller admin:BrandController.fetchBrands","zh":"Legacy Controller 是一种用于创建 Controller 和 ApiMapper 的 AI 工具","ja":"Legacy Controller は、API マッパーを作成する AI エージェントです","ko":"Legacy Controller는 Controller와 ApiMapper를 생성하는 AI 에이전트입니다","es":"Legacy-controller es un agente de AI que crea controladores y mapeadores de API para aplicaciones legacy.","fr":"Legacy-controller est un agent IA qui crée des contrôleurs et des mapeurs d''API pour les applications legacy.","de":"Legacy-controller ist ein KI-Agent, der Controller und API-Mapper für Legacy-Anwendungen erstellt.","pt":"Legacy Controller é um componente que cria Controller e ApiMapper para a API, facilitando a migração","ru":"Legacy Controller - компонент, создающий Controller и ApiMapper для API, облегчающий миграцию с помощью ИИ Агентов","ar":"Legacy Controller هو مكون يخلق Controller و ApiMapper ل واجهة برمجة التطبيقات، مما يسهل الهجرة"},"features":{"en":["Generates Controller and ApiMapper for the last stage of the migration cycle","Utilizes commands like /legacy-controller admin:BrandController.fetchBrands and /legacy-controller web:ProductController.fetchProductGroups","Requires completion of previous stages: /legacy-convert, /legacy-query, and /legacy-service","Produces output in the form of Admin API files, such as Legacy{Domain}QueryV1Controller.java","Supports setup for both Admin API and web API","Creates files in the adapter-in/rest-api-admin directory"],"zh":["支持创建 Controller 和 ApiMapper","实现马伊格雷이션周期的最后一步","需要完成 `/legacy-convert`、`/legacy-query` 和 `/legacy-service` 步骤","输出 Admin API 和 REST API","支持使用 CLI 命令进行操作","提供 Java 代码生成"],"ja":["Controller と ApiMapper の作成をサポート","マイグレーションサイクルの最後のステップを実現","/legacy-convert、/legacy-query、/legacy-service のステップを完了する必要がある","Admin API と REST API を出力","CLI コマンドによる操作をサポート","Java コードの生成を提供"],"ko":["Controller와 ApiMapper 생성 지원","마이그레이션 사이클의 마지막 단계 구현","/legacy-convert, /legacy-query, /legacy-service 단계 완료 필요","Admin API와 REST API 출력","CLI 명령어를 통한 운영 지원","Java 코드 생성 제공"],"es":["Crea controladores y mapeadores de API para aplicaciones legacy","Integración con Request/Response DTO","Compatibilidad con capas de persistencia","Soporte para API de administración","Generación de código para controladores y mapeadores de API"],"fr":["Crée des contrôleurs et des mapeurs d''API pour les applications legacy","Intégration avec Request/Response DTO","Compatibilité avec les couches de persistance","Prise en charge des API d''administration","Génération de code pour les contrôleurs et les mapeurs d''API"],"de":["Erstellt Controller und API-Mapper für Legacy-Anwendungen","Integration mit Request/Response-DTO","Kompatibilität mit Persistenzschichten","Unterstützung für Admin-APIs","Codegenerierung für Controller und API-Mapper"],"pt":["Criação de Controller e ApiMapper para a API","Integração com o ciclo de migração","Suporte à criação de API Admin","Utilização de tecnologias como Java e REST API","Facilita a migração de API legada","Melhora a eficiência da aplicação"],"ru":["Создание Controller и ApiMapper для API","Интеграция с циклом миграции","Поддержка создания API Admin","Использование технологий như Java и REST API","Облегчает миграцию API legacy с помощью ИИ Агентов","Повышает эффективность приложения"],"ar":["إنشاء Controller و ApiMapper ل واجهة برمجة التطبيقات","التكامل مع دورة الهجرة","دعم إنشاء واجهة برمجة التطبيقات Admin","استخدام تقنيات مثل Java و REST API","تسهيل هجرة واجهة برمجة التطبيقات القديمة","تحسين كفاءة التطبيق"]},"keywords":{"en":["how to use legacy-controller","legacy-controller setup guide","what is legacy-controller","legacy-controller alternative","legacy-controller vs API mapper","legacy-controller install","legacy-controller tutorial","legacy-controller for AI agents","legacy-controller API integration"],"zh":["Legacy Controller","AI 工具","API Mapper","马伊格雷이션周期","Java 开发","CLI 命令","REST API","Admin API","代码生成"],"ja":["Legacy Controller","AI エージェント","API マッパー","マイグレーションサイクル","Java 開発","CLI コマンド","REST API","Admin API","コード生成"],"ko":["Legacy Controller","AI 에이전트","API Mapper","마이그레이션 사이클","Java 개발","CLI 명령어","REST API","Admin API","코드 생성"],"es":["legacy-controller","API de administración","Request/Response DTO","capas de persistencia","agentes de AI","herramientas de desarrollo","integración de API","controladores de API","mapeadores de API"],"fr":["legacy-controller","API d''administration","Request/Response DTO","couches de persistance","agents IA","outils de développement","intégration d''API","contrôleurs d''API","mapeurs d''API"],"de":["legacy-controller","Admin-API","Request/Response-DTO","Persistenzschichten","KI-Agenten","Entwicklungstools","API-Integration","API-Controller","API-Mapper"],"pt":["Legacy Controller","Migração de API","Criação de Controller","ApiMapper","Java","REST API","API Admin","H Ferramentas de desenvolvimento","Desenvolvimento de software","Tecnologias de informação"],"ru":["Legacy Controller","Миграция API","Создание Controller","ApiMapper","Java","REST API","API Admin","ИИ Агенты","Инструменты разработки","Разработка программного обеспечения","Технологии информации"],"ar":["Legacy Controller","هجرة واجهة برمجة التطبيقات","إنشاء Controller","ApiMapper","Java","REST API","واجهة برمجة التطبيقات Admin","أدوات التطوير","تطوير البرمجيات","تقنيات المعلومات","هندسة البرمجيات"]}},"owner":"ryu-qqq","repo":"conventionHub","repoPath":"ryu-qqq/conventionHub","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.363Z","topics":[],"category":"community","skillMd":{"name":"legacy-controller","description":"마이그레이션 사이클의 마지막 단계. Controller + ApiMapper 생성하여 전체 흐름 완성.","bodyPreview":"# /legacy-controller\n\n마이그레이션 사이클의 **마지막 단계**. Controller + ApiMapper를 생성합니다.\n\n## 사용법\n\n```bash\n/legacy-controller admin:BrandController.fetchBrands\n/legacy-controller web:ProductController.fetchProductGroups\n```\n\n## 전제조건\n\n이전 단계들이 완료되어 있어야 함:\n1. `/legacy-convert` - Request/Response DTO\n2. `/legacy-query` - Persistence Layer\n3. `/legacy-service` - Application Layer\n\n## 출력\n\n**Admin API:**\n```\nadapter-in/rest-api-admin/.../admin/v1/{domain}/\n├── controller/Legacy{Domain}QueryV1Controller.java\n└── map","body":"# /legacy-controller\n\n마이그레이션 사이클의 **마지막 단계**. Controller + ApiMapper를 생성합니다.\n\n## 사용법\n\n```bash\n/legacy-controller admin:BrandController.fetchBrands\n/legacy-controller web:ProductController.fetchProductGroups\n```\n\n## 전제조건\n\n이전 단계들이 완료되어 있어야 함:\n1. `/legacy-convert` - Request/Response DTO\n2. `/legacy-query` - Persistence Layer\n3. `/legacy-service` - Application Layer\n\n## 출력\n\n**Admin API:**\n```\nadapter-in/rest-api-admin/.../admin/v1/{domain}/\n├── controller/Legacy{Domain}QueryV1Controller.java\n└── mapper/Legacy{Domain}V1ApiMapper.java\n```\n\n**Web API:**\n```\nadapter-in/rest-api/.../v1/{domain}/\n├── controller/Legacy{Domain}QueryV1Controller.java\n└── mapper/Legacy{Domain}V1ApiMapper.java\n```\n\n## 생성 컴포넌트\n\n| 컴포넌트 | 역할 |\n|---------|------|\n| **Controller** | REST 엔드포인트, UseCase 호출 |\n| **ApiMapper** | Request→Command, Result→Response 변환 |\n\n## 마이그레이션 완료\n\n이 단계 완료 시 하나의 엔드포인트에 대한 전체 마이그레이션이 완료됩니다.\n"},"lastSynced":"2026-03-08T02:04:18.162Z","agentAnalysis":{"suitability":{"en":"Perfect for API Integration Agents needing streamlined Controller and ApiMapper generation for legacy system migration.","zh":"适用于需要简化控制器和ApiMapper生成以迁移遗留系统的API集成代理。","ja":"API統合エージェントがレガシーシステムの移行のためにストリームライン化されたコントローラーとApiMapperの生成を必要とする場合に適しています。","ko":"레거시 시스템 마이그레이션을 위해 스트림 라인화 된 컨트롤러 및 ApiMapper 생성이 필요한 API 통합 에이전트에 적합합니다.","es":"Perfecto para Agentes de Integración de API que necesitan una generación de Controlador y ApiMapper optimizada para la migración de sistemas heredados.","fr":"Parfait pour les Agents d''Intégration d''API nécessitant une génération de Contrôleur et d''ApiMapper rationalisée pour la migration de systèmes hérités.","de":"Perfekt für API-Integration-Agenten, die eine optimierte Controller- und ApiMapper-Generierung für die Migration von Legacy-Systemen benötigen.","pt":"Perfeito para Agentes de Integração de API que necessitam de geração de Controlador e ApiMapper simplificada para migração de sistemas legados.","ru":"Идеально подходит для агентов интеграции API, которым требуется упрощенная генерация контроллера и ApiMapper для миграции устаревших систем.","ar":"مثالي للوكلاء الذين يحتاجون إلى توليد مراقب و ApiMapper简化 للهجرة لنظام موروث"},"recommendation":{"en":"Empowers agents to generate Controller and ApiMapper for the last stage of the migration cycle, providing seamless API integration with Admin API and web endpoints, utilizing protocols like REST and handling file formats within adapter-in/rest-api-admin directories.","zh":"赋予代理生成控制器和ApiMapper的能力，以完成迁移周期的最后阶段，提供与Admin API和Web端点的无缝API集成，利用REST等协议，并在适配器-in/rest-api-admin目录中处理文件格式。","ja":"エージェントがコントローラーとApiMapperを生成する能力を付与し、移行サイクルの最後のステージを完了し、Admin APIとWebエンドポイントのシームレスなAPI統合を提供し、RESTなどのプロトコルを利用し、adapter-in/rest-api-adminディレクトリ内でファイル形式を処理します。","ko":"에이전트가 컨트롤러와 ApiMapper를 생성하여 마이그레이션 사이클의 마지막 단계를 완료하고 Admin API 및 웹 엔드 포인트와의無段계 API 통합을 제공하며 REST 등의 프로토콜을 활용하고 어댑터 -in/rest-api-admin 디렉토리 내에서 파일 형식을 처리합니다.","es":"Habilita a los agentes a generar Controlador y ApiMapper para la última etapa del ciclo de migración, proporcionando una integración de API sin problemas con Admin API y puntos finales web, utilizando protocolos como REST y manejando formatos de archivo dentro de los directorios adapter-in/rest-api-admin.","fr":"Permet aux agents de générer un Contrôleur et un ApiMapper pour la dernière étape du cycle de migration, fournissant une intégration d''API transparente avec Admin API et points de terminaison web, en utilisant des protocoles tels que REST et en gérant les formats de fichiers au sein des répertoires adapter-in/rest-api-admin.","de":"Ermächtigt Agenten, Controller und ApiMapper für die letzte Phase des Migrationszyklus zu generieren, indem eine nahtlose API-Integration mit Admin API und Web-Endpunkten bereitgestellt wird, wobei Protokolle wie REST verwendet und Dateiformate innerhalb der Verzeichnisse adapter-in/rest-api-admin gehandhabt werden.","pt":"Habilita agentes a gerar Controlador e ApiMapper para a última etapa do ciclo de migração, fornecendo integração de API sem problemas com Admin API e pontos de extremidade da web, utilizando protocolos como REST e manipulando formatos de arquivo dentro dos diretórios adapter-in/rest-api-admin.","ru":"Наделяет агентов возможностью генерировать контроллер и ApiMapper на последней стадии цикла миграции, обеспечивая бесперебойную интеграцию API с Admin API и веб-конечными точками, используя протоколы типа REST и обрабатывая форматы файлов в директориях adapter-in/rest-api-admin.","ar":"تمكين الوكلاء من توليد مراقب و ApiMapper للstage الأخير من دورة الهجرة، وتوفير تكامل API بدون مشاكل مع Admin API ونقاط النهاية على الويب، واستخدام بروتوكولات مثل REST ومعالجة صيغ الملفات داخل المجلدات adapter-in/rest-api-admin"},"useCases":{"en":["Automating legacy system migration with Controller and ApiMapper generation","Streamlining API integration for Admin API and web endpoints","Simplifying migration cycle completion with generated Controller and ApiMapper"],"zh":["使用控制器和ApiMapper生成自动化遗留系统迁移","简化Admin API和Web端点的API集成","使用生成的控制器和ApiMapper简化迁移周期的完成"],"ja":["コントローラーとApiMapperの生成を使用したレガシーシステムの移行の自動化","Admin APIとWebエンドポイントのAPI統合のストリームライン化","生成されたコントローラーとApiMapperを使用した移行サイクルの完了の簡素化"],"ko":["컨트롤러 및 ApiMapper 생성을 사용한 레거시 시스템 마이그레이션 자동화","Admin API 및 웹 엔드 포인트의 API 통합을 위한 스트림 라인화","생성 된 컨트롤러 및 ApiMapper를 사용한 마이그레이션 사이클 완성의 단순화"],"es":["Automatización de la migración de sistemas heredados con generación de Controlador y ApiMapper","Optimización de la integración de API para Admin API y puntos finales web","Simplificación de la finalización del ciclo de migración con Controlador y ApiMapper generados"],"fr":["Automatisation de la migration de systèmes hérités avec génération de Contrôleur et d''ApiMapper","Optimisation de l''intégration d''API pour Admin API et points de terminaison web","Simplification de l''achèvement du cycle de migration avec Contrôleur et ApiMapper générés"],"de":["Automatisierung der Migration von Legacy-Systemen mit Controller- und ApiMapper-Generierung","Optimierung der API-Integration für Admin API und Web-Endpunkte","Vereinfachung der Vervollständigung des Migrationszyklus mit generierten Controller und ApiMapper"],"pt":["Automatizar a migração de sistemas legados com geração de Controlador e ApiMapper","Simplificar a integração de API para Admin API e pontos de extremidade da web","Simplificar a conclusão do ciclo de migração com Controlador e ApiMapper gerados"],"ru":["Автоматизировать миграцию устаревших систем с помощью генерации контроллера и ApiMapper","Упростить интеграцию API для Admin API и веб-конечных точек","Упростить завершение цикла миграции с помощью сгенерированных контроллера и ApiMapper"],"ar":["أتمتة هجرة الأنظمة الموروثة بتوليد مراقب و ApiMapper","تبسيط تكامل API لنقاط النهاية على الويب والـ Admin API","تبسيط إكمال دورة الهجرة بالمراقب و ApiMapper المولد"]},"limitations":{"en":["Requires completion of previous migration stages (/legacy-convert, /legacy-query, /legacy-service)","Specific to legacy system migration context"],"zh":["需要完成之前的迁移阶段(/legacy-convert, /legacy-query, /legacy-service)","特定于遗留系统迁移的上下文"],"ja":["以前の移行ステージの完了が必要(/legacy-convert, /legacy-query, /legacy-service)","レガシーシステムの移行のコンテキストに特有"],"ko":["이전 마이그레이션 단계의 완료가 필요(/legacy-convert, /legacy-query, /legacy-service)","레거시 시스템 마이그레이션의 컨텍스트에 특정"],"es":["Requiere la finalización de las etapas de migración anteriores (/legacy-convert, /legacy-query, /legacy-service)","Específico del contexto de migración de sistemas heredados"],"fr":["Nécessite l''achèvement des étapes de migration précédentes (/legacy-convert, /legacy-query, /legacy-service)","Spécifique au contexte de migration de systèmes hérités"],"de":["Erfordert den Abschluss der vorherigen Migrationsphasen (/legacy-convert, /legacy-query, /legacy-service)","Spezifisch für den Kontext der Migration von Legacy-Systemen"],"pt":["Requer a conclusão das etapas de migração anteriores (/legacy-convert, /legacy-query, /legacy-service)","Específico para o contexto de migração de sistemas legados"],"ru":["Требует завершения предыдущих стадий миграции (/legacy-convert, /legacy-query, /legacy-service)","Специфичен для контекста миграции устаревших систем"],"ar":["يتطلب إكمال مراحل الهجرة السابقة (/legacy-convert, /legacy-query, /legacy-service)","محدد لسياق هجرة الأنظمة الموروثة"]},"version":4},"contentHash":"d1f4d9f11435eef1a5739707b4502e0b8e97b52b28085c96684870808765e912","qualityScore":36}');
