INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryu-qqq/conventionHub/legacy-controller', 'legacy-controller', 'ryu-qqq', 'conventionHub', 'community', 'legacy-controller ryu-qqq conventionHub community The legacy-controller skill generates Controller and ApiMapper for the last stage of the migration cycle, benefiting developers with streamlined API integration. Legacy Controller 是一种 AI 工具，用于创建 Controller 和 ApiMapper，完成马伊格雷이션周期的最后一步 Legacy Controller は、API マッパーを作成し、マイグレーションサイクルを完了する AI エージェントです Legacy Controller는 마이그레이션 사이클의 마지막 단계에서 Controller와 ApiMapper를 생성하는 AI 에이전트입니다 Legacy-controller es una herramienta para crear controladores y mapeadores de API para aplicaciones legacy. Permite la integración con Request/Response DTO y capas de persistencia. Legacy-controller est un outil pour créer des contrôleurs et des mapeurs d''API pour les applications legacy. Il permet l''intégration avec Request/Response DTO et les couches de persistance. Legacy-controller ist ein Tool zum Erstellen von Controllern und API-Mappern für Legacy-Anwendungen. Es ermöglicht die Integration mit Request/Response-DTO und Persistenzschichten. O Legacy Controller é a última etapa do ciclo de migração, responsável por criar Controller e ApiMapper para a API Legacy Controller - последний этап цикла миграции, отвечающий за создание Controller и ApiMapper для API с использованием ИИ Агентов Legacy Controller هو المرحلة الأخيرة من دورة الهجرة، مسؤول عن إنشاء Controller و ApiMapper ل واجهة برمجة التطبيقات how to use legacy-controller legacy-controller setup guide what is legacy-controller legacy-controller alternative legacy-controller vs API mapper legacy-controller install legacy-controller tutorial legacy-controller for AI agents legacy-controller API integration Legacy Controller AI 工具 API Mapper 马伊格雷이션周期 Java 开发 CLI 命令 REST API Admin API 代码生成 Generates Controller and ApiMapper for the last stage of the migration cycle Utilizes commands like /legacy-controller admin:BrandController.fetchBrands and /legacy-controller web:ProductController.fetchProductGroups Requires completion of previous stages: /legacy-convert, /legacy-query, and /legacy-service Produces output in the form of Admin API files, such as Legacy{Domain}QueryV1Controller.java Supports setup for both Admin API and web API Creates files in the adapter-in/rest-api-admin directory legacy-controller is a skill that creates Controller and ApiMapper for the final stage of the migration cycle, utilizing commands like /legacy-controller admin:BrandController.fetchBrands');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aviz85/ai-music-video-maker/video-common', 'community', 'aviz85', 'ai-music-video-maker', 'aviz85/ai-music-video-maker', 'video-common', 0, 0, 36, '2026-03-08T01:57:15.363Z', '2026-03-08T02:04:18.198Z', '507719083fb590b1d9b6135e65b41c6585350fa7a26d8c61bfd6c1bc9785b6d7', '{"id":"aviz85/ai-music-video-maker/video-common","name":"video-common","description":{"en":"The video-common skill provides shared utilities for video skills, enabling developers to create complex video compositions and render output efficiently. It benefits developers working with video skills in this project.","zh":"Remotion Common Utilities提供共享的模式和引用，用于所有视频技能的开发","ja":"Remotion Common Utilitiesは、すべてのビデオスキルの開発に共有されるパターンと参照を提供します","ko":"Remotion Common Utilities는 모든 비디오 스킬 개발에 공유되는 패턴과 참조를 제공합니다","es":"Video-common es un conjunto de utilidades compartidas para Remotion, que facilita el desarrollo de composiciones de video. Ofrece un proyecto estructurado con src, public y out","fr":"Video-common est un ensemble d''utilitaires partagés pour Remotion, qui facilite le développement de compositions de vidéo. Il propose un projet structuré avec src, public et out","de":"Video-common ist eine Sammlung von gemeinsamen Utilitys für Remotion, die die Entwicklung von Video-Kompositionen erleichtert. Es bietet ein strukturiertes Projekt mit src, public und out","pt":"O Video-Common é um conjunto de utilitários compartilhados para skills de vídeo, fornecendo estrutura de projeto e APIs importantes para desenvolvedores","ru":"Video-Common - это набор общих утилит для навыков видео, обеспечивающий структуру проекта и важные API для разработчиков","ar":"الفيديو المشترك هو مجموعة من الأدوات المشتركة لمهارات الفيديو، يوفر هيكلاً لمشروع وواجهات برمجة تطبيقات مهمة لمطوري التطبيقات"},"seo":{"title":{"en":"video-common: Shared Utilities Setup Guide | AI Agent Skill","zh":"视频公共库Setup Guide - Remotion Common Utilities","ja":"ビデオ共通ライブラリのベストプラクティス - Remotion Common Utilities","ko":"비디오 공통 라이브러리 설정 가이드 - Remotion Common Utilities","es":"Guía de configuración de video-common: Utilidades compart...","fr":"Guide de démarrage de video-common: Utilitaires partagés ...","de":"Einrichtungsleitfaden für video-common: Gemeinsame Utilit...","pt":"Guia de Configuração do Video-Common: Utilitários Compart...","ru":"ИИ Агенты: Настройка Video-Common для Разработчиков","ar":"دليل إعداد الفيديو المشترك: أدوات مشتركة لمطوري التطبيقات"},"description":{"en":"Unlock the full potential of video skills with video-common. Discover how to leverage shared patterns and references for seamless video composition and rende...","zh":"了解Remotion Common Utilities的项目结构和关键API，提高视频开发效率","ja":"Remotion Common Utilitiesのプロジェクト構造と主要APIをマスターし、ビデオ開発を効率化する","ko":"Remotion Common Utilities의 프로젝트 구조와 주요 API를 익히고 비디오 개발 효율성을 향상시킵니다","es":"Aprende a configurar video-common con nuestras utilidades compartidas para Remotion. Mejora tus habilidades de desarrollo con nuestras guías","fr":"Découvrez comment configurer video-common avec nos utilitaires partagés pour Remotion. Améliorez vos compétences de développement avec nos guides","de":"Erfahren Sie, wie Sie video-common mit unseren gemeinsamen Utilitys für Remotion einrichten. Verbessern Sie Ihre Entwicklerfähigkeiten mit unseren Anleitungen","pt":"Aprenda a configurar o Video-Common, um conjunto de utilitários compartilhados para skills de vídeo, e melhore sua produtividade como desenvolvedor","ru":"Узнайте, как настроить Video-Common, набор общих утилит для навыков видео, и повысьте свою производительность как разработчика","ar":"تعلم كيفية إعداد الفيديو المشترك، مجموعة من الأدوات المشتركة لمهارات الفيديو، وزيادة إنتاجيتك كمطور"},"definition":{"en":"video-common is a collection of shared patterns and references for all video skills in a project, facilitating efficient video composition and rendering.","zh":"Remotion Common Utilities是一套为视频技能提供共享模式和引用的工具集","ja":"Remotion Common Utilitiesは、ビデオスキルに共有されるパターンと参照を提供するツールセットです","ko":"Remotion Common Utilities는 비디오 스킬에 공유되는 패턴과 참조를 제공하는 도구 세트입니다","es":"Video-common es un conjunto de patrones y referencias compartidas para habilidades de video en Remotion","fr":"Video-common est un ensemble de modèles et de références partagés pour les compétences de vidéo dans Remotion","de":"Video-common ist eine Sammlung von gemeinsamen Mustern und Referenzen für Video-Fähigkeiten in Remotion","pt":"O que é Video-Common? Um conjunto de utilitários compartilhados para skills de vídeo, facilitando o desenvolvimento de aplicações de vídeo","ru":"Что такое Video-Common? Набор общих утилит для навыков видео, упрощающий разработку видео-приложений","ar":"ما هو الفيديو المشترك؟ مجموعة من الأدوات المشتركة لمهارات الفيديو، تسهل تطوير تطبيقات الفيديو"},"features":{"en":["Provides a project structure with src, public, and out directories for organized video development","Includes a composition registry via Root.tsx for managing video compositions","Supports reusable components via the components directory","Utilizes the use API for shared functionality across video skills","Renders output in the out directory for easy access to final video products"],"zh":["Remotion项目结构","use API","组合注册","可重用组件","静态资产管理","渲染输出"],"ja":["Remotionプロジェクト構造","use API","コンポジション登録","再利用可能なコンポーネント","静的アセット管理","レンダリング出力"],"ko":["Remotion 프로젝트 구조","use API","컴포지션 등록","재사용 가능한 컴포넌트","정적 자산 관리","렌더링 출력"],"es":["Estructura de proyecto con src, public y out","Utilidades compartidas para composiciones de video","Compatibilidad con TypeScript","Uso de la API use","Soporte para assets estáticos como fuentes, imágenes y audio","Renderizado de salida en la carpeta out"],"fr":["Structure de projet avec src, public et out","Utilitaires partagés pour les compositions de vidéo","Compatibilité avec TypeScript","Utilisation de l''API use","Prise en charge des assets statiques tels que les polices, les images et les audio","Renderisation de la sortie dans le dossier out"],"de":["Projektstruktur mit src, public und out","Gemeinsame Utilitys für Video-Kompositionen","Kompatibilität mit TypeScript","Verwendung der API use","Unterstützung für statische Assets wie Schriftarten, Bilder und Audio","Renderung der Ausgabe im Ordner out"],"pt":["Estrutura de projeto personalizada com src, public e out","APIs importantes como use","Composições de vídeo personalizadas","Componentes reutilizáveis","Suporte a assets estáticos como fontes, imagens e áudio"],"ru":["Пользовательская структура проекта с src, public и out","Важные API, такие как use","Пользовательские видео-композиции","Переиспользуемые компоненты","Поддержка статических активов, таких как шрифты, изображения и аудио"],"ar":["هيكل مشروع مخصص مع src و public و out","واجهات برمجة تطبيقات مهمة مثل use","تركيبات فيديو مخصصة","مكونات قابلة لإعادة الاستخدام","دعم الملفات الثابتة مثل الخطوط والصور والصوت"]},"keywords":{"en":["how to use video-common","video-common setup guide","video-common alternative","video-common vs Remotion","video-common install","what is video-common","video-common project structure","video-common composition registry"],"zh":["Remotion Common Utilities","视频开发","共享模式","引用","use API","Remotion项目结构","视频技能开发"],"ja":["Remotion Common Utilities","ビデオ開発","共有パターン","参照","use API","Remotionプロジェクト構造","ビデオスキル開発"],"ko":["Remotion Common Utilities","비디오 개발","공유 패턴","참조","use API","Remotion 프로젝트 구조","비디오 스킬 개발"],"es":["video-common","Remotion","desarrollo de video","utilidades compartidas","TypeScript","API use","assets estáticos","renderizado de video","Herramientas de AI","Agentes de IA"],"fr":["video-common","Remotion","développement de vidéo","utilitaires partagés","TypeScript","API use","assets statiques","renderisation de vidéo","Outils d''IA","Agents d''IA"],"de":["video-common","Remotion","Video-Entwicklung","gemeinsame Utilitys","TypeScript","API use","statische Assets","Video-Renderung","AI-Tools","KI-Agenten"],"pt":["Video-Common","utilitários compartilhados","skills de vídeo","desenvolvimento de aplicações de vídeo","estrutura de projeto","APIs importantes","composições de vídeo","componentes reutilizáveis","assets estáticos"],"ru":["Video-Common","общие утилиты","навыки видео","разработка видео-приложений","структура проекта","важные API","видео-композиции","переиспользуемые компоненты","статические активы"],"ar":["الفيديو المشترك","أدوات مشتركة","مهارات الفيديو","تطوير تطبيقات الفيديو","هيكل مشروع","واجهات برمجة تطبيقات مهمة","تركيبات فيديو","مكونات قابلة لإعادة الاستخدام","الملفات الثابتة"]}},"owner":"aviz85","repo":"ai-music-video-maker","repoPath":"aviz85/ai-music-video-maker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.363Z","topics":[],"category":"community","skillMd":{"name":"video-common","description":"Shared Remotion video utilities and patterns. Referenced by other video skills - not invoked directly.","bodyPreview":"# Remotion Common Utilities\n\nShared patterns and references for all video skills in this project.\n\n## Project Structure\n\n```\nremotion-assistant/\n├── src/\n│   ├── index.tsx          # Entry point\n│   ├── Root.tsx           # Composition registry\n│   ├── compositions/      # Video compositions\n│   └── components/        # Reusable components\n├── public/                # Static assets\n│   ├── fonts/\n│   ├── images/\n│   └── audio/\n└── out/                   # Rendered output\n```\n\n## Key APIs\n\n- `use","body":"# Remotion Common Utilities\n\nShared patterns and references for all video skills in this project.\n\n## Project Structure\n\n```\nremotion-assistant/\n├── src/\n│   ├── index.tsx          # Entry point\n│   ├── Root.tsx           # Composition registry\n│   ├── compositions/      # Video compositions\n│   └── components/        # Reusable components\n├── public/                # Static assets\n│   ├── fonts/\n│   ├── images/\n│   └── audio/\n└── out/                   # Rendered output\n```\n\n## Key APIs\n\n- `useCurrentFrame()` - Current frame number\n- `useVideoConfig()` - { width, height, fps, durationInFrames }\n- `interpolate(frame, [in], [out])` - Map values\n- `spring({ frame, fps, config })` - Physics animations\n\n## Adding New Compositions\n\n1. Create component in `src/compositions/`\n2. Register in `src/Root.tsx` with `<Composition>`\n3. Set: id, component, durationInFrames, fps, width, height\n\n## See References\n\n- [codecs.md](references/codecs.md) - Encoding options\n- [animations.md](references/animations.md) - Animation patterns\n"},"lastSynced":"2026-03-08T02:04:18.198Z","agentAnalysis":{"suitability":{"en":"Perfect for Media Processing Agents needing efficient video composition and rendering capabilities.","zh":"非常适合需要高效视频组合和渲染能力的媒体处理代理。","ja":"メディア処理エージェントが効率的なビデオ構成とレンダリング機能を必要とする場合に最適です。","ko":"효율적인 비디오 구성 및 렌더링 기능이 필요한 미디어 처리 에이전트에 적합합니다.","es":"Perfecto para Agentes de Procesamiento de Medios que necesitan capacidades de composición y renderizado de video eficientes.","fr":"Parfait pour les agents de traitement des médias nécessitant des capacités de composition et de rendu vidéo efficaces.","de":"Perfekt für Media-Processing-Agents, die effiziente Videozusammensetzung- und Renderfunktionen benötigen.","pt":"Perfeito para Agentes de Processamento de Mídia que necessitam de capacidades de composição e renderização de vídeo eficientes.","ru":"Идеально подходит для агентов обработки медиа, которым необходимы эффективные возможности композиции и рендеринга видео.","ar":"مثالي للوكلاء معالجة الوسائط التي تحتاج إلى مهارات التركيب والتحويل الفيديوي الفعال"},"recommendation":{"en":"Empowers agents to create complex video compositions using shared utilities and render output efficiently with Remotion Common Utilities, leveraging TypeScript and React components like index.tsx and Root.tsx.","zh":"赋予代理创建复杂视频组合的能力，使用共享工具和Remotion Common Utilities，利用TypeScript和React组件（如index.tsx和Root.tsx）高效渲染输出。","ja":"エージェントが共有ユーティリティとRemotion Common Utilitiesを使用して複雑なビデオ構成を作成し、TypeScriptとReactコンポーネント（例：index.tsxとRoot.tsx）を使用して効率的に出力することを可能にします。","ko":"에이전트가 공유 유틸리티와 Remotion Common Utilities를 사용하여 복잡한 비디오 구성を作成하고, TypeScript와 React 컴포넌트(예: index.tsx와 Root.tsx)를 사용하여 효율적으로 출력을 렌더링할 수 있도록 합니다.","es":"Habilita a los agentes a crear composiciones de video complejas utilizando utilidades compartidas y renderizar la salida de forma eficiente con Remotion Common Utilities, aprovechando TypeScript y componentes React como index.tsx y Root.tsx.","fr":"Permet aux agents de créer des compositions vidéo complexes en utilisant des utilitaires partagés et de rendre la sortie de manière efficace avec Remotion Common Utilities, en exploitant TypeScript et des composants React tels que index.tsx et Root.tsx.","de":"Ermächtigt Agenten, komplexe Videozusammensetzungen mit Hilfe von gemeinsam genutzten Utilities und einer effizienten Ausgabe mit Remotion Common Utilities zu erstellen, wobei TypeScript und React-Komponenten wie index.tsx und Root.tsx genutzt werden.","pt":"Habilita os agentes a criarem composições de vídeo complexas usando utilitários compartilhados e renderizar a saída de forma eficiente com Remotion Common Utilities, aproveitando TypeScript e componentes React como index.tsx e Root.tsx.","ru":"Наделяет агентов возможностью создавать сложные видеокомпозиции с помощью общих утилит и эффективно рендерить вывод с помощью Remotion Common Utilities, используя TypeScript и компоненты React, такие как index.tsx и Root.tsx.","ar":"تمكين الوكلاء من إنشاء تركيبات فيديو معقدة باستخدام الأدوات المساعدة المشتركة وتصيير الإخراج بفعالية مع Remotion Common Utilities، واستخدام TypeScript ومكونات React مثل index.tsx و Root.tsx."},"useCases":{"en":["Composing multiple video elements into a single output","Rendering video compositions with customized fonts and audio","Debugging video rendering issues with out/ directory output"],"zh":["将多个视频元素组合成单个输出","使用自定义字体和音频渲染视频组合","使用out/目录输出调试视频渲染问题"],"ja":["複数のビデオ要素を1つの出力に組み合わせる","カスタマイズされたフォントとオーディオを使用してビデオ構成をレンダリングする","out/ディレクトリの出力を使用してビデオレンダリングの問題をデバッグする"],"ko":["여러개의 비디오 요소를 하나의 출력으로 결합하는 것","사용자 지정 글꼴과 오디오를 사용하여 비디오 구성 렌더링","out/ 디렉토리 출력을 사용하여 비디오 렌더링 문제를 디버깅하는 것"],"es":["Componer varios elementos de video en una sola salida","Renderizar composiciones de video con fuentes y audio personalizados","Depurar problemas de renderizado de video con salida de directorio out/"],"fr":["Composer plusieurs éléments vidéo en une seule sortie","Rendre des compositions vidéo avec des polices et des audio personnalisés","Déboguer les problèmes de rendu vidéo avec une sortie de répertoire out/"],"de":["Mehrere Videoelemente in einer einzigen Ausgabe zusammensetzen","Videozusammensetzungen mit benutzerdefinierten Schriftarten und Audio rendern","Video-Renderprobleme mit Ausgabe im Verzeichnis out/ debuggen"],"pt":["Compor vários elementos de vídeo em uma saída única","Renderizar composições de vídeo com fontes e áudio personalizados","Depurar problemas de renderização de vídeo com saída do diretório out/"],"ru":["Составление нескольких видеоэлементов в один вывод","Рендеринг видеокомпозиций с настраиваемыми шрифтами и аудио","Отладка проблем рендеринга видео с выводом каталога out/"],"ar":["تركيب عدة عناصر فيديو في إخراج واحد","تصيير تركيبات فيديو مع خطوط وأudio مخصصة","تصحيح أخطاء تحويل الفيديو مع إخراج دليل out/"]},"limitations":{"en":["Requires Remotion project structure","Limited to video skills within the project"],"zh":["需要Remotion项目结构","仅限于项目内的视频技能"],"ja":["Remotionプロジェクト構造が必要","プロジェクト内のビデオスキルにのみ限定"],"ko":["Remotion 프로젝트 구조가 필요","프로젝트 내의 비디오 스킬에만 제한"],"es":["Requiere la estructura de proyecto Remotion","Limitado a habilidades de video dentro del proyecto"],"fr":["Nécessite la structure de projet Remotion","Limité aux compétences vidéo au sein du projet"],"de":["Benötigt die Remotion-Projektstruktur","Begrenzt auf Videoskills innerhalb des Projekts"],"pt":["Requer estrutura de projeto Remotion","Limitado a habilidades de vídeo dentro do projeto"],"ru":["Требует структуры проекта Remotion","Ограничен навыками видео внутри проекта"],"ar":["يتطلب هيكل مشروع Remotion","محدود بمهارات الفيديو داخل المشروع"]},"version":4},"contentHash":"507719083fb590b1d9b6135e65b41c6585350fa7a26d8c61bfd6c1bc9785b6d7","qualityScore":36}');
