INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jhb-software/payload-astro-website-template/intl', 'intl', 'jhb-software', 'payload-astro-website-template', 'community', 'intl jhb-software payload-astro-website-template community The intl skill enables developers to build multi-language websites with Astro and Payload CMS, featuring localized fields, translatable text, and global labels management. intl 是一个用于构建多语言网站的全功能模板，支持 Payload CMS 和 Astro intl は、マルチ言語サイトを構築するための完全な機能を持つテンプレートで、Payload CMS と Astro をサポート intl은 다국어 웹사이트를 구축하기 위한 완전한 기능을 갖춘 템플릿으로 Payload CMS와 Astro를 지원 Plantilla completa para sitios web de contenido con Payload CMS y Astro, con enfoque en internacionalización y escalabilidad Modèle complet pour les sites web de contenu avec Payload CMS et Astro, axé sur l''internationalisation et l''évolutivité Vollständiges Template für Inhalts-Websites mit Payload CMS und Astro, mit Fokus auf Internationalisierung und Skalierbarkeit O Intl é um modelo completo para construir sites de conteúdo performáticos e escaláveis com Payload CMS e Astro. Intl - это полнофункциональный шаблон для создания производительных и масштабируемых сайтов с Payload CMS и Astro. Intl هو نموذج كامل لإنشاء مواقع ويب ذات أداء عالٍ وقابلة للتوسيع مع Payload CMS و Astro. how to use intl with Astro intl vs Payload CMS intl localization setup guide what is intl in web development intl alternative for internationalization intl install and setup tutorial building multi-language websites with intl intl and Astro integration Payload CMS and intl tutorial intl 技术 多语言网站 Payload CMS Astro localized 字段 全局标签 AIエージェント 网站国际化 Supports localized fields with `localized: true` in Payload CMS Enables translatable text in Astro components Manages global labels via `/cms/src/globals/labels.ts` Allows for multi-language website development Integrates with Astro for performant and scalable content-driven websites Utilizes Payload CMS for efficient content management intl is a fully featured template for building internationalized websites with Payload CMS and Astro, supporting localized fields and translations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('find-xposed-magisk/lobe-chat/hotkey', 'community', 'find-xposed-magisk', 'lobe-chat', 'find-xposed-magisk/lobe-chat', 'hotkey', 0, 0, 36, '2026-03-08T01:57:15.365Z', '2026-03-08T02:04:20.537Z', '06629806123ba243a0222e25e96ab402889832694e529498aee4543f613778bd', '{"id":"find-xposed-magisk/lobe-chat/hotkey","name":"hotkey","description":{"en":"hotkey is an open-source framework that supports multiple AI providers and multi-modal interactions. It benefits developers who want to create custom chat applications.","zh":"Hotkey 是一个开源的现代设计 LLMS/AI 聊天框架，支持多人工智能供应商和多模态。通过配置 Hotkey，可以提高您的 AI 聊天应用程序的效率","ja":"Hotkey は、オープンソースのモダンな設計の LLMS/AI チャットフレームワークで、マルチ AI プロバイダーとマルチモーダルをサポートします。Hotkey を設定することで、AI チャットアプリケーションの効率を上げることができます","ko":"Hotkey 는 오픈소스의 현대적인 디자인의 LLMS/AI 채팅 프레임워크로, 다중 인공지능 공급자 및 다중 모드를 지원합니다. Hotkey 를 설정하여 AI 채팅 애플리케이션의 효율성을 높일 수 있습니다","es":"El hotkey es una característica clave para mejorar la experiencia del usuario en aplicaciones de chat de inteligencia artificial. Con nuestra guía, aprende a configurar hotkeys para tu aplicación","fr":"Le hotkey est une fonctionnalité clé pour améliorer l''expérience utilisateur dans les applications de chat d''intelligence artificielle. Avec notre guide, découvrez comment configurer des hotkeys pour votre application","de":"Der Hotkey ist eine wichtige Funktion, um die Benutzererfahrung in KI-Chat-Anwendungen zu verbessern. Mit unserem Leitfaden erfahren Sie, wie Sie Hotkeys für Ihre Anwendung konfigurieren","pt":"O hotkey é uma funcionalidade que permite configurar atalhos de teclado para melhorar a eficiência das aplicações de chat com suporte a múltiplos fornecedores de IA.","ru":"Горячие клавиши - это функция, которая позволяет настроить клавиатурные сокращения для улучшения эффективности чат-приложений с поддержкой нескольких провайдеров ИИ.","ar":"Hotkey هو ميزة تسمح بإعداد اختصارات لوحة المفاتيح لتحسين كفاءة تطبيقات الدردشة التي تدعم العديد من مزودي الإجENTS الإصطناعية."},"seo":{"title":{"en":"hotkey: Setup Guide for AI Agents | AI Agent Skill","zh":"Hotkey 设置指南 - 快捷键配置最佳实践","ja":"Hotkey セットアップガイド - AIエージェントのキーボードショートカット","ko":"Hotkey 설정 가이드 - 한국형 AI 도구의 단축키 구성","es":"Guía de Configuración de Hotkey para Agentes de Inteligen...","fr":"Guide de Configuration de Hotkey pour les Agents d''Intell...","de":"Hotkey-Konfigurationsleitfaden für KI-Agents","pt":"Guia de Configuração de Hotkey para Ferramentas de IA","ru":"Настройка горячих клавиш для инструментов ИИ Агентов","ar":"دليل إعداد Hotkey لأدوات الإجENTS الإصطناعية"},"description":{"en":"Discover how to deploy your private ChatGPT chat app with hotkey, an open-source LLMs/AI chat framework. Get started now and explore its multi-modal capabili...","zh":"了解如何配置 Hotkey 以提高您的 AI 聊天应用程序的效率，支持多人工智能供应商和多模态","ja":"AIエージェントのキーボードショートカットを設定する方法を学び、効率を上げましょう。マルチ AI プロバイダーとマルチモーダルをサポート","ko":"Hotkey 를 설정하여 AI 채팅 애플리케이션의 효율성을 높이고, 다중 인공지능 공급자 및 다중 모드 지원에 대해 알아보세요","es":"Aprende a configurar hotkeys para tu aplicación de chat de inteligencia artificial con nuestra guía paso a paso","fr":"Découvrez comment configurer des hotkeys pour votre application de chat d''intelligence artificielle avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Hotkeys für Ihre KI-Chat-Anwendung mit unserem Schritt-für-Schritt-Leitfaden konfigurieren","pt":"Aprenda a configurar hotkeys para melhorar a eficiência das suas aplicações de chat com suporte a múltiplos fornecedores de IA","ru":"Узнайте, как настроить горячие клавиши для улучшения эффективности ваших чат-приложений с поддержкой нескольких провайдеров ИИ","ar":"تعلم كيفية إعداد Hotkey لتحسين كفاءة تطبيقات الدردشة الخاصة بك مع دعم العديد من مزودي الإجENTS الإصطناعية"},"definition":{"en":"hotkey is an open-source, modern-design LLMs/AI chat framework that supports multiple AI providers and multi-modal interactions","zh":"Hotkey 是一个配置快捷键的功能，用于提高 AI 聊天应用程序的效率","ja":"Hotkey は、AI チャットアプリケーションの効率を上げるために、キーボードショートカットを設定する機能です","ko":"Hotkey 는 AI 채팅 애플리케이션의 효율성을 높이기 위해 단축키를 설정하는 기능입니다","es":"Un hotkey es una tecla de acceso rápido que permite a los usuarios interactuar con una aplicación de chat de inteligencia artificial de manera más eficiente","fr":"Un hotkey est une touche d''accès rapide qui permet aux utilisateurs d''interagir avec une application de chat d''intelligence artificielle de manière plus efficace","de":"Ein Hotkey ist eine Schnelltaste, die es Benutzern ermöglicht, mit einer KI-Chat-Anwendung auf effizientere Weise zu interagieren","pt":"O que é hotkey? É uma funcionalidade de atalho de teclado para aplicações de chat de IA.","ru":"Что такое горячие клавиши? Это функция клавиатурного сокращения для чат-приложений ИИ.","ar":"ما هو Hotkey? إنه ميزة اختصار لوحة المفاتيح لتطبيقات الدردشة الإصطناعية."},"features":{"en":["Supports multiple AI providers, including OpenAI, Claude 3, and Gemini","Offers multi-modal interactions, including Vision and TTS","Allows for custom hotkey registration via the HotkeyEnum constant","Enables default hotkey registration in the HOTKEYS_REGISTRATION array","Utilizes the combineKeys function from @lobehub/ui for key mapping","Supports plugin systems for extensibility"],"zh":["支持多人工智能供应商（OpenAI/Claude 3/Gemini/Ollama/Bedrock/Azure/Mistral/Conspirity）","支持多模态（Vision/TTS）","插件系统","一键免费部署您的私人 ChatGPT 聊天应用程序","配置快捷键以提高效率","支持 TypeScript 和 JavaScript"],"ja":["マルチ AI プロバイダー（OpenAI/Claude 3/Gemini/Ollama/Bedrock/Azure/Mistral/Conspirity）をサポート","マルチモーダル（Vision/TTS）をサポート","プラグインシステム","一键無料デプロイ您的私的 ChatGPT チャットアプリケーション","キーボードショートカットを設定して効率を上げる","TypeScript と JavaScript をサポート"],"ko":["다중 인공지능 공급자（OpenAI/Claude 3/Gemini/Ollama/Bedrock/Azure/Mistral/Conspirity）를 지원","다중 모드（Vision/TTS）를 지원","플러그인 시스템","한 번의 클릭으로 무료로 배포하는 개인용 ChatGPT 채팅 애플리케이션","단축키를 설정하여 효율성을 높이는 기능","TypeScript 및 JavaScript 를 지원"],"es":["Soporte para múltiples proveedores de inteligencia artificial (OpenAI, Claude 3, Gemini, etc.)","Capacidad para registrar hotkeys personalizados","Integración con la biblioteca @lobehub/ui para combinar teclas","Compatibilidad con TypeScript para una mejor experiencia de desarrollo","Funcionalidad de conversación con soporte para hotkeys","Sistema de plugins para extender la funcionalidad de la aplicación"],"fr":["Prise en charge de plusieurs fournisseurs d''intelligence artificielle (OpenAI, Claude 3, Gemini, etc.)","Capacité à enregistrer des hotkeys personnalisés","Intégration avec la bibliothèque @lobehub/ui pour combiner des touches","Compatibilité avec TypeScript pour une meilleure expérience de développement","Fonctionnalité de conversation avec prise en charge de hotkeys","Système de plugins pour étendre la fonctionnalité de l''application"],"de":["Unterstützung für mehrere KI-Anbieter (OpenAI, Claude 3, Gemini usw.)","Funktion zum Registrieren benutzerdefinierter Hotkeys","Integration mit der Bibliothek @lobehub/ui zum Kombinieren von Tasten","Kompatibilität mit TypeScript für eine bessere Entwicklererfahrung","Konversationsfunktion mit Hotkey-Unterstützung","Plugin-System zur Erweiterung der Anwendungsfunctonalität"],"pt":["Suporte a múltiplos fornecedores de IA","Configuração de atalhos de teclado personalizados","Integração com o framework Lobe Chat","Suporte a múltiplas modalidades (Vision/TTS)","Sistema de plug-ins para extensibilidade"],"ru":["Поддержка нескольких провайдеров ИИ","Настройка пользовательских клавиатурных сокращений","Интеграция с фреймворком Lobe Chat","Поддержка нескольких модальностей (Vision/TTS)","Система плагинов для расширения"],"ar":["دعم العديد من مزودي الإجENTS الإصطناعية","إعداد اختصارات لوحة المفاتيح المخصصة","التكامل مع إطار العمل Lobe Chat","دعم العديد من الوضعيات (Vision/TTS)","نظام الإضافات لتوسيع إمكانيات البرنامج"]},"keywords":{"en":["how to use hotkey","hotkey setup guide","hotkey alternative","hotkey vs Claude 3","hotkey install","what is hotkey","hotkey for AI agents","hotkey multi-modal support","hotkey plugin system"],"zh":["Hotkey 设置","AI 聊天应用程序","多人工智能供应商","多模态","插件系统","快捷键配置","TypeScript","JavaScript","AI 工具","LLMS/AI 聊天框架"],"ja":["Hotkey セットアップ","AI チャットアプリケーション","マルチ AI プロバイダー","マルチモーダル","プラグインシステム","キーボードショートカット","TypeScript","JavaScript","AI エージェント","LLMS/AI チャットフレームワーク"],"ko":["Hotkey 설정","AI 채팅 애플리케이션","다중 인공지능 공급자","다중 모드","플러그인 시스템","단축키 구성","TypeScript","JavaScript","AI 도구","LLMS/AI 채팅 프레임워크"],"es":["hotkey","agentes de inteligencia artificial","configuración de hotkeys","desarrollo de aplicaciones de chat","inteligencia artificial","OpenAI","TypeScript","biblioteca @lobehub/ui","sistema de plugins"],"fr":["hotkey","agents d''intelligence artificielle","configuration de hotkeys","développement d''applications de chat","intelligence artificielle","OpenAI","TypeScript","bibliothèque @lobehub/ui","système de plugins"],"de":["Hotkey","KI-Agents","Hotkey-Konfiguration","Entwicklung von Chat-Anwendungen","Künstliche Intelligenz","OpenAI","TypeScript","Bibliothek @lobehub/ui","Plugin-System"],"pt":["hotkey","ferramentas de IA","chat de IA","atalhos de teclado","configuração de hotkey","Lobe Chat","fornecedores de IA","modalidades de IA"],"ru":["горячие клавиши","инструменты ИИ","чат-боты ИИ","клавиатурные сокращения","настройка горячих клавиш","Lobe Chat","провайдеры ИИ","модальности ИИ"],"ar":["Hotkey","أدوات الإجENTS الإصطناعية","دردشة الإجENTS الإصطناعية","اختصارات لوحة المفاتيح","إعداد Hotkey","Lobe Chat","مزودي الإجENTS الإصطناعية","وضعيات الإجENTS الإصطناعية"]}},"owner":"find-xposed-magisk","repo":"lobe-chat","repoPath":"find-xposed-magisk/lobe-chat","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.365Z","topics":[],"category":"community","skillMd":{"name":"hotkey","description":"Guide for adding keyboard shortcuts. Use when implementing new hotkeys, registering shortcuts, or working with keyboard interactions. Triggers on hotkey implementation or keyboard shortcut tasks.","bodyPreview":"# Adding Keyboard Shortcuts Guide\n\n## Steps to Add a New Hotkey\n\n### 1. Update Hotkey Constant\n\nIn `src/types/hotkey.ts`:\n\n```typescript\nexport const HotkeyEnum = {\n  // existing...\n  ClearChat: ''clearChat'', // Add new\n} as const;\n```\n\n### 2. Register Default Hotkey\n\nIn `src/const/hotkeys.ts`:\n\n```typescript\nimport { KeyMapEnum as Key, combineKeys } from ''@lobehub/ui'';\n\nexport const HOTKEYS_REGISTRATION: HotkeyRegistration = [\n  {\n    group: HotkeyGroupEnum.Conversation,\n    id: HotkeyEnum.Clear","body":"# Adding Keyboard Shortcuts Guide\n\n## Steps to Add a New Hotkey\n\n### 1. Update Hotkey Constant\n\nIn `src/types/hotkey.ts`:\n\n```typescript\nexport const HotkeyEnum = {\n  // existing...\n  ClearChat: ''clearChat'', // Add new\n} as const;\n```\n\n### 2. Register Default Hotkey\n\nIn `src/const/hotkeys.ts`:\n\n```typescript\nimport { KeyMapEnum as Key, combineKeys } from ''@lobehub/ui'';\n\nexport const HOTKEYS_REGISTRATION: HotkeyRegistration = [\n  {\n    group: HotkeyGroupEnum.Conversation,\n    id: HotkeyEnum.ClearChat,\n    keys: combineKeys([Key.Mod, Key.Shift, Key.Backspace]),\n    scopes: [HotkeyScopeEnum.Chat],\n  },\n];\n```\n\n### 3. Add i18n Translation\n\nIn `src/locales/default/hotkey.ts`:\n\n```typescript\nconst hotkey: HotkeyI18nTranslations = {\n  clearChat: {\n    desc: ''清空当前会话的所有消息记录'',\n    title: ''清空聊天记录'',\n  },\n};\n```\n\n### 4. Create and Register Hook\n\nIn `src/hooks/useHotkeys/chatScope.ts`:\n\n```typescript\nexport const useClearChatHotkey = () => {\n  const clearMessages = useChatStore((s) => s.clearMessages);\n  return useHotkeyById(HotkeyEnum.ClearChat, clearMessages);\n};\n\nexport const useRegisterChatHotkeys = () => {\n  useClearChatHotkey();\n  // ...other hotkeys\n};\n```\n\n### 5. Add Tooltip (Optional)\n\n```tsx\nconst clearChatHotkey = useUserStore(settingsSelectors.getHotkeyById(HotkeyEnum.ClearChat));\n\n<Tooltip hotkey={clearChatHotkey} title={t(''clearChat.title'', { ns: ''hotkey'' })}>\n  <Button icon={<DeleteOutlined />} onClick={clearMessages} />\n</Tooltip>;\n```\n\n## Best Practices\n\n1. **Scope**: Choose global or chat scope based on functionality\n2. **Grouping**: Place in appropriate group (System/Layout/Conversation)\n3. **Conflict check**: Ensure no conflict with system/browser shortcuts\n4. **Platform**: Use `Key.Mod` instead of hardcoded `Ctrl` or `Cmd`\n5. **Clear description**: Provide title and description for users\n\n## Troubleshooting\n\n- **Not working**: Check scope and RegisterHotkeys hook\n- **Not in settings**: Verify HOTKEYS_REGISTRATION config\n- **Conflict**: HotkeyInput component shows warnings\n- **Page-specific**: Ensure correct scope activation\n"},"lastSynced":"2026-03-08T02:04:20.537Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing customizable keyboard shortcut integration in chat applications.","zh":"适合需要自定义键盘快捷键集成的聊天应用中的 AI 代理。","ja":"チャットアプリケーションでカスタマイズ可能なキーボードショートカット統合を必要とする AI エージェントに最適です。","ko":"채팅 애플리케이션에서 사용자 지정 가능한 키보드 단축키 통합이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan integración personalizable de atajos de teclado en aplicaciones de chat.","fr":"Parfait pour les agents IA nécessitant une intégration de raccourcis clavier personnalisables dans les applications de chat.","de":"Perfekt für KI-Agents, die eine anpassbare Tastenkürzel-Integration in Chat-Anwendungen benötigen.","pt":"Perfeito para Agentes de IA que necessitam de integração de atalhos de teclado personalizáveis em aplicações de chat.","ru":"Идеально для агентов ИИ, которым необходима настраиваемая интеграция клавиатурных сокращений в чат-приложениях.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى دمج اختصارات لوحة المفاتيح القابلة للتعديل في تطبيقات الدردشة."},"recommendation":{"en":"Empowers agents to register default hotkeys and update hotkey constants using TypeScript, enabling multi-modal interactions with libraries like @lobehub/ui.","zh":"使代理能够使用 TypeScript 注册默认热键并更新热键常量，实现与 @lobehub/ui 等库的多模式交互。","ja":"TypeScript を使用してデフォルトのホットキーを登録し、ホットキーコンスタントを更新することで、@lobehub/ui などのライブラリとのマルチモーダルなインタラクションを可能にします。","ko":"TypeScript를 사용하여 기본 핫キー 등록 및 핫키 常数 업데이트를 통해 @lobehub/ui와 같은 라이브러리의 멀티모달 상호작용을 가능하게 합니다.","es":"Habilita a los agentes a registrar hotkeys predeterminados y actualizar constantes de hotkey utilizando TypeScript, lo que permite interacciones multimodales con bibliotecas como @lobehub/ui.","fr":"Permet aux agents d''enregistrer des raccourcis clavier par défaut et de mettre à jour des constantes de raccourci clavier à l''aide de TypeScript, permettant ainsi des interactions multimodales avec des bibliothèques comme @lobehub/ui.","de":"Ermächtigt Agents, Standard-Hotkeys zu registrieren und Hotkey-Konstanten mit TypeScript zu aktualisieren, ermöglicht so multimodale Interaktionen mit Bibliotheken wie @lobehub/ui.","pt":"Habilita os agentes a registrar atalhos padrão e atualizar constantes de atalhos usando TypeScript, permitindo interações multimodais com bibliotecas como @lobehub/ui.","ru":"Наделяет агентов возможностью регистрировать стандартные горячие клавиши и обновлять константы горячих клавиш с помощью TypeScript, обеспечивая многомодальные взаимодействия с библиотеками như @lobehub/ui.","ar":"تمكين الوكلاء من تسجيل الاختصارات الافتراضية وتحديث ثوابت الاختصارات باستخدام TypeScript ، مما يسمح بالتفاعلات متعددة الوضع مع المكتبات مثل @lobehub/ui."},"useCases":{"en":["Registering new hotkeys for conversation management","Updating hotkey constants for custom chat applications","Implementing keyboard shortcuts for efficient user interaction"],"zh":["为会话管理注册新的热键","为自定义聊天应用程序更新热键常量","实现键盘快捷方式以实现高效的用户交互"],"ja":["会話管理のための新しいホットキーを登録する","カスタムチャットアプリケーションのためのホットキーコンスタントを更新する","効率的なユーザーインタラクションのためのキーボードショートカットを実装する"],"ko":["대화 관리를 위한 새로운 핫키 등록","사용자 지정 채팅 애플리케이션을 위한 핫키 상수 업데이트","효율적인 사용자 상호작용을 위한 키보드 단축키 구현"],"es":["Registrar nuevos hotkeys para la gestión de conversaciones","Actualizar constantes de hotkey para aplicaciones de chat personalizadas","Implementar atajos de teclado para una interacción eficiente del usuario"],"fr":["Enregistrer de nouveaux raccourcis clavier pour la gestion de conversations","Mettre à jour des constantes de raccourci clavier pour des applications de chat personnalisées","Implémenter des raccourcis clavier pour une interaction utilisateur efficace"],"de":["Registrieren neuer Hotkeys für die Konversationsverwaltung","Aktualisieren von Hotkey-Konstanten für benutzerdefinierte Chat-Anwendungen","Implementieren von Tastenkürzeln für eine effiziente Benutzerinteraktion"],"pt":["Registrar novos atalhos para gerenciamento de conversas","Atualizar constantes de atalhos para aplicações de chat personalizadas","Implementar atalhos de teclado para interação de usuário eficiente"],"ru":["Регистрация новых горячих клавиш для управления разговорами","Обновление констант горячих клавиш для пользовательских чат-приложений","Реализация клавиатурных сокращений для эффективного взаимодействия с пользователем"],"ar":["تسجيل اختصارات جديدة لإدارة المحادثات","تحديث ثوابت الاختصارات لتطبيقات الدردشة المخصصة","تنفيذ اختصارات لوحة المفاتيح للتفاعل الفعال للمستخدم"]},"limitations":{"en":["Requires TypeScript configuration","Dependent on @lobehub/ui library"],"zh":["需要 TypeScript 配置","依赖于 @lobehub/ui 库"],"ja":["TypeScript の設定が必要","@lobehub/ui ライブラリに依存する"],"ko":["TypeScript 구성이 필요함","@lobehub/ui 라이브러리에 의존함"],"es":["Requiere configuración de TypeScript","Dependiente de la biblioteca @lobehub/ui"],"fr":["Nécessite une configuration de TypeScript","Dépend de la bibliothèque @lobehub/ui"],"de":["Benötigt TypeScript-Konfiguration","Abhängig von der Bibliothek @lobehub/ui"],"pt":["Requer configuração do TypeScript","Dependente da biblioteca @lobehub/ui"],"ru":["Требует настройки TypeScript","Зависит от библиотеки @lobehub/ui"],"ar":["يتطلب تكوين TypeScript","يعتمد على مكتبة @lobehub/ui"]},"version":4},"contentHash":"06629806123ba243a0222e25e96ab402889832694e529498aee4543f613778bd","qualityScore":36}');
