INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AojdevStudio/Finance-Guru/readiness-report', 'readiness-report', 'AojdevStudio', 'Finance-Guru', 'community', 'readiness-report AojdevStudio Finance-Guru community The readiness-report skill evaluates a repository''s support for autonomous AI development, analyzing nine technical pillars and five maturity levels to identify gaps and prioritize fixes for AI-assisted development. Readiness Report 评估代码库的 AI 开发准备情况，帮助开发者找到改进的机会 Readiness Report はコードベースの AI 開発の準備状況を評価し、開発者が改善の機会を特定できるようにします Readiness Report는 코드베이스의 AI 개발 준비 상황을 평가하여 개발자가 개선할 기회를 찾아갈 수 있도록 도와줍니다 El informe de preparación para agentes de IA evalúa la preparación de un repositorio para el desarrollo autónomo de IA analizando nueve pilares técnicos y cinco niveles de madurez Le rapport de préparation pour les agents d''IA évalue la préparation d''un référentiel pour le développement autonome d''IA en analysant neuf piliers techniques et cinq niveaux de maturité Der Bereitschaftsbericht für KI-Agenten bewertet die Bereitschaft eines Repositorys für die autonome KI-Entwicklung, indem er neun technische Säulen und fünf Reifegrade analysiert O readiness-report é uma ferramenta que avalia a prontidão do seu repositório para desenvolvimento autônomo de IA, identificando lacunas e priorizando soluções Readiness-report - это инструмент, который оценивает готовность вашего репозитория для автономного развития ИИ, выявляя пробелы и определяя приоритеты для их устранения تقرير الجاهزية هو أداة لتقييم جاهزية مستودعك لتنمية الوكلاء الذكيين، وتحديد الفجوات وترتيب الأولويات لمعالجتها how to use readiness-report readiness-report alternative readiness-report setup guide what is readiness-report readiness-report vs competitor readiness-report install AI agent development autonomous AI development codebase readiness AIエージェント Readiness Report AI 开发 代码库评估 技术支柱 成熟度级别 CLI 命令 AI 工具 Evaluates repositories across nine technical pillars Analyzes five maturity levels for AI-assisted development Identifies gaps in feedback loops, documentation, and tooling Prioritizes fixes to improve codebase readiness Runs using the `/readiness-report` command readiness-report is a skill that measures a codebase''s preparedness for AI-assisted development, analyzing feedback loops, documentation, and tooling to prevent errors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dartsim/dart/dart-ci', 'community', 'dartsim', 'dart', 'dartsim/dart', 'dart-ci', 0, 0, 36, '2026-03-08T01:57:15.370Z', '2026-03-08T02:04:26.934Z', 'a2b9639f752dcf7cc0f5cb351e99f44b340d9a6598587a747d83d623a4eae562', '{"id":"dartsim/dart/dart-ci","name":"dart-ci","description":{"en":"The dart-ci skill helps developers debug CI failures and work with GitHub Actions, providing quick commands for monitoring PR checks and viewing run details.","zh":"Dart CI/CD 故障排除工具，用于调试 CI 失败和优化 GitHub Actions","ja":"Dart CI/CD のトラブルシューティング ツールを使用して CI 失敗をデバッグし、GitHub Actions を最適化します","ko":"Dart CI/CD 문제 해결을 위한 도구로 CI 실패를 디버깅하고 GitHub Actions를 최적화합니다","es":"dart-ci es una herramienta para depuración de CI y CD con GitHub Actions. Proporciona comandos rápidos para monitorear y depurar flujos de trabajo","fr":"dart-ci est un outil de débogage de CI et CD avec GitHub Actions. Il offre des commandes rapides pour surveiller et déboguer les flux de travail","de":"dart-ci ist ein Tool zur Fehlerbehebung von CI und CD mit GitHub Actions. Es bietet Quick-Befehle zur Überwachung und Fehlerbehebung von Workflows","pt":"O DART-CI é uma ferramenta para solucionar problemas de CI/CD, com comandos rápidos para monitorar checks de PR e visualizar detalhes de execução","ru":"DART-CI - инструмент для решения проблем CI/CD, с быстрыми командами для мониторинга проверок PR и просмотра деталей выполнения","ar":"DART-CI هو أداة لحل مشاكل CI/CD، مع أوامر سريعة لمراقبة فحوصات PR وتصفح تفاصيل التشغيل"},"seo":{"title":{"en":"dart-ci: CI/CD Troubleshooting Setup Guide | AI Agent Skill","zh":"Dart CI/CD 故障排除指南","ja":"Dart CI/CD トラブルシューティング ガイド","ko":"Dart CI/CD 문제 해결 가이드","es":"Guía de configuración de dart-ci para depuración de CI","fr":"Guide de configuration de dart-ci pour le débogage de CI","de":"Einrichtungsleitfaden für dart-ci zur CI-Fehlerbeheb