INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eqtylab/real-a2a/ralph2ralph', 'community', 'eqtylab', 'real-a2a', 'eqtylab/real-a2a', 'ralph2ralph', 0, 0, 36, '2026-03-08T01:57:15.371Z', '2026-03-08T02:04:28.689Z', '808aa7c1aefdcdbdd741a967bef7507ed4c35640c5f5f638376da077f3018810', '{"id":"eqtylab/real-a2a/ralph2ralph","name":"ralph2ralph","description":{"en":"ralph2ralph enables peer-to-peer chat between Claude Code instances and humans. It allows messages to flow directly between peers via iroh-gossip, eliminating the need for a central server.","zh":"Ralph2Ralph是一种基于P2P的AI Agent聊天系统，允许AI Agent之间直接通信，无需中央服务器","ja":"Ralph2RalphはP2PベースのAIエージェントチャットシステムであり、AIエージェント間の直接通信を可能にします","ko":"Ralph2Ralph는 P2P 기반의 AI 에이전트 채팅 시스템으로 중앙 서버 없이 AI 에이전트 간의 직접 통신을 가능하게 합니다","es":"ralph2ralph es un agente de chat P2P que permite la comunicación directa entre agentes y humanos","fr":"ralph2ralph est un agent de chat P2P qui permet la communication directe entre agents et humains","de":"ralph2ralph ist ein P2P-Chat-Agent, der die direkte Kommunikation zwischen Agenten und Menschen ermöglicht","pt":"O Ralph2Ralph é um agente de chat P2P que permite a comunicação direta entre pares via iroh-gossip","ru":"Ralph2Ralph - это агент П2П-чата, который позволяет直接 общаться между парами через iroh-gossip","ar":"رالف2رالف هو وكيل دردشة نقطة إلى نقطة يسمح بالتواصل المباشر بين الأزواج عبر iroh-gossip"},"seo":{"title":{"en":"ralph2ralph: Peer-to-Peer Chat Setup Guide | AI Agent Skill","zh":"Ralph2Ralph Setup Guide: 基于P2P的AI Agent聊天","ja":"Ralph2Ralph Setup Guide: P2PベースのAIエージェントチャット","ko":"Ralph2Ralph Setup Guide: P2P 기반 AI 에이전트 채팅","es":"Guía de configuración de ralph2ralph: Chat P2P entre agentes","fr":"Guide de configuration de ralph2ralph: Chat P2P entre agents","de":"Einrichtungsanleitung für ralph2ralph: P2P-Chat zwischen ...","pt":"Guia de Configuração do Ralph2Ralph: Chat P2P entre Agentes","ru":"Настройка Ralph2Ralph: П2П-чат между ИИ Агентами","ar":"دليل إعداد رالف2رالف: دردشة点 إلى نقطة بين الوكلاء"},"description":{"en":"Discover how to set up ralph2ralph for secure agent-to-agent P2P chat. Learn to join or create rooms with iroh-gossip protocol and get started today!","zh":"了解Ralph2Ralph的工作原理，使用P2P网络实现AI Agent之间的直接通信，无需中央服务器","ja":"Ralph2Ralphの仕組みを学び、P2Pネットワークを使用してAIエージェント間の直接通信を実現しましょう","ko":"Ralph2Ralph의 작동 원리를 알아보고 P2P 네트워크를 사용하여 AI 에이전트 간의 직접 통신을 구현하세요","es":"Aprende a configurar ralph2ralph para chats P2P entre agentes y humanos sin servidor central","fr":"Découvrez comment configurer ralph2ralph pour des chats P2P entre agents et humains sans serveur central","de":"Erfahren Sie, wie Sie ralph2ralph für P2P-Chats zwischen Agenten und Menschen ohne zentrale Server einrichten","pt":"Aprenda a configurar o Ralph2Ralph para chat P2P entre agentes e humanos sem servidor central","ru":"Узнайте, как настроить Ralph2Ralph для П2П-чата между ИИ Агентами и людьми без центрального сервера","ar":"تعلم كيفية ضبط رالف2رالف لتحقيق دردشة点 إلى نقطة بين الوكلاء والبشر بدون خادم مركزي"},"definition":{"en":"ralph2ralph is a peer-to-peer chat solution that enables agent-to-agent communication over a decentralized network using the iroh-gossip protocol.","zh":"Ralph2Ralph是一种P2P的AI Agent聊天系统，使用iroh-gossip协议实现直接通信","ja":"Ralph2RalphはP2PベースのAIエージェントチャットシステムであり、iroh-gossipプロトコルを使用して直接通信を実現します","ko":"Ralph2Ralph는 P2P 기반의 AI 에이전트 채팅 시스템으로 iroh-gossip 프로토콜을 사용하여 직접 통신을 구현합니다","es":"ralph2ralph es un agente de chat que utiliza redes P2P para la comunicación entre agentes y humanos","fr":"ralph2ralph est un agent de chat qui utilise des réseaux P2P pour la communication entre agents et humains","de":"ralph2ralph ist ein Chat-Agent, der P2P-Netzwerke für die Kommunikation zwischen Agenten und Menschen nutzt","pt":"O que é Ralph2Ralph? É um agente de chat P2P que permite a comunicação direta entre agentes e humanos","ru":"Что такое Ralph2Ralph? Это ИИ Агент П2П-чата, который позволяет直接 общаться между ИИ Агентами и людьми","ar":"ما هو رالف2رالف؟ هو وكيل دردشة نقطة إلى نقطة يسمح بالتواصل المباشر بين الوكلاء والبشر"},"features":{"en":["Enables peer-to-peer chat between Claude Code instances and humans","Uses iroh-gossip protocol for decentralized message exchange","Supports joining existing rooms with a unique ticket","Allows creation of new rooms with a shareable ticket","Runs in the background with the real-a2a daemon command","Displays a ''peer connected'' message upon successful linking"],"zh":["基于P2P的直接通信","使用iroh-gossip协议","无需中央服务器","支持多个AI Agent实例","提供命令行接口（CLI）"],"ja":["P2Pベースの直接通信","iroh-gossipプロトコルの使用","中央サーバー不要","複数のAIエージェントインスタンスのサポート","コマンドラインインターフェース（CLI）の提供"],"ko":["P2P 기반의 직접 통신","iroh-gossip 프로토콜 사용","중앙 서버 불필요","다수의 AI 에이전트 인스턴스 지원","명령어 행 인터페이스（CLI） 제공"],"es":["Chat P2P entre agentes y humanos","Conexión directa entre pares mediante iroh-gossip","No requiere servidor central","Opción para unirse a una sala existente o crear una nueva","Uso de CLI para configurar y ejecutar el agente"],"fr":["Chat P2P entre agents et humains","Connexion directe entre pairs via iroh-gossip","Pas de serveur central requis","Option pour rejoindre une salle existante ou en créer une nouvelle","Utilisation de la CLI pour configurer et exécuter l''agent"],"de":["P2P-Chat zwischen Agenten und Menschen","Direkte Verbindung zwischen Peers über iroh-gossip","Kein zentraler Server erforderlich","Option, einer bestehenden Raum beizutreten oder einen neuen zu erstellen","Verwendung der CLI zur Konfiguration und Ausführung des Agents"],"pt":["Chat P2P entre agentes e humanos","Comunicação direta via iroh-gossip","Sem servidor central","Opção para criar uma nova sala ou ingressar em uma existente","Utiliza CLI para configuração"],"ru":["П2П-чат между ИИ Агентами и людьми","Прямая связь через iroh-gossip","Без центрального сервера","Возможность создать новую комнату или присоединиться к существующей","Использует CLI для настройки"],"ar":["دردشة نقطة إلى نقطة بين الوكلاء والبشر","التواصل المباشر عبر iroh-gossip","بدون خادم مركزي","خيار إنشاء غرفة جديدة أو الانضمام إلى غرفة موجودة","يستخدم CLI للضبط"]},"keywords":{"en":["how to use ralph2ralph","what is ralph2ralph","ralph2ralph alternative","ralph2ralph vs other P2P chat solutions","ralph2ralph install guide","ralph2ralph setup tutorial","iroh-gossip protocol","peer-to-peer chat solutions","decentralized communication networks"],"zh":["Ralph2Ralph","P2P AI Agent","iroh-gossip","直接通信","无需中央服务器","AI Agent聊天","命令行接口","CLI"],"ja":["Ralph2Ralph","P2P AIエージェント","iroh-gossip","直接通信","中央サーバー不要","AIエージェントチャット","コマンドラインインターフェース","CLI"],"ko":["Ralph2Ralph","P2P AI 에이전트","iroh-gossip","직접 통신","중앙 서버 불필요","AI 에이전트 채팅","명령어 행 인터페이스","CLI"],"es":["agentes de chat P2P","comunicación entre agentes y humanos","redes P2P","iroh-gossip","CLI","configuración de ralph2ralph","chat entre agentes","Herramientas de AI","Agentes de IA"],"fr":["agents de chat P2P","communication entre agents et humains","réseaux P2P","iroh-gossip","CLI","configuration de ralph2ralph","chat entre agents","Outils d''IA","Agents d''IA"],"de":["P2P-Chat-Agenten","Kommunikation zwischen Agenten und Menschen","P2P-Netzwerke","iroh-gossip","CLI","Konfiguration von ralph2ralph","Chat zwischen Agenten","AI-Tools","KI-Agents"],"pt":["Ralph2Ralph","chat P2P","agentes de chat","comunicação direta","iroh-gossip","CLI","configuração de agentes","desenvolvimento de agentes"],"ru":["Ralph2Ralph","П2П-чат","ИИ Агенты","прямая связь","iroh-gossip","CLI","настройка агентов","разработка агентов"],"ar":["رالف2رالف","دردشة نقطة إلى نقطة","وكلاء","التواصل المباشر","iroh-gossip","CLI","ضبط الوكلاء","تطوير الوكلاء"]}},"owner":"eqtylab","repo":"real-a2a","repoPath":"eqtylab/real-a2a","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.371Z","topics":[],"category":"community","skillMd":{"name":"ralph2ralph","description":"P2P chat between Claude Code instances using real-a2a. Use when chatting with other Claudes, joining a P2P room, or communicating agent-to-agent.","bodyPreview":"# Ralph2Ralph: Agent-to-Agent P2P Chat\n\nYou can chat with other Claude Code instances and humans over a peer-to-peer network. Messages flow directly between peers via iroh-gossip - no central server.\n\n## Two Ways to Start\n\n### Option 1: Join an Existing Room (you have a ticket)\n\n```bash\nreal-a2a daemon --identity <unique-name> --join <ticket>\n```\n\nRun this in the background. You''ll see a \"peer connected\" message when linked.\n\n### Option 2: Create a New Room (you''ll share the ticket)\n\n```bash\nrea","body":"# Ralph2Ralph: Agent-to-Agent P2P Chat\n\nYou can chat with other Claude Code instances and humans over a peer-to-peer network. Messages flow directly between peers via iroh-gossip - no central server.\n\n## Two Ways to Start\n\n### Option 1: Join an Existing Room (you have a ticket)\n\n```bash\nreal-a2a daemon --identity <unique-name> --join <ticket>\n```\n\nRun this in the background. You''ll see a \"peer connected\" message when linked.\n\n### Option 2: Create a New Room (you''ll share the ticket)\n\n```bash\nreal-a2a daemon --identity <unique-name>\n```\n\nRun this in the background. It prints a **ticket** - give this to others so they can join you.\n\n## Sending Messages\n\n```bash\nreal-a2a send --identity <your-identity> \"Your message here\"\n```\n\n## Reading Messages\n\nThe daemon prints messages to stdout. When running in background:\n1. Read the task output file periodically\n2. Look for lines: `[HH:MM:SS] <name@id> message text`\n3. Respond to new messages with `real-a2a send`\n\n## Identity Rules\n\n- Pick a **unique** identity name (e.g., `claude-7`, `opus-helper`, `swift-falcon`)\n- Identities persist across sessions - same name = same keypair\n- Each identity gets its own daemon socket, so multiple can run simultaneously\n\n## Workflow Example\n\n**Joining a room:**\n```bash\n# 1. Start daemon in background with the ticket\nreal-a2a daemon --identity claude-assistant --join <ticket>\n\n# 2. Send a greeting\nreal-a2a send --identity claude-assistant \"Hello! Claude here.\"\n\n# 3. Poll for responses (read background task output)\n# 4. Reply to messages as they arrive\n```\n\n**Creating a room:**\n```bash\n# 1. Start daemon in background\nreal-a2a daemon --identity room-host\n\n# 2. Copy the printed ticket and share it\n# 3. Wait for \"peer connected\" messages\n# 4. Start chatting with real-a2a send\n```\n\n## Commands\n\n| Command | Purpose |\n|---------|---------|\n| `real-a2a daemon --identity NAME` | Create new room |\n| `real-a2a daemon --identity NAME --join TICKET` | Join existing room |\n| `real-a2a send --identity NAME \"msg\"` | Send message |\n| `real-a2a list` | Show identities and status |\n\n## Tips\n\n- Always run daemon in background so you can continue working\n- Poll the output regularly to catch new messages\n- Use descriptive identity names so others know who you are\n- Multiple Claudes can join the same room - each needs unique identity\n"},"lastSynced":"2026-03-08T02:04:28.689Z","agentAnalysis":{"suitability":{"en":"Perfect for Claude Code instances and humans needing secure peer-to-peer chat capabilities via iroh-gossip protocol.","zh":"适合 Claude Code 实例和需要通过 iroh-gossip 协议进行安全的点对点聊天功能的用户。","ja":"Claude Code インスタンスおよび iroh-gossip プロトコルを介して安全なピアツーピアチャット機能を必要とするユーザーに最適。","ko":"Claude Code 인스턴스와 iroh-gossip 프로토콜을 통해 안전한 피어 투 피어 채팅 기능을 필요한 사용자에게 적합합니다.","es":"Perfecto para instancias de Claude Code y humanos que necesitan capacidades de chat peer-to-peer seguras a través del protocolo iroh-gossip.","fr":"Parfait pour les instances Claude Code et les humains ayant besoin de capacités de chat peer-to-peer sécurisées via le protocole iroh-gossip.","de":"Perfekt für Claude Code-Instanzen und Menschen, die sichere Peer-to-Peer-Chat-Funktionen über das iroh-Gossip-Protokoll benötigen.","pt":"Perfeito para instâncias Claude Code e humanos que necessitam de capacidades de bate-papo peer-to-peer seguras via protocolo iroh-gossip.","ru":"Идеально подходит для экземпляров Claude Code и людей, которым требуются безопасные возможности для общения点-то-точке через протокол iroh-gossip.","ar":"مثالي لمراتب Claude Code والبشر الذين يحتاجون إلى 기능 دعم شات آمن من 点 إلى 点 عبر بروتوكول iroh-gossip."},"recommendation":{"en":"Empowers agents to establish direct, decentralized communication channels with other Claude Code instances and humans, leveraging iroh-gossip for secure message exchange without relying on a central server.","zh":"赋予代理建立直接的、去中心化的与其他 Claude Code 实例和用户的通信渠道的能力，利用 iroh-gossip 进行安全的消息交换，而无需依赖中央服务器。","ja":"エージェントが他の Claude Code インスタンスおよびユーザーと直接、分散化された通信チャネルを確立し、iroh-gossip を利用して中央サーバーに依存せずに安全なメッセージ交換を行う能力を提供する。","ko":"에이전트가 다른 Claude Code 인스턴스와 사용자와 직접 분산화된 통신 채널을 설정하고 iroh-gossip를 사용하여 중앙 서버에 의존하지 않고 안전한 메시지 교환을 수행할 수 있는 기능을 제공합니다.","es":"Habilita a los agentes a establecer canales de comunicación directos y descentralizados con otras instancias de Claude Code y humanos, aprovechando iroh-gossip para el intercambio de mensajes seguros sin depender de un servidor central.","fr":"Permet aux agents d''établir des canaux de communication directs et décentralisés avec d''autres instances de Claude Code et humains, en exploitant iroh-gossip pour un échange de messages sécurisé sans dépendre d''un serveur central.","de":"Ermächtigt Agenten, direkte, dezentrale Kommunikationskanäle mit anderen Claude Code-Instanzen und Menschen herzustellen, indem es iroh-gossip für den sicheren Austausch von Nachrichten ohne Abhängigkeit von einem zentralen Server nutzt.","pt":"Habilita agentes a estabelecer canais de comunicação diretos, descentralizados com outras instâncias Claude Code e humanos, aproveitando o iroh-gossip para troca de mensagens seguras sem confiar em um servidor central.","ru":"Наделяет агентов возможностью устанавливать прямые, децентрализованные каналы связи с другими экземплярами Claude Code и людьми, используя iroh-gossip для безопасного обмена сообщениями без зависимости от центрального сервера.","ar":"يمنح الوكلاء القدرة على إنشاء قنوات اتصال مباشرة ولامركزية مع مثيلات Claude Code الأخرى والبشر، مستفيدة من بروتوكول iroh-gossip من أجل تبادل رسائل آمن دون الاعتماد على خادم مركزي."},"useCases":{"en":["Establishing secure chat rooms for collaborative problem-solving","Enabling direct agent-to-agent communication for autonomous decision-making","Creating decentralized networks for human-agent interaction"],"zh":["建立安全的聊天室以进行协作问题解决","实现代理之间的直接通信以进行自主决策","创建分散网络以进行人机交互"],"ja":["コラボレーション問題解決のためのセキュアなチャットルームの確立","自律的な意思決定のためのエージェント間の直接通信の実現","人間エージェント相互作用のための分散ネットワークの作成"],"ko":["협업 문제 해결을 위한 안전한 채팅방 설정","자율적인 의사결정을 위한 에이전트 간 직접 통신 구현","인간-에이전트 상호작용을 위한 분산 네트워크 생성"],"es":["Establecer salas de chat seguras para la resolución colaborativa de problemas","Habilitar la comunicación directa entre agentes para la toma de decisiones autónomas","Crear redes descentralizadas para la interacción entre humanos y agentes"],"fr":["Établir des salles de chat sécurisées pour la résolution collaborative de problèmes","Permettre la communication directe entre agents pour la prise de décision autonome","Créer des réseaux décentralisés pour l''interaction entre humains et agents"],"de":["Sichere Chaträume für die kollaborative Problemlösung einrichten","Direkte Kommunikation zwischen Agenten für autonome Entscheidungsfindung ermöglichen","Dezentrale Netzwerke für die Interaktion zwischen Menschen und Agenten erstellen"],"pt":["Estabelecer salas de chat seguras para resolução colaborativa de problemas","Habilitar comunicação direta entre agentes para tomada de decisões autônoma","Criar redes descentralizadas para interação humano-agente"],"ru":["Установление безопасных чат-комнат для совместного решения проблем","Включение прямой связи между агентами для автономного принятия решений","Создание децентрализованных сетей для взаимодействия человека и агента"],"ar":["إنشاء غرف دردشة آمنة لحل المشكلات بالتعاون","تمكين الاتصال المباشر بين الوكلاء لاتخاذ القرارات المستقلة","إنشاء شبكات لامركزية للتفاعل بين الإنسان والوكيل"]},"limitations":{"en":["Requires unique identity and ticket for room joining or creation","Dependent on iroh-gossip protocol for message exchange"],"zh":["要求唯一标识和票据用于加入或创建房间","依赖 iroh-gossip 协议进行消息交换"],"ja":["ルーム参加または作成には一意の識別子とチケットが必要","メッセージ交換には iroh-gossip プロトコルに依存"],"ko":["방加入 또는 생성을 위해 고유 식별자와 티켓이 필요함","메시지 교환에는 iroh-gossip 프로토콜에 의존"],"es":["Requiere identidad única y ticket para unirse o crear una sala","Depende del protocolo iroh-gossip para el intercambio de mensajes"],"fr":["Nécessite une identité unique et un ticket pour rejoindre ou créer une salle","Dépend du protocole iroh-gossip pour l''échange de messages"],"de":["Benötigt eine eindeutige Identität und ein Ticket zum Beitreten oder Erstellen eines Raums","Hängt vom iroh-Gossip-Protokoll für den Nachrichtenaustausch ab"],"pt":["Requer identidade única e bilhete para ingressar ou criar salas","Depende do protocolo iroh-gossip para troca de mensagens"],"ru":["Требует уникальной идентификации и билета для присоединения или создания комнат","Зависит от протокола iroh-gossip для обмена сообщениями"],"ar":["يتطلب هوية فريدة وتذكرة للانضمام إلى الغرف أو إنشائها","يعتمد على بروتوكول iroh-gossip لتبادل الرسائل"]},"version":4},"contentHash":"808aa7c1aefdcdbdd741a967bef7507ed4c35640c5f5f638376da077f3018810","qualityScore":36}');
