INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eqtylab/real-a2a/ralph2ralph', 'ralph2ralph', 'eqtylab', 'real-a2a', 'community', 'ralph2ralph eqtylab real-a2a community ralph2ralph enables peer-to-peer chat between Claude Code instances and humans. It allows messages to flow directly between peers via iroh-gossip, eliminating the need for a central server. Ralph2Ralph是一种基于P2P的AI Agent聊天系统，允许AI Agent之间直接通信，无需中央服务器 Ralph2RalphはP2PベースのAIエージェントチャットシステムであり、AIエージェント間の直接通信を可能にします Ralph2Ralph는 P2P 기반의 AI 에이전트 채팅 시스템으로 중앙 서버 없이 AI 에이전트 간의 직접 통신을 가능하게 합니다 ralph2ralph es un agente de chat P2P que permite la comunicación directa entre agentes y humanos ralph2ralph est un agent de chat P2P qui permet la communication directe entre agents et humains ralph2ralph ist ein P2P-Chat-Agent, der die direkte Kommunikation zwischen Agenten und Menschen ermöglicht O Ralph2Ralph é um agente de chat P2P que permite a comunicação direta entre pares via iroh-gossip Ralph2Ralph - это агент П2П-чата, который позволяет直接 общаться между парами через iroh-gossip رالف2رالف هو وكيل دردشة نقطة إلى نقطة يسمح بالتواصل المباشر بين الأزواج عبر iroh-gossip how to use ralph2ralph what is ralph2ralph ralph2ralph alternative ralph2ralph vs other P2P chat solutions ralph2ralph install guide ralph2ralph setup tutorial iroh-gossip protocol peer-to-peer chat solutions decentralized communication networks Ralph2Ralph P2P AI Agent iroh-gossip 直接通信 无需中央服务器 AI Agent聊天 命令行接口 CLI Enables peer-to-peer chat between Claude Code instances and humans Uses iroh-gossip protocol for decentralized message exchange Supports joining existing rooms with a unique ticket Allows creation of new rooms with a shareable ticket Runs in the background with the real-a2a daemon command Displays a ''peer connected'' message upon successful linking ralph2ralph is a peer-to-peer chat solution that enables agent-to-agent communication over a decentralized network using the iroh-gossip protocol.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('antorsae/dual-agent/read-task', 'community', 'antorsae', 'dual-agent', 'antorsae/dual-agent', 'read-task', 0, 0, 36, '2026-03-08T01:57:15.372Z', '2026-03-08T02:04:29.326Z', '39870b52a0274aa5fcfa50556601804041b2051906f0b6f3badf1d19cebd207b', '{"id":"antorsae/dual-agent/read-task","name":"read-task","description":{"en":"The read-task skill enables AI agents to read and execute tasks delegated from Claude Code in a collaborative tmux session, benefiting developers who work with dual-agent environments.","zh":"Read-Task 技术用于读取和执行 Claude Code 委托的任务，实现双向开发环境","ja":"Read-Task は Claude Code から委託されたタスクを読み取り、実行し、双方向開発環境を実現します","ko":"Read-Task 기술은 Claude Code에서 위임된 작업을 읽고 실행하여 쌍방향 개발 환경을 구현합니다","es":"El skill read-task permite la lectura y ejecución de tareas delegadas desde Claude Code en un entorno de desarrollo dual con Codex CLI","fr":"Le skill read-task permet la lecture et l''exécution de tâches déléguées depuis Claude Code dans un environnement de développement dual avec Codex CLI","de":"Das read-task-Skill ermöglicht das Lesen und Ausführen von Aufgaben, die von Claude Code in einer dualen Entwicklungsumgebung mit Codex CLI delegiert werden","pt":"O Read-Task é uma habilidade que permite executar tarefas delegadas do Claude Code em uma sessão colaborativa do tmux, utilizando o Codex CLI.","ru":"Read-Task - это навык, который позволяет выполнять задачи, делегированные из Claude Code в среде разработки с ИИ Агентами, используя Codex CLI.","ar":"مهام القراءة هي مهارة تسمح بتنفيذ المهام الموكلة من Claude Code في جلسة تعاونية من tmux، باستخدام Codex CLI."},"seo":{"title":{"en":"read-task: Dual-Agent Development Environment Setup Guide...","zh":"Read-Task Setup Guide: Dual-Agent Development Environment","ja":"Read-Task を使った双方向エージェント開発環境の構築","ko":"Read-Task 설정 가이드: 쌍방향 에이전트 개발 환경","es":"Guía de configuración de read-task: entorno de desarrollo...","fr":"Guide de configuration de read-task : environnement de dé...","de":"Einrichtungsleitfaden für read-task: Duales Entwicklungsu...","pt":"Guia de Configuração do Read-Task: Integração com Claude ...","ru":"Настройка Read-Task: Работа с ИИ Агентами в среде разработки","ar":"دليل إعداد مهام القراءة: دمج Claude Code و Codex CLI"},"description":{"en":"Unlock efficient coding with read-task, a collaborative tmux session pairing Claude Code with Codex CLI. Learn how to set up and leverage this dual-agent dev...","zh":"了解 Read-Task 技术，实现 Claude Code 与 Codex CLI 的协同 tmux 会话","ja":"Read-Task を使用して Claude Code と Codex CLI の共同 tmux セッションを実現する","ko":"Read-Task 기술을 통해 Claude Code와 Codex CLI의 협업 tmux 세션을 구현하세요","es":"Aprende a configurar read-task con Claude Code y Codex CLI en una sesión colaborativa de tmux para un desarrollo eficiente","fr":"Découvrez comment configurer read-task avec Claude Code et Codex CLI dans une session collaborative tmux pour un développement efficace","de":"Erfahren Sie, wie Sie read-task mit Claude Code und Codex CLI in einer gemeinsamen tmux-Sitzung für eine effiziente Entwicklung konfigurieren","pt":"Aprenda a configurar o Read-Task para executar tarefas delegadas do Claude Code em uma sessão colaborativa do tmux","ru":"Узнайте, как настроить Read-Task для выполнения задач, делегированных из Claude Code в среде разработки с ИИ Агентами","ar":"تعرف على كيفية إعداد مهام القراءة لتنفيذ المهام الموكلة من Claude Code في جلسة تعاونية من tmux"},"definition":{"en":"read-task is a skill that facilitates collaborative development by pairing Claude Code with Codex CLI in a tmux session, enabling efficient task execution and delegation.","zh":"Read-Task 是一种读取和执行任务的技术，用于双向开发环境","ja":"Read-Task はタスクを読み取り実行する技術であり、双方向開発環境で使用されます","ko":"Read-Task는 작업을 읽고 실행하는 기술로 쌍방향 개발 환경에서 사용됩니다","es":"read-task es un skill que permite la lectura y ejecución de tareas en un entorno de desarrollo dual con Claude Code y Codex CLI","fr":"read-task est un skill qui permet la lecture et l''exécution de tâches dans un environnement de développement dual avec Claude Code et Codex CLI","de":"read-task ist ein Skill, der das Lesen und Ausführen von Aufgaben in einer dualen Entwicklungsumgebung mit Claude Code und Codex CLI ermöglicht","pt":"Read-Task é uma habilidade de AI que executa tarefas delegadas em uma sessão colaborativa","ru":"Read-Task - это навык ИИ, который выполняет делегированные задачи в среде разработки","ar":"مهام القراءة هي مهارة ذكاء اصطناعي تنفذ المهام الموكلة في جلسة تعاونية"},"features":{"en":["Resolves the .agent-collab directory for seamless file operations","Utilizes bash commands for directory resolution and task execution","Supports collaborative development via tmux sessions","Pairs Claude Code with Codex CLI for efficient task delegation","Enables task execution outside the project root directory"],"zh":["双向开发环境","Claude Code 与 Codex CLI 的协同 tmux 会话","读取和执行任务","支持多种开发语言","实现自动化开发流程"],"ja":["双方向開発環境","Claude Code と Codex CLI の共同 tmux セッション","タスクの読み取りと実行","多種の開発言語をサポート","自動化開発プロセスを実現"],"ko":["쌍방향 개발 환경","Claude Code와 Codex CLI의 협업 tmux 세션","작업 읽기 및 실행","다양한 개발 언어 지원","자동화 개발 프로세스 구현"],"es":["Entorno de desarrollo dual con Claude Code y Codex CLI","Lectura y ejecución de tareas delegadas desde Claude Code","Uso de tmux para sesiones colaborativas","Resolución de la carpeta .agent-collab para operaciones de archivos","Compatibilidad con comandos de CLI para operaciones de archivos"],"fr":["Environnement de développement dual avec Claude Code et Codex CLI","Lecture et exécution de tâches déléguées depuis Claude Code","Utilisation de tmux pour des sessions collaboratives","Résolution du répertoire .agent-collab pour les opérations de fichiers","Compatibilité avec les commandes CLI pour les opérations de fichiers"],"de":["Duales Entwicklungsumgebung mit Claude Code und Codex CLI","Lesen und Ausführen von Aufgaben, die von Claude Code delegiert werden","Verwendung von tmux für gemeinsame Sitzungen","Auflösung des Verzeichnisses .agent-collab für Dateioperationen","Kompatibilität mit CLI-Befehlen für Dateioperationen"],"pt":["Integração com Claude Code","Utilização do Codex CLI","Sessão colaborativa do tmux","Resolução do diretório .agent-collab","Execução de tarefas delegadas"],"ru":["Интеграция с ИИ Агентами","Использование Codex CLI","Совместная сессия tmux","Разрешение директории .agent-collab","Выполнение делегированных задач"],"ar":["التكامل مع Claude Code","استخدام Codex CLI","جلسة تعاونية من tmux","تحليل دليل .agent-collab","تنفيذ المهام الموكلة"]},"keywords":{"en":["how to use read-task","read-task setup guide","read-task alternative","read-task vs Codex","collaborative development environment","tmux session management","Claude Code integration","Codex CLI tutorial","dual-agent development best practices"],"zh":["Read-Task","双向开发环境","Claude Code","Codex CLI","tmux","自动化开发","AIエージェント","开发工具"],"ja":["Read-Task","双方向開発環境","Claude Code","Codex CLI","tmux","自動化開発","AIエージェント","開発ツール"],"ko":["Read-Task","쌍방향 개발 환경","Claude Code","Codex CLI","tmux","자동화 개발","AI 에이전트","개발 도구"],"es":["read-task","Claude Code","Codex CLI","tmux","desarrollo dual","lectura de tareas","ejecución de tareas","Herramientas de AI","Agentes de IA"],"fr":["read-task","Claude Code","Codex CLI","tmux","développement dual","lecture de tâches","exécution de tâches","Outils d''IA","Agents d''IA"],"de":["read-task","Claude Code","Codex CLI","tmux","duale Entwicklung","Lesen von Aufgaben","Ausführen von Aufgaben","KI-Tools","KI-Agenten"],"pt":["Read-Task","Claude Code","Codex CLI","tmux","AI Agents","desenvolvimento colaborativo","execução de tarefas","integração de ferramentas"],"ru":["Read-Task","ИИ Агенты","Claude Code","Codex CLI","tmux","среда разработки","выполнение задач","интеграция инструментов"],"ar":["مهام القراءة","Claude Code","Codex CLI","tmux","وكلاء الذكاء الاصطناعي","التطوير التعاوني","تنفيذ المهام","تكامل الأدوات"]}},"owner":"antorsae","repo":"dual-agent","repoPath":"antorsae/dual-agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.372Z","topics":[],"category":"community","skillMd":{"name":"read-task","description":"Read and execute task delegated from Claude. Use when user says read task, get task, or pick up claude task.","bodyPreview":"# Read Task Skill\n\nRead and execute a task delegated from Claude Code.\n\n## Steps\n\nBefore any file operations, resolve the `.agent-collab` directory so commands work outside the project root:\n\n```bash\nAGENT_COLLAB_DIR=\"${AGENT_COLLAB_DIR:-}\"\nif [ -n \"$AGENT_COLLAB_DIR\" ]; then\n  if [ -d \"$AGENT_COLLAB_DIR/.agent-collab\" ]; then\n    AGENT_COLLAB_DIR=\"$AGENT_COLLAB_DIR/.agent-collab\"\n  elif [ ! -d \"$AGENT_COLLAB_DIR\" ]; then\n    AGENT_COLLAB_DIR=\"\"\n  fi\nfi\n\nif [ -z \"$AGENT_COLLAB_DIR\" ]; then\n  AGE","body":"# Read Task Skill\n\nRead and execute a task delegated from Claude Code.\n\n## Steps\n\nBefore any file operations, resolve the `.agent-collab` directory so commands work outside the project root:\n\n```bash\nAGENT_COLLAB_DIR=\"${AGENT_COLLAB_DIR:-}\"\nif [ -n \"$AGENT_COLLAB_DIR\" ]; then\n  if [ -d \"$AGENT_COLLAB_DIR/.agent-collab\" ]; then\n    AGENT_COLLAB_DIR=\"$AGENT_COLLAB_DIR/.agent-collab\"\n  elif [ ! -d \"$AGENT_COLLAB_DIR\" ]; then\n    AGENT_COLLAB_DIR=\"\"\n  fi\nfi\n\nif [ -z \"$AGENT_COLLAB_DIR\" ]; then\n  AGENT_COLLAB_DIR=\"$(pwd)\"\n  while [ \"$AGENT_COLLAB_DIR\" != \"/\" ] && [ ! -d \"$AGENT_COLLAB_DIR/.agent-collab\" ]; do\n    AGENT_COLLAB_DIR=\"$(dirname \"$AGENT_COLLAB_DIR\")\"\n  done\n  AGENT_COLLAB_DIR=\"$AGENT_COLLAB_DIR/.agent-collab\"\nfi\n```\n\nIf `$AGENT_COLLAB_DIR` does not exist, stop and ask for the project root.\n\n### 1. Update Status\n\nWrite `working` to `$AGENT_COLLAB_DIR/status`\n\n### 2. Read the Task\n\nRead `$AGENT_COLLAB_DIR/requests/task.md` and parse:\n- Task Type: CODE_REVIEW, IMPLEMENT, or PLAN_REVIEW\n- All requirements and context\n\n### 3. Read Shared Context\n\nAlso read `$AGENT_COLLAB_DIR/context/shared.md` for project context.\n\n### 4. Execute Based on Task Type\n\n#### CODE_REVIEW\n\nPerform thorough code review:\n- Analyze code line by line\n- Look for bugs, logic errors, edge cases\n- Check for security vulnerabilities\n- Identify performance problems\n- Check error handling\n- Suggest concrete improvements with code examples\n\nBe thorough - take your time.\n\n#### IMPLEMENT\n\nImplement the requested feature:\n- Follow all requirements exactly\n- Match existing code patterns\n- Write clean, well-structured code\n- Handle edge cases and errors\n- Write code to specified target files\n\nTake time for high-quality implementation.\n\n#### PLAN_REVIEW\n\nCritically analyze the plan:\n- Evaluate overall approach\n- Identify failure modes\n- Consider scalability/maintainability\n- Suggest alternatives if applicable\n- Point out missing considerations\n- Assess risks\n- Provide concrete recommendations\n\n### 5. Write Response\n\nWrite complete response to `$AGENT_COLLAB_DIR/responses/response.md`:\n\n```markdown\n# Codex Response\n\n## Task Type\n[Task type handled]\n\n## Completed At\n[Timestamp]\n\n## Summary\n[Brief summary]\n\n## Detailed Findings/Output\n\n[For CODE_REVIEW:]\n### Critical Issues\n[List with severity]\n\n### Security Concerns\n[Security issues]\n\n### Suggestions\n[Improvements with examples]\n\n---\n\n[For IMPLEMENT:]\n### Implementation Overview\n[What was implemented]\n\n### Files Created/Modified\n[List of files]\n\n### Integration Notes\n[How to integrate]\n\n---\n\n[For PLAN_REVIEW:]\n### Overall Assessment\n[Is plan sound?]\n\n### Concerns\n[Issues identified]\n\n### Recommendations\n[Specific suggestions]\n```\n\n### 6. Update Status\n\nWrite `done` to `$AGENT_COLLAB_DIR/status`\n\n### 7. Notify\n\nTell user response is ready and Claude can read it with `/codex-read`.\n"},"lastSynced":"2026-03-08T02:04:29.326Z","agentAnalysis":{"suitability":{"en":"Ideal for Collaborative Agents like Claude Code that need to delegate tasks to other agents in a tmux session for efficient workflow management.","zh":"适用于Claude Code等协作代理，需要将任务委托给tmux会话中的其他代理以实现高效的工作流管理。","ja":"Claude Codeのようなコラボレーションエージェントに適しており、tmuxセッション内の他のエージェントにタスクを委任して効率的なワークフローマネジメントを行う必要があります。","ko":"클라우드 코드와 같은 협업 에이전트에 적합하며, 효율적인 워크플로우 관리를 위해 tmux 세션의 다른 에이전트에게 작업을 위임하는 데 필요합니다.","es":"Ideal para agentes colaborativos como Claude Code que necesitan delegar tareas a otros agentes en una sesión de tmux para una gestión eficiente del flujo de trabajo.","fr":"Idéal pour les agents collaboratifs comme Claude Code qui doivent déléguer des tâches à d''autres agents dans une session tmux pour une gestion efficace du flux de travail.","de":"Ideal für kollaborative Agenten wie Claude Code, die Aufgaben an andere Agenten in einer tmux-Sitzung delegieren müssen, um eine effiziente Arbeitsablaufverwaltung zu ermöglichen.","pt":"Ideal para agentes colaborativos como Claude Code que precisam delegar tarefas a outros agentes em uma sessão tmux para gerenciamento eficiente de fluxo de trabalho.","ru":"Идеально подходит для сотрудничества агентов, таких как Claude Code, которые нуждаются в делегировании задач другим агентам в сессии tmux для эффективного управления рабочим процессом.","ar":"مثالي للوكلاء التعاونيين مثل Claude Code الذين يحتاجون إلى تفويض المهام إلى وكلاء آخرين في جلسة tmux لإدارة تدفق العمل الفعالة."},"recommendation":{"en":"Empowers agents to execute tasks delegated from Claude Code, utilizing the `.agent-collab` directory for seamless collaboration and file operations, leveraging bash scripting for dynamic directory resolution and command execution.","zh":"赋予代理执行Claude Code委托的任务的能力，利用`.agent-collab`目录实现无缝的协作和文件操作，利用bash脚本实现动态目录解析和命令执行。","ja":"Claude Codeから委任されたタスクを実行するエージェントを強化し、`.agent-collab`ディレクトリを使用してシームレスなコラボレーションとファイル操作を行い、bashスクリプティングを使用して動的なディレクトリ解決とコマンド実行を行います。","ko":"클라우드 코드에서 위임된 작업을 실행하는 에이전트를 강화하여 `.agent-collab` 디렉토리를 사용하여無縫의 협업과 파일 작업을 수행하고, bash 스크립팅을 사용하여 동적 디렉토리 해석과 명령어 실행을 합니다.","es":"Habilita a los agentes a ejecutar tareas delegadas desde Claude Code, utilizando el directorio `.agent-collab` para una colaboración y operaciones de archivos sin problemas, aprovechando la programación de bash para la resolución dinámica de directorios y la ejecución de comandos.","fr":"Permet aux agents d''exécuter des tâches déléguées depuis Claude Code, en utilisant le répertoire `.agent-collab` pour une collaboration et des opérations de fichiers sans problème, en exploitant la programmation bash pour la résolution dynamique de répertoires et l''exécution de commandes.","de":"Ermächtigt Agenten, Aufgaben auszuführen, die von Claude Code delegiert wurden, unter Verwendung des Verzeichnisses `.agent-collab` für eine nahtlose Zusammenarbeit und Dateivorgänge, wobei bash-Skripting für die dynamische Verzeichnisaufklärung und Befehlsausführung genutzt wird.","pt":"Habilita os agentes a executar tarefas delegadas do Claude Code, utilizando o diretório `.agent-collab` para colaboração e operações de arquivo sem interrupção, aproveitando a scriptação bash para resolução dinâmica de diretórios e execução de comandos.","ru":"Наделяет агентов возможностью выполнять задачи, делегированные от Claude Code, используя каталог `.agent-collab` для беспрепятственного сотрудничества и файловых операций, используя скрипты bash для динамического разрешения каталогов и выполнения команд.","ar":"تمكين الوكلاء من تشغيل المهام المفوضة من Claude Code، باستخدام دليل `.agent-collab` للتعاون والعمليات الملفية دون انقطاع، والاستفادة من البرمجة النصية bash لحل دليل动态 وتشغيل أوامر."},"useCases":{"en":["Executing tasks from Claude Code in a collaborative environment","Managing dual-agent workflows with precision","Automating file operations within a tmux session"],"zh":["在协作环境中执行Claude Code的任务","精确地管理双代理工作流","在tmux会话中自动化文件操作"],"ja":["コラボレーション環境でClaude Codeのタスクを実行する","二重エージェントワークフローを精密に管理する","tmuxセッション内でファイル操作を自動化する"],"ko":["협업 환경에서 클라우드 코드의 작업을 실행하는 것","이중 에이전트 워크플로우를 정밀하게 관리하는 것","tmux 세션 내에서 파일 작업을 자동화하는 것"],"es":["Ejecutar tareas desde Claude Code en un entorno colaborativo","Gestionar flujos de trabajo de doble agente con precisión","Automatizar operaciones de archivos dentro de una sesión de tmux"],"fr":["Exécuter des tâches depuis Claude Code dans un environnement collaboratif","Gérer des flux de travail à double agent avec précision","Automatiser les opérations de fichiers à l''intérieur d''une session tmux"],"de":["Ausführen von Aufgaben von Claude Code in einer kollaborativen Umgebung","Verwalten von Doppelagenten-Workflows mit Präzision","Automatisieren von Dateivorgängen innerhalb einer tmux-Sitzung"],"pt":["Execução de tarefas do Claude Code em um ambiente colaborativo","Gerenciamento de fluxos de trabalho de agente duplo com precisão","Automação de operações de arquivo dentro de uma sessão tmux"],"ru":["Выполнение задач от Claude Code в сотрудничестве среде","Управление рабочими процессами двойного агента с точностью","Автоматизация файловых операций внутри сессии tmux"],"ar":["تشغيل المهام من Claude Code في بيئة تعاونية","إدارة تدفقات العمل للوكيل المزدوج بدقة","تحويل العمليات الملفية تلقائيًا داخل جلسة tmux"]},"limitations":{"en":["Requires access to the `.agent-collab` directory","Dependent on Claude Code for task delegation","Limited to bash-compatible environments"],"zh":[".agent-collab目录的访问权限要求","依赖于Claude Code进行任务委托","仅限bash兼容环境"],"ja":[".agent-collabディレクトリへのアクセス権の要求","Claude Codeへの依存によるタスク委任","bash互換環境への限定"],"ko":[".agent-collab 디렉토리 접근 권한 요구","클라우드 코드에 의한 작업 위임에 의한 의존","bash 호환 환경에 대한 제한"],"es":["Requiere acceso al directorio `.agent-collab`","Depende de Claude Code para la delegación de tareas","Limitado a entornos compatibles con bash"],"fr":["Nécessite l''accès au répertoire `.agent-collab`","Dépend de Claude Code pour la délégation de tâches","Limité aux environnements compatibles bash"],"de":["Erfordert Zugriff auf das Verzeichnis `.agent-collab`","Hängt von Claude Code für die Aufgabenübertragung ab","Begrenzt auf bash-kompatible Umgebungen"],"pt":["Requer acesso ao diretório `.agent-collab`","Dependente do Claude Code para delegação de tarefas","Limitado a ambientes compatíveis com bash"],"ru":["Требует доступа к каталогу `.agent-collab`","Зависит от Claude Code для делегирования задач","Ограничен средами, совместимыми с bash"],"ar":["يتطلب الوصول إلى الدليل `.agent-collab`","يعتمد على Claude Code لتفويض المهام","محدود بالبيئات المتوافقة مع bash"]},"version":4},"contentHash":"39870b52a0274aa5fcfa50556601804041b2051906f0b6f3badf1d19cebd207b","qualityScore":36}');
